func backtrack(_ l: Int, _ r: Int) -> Int {
  if l == r {
    return 0
  }
  if dp[l][r] != -1 {
    return dp[l][r]
  }

  var ans = sum[r+1] - sum[l]
  var minCost = Int.max
  for i in l..<r {
    minCost = min(minCost, backtrack(l, i) + backtrack(i+1, r))
  }
  dp[l][r] = ans + minCost
  return dp[l][r]
}
