long long int getMin(long long int p,long long int q){
	return (p<q)?p:q;
}

long long int minCost(int start,int end){
	if(start == end)
		return 0;
	if(visted[start][end] == true)
		return dp[start][end];

	long long int min = (long long int)2<<60;
	long long int x,y,current;
	for(int mid = start;mid<end;mid++){
		x = minCost(start,mid);
		y = minCost(mid+1,end);
		current = (prefix[mid]-prefix[start-1])+(prefix[end]-prefix[mid]);
		min = getMin(min,current+x+y);
	}

	dp[start][end] = min;
	visted[start][end] = true;
	return min;

}

