typedef long long ll;

const ll INF = 1e18;
const int MAXN = 400;
vector<vector<ll>> dp(MAXN,vector<ll>(MAXN));

ll calcdp( int l, int r, vector<ll>& cumsuma ){
	if(l==r) return dp[l][r] = 0;
	if(dp[l][r] > 0) return dp[l][r];

	ll res = INF;
	for(int i = l; i < r; i++){
		res = min( res, calcdp(l,i,cumsuma) + calcdp(i+1,r,cumsuma));
	}

	if(l==0) res += cumsuma[r];
	else res += cumsuma[r] - cumsuma[l-1];

	return dp[l][r] = res;
}

