const int MAXN = 405;

int N;
ll A[MAXN], pre[MAXN];

template <const int MAXN, class T> struct KnuthOptimization {
    T dp[MAXN][MAXN], INF; int mid[MAXN][MAXN];
    KnuthOptimization(T INF) : INF(INF) {}
    T cost(int l, int m, int r) { return pre[r] - pre[l]; }
    T solve(int N) {
        for (int l = N - 1; l >= 0; l--) for (int r = l; r <= N; r++) {
            if (r - l < 2) { dp[l][r] = 0; mid[l][r] = l; continue; }
            dp[l][r] = INF;
            for (int m = mid[l][r - 1]; m <= mid[l + 1][r]; m++) {
                T temp = dp[l][m] + dp[m][r] + cost(l, m, r);
                if (dp[l][r] > temp) { dp[l][r] = temp; mid[l][r] = m; }
            }
        }
        return dp[0][N];
    }
};

KnuthOptimization<MAXN, ll> DP(LL_INF);

int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    read(N);
    read(A, A + N);
    pre[0] = 0;
    partial_sum(A, A + N, pre + 1);
    writeln(DP.solve(N));
    return 0;
}

