long long cal_sum(const vector<int> &a, int i, const bitset<399> s) {
	long long res = 0;
	int l = i, r = i;
	while(l >= 0 && s[l]) {
		res += a[l];
		l--;
	}
	while(r + 1 < a.size() && s[r]) {
		res += a[r + 1];
		r++;
	}

	return res;
}

int main() {
	int N;
