	vector<int> a(N);
	for(auto & x: a) cin >> x;

	vector<vector<pair<long long,bitset<399> > > > dp(N, vector<pair<long long, bitset<399> > >(N - 1, make_pair(0, bitset<399>())));

	for(int i = 1; i < N; i++) {
		for(int j = 0; j < N - 1; j++) {
				long long m = LLONG_MAX;
				bitset<399> s;
			for(int k = 0; k < N - 1; k++) {
				bitset<399> ss = dp[i - 1][k].second;

				if(ss[j] || k == j) continue;
				ss[j] = true;
				long long mm = dp[i - 1][k].first + cal_sum(a, j, ss);
				if(mm >= 0 && m > mm) {
					m = mm;
					s = ss;
				}
			}
			//cout << i << " " << j << " " << m << " " << s << endl;
			dp[i][j] = make_pair(m, s);
		}
	}

	long long res = LLONG_MAX;
	for(auto x: dp[N - 1]) {
		res = min(res, x.first);
	}

	cout << res << endl;
}

