int a[N], n;
PXSum<ll> px;

ll solve(int l, int r) {
  if (l+1 == r) return 0;
  if (dp[l][r] == LINF) {
    for (int s = l+1; s < r; ++s) {
      dp[l][r] = min(dp[l][r], solve(l, s) + solve(s, r));
    }
    dp[l][r] += px.query(l, r);
  }
  return dp[l][r];
}

