long long rek(int l, int r){
    if(l == r)
        return 0;
    if(dp[l][r])
        return dp[l][r];

    long long rz = LLONG_MAX;
    for(int k = l + 1; k <= r; ++k){
        rz = min(rz, rek(l, k - 1) + rek(k, r) + p[r] - (l ? p[l - 1] : 0));
