long long rec(int l, int r, vector<vector<long long>>& dp, const long long* a){
  if(dp[l][r] != -1) return dp[l][r];
  if(l == r - 1) return dp[l][r] = 0;

  long long ret = INF;
  for(int i = l + 1; i < r; i++){
    ret = min(rec(l, i, dp, a) + rec(i, r, dp, a), ret);
  }

  ret += a[r] - a[l];

  return dp[l][r] = ret;
}

