long long int util(vector<long long int>&v,int i,int j)
{
    if(i>=j) return 0;
    if(dp[i][j]!=-1) return dp[i][j];
    long long int tot=0;
    for(int in = i;in<=j;in++)
    {
        tot+=v[in];
    }
    long long int mi = LLONG_MAX;
    for(int k=i;k<j;k++)
    {
        long long int temp = tot+util(v,i,k)+util(v,k+1,j);
        mi = min(mi,temp);
    }
    dp[i][j]=mi;
    return mi;
}
