vector<vector<long long>> memo;

long long minimize(int start, int end) {
    if(start + 1 >= end)
        return 0;

    if(memo[start][end] != -1)
        return memo[start][end];

    memo[start][end] = LLONG_MAX;
    for(int i = start + 1; i < end; i++)
        memo[start][end] = min( memo[start][end], minimize( start, i) + minimize( i, end));

    for(int i = start; i < end; i++)
        memo[start][end] += a[i];

    return memo[start][end];
}

