LL dp(int L, int R){
	if(vis[L][R]) return d[L][R];
	if(L == R) return d[L][R] = 0;
	d[L][R] = inf;
	for(int i = L + 1; i <= R; ++i){
		d[L][R] = min(d[L][R], dp(L, i - 1) + dp(i, R) + s[R] - s[L - 1]); 
	}
	return d[L][R];
}

