ll dfs(int l,int r){
	if(dp[l][r]!=LLMAX)return dp[l][r];
	ll ret=LLMAX;
	for(int i=l;i<r;i++){
		ll lmin=dfs(l,i);
		ll rmin=dfs(i+1,r);
		ret=min(ret,lmin+rmin);
	}
	return dp[l][r]=(ret+acc[r+1]-acc[l]);
}
