ll f(int l, int r) {
	ll& ret = memo[l][r];
	if (ret >= 0) return ret;
	if (l + 1 == r) return ret = 0;

	ret = (ll)1e18;
	for (int d = l + 1; d < r; d++) {
		ll tmp = sa[r] - sa[l] + f(l, d) + f(d, r);
		ret = min(ret, tmp);
	}

	return ret;
}

