const int MAX = 410;
const ll INF = LLONG_MAX;
int N;
ll dp[MAX][MAX], size[MAX];

ll get_size(int l, int r) {
  return size[r+1] - size[l];
}

ll solve(int l, int r) {
  if (l >= r) return 0;
  if (dp[l][r] >= 0) return dp[l][r];
  if (r-l == 1) return dp[l][r] = get_size(l, r);

  ll ret = INF;
  FOR (i, l, r+1) ret = min(ret, solve(l, i-1) + solve(i+1, r) + min(get_size(l, i), get_size(i, r)) + get_size(l, r));
  return dp[l][r] = ret;
}

