const double epsilon = 1e-8;
const int infinite    = 1000000000;
const long long infiniteLL = 1000000000000000000LL;
const long long modulo = 1000000007;

struct Solver {
    vector<long long> prefix;

    long long prefixSum(int i, int j) {
        long long result = prefix[j];

        if (i > 0) {
            result -= prefix[i - 1];
        }

        return result;
    }

    long long solve(int N, vector<int>& a) {
        prefix.resize(N, 0);
        prefix[0] = a[0];

        for (int i = 1; i < N; ++i) {
            prefix[i] = prefix[i - 1] + a[i];
        }

        vector< vector<long long> > dp(N + 1, vector<long long> (N + 1, infiniteLL));
        // dp[i][j] = minimum total cost to merge interval [i...j] into one vertex.

        for (int i = N - 1; i >= 0; --i) {
            dp[i][i] = 0;

            for (int j = i; j < N; ++j) {
                for (int k = i; k < j; ++k) {
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j] + prefixSum(i, j));
                }
            }
        }

        return dp[0][N - 1];
    }
};

int main()
{
    int nTest = 1;

    for (int test = 1; test <= nTest; ++test) {
        int N = readInt();
        vector<int> a(N);

        for (int& x : a) {
            x = readInt();
        }

        Solver solver;
        long long result = solver.solve(N, a);
        cout << result << endl;
    }

    return 0;
}

