int call(int i,int j,vector<int>&A, vector<vector<int> >&dp)
{
    if(i==j)
    {
        return 0;
    }
    if(dp[i][j]!=-1)
    {
        return dp[i][j];
    }

    dp[i][j]=INF;
    int add=A[j];
    if(i>0)
    {
        add-=A[i-1];
    }
    //cout<<i<<" "<<j<<" "<<add<<" ";
    for(int k=i;k<j;k++)
    {
        dp[i][j]=min(dp[i][j],call(i,k,A,dp)+call(k+1,j,A,dp)+add);
    }
    return dp[i][j];
}

