 * [l, r) までを合体させた時の最小コスト
 */
LL rec(int l, int r) {
    if(dp[l][r] != LINF) {
        return dp[l][r];
    }

    if(l == r) {
        return 0;
    }
    if(r - l == 1) {
        return v[l];
    }

    LL res = LINF;
    for(int i = l + 1; i <= r - 1; ++i) {
        res = min(res, rec(l, i) + rec(i, r));
    }

    return dp[l][r] = res + (cum[r] - cum[l]);
}

