ll calc(int l, int r) {
    if (l >= r)
        return 0;
    if (l + 1 == r)
        return p[r] - p[l - 1];
    if (~dp[l][r])
        return dp[l][r];
    dp[l][r] = 1e14;
    for (int i = l; i < r; ++i) {
        ll x = calc(l, i);
        ll y = calc(i + 1, r);
        dp[l][r] = min(dp[l][r], x + y + p[r] - p[l - 1]);
    }
    return dp[l][r];
}

