ll dfs(int left, int right)
{
    if (dp[left][right] != -1) {
        return dp[left][right];
    }
    else if (left == right) {
        return 0;
    }
    else if (left + 1 == right) {
        dp[left][right] = csum[left][right];
        return csum[left][right];
    }
    else {
        ll minCost = 1000000000000000;
        for (int m = left; m < right; ++m) {
            ll t = dfs(left, m) + dfs(m + 1, right) +(csum[left][m] + csum[m + 1][right]);
            if (t < minCost) minCost = t;
        }
        dp[left][right] = minCost;
        return minCost;
    }
}

