ll memoize(int l, int r){
    if (l == r){
        return dp[l][r] = a[l];
    }
    if(dp[l][r] != INF){
        return dp[l][r];
    }
    for (int k = l;k < r;k++){
        dp[l][r] = min(dp[l][r], memoize(l, k) + memoize(k + 1, r) + sum[r] - sum[l - 1]);
    }
    return dp[l][r];
}

