// Returns <value of the unit after combining, cost of combination> 
pair<ll, ll> f(vector<ll>& A, int i, int j, vector<vector<pair<ll, ll> >> &dp) {
  	// base case 
	if(i == j) {
      	return {A[i], 0};
    }

  	if(dp[i][j].first!=0) {
      	return dp[i][j];
    }

  	ll minCost = LONG_MAX;
  	ll size = 0;
  	for(int k=i; k<j;k++){
      	auto x =  f(A, i, k, dp);
      	auto y = f(A, k+1, j, dp);
		size = x.first + y.first;

      	ll cost = size + x.second + y.second;
    	minCost = min(minCost, cost);
    }
  	dp[i][j] = {size, minCost};
  	return {size, minCost};
}

