int kadane(int* a,int n)
{
	int loc=a[0],glo=a[0];
	for(int i=1;i<n;i++)
	{
		loc=max(a[i],loc+a[i]);
		glo=max(glo,loc);
	}
	return glo;
}

int help(vector<int>& a,int i,int j)
{
	int s=0;
	for(int k=i;k<=j;k++)
		s+=a[k];
	return s;
}
int solve(vector<int>& a,int i,int j)
{
	if(i==j) return 0;

	int ans=inf;

	for(int k=i;k<j;k++)
	{
		int left=solve(a,i,k);
		int right=solve(a,k+1,j);
		ans=min(ans,left+right+help(a,i,j));
	}
	return ans;
}


