            int j=i+len-1;
            if(len==1)
            {
                d[i][j]=0;
                continue;
            }
            if(len==2)
            {
                d[i][j]=a[i]+a[j];
                continue;
            }
            d[i][j]=10000000000;
            for(int k=i;k<=j-1;k++)
            {
                d[i][j]=min(d[i][j],d[i][k]+d[k+1][j]+sum[j]-sum[i-1]);
            }
        }
    }
    cout<<d[1][n];
    return 0;
}

