using namespace std;
vector<long> sum;
vector<vector<long>> dp;
long solve(vector<long>&v, int i, int j)
{
    if(i > j)
        return 0;
    if(i == j)
        return v[i];
    if(i + 1 == j)
        return (long)v[i] + v[j];
    if(dp[i][j] != -1)
        return dp[i][j];
    else
    {
        long sumij = sum[j] - (i - 1 >= 0 ? sum[i - 1] : 0);
        long cost = LONG_MAX;
        cost = min(cost, solve(v, i, j - 1) + sumij);
        cost = min(cost, solve(v, i + 1, j) + sumij);
        for(int k = i + 1; k < j; k++)
        {
            long sumik = sum[k] - (i - 1 >= 0 ? sum[i - 1] : 0);
            long sumkj = sum[j] - (k - 1 >= 0 ? sum[k - 1] : 0);
            long costik_ = solve(v, i, k - 1), costk_j = solve(v, k + 1, j);
            cost = min(cost, costik_ + sumik + costk_j + sumij);
            cost = min(cost, costik_ + sumkj + costk_j + sumij);
        }
        dp[i][j] = cost;
        return cost;
    }
    return LONG_MAX;
}

