ll pref[405];

ll jum(ll a, ll b) {
	ll res = pref[b];
	if (a) res -= pref[a - 1];
	return res;
}

ll rek(int a, int b) {
	if (a == b) return 0;
	ll &ret = DP[a][b];
	if (ret != -1) return ret;
	ret = INF;
	FOR(i, a, b) {
		if (i == a) {
			ll val = jum(a, b) + rek(a + 1, b);
			ret = min(ret, val);
		}
		else if (i == b) {
			ll val = jum(a, b) + rek(a, b - 1);
			ret = min(ret, val);
		}
		else {
			ll val = min(2 * jum(a, i - 1) + 2 * A[i] + jum(i + 1, b)
						,2 * jum(i + 1, b) + 2 * A[i] + jum(a, i - 1));
			val += rek(a, i - 1) + rek(i + 1, b);
			ret = min(ret, val);
		}
	}

	return ret;
}

