long long calc(int i, int j) {
	if (i == j) return 0;
	else if (DP[i][j] != -1) return DP[i][j];
	else {
		long long min = calc(i,i) + calc(i + 1,j);
		for (int k = 1; k < j - i; k++) {
			if (min > calc(i, i + k) + calc(i + k + 1, j)) {
				min = calc(i, i + k) + calc(i + k + 1, j);
			}
		}
		long long sum = 0;
		for (int k = i; k <= j; k++)
			sum += a[k];
		return DP[i][j] = min + sum;
	}
}


