pair<uint64_t, uint64_t> dfs(const vector<uint64_t>& a, const uint32_t l, const uint32_t r){
	if(l == r) return make_pair(a[l], a[l]);

	uint64_t ansc = UINT64_MAX;
	uint64_t anss = 0;

	for(uint32_t d=l; d<r; d++) {
		auto dfsl = dfs(a, l, d);
		auto dfsr = dfs(a, d+1, r);

		uint64_t tansc = dfsl.first + dfsr.first + dfsl.second + dfsr.second;
		if(tansc < ansc) {
			ansc = tansc;
			anss = dfsl.second + dfsr.second;
		}
	}

	return make_pair(ansc, anss);
}


