    ll til_now = llmax;
    ll this_half;
    for (ll first = 1; first < len; ++first) {
        ll x = helper(l, first);
        ll part1 = half;
        ll y = helper(l+first, len - first);
        ll part2 = half;

        ll tmp = part1 + part2;
