int main(int argc, char *argv[])
{
    int N;
    cin >> N;
    vector<long> slimes(N);
    vector<long> S(N);
    for (int i = 0; i < N; i++) {
        cin >> slimes[i];
    }
    S[0] = slimes[0];
    for (int i = 1; i < N; i++) {
        S[i] = S[i - 1] + slimes[i];
    }
    auto sum = [&](int l, int r) -> long {
        if (l > r) return 0;
        return S[r] - (l == 0 ? 0 : S[l - 1]);
    };
    const long INF = 1e18;
    vector<vector<long>> dp(N + 1, vector<long>(N + 1, INF));
    for (int i = 0; i < N; i++) {
        dp[i][i] = 0;
    }
    for (int L = N - 1; L >= 0; L--) {
        for (int R = L; R < N; R++) {
            for (int k = L; k <= R; k++) {
                int v = slimes[k];
                long l = sum(L, k - 1);
                long r = sum(k + 1, R);
                long cost = (l == 0 || r == 0) ? v + l + r : 2 * (v + min(l, r)) + max(l, r);
                dp[L][R] = min(dp[L][R],
                               (L == k ? 0 : dp[L][k - 1]) + (k + 1 > R ? 0 : dp[k + 1][R]) + cost);
            }
        }
    }
    cout << dp[0][N - 1] << endl;
    return 0;
}

