ll dfs(vector<ll> v){
  if(v.size()<=1) return 0;
  ll ret = 0LL;
  vector<ll> sum;
  for (int i = 0; i < v.size()-1; i++)
  {
    sum.push_back(v[i]+v[i+1]);
  }
  auto itr = min_element(sum.begin(),sum.end());
  int idx = itr-sum.begin();
  v.erase(v.begin()+idx+1);
  v[idx] = *itr;
  ret += *itr;
  ret += dfs(v);
  return ret;
}

