ll pound(int left, int right)
{
    if (left == right)
        return 0;

    if (vis[left][right])
        return dp[left][right];

    vis[left][right] = 1;

    ll mn = INF;
    for (int i = left; i < right; ++i)
        mn = min(mn, pound(left, i) + pound(i + 1, right) + csum[right + 1] - csum[left]);
    return dp[left][right] = mn;
}

