const int INF = 1e9;

void solve(ll N, std::vector<ll> a) {
  priority_queue<ll, vector<ll>, greater<ll>> q;
  rep(i, N) q.push(a.at(i));

  ll ans = 0;

  while (!q.empty()) {
    ll v1 = q.top();
    q.pop();

    if (q.empty()) {
      break;
    }

    ll v2 = q.top();
    q.pop();
    q.push(v1 + v2);
    ans += v1 + v2;
  }

  cout << ans << endl;
}

