ll f(vector<vector<ll>>& dp, const vector<ll>& A, const vector<ll>& sum, int N, int beg, int end){
    if(dp[beg][end] != -1)return dp[beg][end];
    if(end - beg == 1){
        dp[beg][end] = A[beg]+A[end];
        return dp[beg][end];
    }
    if(end == beg){
        dp[beg][end] = 0;
        return dp[beg][end];
    }
    dp[beg][end] = 10000000000000LL;
    for(int i = beg;i < end;i++){
        ll c = f(dp,A,sum,N,beg,i) + f(dp,A,sum,N,i+1,end) + sum[end+1]-sum[beg];
        dp[beg][end] = min(dp[beg][end], c);
    }
    return dp[beg][end];

}

