      for(int k = i + 1; k + 1 < j; ++k) {
        mn = min(mn, dp[i][k] + dp[k + 1][j]);
      }
      dp[i][j] = mn + cost;
    }
  }

  printf("%lld\n", dp[0][N - 1]);
  return 0;
