const int MOD = 1e9+7;
ll dp[405][405];
int v[405];
ll psum[405];
bool mark[405][405];

ll f(int l, int r) {
	if(l == r) return 0;
	if(mark[l][r]) return dp[l][r];
	mark[l][r] = true;

	ll ret = 1e18;
	for(int i = l; i < r; i++) {
		ll junta = v[i];
		ll left = 0, pleft = 0, right = 0, pright = 0;
		int qtt = 0;
		if(i > l) {
			left = f(l, i-1);
			pleft = psum[i-1] - psum[l-1];
			qtt++;
		}
		if(i < r) {
			right = f(i+1, r);
			pright = psum[r] - psum[i];
			qtt++;
		} 
		ll a1 = 0, a2 = 0;
		if(qtt == 2) {
			a1 = min(pleft, pright);
			a2 = max(pleft, pright);
		}
		else if(qtt == 1) {
			if(i > l) a1 = pleft;
			else a1 = pright;
		}
		ret = min(ret, qtt*junta + a1*qtt + (qtt-1)*a2 + left + right);
	}

	return dp[l][r] = ret;
}

