const ll INF = static_cast<ll>(1e9) + 7ll;
const ll LINF = INF * INF;
const int MAXN = static_cast<int>(1e3) + 17;

int n;
ll a[MAXN], S[MAXN];
bool used[MAXN][MAXN];
ll dp[MAXN][MAXN];

