    if (!(cin >> n))
        return false;

    forn (i, n)
        cin >> a[i + 1];

    return true;
}

void dfs(int l, int r) {
    if (used[l][r])
        return ;

    used[l][r] = true;

    if (l == r) {
        dp[l][r] = 0;
        return ;
    }

    dp[l][r] = INF * INF;

    for (int m = l; m < r; ++m) {
        dfs(l, m);
        dfs(m + 1, r);
        dp[l][r] = min(dp[l][r], S[r] - S[l - 1] + dp[l][m] + dp[m + 1][r]);
    }
}

void solve() {
    for (int i = 1; i <= n; ++i)
        S[i] = S[i - 1] + a[i];

    dfs(1, n);
    cout << dp[1][n] << endl;
}

