int cal(int cost, int l, int r)
{
	int mm = 1e18;
	for(int i = l; i < r; i++)
	{
		if(cost == dp[l][i] + dp[i + 1][r])
		{
			int a = 0, b = 0;
			if(i - l + 1 > 1)
			{
				a = cal(dp[l][i], l, i);
				// cout << l << " " << i << endl;
			}
			if(r - i > 1)
			{
				b = cal(dp[i + 1][r], i + 1, r);
			}
			mm = min(mm, cost + a + b);
		}
	}
	return mm;
}

