template <typename T>
class CumulativeSum {
	vector<T> a;

  public:
	CumulativeSum(vector<T>& x) : a(x.size() + 1, 0) {
		rep(i, x.size()) { a[i + 1] = a[i] + x[i]; }
	}
	T get(int l, int r) { // [l, r]$B$N6h4V$N9g7W$r5a$a$k(B
		return a[r + 1] - a[l];
	}
	T operator[](const int i) const { return a[i]; }
};

