int dfs(int l, int r, CumulativeSum<int>& sum) { // [l, r)
	if (l > r) return 0;
	// if(l > r) return INF;
	if (memo[l][r] != -1) return memo[l][r];
	// if(r -l == 1){ return sum.get(l,r-1); }
	// cout << l << ' ' << r << endl;
	// cout << min(dfs(l, r - 1) + a[r - 1], dfs(l + 1, r) + a[l]) << endl;

	int res = INF;
	range(i, l + 1, r) {
		if (i == l + 1)
			res = min(res,
					  dfs(l, i, sum) + dfs(i, r, sum) + sum.get(l + 1, r - 1));
		else if (i + 1 == r)

			res = min(res, dfs(l, i, sum) + dfs(i, r, sum) + sum.get(l, r - 2));
		else
			res = min(res, dfs(l, i, sum) + dfs(i, r, sum) + sum.get(l, r - 1));
	}
	if (r - l <= 2) res = sum.get(l, r - 1);
	//cout << l << ' ' << r << ' ' << res << endl;
	return memo[l][r] = res;
}

