int n , a[200] ,pr[N], dp[N][N];
bool was[N][N];
int get(int l , int r){
	if(l == r)
		return 0;
	if(l == r - 1)
		return a[l] + a[r];
	if(was[l][r])
		return dp[l][r];
	was[l][r] = 1;
	int cur = 1e18;
	for(int i = l ; i < r ; i++)
		cur = min(cur , get(l , i) + get(i + 1 , r));
	dp[l][r] = cur + pr[r] - pr[l - 1];
	return dp[l][r];
}
