int calc(int i,int j)
{
    if(i == j) return 0;

    if(dp[i][j] != -1) return dp[i][j];

    assert(i < j);

    dp[i][j] = inf;

    for(int k=i;k<j;k++) dp[i][j] = min(dp[i][j], calc(i,k) + calc(k+1,j) + a[j] - a[i-1]);

    return dp[i][j];
}

