template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return 1; } return 0; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }

const long long MAX = 5100000;
const long long INF = 1LL << 60;
const long long mod = 1000000007LL;
//const long long mod = 998244353LL;

using namespace std;
typedef unsigned long long ull;
typedef long long ll;

int N;
vector<vector<ll>> dp;
vector<ll> a;
vector<ll> sum;

ll dfs(int left, int right) {
	if (left == right) return 0; //くっついてないときのcostは0
	if (dp[left][right] != INF) return dp[left][right]; //すでに計算済みなら返す
	ll cost = sum[right + 1] - sum[left]; //くっつけるcost
	ll res = INF; //[left, right]の解
	for (int k = left; k < right; k++) { //中継地点
		chmin(res, dfs(left, k) + dfs(k + 1, right) + cost);
	}
	return dp[left][right] = res; //dpに格納してから返すのを忘れずに
}

