ll search(const int start, const int end){
  if(start>=end) return dp[start][end]=0;
  if(dp[start][end]>=0) return dp[start][end];
  if(start+1==end) return dp[start][end] = a[start]+a[end];
  ll tmp=INFLL;
  ll sum=0;
  rep(i, start, end){
    ll tmp1 = search(start, i);
    ll tmp2 = search(i+1, end);
    tmp = min(tmp, tmp1+tmp2);
    sum += a[i];
  }
  sum += a[end];
  return dp[start][end] = tmp+sum;
}

