ll A[1000];
ll dp[1000][1000];
ll pref[1000];
inline void sumwork()
{
	FORI(i,1,N+1)
	{
		pref[i]=pref[i-1]+A[i];
	}
	FORI(i,N+1,2*N+1)
	{
		pref[i]=pref[i-1]+A[i-N];
	}
}
inline ll sum(ll s,ll e)
{
	if (s<=e)
	{
		return pref[e]-pref[s-1];
	}
	else
	{
		return pref[N+e]-pref[s-1];
	}
}
inline ll make(ll s,ll e)
{
	if (s==e)
	{
		dp[s][e]=0;
		return 0;
	}
	else if(dp[s][e]!=-1)
	{
		return dp[s][e];
	}
	else
	{
		dp[s][e]=inf;
		ll x=s;
		while(x!=e)
		{
			if (x+1>=N)
			{
				dp[s][e]=min(dp[s][e],make(s,x)+make((x+1)-N,e)+sum(s+1,e+1));
			}
			else
			{
				dp[s][e]=min(dp[s][e],make(s,x)+make(x+1,e)+sum(s+1,e+1));
			}
			x++;
			if (x>=N)
			{
				x=x-N;
			}
		}
		return dp[s][e];
	}
}

