// Get minimum cost in [l,r)
ll dfs(int l, int r){
    if(memo[l][r] != -1){return memo[l][r];}
    if(r-l <= 1){return 0;}
    ll ret = 1e12;
    for(int i=l+1; i<r; i++){
        ll val = 0;
        val += dfs(l, i);
        val += dfs(i, r);
        ret = min(val, ret);
    }
    ret += a_sum[r] - a_sum[l];
    memo[l][r] = ret;
    return ret;
}

