int findMinCost(int start, int end)
{
	if(dp[start][end] != -1)
		return dp[start][end];
	if(start == end)
		return (dp[start][end] = 0);
	if(end - start == 1)
			return (dp[start][end] = A[end] - A[start-1]);
	int ans = 1e16;
	for(int mid = start; mid < end; mid++)
		ans = min(ans, findMinCost(start,mid) + findMinCost(mid+1, end) + A[end] - A[start-1]);
