#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
#define FOR(i, m, n) for(int i = (int)(m); i < (int)(n); ++i)


int main()
{
    int N;
    cin >> N;
    vector<long long> a(N+1);
    REP(i, N) cin >> a[i+1];

    vector<long long> s(a);
    REP(i, N) s[i+1] += s[i];

    // dp[i][j]: 1-index で [i,j] のスライムを一つにするのに必要な最小のコスト
    vector<vector<long long>> dp(N+1, vector<long long>(N+1, 1e+18));

    FOR(i, 1, N+1) dp[i][i] = 0;
    FOR(len, 2, N+1){
        FOR(l, 1, N+1){
            int r = l+len-1;
            if(r > N) break;
            FOR(k, l, r){ 
                dp[l][r] = min(dp[l][r], dp[l][k]+dp[k+1][r]+s[r]-s[l-1]);
            }
        }
    }
    cout << dp[1][N] << endl;

    return 0;
}

