int main()
{
	int N;
	cin >> N;

	ll a;
	vector<ll> cum(N+1, 0);
	REP(i, N) {
		cin >> a;
		cum[i + 1] = a + cum[i];
	}

	vector<vector<ll>> dp(N+2, vector<ll>(N+2, 1e10));
	REP(i, N) {
		dp[i][i+1] = 0;
	}

	FOR(w, 1, N) {
		REP(i, N - w) {
			int j = i + w + 1;
			FOR(k, i, j) {
				chmin<ll>(dp[i][j], dp[i][k] + dp[k][j] + cum[j] - cum[i]);
			}
		}
	}

	for (auto& col : dp) {
		view(col);
	}

	cout << dp[0][N] << endl;

}

