ll rec(int i , int j){
	if(i==j)return 0;
	if(j==i+1)return a[i]+ a[j];	

	ll& ans = dp[i][j];
	if(ans!=-1)return ans;
	ans = 1e18;

	for(int idx = i; idx < j ; ++idx){
		ans = min(ans, rec(i,idx) + rec(idx+1,j) + sum(i,j));
	}
	return ans;
}


