const ll mod = 1000000007;

static const ll INF = 1e15;

int main() {
	int n;
	cin >> n;
	vector<ll> as(n);
	rep(i, n) cin >> as[i];
	vector<ll> asum(n + 1, 0);
	rep(i, n) {
		asum[i + 1] = asum[i] + as[i];
	}
	//dp[i][j]...iからjまでの合成コストの総和の最小値
	//dp[i][j]...min(dp[i][i] + dp[i+1][j] + asum[j] - asum[i-1] ,
	// dp[i][i+1] + dp[i+2][j] + asum[j]  - asum[i-1] , ...
	// dp[i][j-1] + dp[j][j] + asum[j]  - asum[i-1] )
	vector<vector<ll>> dp(n, vector<ll>(n, INF));
	rep(i, n) {
		dp[i][i] = 0;
	}
	for (int length = 2; length <= n; length++) {
		for (int left = 0; left <= n - length; left++) {
			int right = left + length - 1;
			ll add = asum[right + 1] - asum[left];
			ll cost = INF;
			for (int shift = 0; left + shift + 1 <= right; shift++) {
				ll a = dp[left][left + shift] + dp[left + shift + 1][right];
				cost = min(cost, a);
			}
			cost += add;
			dp[left][right] = cost;
		}
	}
	cout << dp[0][n - 1] << endl;
	return 0;
}

