#define FOR(i,a,b) for(int i=(a);i<(b);++i)
#define REP(i,n) FOR(i,0,n)
#define OUT(v) cout<<v<<"\n"
const int MOD = 1e9+7;
const ll INF = 1e12;

int N;
int A[401];
ll dp[401][401];
ll sum[401];
ll solve(int s, int t) {
  if (dp[s][t] != INF)
    return dp[s][t];
  if (s + 1 == t)
    return 0;

  ll ans = INF;
  FOR(i, s + 1, t)
    ans = min(ans, (sum[t] - sum[s]) + solve(s, i) + solve(i, t));

  return dp[s][t] = ans;
}
int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  cin >> N;

  sum[0] = 0;
  REP(i, N) {
    cin >> A[i];
    sum[i+1] = (ll)sum[i] + A[i];
  }

  REP(i, 401) REP(j, 401)
    dp[i][j] = INF;

  OUT(solve(0, N));

  return 0;
}

