ll solve(int p, int q) {
    if (dp[p][q] >= 0) return dp[p][q];

    if (p == q) dp[p][q] = 0;
    else if (q - p == 1) dp[p][q] = a[p] + a[q];
    else {
        ll mn = 1e18;
        for (int i = 0; i < q - p; i++) {
            mn = min(mn, solve(p, p + i) + solve(p + i + 1, q) + sum[q] - sum[p - 1]);
        }
        dp[p][q] = mn;
    }
    return dp[p][q];
}

