#define reps(i,s,n) for(long long i=s;i<n;i++)
using namespace std;

map<pair<int, int>, long long> memo;
vector<long long> d(1);

long long split_slime(int l, int r) {
	if (l + 1 == r) return 0;
	if (memo.find(make_pair(l, r)) != memo.end()) return memo[make_pair(l, r)];
	long long mn = (1LL << 60);
	reps(i,l+1,r) mn = min(mn, (d[i] - d[l]) + (d[r] - d[i]) + split_slime(l, i) + split_slime(i, r));
	return memo[make_pair(l, r)] = mn;
}

int main(void) {
	int n;
