using namespace std;

ll solve(int l, int r, vector<ll> &sum, vector<vector<ll>> &dp){
	if(l == r)
		return 0;
	if(dp[l][r] != LLONG_MAX)
		return dp[l][r];
	ll &ret = dp[l][r];
	for(int i{l}; i < r; ++i){

		ret = min(ret, solve(l, i, sum, dp) + solve(i + 1, r, sum, dp) + sum[r + 1] - sum[l]);
	}
	return ret;
}

