		pref[i] = pref[i - 1] + a[i];

	auto getSum = [&](int l, int r) {
		if(l == 0)
			return pref[r];
		return pref[r] - pref[l - 1];
	};

	vector<vector<L>> dp(n, vector<L>(n, L(1e18))); // answer for interval [l, r]
	for(int len = 1; len <= n; ++len)
		for(int l = 0; l <= n - len; ++l) {
			int r = l + len - 1;
			if(l == r)
				dp[l][r] = 0;

			for(int i = l; i < r; ++i)
				dp[l][r] = min(dp[l][r], dp[l][i] + dp[i + 1][r] + getSum(l, r));
		}
	cout << dp[0][n - 1] << '\n';
}

