        return {0, arr[l]};

    if(r == l + 1)
        return {arr[l] + arr[r], arr[l] + arr[r]};

    pii &res = cache[l][r];
    if(res.first != -1 && res.second != -1)
        return res;

    int len = r - l + 1;
    ll minele = LONG_MAX, sum = 0;
    for(int i = 1; i <= len - 1; ++i)
    {
        pii left = dpSol(l, l + (i - 1));
        pii right = dpSol(l + i, r);

        ll temp = left.first + left.second + right.first + right.second;
        if(minele > temp)
        {
            minele = temp;
            sum = left.second + right.second;
        }
    }
    return res = {minele, sum};
}

