template <class T> struct CumulativeSumG{
	vector<T> cum;
	CumulativeSumG(vector<T> &vec): cum(vec.size()+1){
		REP(i, (ll)vec.size()) cum[i+1] = cum[i] + vec[i];
	}
	T operator () (ll s, ll t){ return cum[t+1] - cum[s]; }
};
using CumulativeSum = CumulativeSumG<ll>;


void solve()
{
	ll N;
	cin >> N;
	vll a = cinv(N);

	CumulativeSum cumA(a);

	vvll dp(N, vll(N,INF));
	REP(i, N) dp[i][0] = 0;

	REPS(j, 1, N-1){
		REP(i, N-j){
			REPS(k, 0, j-1){
				chmin(dp[i][j], dp[i][k] + dp[i+k+1][j-k-1]);
			}
			dp[i][j] += cumA(i, i+j);
		}
	}

	cout << dp[0][N-1] << '\n';
}

int main(){
	solve();
	return 0;
}

