int min_cost(int i, int j)
{
	if (i >= j)
		return dp[i][j] = 0;

	if (dp[i][j] != 0)
		return dp[i][j];

	int cur_cost = pre[j] - pre[i - 1];
	int ans = inf;
	for (int k = i + 1; k <= j; k++)
		ans = min(ans, min_cost(i, k - 1) + min_cost(k, j));

	return dp[i][j] = ans + cur_cost;
}

