		{
			int j=i+Len;
			int Interval=Pre[j]-Pre[i-1];
			for(int Turn=i;Turn<j;Turn++)
			{
				Dp[i][j]=min(Dp[i][j],Dp[Turn+1][j]+Dp[i][Turn]+Interval);
			}
		}
	}
	cout<<Dp[1][N]<<endl;
	return 0;
}

