ll f(vector<vector<ll>>& dp, const vector<ll>& A, const vector<ll>& sum, int N, int beg, int end){
    if(dp[beg][end] != -1)return dp[beg][end];
    if(end - beg == 1){
        dp[beg][end] = A[beg]+A[end];
        return dp[beg][end];
    }
    if(end == beg){
        dp[beg][end] = 0;
        return dp[beg][end];
    }
    dp[beg][end] = 10000000000000LL;
    for(int i = beg;i < N;i++){
        int j = i + 2;
        if(j > end)break;
        ll left = f(dp,A,sum,N,beg,i);
        ll right = f(dp,A,sum,N,j,end);
        ll c = min(2*(sum[end+1]-sum[beg])-(sum[i+1]-sum[beg]), (sum[end+1] - sum[beg])+(sum[j] - sum[beg]));
        dp[beg][end] = min(dp[beg][end], left+right+c);
    }
    return dp[beg][end];

}

