#include <bits/stdc++.h>

using namespace std;

const int MAXN = 400;
const long long LLINF = 1e15;

int a[MAXN + 7];
long long pre[MAXN + 7];

long long sum(int l, int r) {
  return pre[r] - pre[l - 1];
}

long long dp[MAXN + 7][MAXN + 7];

long long dpf(int l, int r) {
  if (l > r) {
    return 0;
  }
  long long &d = dp[l][r];
  if (d != -1) {
    return d;
  }
  if (l == r) {
    return d = a[l];
  }
  if (l == r - 1) {
    return d = a[l] + a[r];
  }
  d = LLINF;
  for (int i = l; i <= r; i++) {
    long long t = dpf(l, i - 1) + dpf(i + 1, r);
    if (i == l or i == r) {
      t += sum(l, r);
    }
    else {
      long long left = sum(l, i - 1);
      long long right = sum(i + 1, r);
      if (left > right) {
        swap(left, right);
      }
      t += 2 * sum(l, r) - right;
    }
    if (d > t) {
      // cerr << l << " " << i << " " << r << "\n";
      d = t;
    }
  }
  return d;
}

