ll sum[500];
ll dp[500][500];

ll memo(int L, int R) {
	if(L == R) return 0;
	if(L+1 == R) return a[L] + a[R];
	if(dp[L][R] != -1) return dp[L][R];
	ll res = 1e18;
	for(int i=L; i<R; i++) {
		res = min(res, sum[R] - sum[L-1] + memo(L, i) + memo(i+1, R));
	}
	return dp[L][R] = res;
}

