ll cnt(ll i,ll j)
{
    if(i>=j)
        return 0;
    if(dp[i][j]!=-1)
        return dp[i][j];
    ll m1=a[i]+a[i+1],m2=a[j]+a[j-1];
    a[i+1]+=a[i];
    m1 += cnt(i+1,j);
    a[i+1]-=a[i];
    a[j-1]+=a[j];
    m2 += cnt(i,j-1);
    a[j-1]-=a[j];
    dp[i][j] = min(m1,m2);
    return dp[i][j];
}
