long long int solve(long long int arr[],int i,int j)
{
	if(dp[i][j]!=-1)
		return dp[i][j];
	if(i==j)
	{
		dp[i][j]=0;
		return dp[i][j];
	}
	long long int mn=INF;
	for(int k=i+1;k<=j;k++)
		mn=min(mn,solve(arr,i,k-1)+solve(arr,k,j));
	dp[i][j]=mn;
	for(int k=i;k<=j;k++)
	 	dp[i][j]+=arr[k];
	return dp[i][j];
}

