	FOR(i,1,n+1){
		cin >> a[i];
		sum[i] = sum[i-1] + a[i];// 累積和を計算しておく -> 合体のコストを高速に計算するため
	}
	FOR(i,1,n+1){
		FOR(j,1,n+1){
			dp[i][j] = 1LL<<50;// 最小を求めたいので、初期値は大きい値にしておく
			if(i==j)dp[i][j] = 0;
			// i==jではスライムが1体しかいないので合体コストは0,この情報からどのようにループをすればいいか考える
			// 1体の次は2体の結合、次は3体の結合...と求められそう
		}
	}

	FOR(i,1,n+1){ // i := 幅 -> 区間の幅が小さいものから決まっていく
		FOR(j,1,n+1-i){ // j := 左端 -> [j,j+i]の区間を考える
			FOR(k,j,j+i){ // [j,k]と[k+1,j]の合体を考える , それぞれ今考えている区間の長さより短いので計算済みである
				dp[j][j+i] = min(dp[j][j+i] , dp[j][k] + dp[k+1][j+i] + sum[j+i] - sum[j-1]);
