template <class T> inline bool chmin(T &a, const T &b) {
  return (a > b) ? a = b, true : false;
}

int main() {
  int N;
  std::cin >> N;
  std::vector<long long> a(N);
  for (int i = 0; i < N; ++i)
    std::cin >> a[i];

  long long inf = 1LL << 60;
  std::vector<std::vector<long long>> dp(N + 3,
                                         std::vector<long long>(N + 3, inf));

  std::vector<long long> s(N + 3, 0);
  for (int i = 0; i < N; ++i)
    s[i + 1] = s[i] + a[i];

  std::function<long long(int, int)> rec = [&](int l, int r) {
    if (dp[l][r] != inf)
      return dp[l][r];
    if (l + 1 == r)
      return dp[l][r] = 0;
    long long res = inf;
    for (int k = l + 1; k < r; ++k) {
      long long lc = rec(l, k);
      long long rc = rec(k, r);
      chmin(res, lc + rc + s[r] - s[l]);
    }
    return dp[l][r] = res;
  };

  std::cout << rec(0, N) << std::endl;
}

