}

//a[L]からa[R]までの総和
ll get(int L,int R)
{
    ll res = b[R];
    if(L) res -= b[L - 1];
    return res;
}

//探索フラグ:Have visted
bool vis[404][404];
//メモ
ll memo[404][404];
//メモ化再帰
ll dp(int L,int R)
{
    if(vis[L][R] == true) return memo[L][R];
    else if(L == R){
     vis[L][R] = true; //フラグを立てる
     return memo[L][R] = 0; //メモしながらリターン
    }
    else {
        vis[L][R] = true; //フラグを立てる
        ll res = infl; //inflは十分に大きい
        //cで二つに区切ってmin全探索
        for(int c = L; c < R; c++){
            res = min(res,dp(L,c) + dp(c + 1,R) + get(L,R));  
        }
        return memo[L][R] = res; //メモしながらリターン
    }
}

