ll calc(int i, int j, int k) {
    if(i == n) return INF;
    if(j == 0 && k == 0) return 0;

    ll &r = dp[i][j][k];
    if(r != -1) return r;

    ll res = INF;

    if(k) res = calc(i + 1, j + 1, k - 1);

    ll izq, der;

    if(i == 0 || j == 0) izq = 0;
    else izq = calc(i - j, 0, j - 1);

    if(i == n - 1 || k == 0) der = 0;
    else der = calc(i + 1, 0, k - 1);

    ll sumizq = sum[i] - sum[i - j];
    ll sumder = sum[i + k + 1] - sum[i + 1];

    ll cand = izq + der + 2 * min(sumizq, sumder) + a[i] + max(sumizq, sumder);
    if(j && k) cand += a[i];
    res = min(cand, res);
    // cout << i << " " << j << " " << k << " " << sumizq << " " << sumder << " " << res << endl;
    return r = res;
}

