ll get(int l, int r) {
    ll tmp = INF;
    if(check[l][r]) 
        return dp[l][r];

    check[l][r] = true;
    if(l == r) {
        return 0;
    }
    rep(i, l, r) {
        ll a = get(l, i);
        ll b = get(i+1, r);
        tmp = min(tmp, a + b);
    }
    ll ans = sum[r] - sum[l-1] + tmp;
    dp[l][r] = ans;
    return ans;
}

