void preprocess(vector<ll> &v,ll n){
    for(ll i=1;i<=n;i++){
        for(ll j=i;j<=n;j++){
            sum[i][j]=v[j]+((i==j) ? 0 : sum[i][j-1]);
        }
    }
}
ll solve(vector<ll> v,ll i,ll j)
{
    if(i==j){
        return 0;
    }
    if(dp[i][j]!=-1){
        return dp[i][j];
    }
    ll mincost=inf;
    for(ll k=i;k<j;k++){
        mincost=min(mincost,sum[i][j]+solve(v,i,k)+solve(v,k+1,j));
    }
    return dp[i][j]=mincost;
}
