vector <ll> merge(vector <ll> vec, ll min_idx){
    vector <ll> ret;
    REP(i, vec.size()){
        if (i != min_idx){
            ret.push_back(vec[i]);
        } else {
            ret.push_back(vec[i] + vec[i+1]);
            i++;
        }
    }
    return ret;
}

ll min_idx(vector <ll> vec){
    ll m = 1e18;
    ll ret;
    REP(i, vec.size()){
        if (m > vec[i]){
            ret = i;
            m = vec[i];
        }
    }
    return ret;
}


int main(void){
    ll n; cin >> n;
    vector <ll> as;
    REP(i, n){
        ll a; cin >> a;
        as.push_back(a);
    }
    ll ans = 0;
    REP(i, n-2){
        ll idx = min_idx(as);
        if ((idx > 0)){
            if ((idx == as.size()-1) or (as[idx+1] - as[idx-1] > 0)){
                idx--;
            }
        }
        ans += as[idx] + as[idx+1];
        as = merge(as, idx);
    }
    ans += as[0] + as[1];
    cout << ans << endl;
    return 0;
}

