template <typename T>
class RecursiveFunction {
    T t;

public:
    RecursiveFunction(T&& t) : t(forward<T>(t)) {}

    template <typename... Args>
    auto operator() (Args&&... args) const {
        return t(*this, forward<Args>(args)...);
    }
};


class NSlimes {
public:
    void solve() {
        int N = in.readInt();
        arri a = in.readIntArray(N);
        arr2d<ll> dp(N, N, 1e18);
        arr2d<bool> state(N, N, false);
        arr<ll> pref(N + 1, 0);
        for (int i : range(N)) {
            pref[i + 1] = pref[i] + a[i];
        }
        RecursiveFunction rec = [&] (auto const& self, int l, int r) -> ll {
            if (l >= r)
                return 0;
            if (state(l, r))
                return dp(l, r);
            state(l, r) = true;
            for (int i = l; i < r; i++) {
                minim(dp(l, r), self(l, i) + self(i + 1, r));
            }
            return dp(l, r) = dp(l, r) + pref[r + 1] - pref[l];
        };
        ll ans = rec(0, N - 1);
        out.printLine(ans);
    }
};


