int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int N, K;
    cin >> N >> K;

    vector<int> arr(N);
    for (int i = 0; i < N; i++) {
        cin >> arr[i];
    }

    vector<vector<int>> dp(K+1, vector<int>(N+1));
    for (int i = 0; i <= N; i++) {
        dp[0][i] = 1;
    }

    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= K; j++) {
            int res = dp[j-1][i];
            res = (res + dp[j][i-1]) % md;

            if (j > arr[i-1]) {
                res = (res - dp[j - 1 - arr[i-1]][i-1]);
                if (res < 0) res += md;
            }
            dp[j][i] = res;
        }
    }

    cout << dp[K][N] << "\n";
}

