ll calc(ll left, ll right){
    if(left == right){
        return 0;
    }
    if(dp.at(left).at(right) != -1){
        return dp.at(left).at(right);
    }

    ll ans = numeric_limits<ll>::max();
    for(ll x = left + 1; x <= right; ++x){
        ans = min(
            ans,
            cs.at(right + 1) - cs.at(left) + calc(left, x - 1) + calc(x, right)
        );
    }
    dp.at(left).at(right) = ans;
    return ans;
}

