/* EDPC N 2019/1/6
 * 区間DP
 *  N: 2~400
 *  a: 1~10^9
 * 2020.3.31 作成
 */
#include<iostream>
#include<vector>
#include<algorithm> // max
//#include<cmath>
using namespace std;

int n;
vector<long> a;
vector<vector<long>> asum;
vector<vector<long>> dp;

void init(){
  cin >> n;
  a.assign(n+1,0);
  for(int i=1; i<n+1; i++){
    cin >> a[i];
  }
  vector<long> t1(n+1, 0);
  dp.assign(n+1, t1);
  asum.assign(n+1, t1);
}

// 漸化式
// dp(L,R) = min{0<=i<=R-L-1}(
//    sum_j=0^i(a[L+j]) +
//    sum_j=0^(R-L+1-i)(a[R-j]) +
//    dp(L,L+i) + dp(L+i+1,R) )
// 全区間のsumは先にやっておくべき
void dodp(){
  // sum_a 計算
  for(int L=1;L<n+1;L++){
    for(int R=L;R<n+1;R++){
      for(int i=L;i<=R;i++){
        asum[L][R] += a[i];
      }
    }
  }
  // dp
  for(int m=2;m<n+1;m++){ // 区間サイズ
    for(int L=1;L+m-1<n+1;L++){ // 左
      long temp = asum[L][L] + asum[L+1][L+m-1] + dp[L][L] + dp[L+1][L+m-1];
      for(int i=1;i<m-1;i++){
        temp = min(temp, asum[L][L+i] + asum[L+i+1][L+m-1] + dp[L][L+i] + dp[L+i+1][L+m-1] );
      }
      dp[L][L+m-1] = temp;
      //cout << "db: (" << L << "," << (L+m-1) << ") " << temp << endl;
    }
  }
  return;
}

int main(){
  init();
  dodp();
  cout << dp[1][n] << endl;
  return 0;
}

