ll dp[N][N];

ll solve (int l, int r) {
	if (l == r)
		return 0;
	if (l == r-1)
		return pref[l] + suf[r];
	ll &ret = dp[l][r];
	if (ret != -1) return ret;
	return ret = min (solve (l+1, r) + pref[l+1],
					  solve (l, r-1) + suf[r-1]);
