vi a(401);


void preprocess(int n)
{
	sum[0] = a[0];
	for (int i = 1 ; i < n ; i++)
	{
		sum[i] = a[i] + sum[i - 1];
	}
}

void solve()
{
	int n; cin >> n;
	scan(a, n);
	// print(a, n);

	memset(sum, 0, sizeof sum);
	preprocess(n);

	for (int L = n - 1 ; L >= 0 ; L--)
	{
		for (int R = L ; R < n; R++)
		{
			if (L == R)dp[L][R] = 0;
			else
			{
				dp[L][R] = inf;
				int s = sum[R];
				if (L - 1 >= 0)s -= sum[L - 1];
				for (int i = L ; i < R ; i++)
				{
					dp[L][R] = min(dp[L][R] , s + dp[L][i] + dp[i + 1][R] );
				}
			}
		}
	}

	cout << dp[0][n - 1] << endl;
}

