long long int memo1[400][400];
long long int memo2[400][400];
bool computed[400][400];

long long int Search(int n, vector<long long int> a, int left, int right, long long int &syn)
{
	if (computed[left][right] == true) {
		syn = memo2[left][right];
		return memo1[left][right];
	}
	long long int min_value = 1000000000LL * 400 + 1;
	if (left == right) {
		min_value = 0;
		syn = a[left];
	}
	else {
		for (int i = left + 1; i <= right; ++i) {
			long long int syn1;
			long long int value1 = Search(n, a, left, i - 1, syn1);
			long long int syn2;
			long long int value2 = Search(n, a, i, right, syn2);
			long long int value = value1 + value2 + syn1 + syn2;
			if (min_value > value) {
				min_value = value;
				syn = syn1 + syn2;
			}
		}
	}
	//cout << left << " " << right << " " << min_value << " " << syn << endl;
	memo1[left][right] = min_value;
	memo2[left][right] = syn;
	computed[left][right] = true;
	return min_value;
}

