//入力値L番目からR番目までの和を返す
ll get(int L,int R)
{
    ll res = s_sum[R];
    if(L) res -= s_sum[L - 1];
    return res;
}

//メモ化再帰
ll memo[404][404];
bool vis[404][404]; //探索済みフラグ

//L番目からR番目までのコストの最小値
ll dp(int L,int R)
{
    if(L == R) return 0;
    else if(vis[L][R] == true) return memo[L][R];//探索済みならリターン
    vis[L][R] = true;//フラグを立てる  

    ll res = infl;//resは十分大きい
    for(int c = L; c < R; c++) res = min(res,dp(L,c) + dp(c+1,R) + get(L,R));//c番目で二つに区切る
    return memo[L][R] = res;//メモしながらリターン
}

