pair<ll, ll>solve(int l = 0, int r = n - 1) {
	if (r < l)return { 0,0 };
	if (r == l)return{ slime[l],0 };
	pair<ll, ll>& ans = res[l][r];
	if (~ans.first)return ans;
	ll x, y, mn = LLONG_MAX, curr;
	bool ok = 0;
	for (int i = l; i <= r; i++) {
		if (i == l) {
			if (solve(i + 1, r).second + solve(i + 1, r).first + slime[i] < mn) {
				mn = solve(i + 1, r).second + solve(i + 1, r).first + slime[i];
				curr = solve(i + 1, r).first + slime[i];
			}
			skip;
		}
		if (i == r) {
			if (solve(l, i - 1).second + solve(l, i - 1).first + slime[i] < mn) {
				mn = solve(l, i - 1).second + solve(l, i - 1).first + slime[i];
				curr = solve(l, i - 1).first + slime[i];
			}
			skip;
		}
		else {
			x = solve(l, i - 1).second, y = solve(i + 1, r).second;
			if (x > y)ok = 1;
			if (ok) {
				if ((solve(i + 1, r).second + solve(i + 1, r).first + slime[i]) * 2 + solve(l, i - 1).second + solve(l, i - 1).first < mn) {
					mn = (solve(i + 1, r).second + solve(i + 1, r).first + slime[i]) * 2 + solve(l, i - 1).second + solve(l, i - 1).first;
					curr = solve(l, i - 1).first + solve(i + 1, r).first + slime[i];
				}
			}
			else {
				if ((solve(l, i - 1).second + solve(l, i - 1).first + slime[i]) * 2 + solve(i + 1, r).second + solve(i + 1, r).first < mn) {
					mn = (solve(l, i - 1).second + solve(l, i - 1).first + slime[i]) * 2 + solve(i + 1, r).second + solve(i + 1, r).first;
					curr = solve(l, i - 1).first + solve(i + 1, r).first + slime[i];
				}
			}
		}
	}
	ans.first = curr, ans.second = mn;
	return ans;
}
