ll dp[405][405];
bool visited[405][405];

ll solve(int L, int R) {
  if(visited[L][R])
    return dp[L][R];
  visited[L][R] = true;

  if(L == R)
    return dp[L][R] = 0;

  ll best = LINF;
  FOR(i, L, R)
    best = min(best, solve(L, i) + solve(i+1, R) + sums[R+1] - sums[L]);
  return dp[L][R] = best;
}

