const int64_t INF = INT64_MAX;

const int MAXN = 410;
int N;
int64_t DIM[MAXN];
int64_t DP[MAXN][MAXN];
int64_t S[MAXN];

int main() {

	cin >> N;
	for (int i = 1; i <= N; i++) {
		cin >> DIM[i];
		S[i] = S[i - 1] + DIM[i];

	}
	for (int i = 1; i < N; i++) {
		DP[i][i + 1] = DIM[i] + DIM[i + 1];
	}

	for (int len = 2; len < N; len++) {
		for (int left = 1; left + len <= N; left++) {
			int right = left + len;

			int64_t mn = INF;

			for (int stop = left; stop < right; stop++) {
				int64_t cost = DP[left][stop] + DP[stop + 1][right] +
								(S[stop] - S[left - 1]) + (S[right] - S[stop]);
				mn = min(mn, cost);
			}
			DP[left][right] = mn;
		}
	}

	for (int i = 1; i <= N; i++) {
		for (int j = 1; j <= N; j++) {
			cout << DP[i][j] << " ";
		}
		cout << endl;
	}

	return 0;
