			x = solve(l, i - 1).second, y = solve(i + 1, r).second;
			if (x > y)ok = 1;
			if (ok) {
				if ((solve(i + 1, r).first + slime[i]) * 2 + solve(i + 1, r).second + solve(l, i - 1).second + solve(l, i - 1).first < mn) {
