ll A[500];
ll mem[500][500];

ll rsum(ll l, ll r) {
	ll sum = 0;
	for (int i=l; i<=r; i++)
		sum += A[i];
	return sum;
}

ll dp(ll l, ll r) {
	if (l > r) 
		return 0;

	if (l == r)
		return 0;

	if (mem[l][r] != -1)
		return mem[l][r];

	ll min_cost = (ll)1e13;

	min_cost = min(min_cost, A[l] + dp(l+1, r) + rsum(l+1, r) );
	min_cost = min(min_cost, A[r] + dp(l, r-1) + rsum(l, r-1) );

	for (ll i=l+1; i<r; i++) {
		ll a = rsum(l, i-1);
		ll b = rsum(i+1, r);
		min_cost = min(min_cost, dp(i+1, r) + dp(l, i-1) + (2*min(a, b) + 2*A[i] + max(a, b))); 
	}

	return mem[l][r] = min_cost;
}

