ll memo(int left, int right) {
    if (past[left][right]) return dp[left][right];
    if (left == right) {
        dp[left][right] = 0;
    } else {
        ll res = LL_INF;
        for (int i = left; i < right; i++) {
            chmin(res, memo(left, i) + memo(i + 1, right) + sum[right] - (left - 1 >= 0 ? sum[left - 1] : 0));
