ll backtrack(ll i , ll j, ll sum){
	ll bl = 1;
	ll ret1 = 0;
	ll ret2 = 0;
	ll mini = inf;
	for (ll k = 1; k <= j - 1; k++){
		if(dp[i][j] == dp[i][j - k] + dp[j-k+1][j]){
			if (i != j - k){
				ret1 = backtrack(i, j - k, sum + dp[i][j]);
				bl = 0;
			}
			if (j != j - k + 1){
				ret2 = backtrack(j, j - k + 1, sum + dp[i][j]);
				bl = 0;
			}
			mini = min(mini, ret1 + ret2);
		}
	}
	if (bl){
		return sum + dp[i][j];
	}
	else{
		return mini;
	}
}

