ll memo[405][405]={};

ll dp(int l,int r){
    if(memo[l][r]!=0) return memo[l][r];
    if(r-l==1){ 
        memo[l][r]=0;
        return 0;
        }
    ll ret=INF;
    for(int m=l+1;m<r;m++){ 
        ret=min(ret,dp(l,m)+dp(m,r));
    }
    ret+=bit.sum(l,r);
    memo[l][r] = ret;
    return ret;
}

