ll slime(int i, int j) {
	if (i == j) return 0;

	if (dp[i][j] != -1) return dp[i][j];

	ll min_cost = INF;
	for (int k = i; k + 1 <= j; k++)
		min_cost = min(min_cost, sum[i][j] + slime(i, k) + slime(k + 1, j));
	return dp[i][j] = min_cost;
}

