int main() {
    int N; cin >> N;
    vector<int> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];
    vector<ll> acc(N + 1, 0);
    for (int i = 0; i < N; i++) acc[i + 1] = acc[i] + a[i];
    vector<vector<ll>> dp(N, vector<ll>(N + 1, 0));
    for (int w = 2; w <= N; w++) {
        for (int i = 0; i + w <= N; i++) {
            ll tmp = INF;
            for (int sep = i + 1; sep < i + w; sep++) {
                tmp = min(tmp, dp[i][sep] + dp[sep][i + w]);
            }
            dp[i][i + w] = tmp + acc[i + w] - acc[i];
        }
    }
    cout << dp[0][N] << endl;
    return 0;
}

