  if (r - l == 1) {
    return pll(a[l], 0);
  }
  pll res(INF, INF);
  for (int m = l + 1; m < r; m++) {
    pll temp = calc(l, m) + calc(m, r);
    if (temp.second + temp.first < res.second) {
      res.first = temp.first;
      res.second = temp.second + temp.first;
    }
  }
  return res;
}

