void unoin(ll p, ll q,vi &roots,vi &rank){
  ll rp=root(p,roots);
  ll rq=root(q,roots);
  if(rank[rq]<rank[rp]){
    roots[rq]=rp;
  }
  else if(rank[rp]>rank[rq]){
    roots[rp]=rq;
  }
  else{
    roots[rp]=rq;
    rank[rq]++;
  }

}


