#define INF 9223372036854775807

int64_t rf(vector<vector<int64_t> > &dp, vector<vector<int64_t> > &w, int i, int j) {
    if (dp.at(i).at(j) != INF) {
        return dp.at(i).at(j);
    }
    if (j == i) {
        return 0;
    }
    for (int k = 0; k < j-i; k++) {
        dp.at(i).at(j) = min(dp.at(i).at(j), rf(dp, w, i, i+k) + rf(dp, w, i+1+k, j) + w.at(i).at(j));
    }
    return dp.at(i).at(j);
}

int main() {
    int n; cin >> n;
    vector<vector<int64_t> > dp(n, vector<int64_t>(n, INF));
    vector<vector<int64_t> > w(n, vector<int64_t>(n));
    for (int i = 0; i < n; i++) {
        cin >> w.at(i).at(i);
    }
    for (int i = 0; i < n-1; i++) {
        for (int j = i+1; j < n; j++) {
            w.at(i).at(j) = w.at(i).at(j-1) + w.at(j).at(j);
        }
    }
    cout << rf(dp, w, 0, n-1) << endl;
}

