        DisjointSet(HeapItem<V,K,compare> *it):size(1),par(nullptr),item(it),heap(nullptr){};
        DisjointSet* UFroot(){
            return par==nullptr?this:par=par->UFroot();
        }
        void unite(DisjointSet *ds){
            auto root_this = UFroot(); //DisjointSet*
            auto root_ds = ds->UFroot();
            if(root_this==root_ds) return;
            if(root_this->size < root_ds->size)swap(root_this,root_ds);
            root_ds->par = root_this;
            root_this->size += root_ds->size;
        }
    };

    HollowHeap():count_item(0),count_node(0),root(nullptr),rankmap(3){};
    bool empty(){return root==nullptr;}
