	vector<vector<int>> cache(n,vector<int>(n,-1));

	function<int(int,int)> subarraySum = [&](int l,int r) {
		return prefixSum[r]-(l?prefixSum[l-1]:0);
	};

	function<int(int,int)> dp = [&](int l,int r) {
		if(cache[l][r]!=-1) return cache[l][r];
		if(l==r) return cache[l][r]=0;
		int answer=1e12;
		for(int i=l;i<r;i++) {
			answer=min(answer,dp(l,i)+dp(i+1,r)+subarraySum(l,i)+subarraySum(i+1,r));
		}
		return cache[l][r]=answer;
	};

	cout<<dp(0,n-1);

	return 0;
}

