void solve(){
	//dp[j][j+i]:a[j]~a[j+i]についての最小値
	LL dp[402][402] = {0};
	LL tmp;
	LL sum;

	auto draw_dp_table = [&](int i,int j){
		printf("\nj=%d j+i=%d\n",j,j+i);
