			for(int j=0;j<N;j++){
				cout << dp[i][j] << " ";
			}
			cout << endl;
		}
	};

	for (int i=1;i<N;i++){
		//i（区間の長さ）を固定して
		//j（開始インデックス）を0~N-i-1まで動かしていく
	    for (int j=0;j<N-i;j++){
	    	//いま求めたいのはdp[j][j+i]
	        tmp = INF;
	        //j~j+iの区間の全部の和がsum
	        //これからj~k間とk+1~j+i間を統合するが、そのときのコストがsumなため
	        sum = 0;
	        for (int k=j;k<j+i;k++){
