long long dprec(long long l,long long r,long long change,vector<long long> changed){

    if(dp[l][r][change]){
        return dp[l][r][change];
    }
    if(l == r){

        return dp[l][r][change] = 0;
    }

    changed[l+1] += changed[l];
    dp[l][r][change] = changed[l+1] + dprec(l+1,r,0,changed);
    changed[l+1] -= changed[l];
    changed[r-1]+=changed[r];
    dp[l][r][change] = min(dp[l][r][change],changed[r-1]+dprec(l,r-1,1,changed));
    changed[r-1]-=changed[r];
   // cout<<l<<" "<<r<<" "<<dp[l][r][change]<<endl;
    return dp[l][r][change];
}
