	if (index >= n)
	{
		if(rem == 0)
			return 1;
		else return 0;
	}
	ll &res = memo[index][rem];
	bool exists = false;
	if (rem > 0 && ~memo[index][rem - 1]) {
		res = memo[index][rem - 1];
		exists = true;
	}
	else res = 0;
	int st = !exists ? 0 : rem;
	for (int i = st; i <= rem; i++)
	{
		ll p = recg(index + 1, i);
		if (p == 0) break;
		res += p;
		res %= INF;
	}

	if (rem - a[index] > 0) {
		ll sub = 0;
		if (~memo[index][rem - a[index] - 1]) {
			sub = memo[index][rem - a[index] - 1];
		}
		else {
			sub = recg(index, rem - a[index] - 1);
		}
		ll tmpval = (res + INF - sub) % INF;
		return tmpval;
	}
	return res;
}
