ll calculate(int n){
    int i,j,len;
    for (int len = 1; len < n; len++) {                   //s - length(size) of substring
        for (int l = 1; l+len <= n; l++) {              //l - left point

          int r = l + len;                            //r - right point

          if (len < 2) {
            dp[l][r] = a[r] - a[l-1];                          //DP base - nothing to break
            pi[l][r] = l;                          //pi is equal to left border
            continue;
          }

          int mleft = pi[l][r-1];                  //Knuth's trick: getting bounds on m
          int mright = pi[l+1][r];
          dp[l][r] = INF;

          for (int m = mleft; m<=mright; m++) {     //iterating for m in the bounds only
                ll temp = dp[l][m] + dp[m+1][r] + (a[r]-a[l-1]);
                if (dp[l][r] > temp) {                 //relax current solution
                  dp[l][r] = temp;
                  pi[l][r] = m;
                }
          }


        }
    }

    return dp[1][n];
}
