ll calc(ll a[],ll i,ll j,vector<vector<ll>> &sum,vector<vector<ll>> &dp)
{
    if(i==j)
        return 0;

    if(dp[i][j]!=-1)
        return dp[i][j];

    ll ans=INF;

    for(int k=i;k<j;k++)
    {
        ans=min(ans,sum[i][j]+calc(a,i,k,sum,dp)+calc(a,k+1,j,sum,dp));
    }

    return dp[i][j]=ans;
}

void solve()
{
	ll n,i,j,k,c;
	cin>>n;

	ll a[n+1];

	for(i=1;i<=n;i++)
        cin>>a[i];

    vector<vector<ll>> dp(n+1,vector<ll>(n+1,-1));
    vector<vector<ll>> sum(n+1,vector<ll>(n+1));

    for(i=1;i<=n;i++)
    {
        for(j=i;j<=n;j++)
        {
            if(i==j)
                sum[i][j]=a[j];
            else
                sum[i][j]=sum[i][j-1]+a[j];
        }
    }

    cout<<calc(a,1,n,sum,dp)<<endl;
}

