long long int solve(int l, int r)
{
	if(result[l][r] > 0) return result[l][r];
	if(r - l == 1) return 0;
	result[l][r] = (long long int)mod * mod;
	long long int cost = suma[r] - suma[l];
	for(int i = l + 1; i < r; i++){
		result[l][r] = min(result[l][r], cost + solve(l, i) + solve(i, r));
	}
	return result[l][r];
}

