int prefix_sum(int i, int j)
{
	if (i == 0)
		return prefs[j];
	return
	    prefs[j] - prefs[i - 1];
}

int solve(int i, int j)
{
	if (i >= j)
		return 0;

	if (dp[i][j] != -1)
		return dp[i][j];

	dp[i][j] = LLONG_MAX;

	for (int k = i; k <= j; k++)
	{
		dp[i][j] = min(dp[i][j], solve(i, k) + solve(k + 1, j) + prefix_sum(i, k) + prefix_sum(k + 1, j));
	}

	return dp[i][j];
}

