using namespace std;

vector<ll> v;
vector<ll> pref;
vector<vector<ll>> dp;

ll get(int l, int r)
{
	if (l == r) return v[l];

	if (dp[l][r] == -1)
	{
		for (int i = l; i < r; ++i)
		{
			if (dp[l][r] == -1 || dp[l][r] > get(l, i) + get(i + 1, r))
				dp[l][r] = get(l, i) + get(i + 1, r);
		}

		dp[l][r] += pref[r];
		if (l) dp[l][r] -= pref[l - 1];
	}

	return dp[l][r];
}

void solve()
{
	int n; cin >> n;
	v.resize(n);
	for (int i = 0; i < n; ++i)
		cin >> v[i];
	pref = v;
	for (int i = 1; i < n; ++i)
		pref[i] += pref[i - 1];

	dp.resize(n, vector<ll>(n, -1));

	cout << get(0, n - 1) - pref.back();
}

