using namespace std;

vector<ll> V;
vector<vector<ll>> DP;
vector<ll> P;

int getSum(int start, int end){
    return P[end + 1] - P[start];
}

ll solve(int start, int end){
    ll& dp= DP[start][end];

    if (dp != -1){
        return dp;
    }

    int length = end - start + 1;

    if (length == 2){
        return (dp = (V[start] + V[end]));
    }

    ll ans1 = V[start] + solve(start + 1, end) + getSum(start + 1, end);
    ll ans2 = V[end] + solve(start, end - 1) + getSum(start, end - 1);
    ll ans = min(ans1, ans2);
    for (int i = start + 1; i < (end - 1); i++){
        ll tmp = solve(start, i) + solve(i + 1, end);
        tmp += getSum(start, i) + getSum(i + 1, end);
        ans = min(tmp, ans);
    }
    return dp = ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;
    V = vector<ll>(n);
    DP = vector<vector<ll>>(n, vector<ll>(n, -1));
    P = vector<ll>(n + 1);
    for (auto &v : V) cin >> v;

    for (int i = 1; i <= n; i++){
        P[i] = P[i - 1] + V[i -1];
    }

    ll ans = solve(0, n - 1);
    cout << ans;
    return 0;
}

