ll solve(vector<ll> val){
    if(val.size() == 1) return 0;
    int idx = -1;
    ll cur = 1e18;
    for(int x=0;x<(int) val.size()-1; x++){
        if(val[x] + val[x+1] < cur){
            cur = val[x] + val[x+1];
            idx = x;
        }
    }
    vector<ll> nex;

    for(int x=0;x<(int) val.size(); x++){
        if(x == idx){
            nex.push_back(cur);
            x++;
            continue;
        }
        nex.push_back(val[x]);
    }
    return cur + solve(nex);
}
