int solve(long long l, long long r, vector<long long> &v, vector<long long> &s, vector<vector<long long>> &dp){
	if(l == r)
		return 0;

	if(dp[l][r])
		return dp[l][r];

	long long n = v.size();
	long long res = INT_MAX;
	for(long long i{l}; i < r; ++i){
		res = min(res, solve(l, i, v, s, dp) + solve(i + 1, r, v, s, dp)
							+ s[r + 1] - s[l]);
	}
	return dp[l][r] = res;
}
