pair<long long,long long> dp_func(long long arr[], int i, int j)
{

    if(i==j)
        return {0ll,(long long)arr[i]};

    if(dp[i][j].F!=INF)
        return dp[i][j];

    pair<long long,long long> ans={INF, INF};

    for(int it=i;it<j;it++)
    {
        pair<long long,long long>x = dp_func(arr, i,it);
        pair<long long,long long>y = dp_func(arr,it+1,j);
        if(x.F+y.F+x.S+y.S<=ans.F)
            ans={x.F+y.F+x.S+y.S, x.S+y.S};
    }
    return dp[i][j]=ans;

}

