ll dp[401][401];
ll pref[401];

ll solve(int L,int R){
  if(dp[L][R]!=-1)return dp[L][R];
  else if(L==R)return dp[L][R] = 0;
  ll res = inf,cres;
  for(int i=0;i<R-L;i++){
    cres = solve(L,L+i) + solve(L+i+1,R) + pref[R];
    cres -= (L-1<0 ? 0 : pref[L-1]);
    res = min(res,cres);
  }
  return dp[L][R] = res;
}

