long long split_slime(int l, int r) {
	if (l + 1 == r) return 0;
	pair<int,int> p = make_pair(l, r);
	if (memo.find(p) != memo.end()) return memo[p];
	long long mn = (1LL << 60);
	reps(i,l+1,r) mn = min(mn, (d[i] - d[l]) + (d[r] - d[i]) + split_slime(l, i) + split_slime(i, r));
	return memo[p] = mn;
}

