ll minCost(vi& slimes){
    minHeap hp;
    ll ans = 0;
    for(auto slime:slimes)
        hp.push(slime);
    while(hp.size()!=1){
        ll top1 = hp.top();
        hp.pop();
        ll top2 = hp.top();
        hp.pop();
        ll total = top1 + top2 ;
        // cout << top1 << ' ' << top2 << ' ' << total << endl;
        ans += total;
        hp.push(total);
    }
    return ans;
}

