int get(int l, int r) {
    if (used[l][r]) {
        return table[l][r];
    }
    used[l][r] = 1;
    if (l == r) {
        table[l][r] = 0;
        return table[l][r];
    }
    for (int i = l;i <= r - 1;i++) {
        chkmin(table[l][r], sum[l][i] + sum[i + 1][r] + get(l, i) + get(i + 1, r));
    }
    return table[l][r];
}

