LL dfs(const int i, const int j)
{
    if (i == j)
        return 0;
    LL& ans = dp[i][j];
    if (-1 == ans) {
        ans = inf;
        FOR(k,i+1,j+1) {
            const LL res = dfs(i,k-1) + dfs(k,j) + sum[j]-sum[i-1];
            ans = min(ans,res);
        }
    }
    return ans;
}

