ll memo[405][405];
ll solve(int left, int right, int dpleft, int dpright){
    if(left == right)
        return 0;
    if(left > right)
        return 99999999;
    ll &ans = memo[dpleft][dpright];
    if(ans != -1)
        return ans;
    pair<ll, int> first, second;
    first = a[left], second = a[left+1];
    a[left+1].f = first.f+second.f;
    ans = a[left+1].f+solve(left+1, right, a[left+1].s, a[right].s);
    a[left+1].f = second.f;
    first = a[right], second = a[right-1];
    a[right-1].f = first.f+second.f;
    ans = min(a[right-1].f+solve(left, right-1, a[left].s, a[right-1].s), ans);
    a[right-1].f = second.f;
    return ans;
}
