ll Mixtures(int *arr,int i,int j){
	if(i>j)
	return 0;
	if(dp[i][j]!=-1)
	return dp[i][j];
	ll ans=INT_MAX;
	for(int k=i;k<j;k++){
		ans=min(ans,Mixtures(arr,i,k)+Mixtures(arr,k+1,j)+left(arr,i,k)+right(arr,k+1,j));
	}
	if(ans!=INT_MAX){
