const int N = 1e5 + 10;
int n, m;
vector<int> g[N];
vector<int> dp[N];

int mul(int a, int b)
{
    return ((ll)a * b) % m;
}

int solve(int node, int parent)
{
    int idx;
    if(parent == -1)
        idx = dp[node].size() - 1;
    else
    {
        int st = 0, en = g[node].size() - 1;
        while(st <= en)
        {
            int mid = (st + en) / 2;
            if(g[node][mid] <= parent)
                idx = mid, st = mid + 1;
            else
                en = mid - 1;
        }
    }
    int &ret = dp[node][idx];
    if(ret != -1)
        return ret;
    ret = 1;
    for(auto &x: g[node])
    {
        if(x == parent)
            continue;
        ret = mul(ret, solve(x, node));
    }
    return ret = (ret + 1) % m;
}

