LL MCM( int l , int r ) {
        if( l >= r ) return 0;
        if( dp[l][r] != -1 ) return dp[l][r];
        LL ret = INF;
        for( int i = l; i < r; i++ ) {
                int temp = getsum( l , i ) + getsum( i + 1 , r );
                ret = min( ret , MCM( l , i ) + MCM( i + 1 , r ) + temp );
        }
        return dp[l][r] = ret;
}
