P<ll,ll> dp(int l, int r){
  static ll mm[401][401];
  static ll sum[401][401];
  static bool used[401][401];
  static const ll inf = (1e+9)*410;


  if(l == r) return {0,v[l]};

  if(used[l][r]) return {mm[l][r],sum[l][r]};
  else used[l][r] = true;

  mm[l][r] = inf;
  sum[l][r] = v[r];

  for(int i = l; i < r; ++i){
    ChangeMin(mm[l][r], dp(l,i) + dp(i+1,r));
    sum[l][r] += v[i];
  }

  return {mm[l][r],sum[l][r]};
}

