ll minimum_cost_merge(const vector<int>& a) {
    int n = a.size();
    vector<vector<ll>> dp(n, vector<ll>(n));
    vector<ll> pref_sum(n+1);
    for (int i = 0; i < n; ++i) {
        pref_sum[i+1] = pref_sum[i] + a[i];
    }
    const ll INF = 1e18;
    for (int d = 2; d <= n; ++d) {
        for (int i = 0; i+d-1 < n; ++i) {
            int j = i+d-1;
            dp[i][j] = INF;
            for (int k = i; k < j; ++k) {
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j] + pref_sum[j+1] - pref_sum[i]);
            }
        }
    }
    return dp[0][n-1];
}
