int recursion(int debut , int fin)
{
	if (poids[debut][fin] != -1)
	{
		return poids[debut][fin];
	}
	if (debut == fin)
	{
		return 0;
	}
	poids[debut][fin] = 1e18;
	for (int coupe = debut ; coupe < fin ; coupe++)
	{
		poids[debut][fin] = min(poids[debut][fin] , 
								recursion(debut , coupe) + recursion(coupe + 1 , fin) + cumul[fin + 1] - cumul[debut]);
	}
	return poids[debut][fin];
}
