int DFS(int L,int R,vector<vector<int> > & DP,vector<vector<int> > & flag,vector<int> &vec)
{
  if(L == R)return 0;
  if(flag[L][R]) return DP[L][R];
  flag[L][R] = 1;
  int res = INF;
  for (int i = L; i < R; i++)
  {
    res = min(res,DFS(L,i,DP,flag,vec) + DFS(i+1,R,DP,flag,vec));
  }
  res += vec[R];
  if(L>0)res -=vec[L-1];
  return DP[L][R] = res;

}

