const llong INF = 1e18 + 1e9 + 1;
llong memo[MAXN][MAXN];
// go(L, R): min cost of merging slimes from L to R into a single slime
llong go(int L, int R) {
   if (L == R)
      return 0;
   llong& res = memo[L][R];
   if (res < 0) {
      res = INF;
      FOR(j, L+1, R) {
         // split between j-1 and j
         llong cur = go(L, j-1) + go(j, R) + sum(L, j-1) + sum(j, R);

         res = min(res, cur);
      }
   }
   return res;
}

