long long dfs(vector<vector<long long>> &dp, const vector<long long> &a, const vector<long long> &sum, int begin, int end, const long long init)
{
    if (dp[begin][end] == init)
    {
        if (end - begin > 1)
        {
            for (int i = begin + 1; i < end; i++)
            {
                dp[begin][end] = min(
                    dp[begin][end],
                    dfs(dp, a, sum, begin, i, init) + dfs(dp, a, sum, i, end, init) + (sum[end] - sum[begin]));
            }
        }
        else
        {
            dp[begin][end] = 0;
        }
    }
    return dp[begin][end];
}

