ll memo[401][401];
int n,arr[401];
ll solve(int l,int r){
    if(l>=r) {
        return 0;
    }
    ll &cur=memo[l][r];
    if(cur!=-1)
        return cur;
    cur=1e16;
    ll sum=0;
    for(int i=l;i<=r;i++)
        sum+=arr[i];
    for(int i=l;i<=r;i++){
        cur=min(cur,solve(l,i)+solve(i+1,r)+sum);
    }
    return cur;
}
