int bottom_up(vector<int> &a) {
    memset(dp, -1, sizeof(dp));
    auto sum = [&](int i, int j) {
        int sum = 0;
        for(int k = i; k <= j; ++k) sum += a[k];
        return sum;
    };
    int n = (int)a.size();
    for(int i = n - 1; i >= 0; --i) {
        for(int j = 0; j < n; ++j) {
            if(i == j) dp[i][j] = 0;
            else {
                int s = sum(i, j);
                dp[i][j] = INF;
                for(int k = i; k < j; ++k) {
                    dp[i][j] = min(dp[i][j],
                                dp[i][k] + dp[k+1][j] + s
                            );
                }
            }
        }
    }

    return dp[0][n-1];
}

