#define INF 0x3f3f3f3f3f3f3f3f
#define amount first
#define cost second
#define pll pair<ll, ll>

int N;
ll vals[MAXN];
int vis[MAXN][MAXN];
pll dp[MAXN][MAXN];

pll solve(int l, int r)
{
	if (l > r)
	{
		return {0, 0};
	}

	if (r == l)
	{
		return {vals[r], 0};
	}

	if (vis[l][r])
	{
		return dp[l][r];
	}
	vis[l][r] = 1;

	pll res = {INF, INF};

	for (int i = l; i <= r; i++)
	{
		pll right = {0, 0};
		pll left = {0, 0};

		ll new_cost = 0;

		if (i > l)
		{
			left = solve(l, i - 1);
			new_cost += vals[i];
		}
		if (i < r)
		{
			right = solve(i + 1, r);
			new_cost += vals[i];
		}

		new_cost += left.cost + right.cost 
					  + 2 * min(left.amount, right.amount)
					  + max(left.amount, right.amount);

		if (new_cost < res.cost)
		{
			res.cost = new_cost;
			res.amount = left.amount + right.amount + vals[i];
		}

	}

	dp[l][r] = res;
	return res;
}

