ll slime(int x, int y) {
	if (dp[x][y]) return dp[x][y];
	if (x == y) return 0;
	if (x + 1 == y) return dp[x][y] = a[x] + a[y];

	ll mmin = min(slime(x + 1, y), slime(x, y - 1));
