constexpr int INF = (1 << 30);
constexpr ll INFL = (1ll << 60);
constexpr ll MOD = 1000000007;// 10^9+7

int N;
vector<ll> a, imos;
vector<vector<ll>> dp;

// find cost [l,r)
ll solve(int l, int r)
{
	if(dp[l][r] != INFL)return dp[l][r];
	if(l + 1 == r)return dp[l][r] = 0;

	ll res = INFL;
	FOR(k, l + 1, r)
	{
		ll tmp = solve(l, k) + solve(k, r) + (imos[r - 1] - (l == 0 ? 0 : imos[l - 1]));
		res = min(res, tmp);
	}
	return dp[l][r] = res;
}

//メイン関数
