{
	// input
	cin >> N;
	a.resize(N);
	dp.resize(N + 1, vector<ll>(N + 1, INFL));
	REP(i, N)cin >> a[i];
	imos = a;
	REP(i, N - 1)imos[i + 1] += imos[i];

	cout << solve(0, N) << endl;
	cin >> N;
	return 0;
}

