int N;
long long a[405];       // 累積和
long long dp[405][405];
bool flag[405][405];

long long rec(int l, int r) {
    if (l == r) return 0;
    if (flag[l][r]) return dp[l][r];
    flag[l][r] = true;

    long long res = INF;
    for (int i = l; i < r; i++) {
        res = min(res, rec(l, i) + rec(i+1, r));
    }
    long long sum = a[r] - (l ? a[l-1] : 0);
    res += sum;

    return dp[l][r] = res;    
}

