long long int dp[MAX_N + 1][MAX_N + 1];

long long int dfs(int l, int r)
{
    if (dp[l][r])
    {
        return dp[l][r];
    }
    long long int cost = INF;
    long long int sum = 0;
    for (int i = l; i <= r; i++)
    {
        sum += a[i];
    }
    for (int i = l; i <= r; i++)
    {
        cost = min(cost, dfs(l, i) + dfs(i + 1, r));
    }
    dp[l][r] = cost + sum;
    return dp[l][r];
}

