#include <bits/stdc++.h>
#define int long long
using namespace std;

const int N = 410, inf = 1e18;
int n, a[N], dp[N][N], pref[N];
bool visited[N][N];

int solve(int l, int r) {
	if (visited[l][r])
		return dp[l][r];
	visited[l][r] = true;
	if (l == r)
		return dp[l][r] = 0;
	dp[l][r] = inf;
	for (int i = l; i <= r; i++)
		dp[l][r] = min(dp[l][r], solve(l, i) + solve(i + 1, r));
	return dp[l][r] = dp[l][r] + pref[r] - pref[l - 1];
}

signed main() {
	ios_base::sync_with_stdio(false);

	cin >> n;
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
		pref[i] = pref[i - 1] + a[i];
	}
	memset(visited, false, sizeof(visited));
	int ans = solve(1, n);
	cout << ans;

	return 0;
}

