const ll INF = 1e18 + 5;
int main() { 
	int n;
	cin >> n;
	vector<ll> arr(n,0);
	for(int i = 0; i < n; ++i){
		cin >> arr[i];
	}
	vector<vector<pair<ll,ll>>> dp(n, vector<pair<ll,ll>> (n,{INF,(ll)-1}));

	for(int i = n-1; i >= 0; i--){
		for(int j = i; j < n; ++j){
			if(i == j){
				dp[i][j] = {0,arr[i]};
				continue;
			}
			for(int k = i; k < j; ++k){
				ll temp = dp[i][k].first + dp[i][k].second + dp[k+1][j].first + dp[k+1][j].second;
				if(dp[i][j].first > temp){
					dp[i][j] =  {temp,dp[i][k].second + dp[k+1][j].second};
				}
			}
		}
	}
	cout << dp[0][n-1].first<<endl;

}

