    std::ifstream in("/home/share/inputf.in");
    std::cin.rdbuf(in.rdbuf());
    #endif
    const int MAX_N = 400;
    const int64_t INF = 1e16;
    int N;
    cin >> N;
    // O(N^2)
    // (n, i) => cost
    // 左からi番目のスライムからn+1個が合体するときのコストとサイズ
    vector<int64_t> cost[MAX_N + 1];
    vector<int64_t> size[MAX_N + 1];
    for(int i = 1; i <= N; i++) {
        cost[i] = vector<int64_t>(N + 1 - i);
        size[i] = vector<int64_t>(N + 1 - i);
        for(int j = 0; j <= N - i; j++) {
            cost[i][j] = INF;
            size[i][j] = 0;
        }
    }
    for(int i = 0; i < N; i++) {
        cin >> size[1][i];
        cost[1][i] = 0;
    }
    for(int n = 2; n <= N; n++) {
        for(int i = 0; i <= N - n; i++) {
            for(int m = 1; m < n; m++) {
                size[n][i] = size[1][i] + size[n - 1][i + 1];
                cost[n][i] = min(cost[n][i], cost[m][i] + cost[n - m][i + m] + size[n][i]);
            }
        }
    }
    cout << cost[N][0] << endl;
    return 0;
}

