		return dp[i][j];

	//recursive
	ll minCost = INT_MAX;//store the minm value
	for (int k = i; k < j; k++)
	{
		minCost = min(minCost, sum[i][j] + solve(v, i, k) + solve(v,  k + 1, j));
	}

	return dp[i][j] = minCost;
}

void preprocess(vector<int>& v, int n)
{
	for (int i = 1; i <= n; i++ )
	{
		for (int j = i; j <= n; j++)
		{
			sum[i][j] = v[j] + ((j == i) ? 0 : sum[i][j - 1]);
		}
	}
}

