        dp[inicio][fim] = min (dp[inicio][fim], dp[inicio][j] + dp[j + 1][fim] + prefix [fim + 1] - prefix[inicio]);
      }
    } 
  }
  cout << dp[0][n - 1] << '\n';
  return 0;
}

