using namespace std;
typedef long long ll;



ll solve(int i, int j, vector <vector<ll>> &dp, vector<int> &a, vector<ll> &sum) {
  if (dp[i][j] != -1) {
    return dp[i][j];
  }
  if (i == j) {
    return dp[i][j] = 0;
  }
  ll cost = 1e15;
  for (int k = i; k < j; k++) {
    cost = min(cost, solve(i, k, dp, a, sum) + solve(k+1, j, dp, a, sum));
  }
  dp[i][j] = cost + sum[j+1] - sum[i];
  return dp[i][j];
}

