int cost(int i, int j) {
	if (j - i == 1) return 0;
	if (dp[i][j]) return dp[i][j];
	int mincost = INT64_MAX;
	for (int k = i + 1; k < j; k++)
		mincost = min(mincost, cost(i, k) + cost(k, j));
	return dp[i][j] = ca[j - 1] - ca[i - 1] + mincost;
}

