    SegmentTree tree(a);
    for(ll term = 2; term <= N; ++term){
        rep(i, N - term + 1){
            rep(j, term - 1){
                chmin(dp[i][i + term], dp[i][i + j + 1] + dp[i + j + 1][i + term] + tree.query(i, i + term));
            }
        }
    }
    pt(dp[0][N]);
}

