int solve(int L , int R) {
    if(L == R) return dp[L][R] = a[R]-a[L-1];
    else if(dp[L][R] != -1) return dp[L][R];
    else {
        dp[L][R] = INT64_MAX;
        int cost = a[R]-a[L-1];
        for(int k = L; k < R; k++) dp[L][R] = min(dp[L][R] , cost + solve(L,k) + solve(k+1 , R));
        return dp[L][R];
    } 
}

