struct Treap {
  long long value;
  long long priority;
  Treap* left;
  Treap* right;
  long long max;
  int size;
};

Treap* const emptyTreap = new Treap {
  0, LONG_LONG_MIN, NULL, NULL, 0, 0
};

int size(Treap* root) {
  return root->size;
}

long long getKth(Treap* root, int k) {
  assert(0 <= k && k < root->size);
  if (k < root->left->size)
    return getKth(root->left, k);
  else if (k == root->left->size)
    return root->value;
  else
    return getKth(root->right, k - root->left->size - 1);
}

Treap* recompute(Treap* newLeft, Treap* root, Treap* newRight) {
  root->left = newLeft;
  root->right = newRight;
  root->max = std::max({root->left->max, root->value, root->right->max});
  root->size = root->left->size + 1 + root->right->size;
  return root;
}

Treap* popLast(Treap* root) {
  if (root->right != emptyTreap)
    return recompute(root->left, root, popLast(root->right));
  else
    return root->left;
}

std::pair<Treap*, Treap*> split(Treap* root, long long value) {
  std::pair<Treap*, Treap*> answer;
  if (root == emptyTreap) {
    answer.first = emptyTreap;
    answer.second = emptyTreap;
  } else if (std::max(root->value, root->right->max) < value) {
    auto p = split(root->left, value);
    answer.first = p.first;
    answer.second = recompute(p.second, root, root->right);
  } else {
    auto p = split(root->right, value);
    answer.first = recompute(root->left, root, p.first);
    answer.second = p.second;
  }
  return answer;
}

Treap* newTreap(long long value) {
  long long priority =
      (long long)rand() << 48
    | (long long)rand() << 32
    | (long long)rand() << 16
    | (long long)rand() <<  0;
  if (priority == LONG_LONG_MIN)
    priority++;
  return new Treap {
    value, priority, emptyTreap, emptyTreap, value, 1
  };
}

Treap* join(Treap* first, Treap* second) {
  if (first == emptyTreap)
    return second;
  else if (second == emptyTreap)
    return first;
  else if (first->priority < second->priority)
    return recompute(join(first, second->left), second, second->right);
  else
    return recompute(first->left, first, join(first->right, second));
}

void dump(Treap* root, int offset = 0) {
  assert(root != NULL);
  if (root != emptyTreap) {
    dump(root->left, offset + 1);
    for (int i = 0; i < offset; i++)
      printf("  ");
    printf("%lld\t%5lld%5d%20lld\n",
      root->value, root->max, root->size, root->priority);
    dump(root->right, offset + 1);
  }
}

long long answer;

Treap* compressLast2(Treap* root) {
  long long sum = getKth(root, size(root) - 1);
  root = popLast(root);
  sum += getKth(root, size(root) - 1);
  root = popLast(root);
  auto p = split(root, sum);
  root = join(join(p.first, newTreap(sum)), p.second);
  //dump(root);
  answer += sum;
  //printf("+%lld\n", sum);
  return root;
}

int main() {
