  scanf("%d", &n);
  long long a[n];
  for (long long &ai : a)
    scanf("%lld", &ai);

  answer = 0;
  Treap* root = emptyTreap;
  for (long long ai : a) {
    while (size(root) >= 2
      && getKth(root, size(root) - 2) <= ai)
      root = compressLast2(root);
    root = join(root, newTreap(ai));
    //dump(root);
    //printf("\n");
  }
  while (size(root) >= 2)
    root = compressLast2(root);

  printf("%lld\n", answer);
  return 0;
}

