	if(l == r) return {0, a[l]};
	if(l > r) return {0, 0};
	auto &ret = dp[l][r];
	if(ret.first != -1) return ret;
	auto left2 = solve(l+2, r);
	left2.second += a[l] + a[l+1];
	left2.first += a[l] + a[l+1] + left2.second;
	auto left = solve(l+1, r);
	left.second += a[l];
	left.first += left.second;
	auto right = solve(l, r-1);
	right.second += a[r];
	right.first += right.second;
	auto right2 = solve(l, r-2);
	right2.second += a[r-1] + a[r];
	right2.first += right2.second + a[r-1] + a[r];

	vector<pair<LL,LL>> temp;
	temp.push_back(left2);
	temp.push_back(left);
	temp.push_back(right);
	temp.push_back(right2);
	sort(temp.begin(), temp.end());
	ret = temp[0];
	return ret;
}

