ll getSum(int start, int end){
    return P[end + 1] - P[start];
}

ll solve(int start, int end){
    ll& dp= DP[start][end];

    if (dp != -1){
        return dp;
    }

    int length = end - start + 1;
    if (length == 1){
        return dp = 0;
    }
    if (length == 2){
        return (dp = (V[start] + V[end]));
    }

    ll ans = INT64_MAX;
    for (int i = start; i < end; i++){
        ll tmp = solve(start, i) + solve(i + 1, end);
        ans = min(tmp, ans);
    }
    return dp = ans + getSum(start, end);
}

