      dp[a][b]=0;
      return 0;
   }
   int temp;
      for(int k=a;k<b;++k)
      {
         temp=HarryMatMul(val,a,k)+HarryMatMul(val,k+1,b)
         +Sum(val,a,k)+Sum(val,k+1,b);

         if(dp[a][b]==-1||temp<dp[a][b])
            dp[a][b]=temp;
      }
      //for(int i=--0;i<)
      return dp[a][b];
}
