// [i, j) における最適値
LL dp[402][402];
LL cum[402];
bool flg[402][402];

LL rec(int l, int r)
{
    if (abs(l - r) == 1 or flg[l][r])
        return dp[l][r];

    flg[l][r] = true;

    LL ans = LLINF;
    for (int i = l + 1; i < r; i++)
    {
        ans = min(ans, rec(l, i) + rec(i, r));
    }
    ans += cum[r - 1] - cum[l - 1];
    return dp[l][r] = ans;
}

void solve()
{
    int N;
    cin >> N;
    REP0 (i, N)
    {
        cin >> cum[i];
        if (i)
            cum[i] += cum[i - 1];
    }

    cout << rec(0, N) << endl;
}

