long long dp(int m,int n)
{
    //メモ済み
    if(fmin[m][n] != INT_MAX) return fmin[m][n];
    //メモしていない
    else {
        //if(n - m == 1) return fmin[m][n] = p[m] + p[n];
        if(m == n) return fmin[m][n] = 0;
        else{
            long long t = INT_MAX;
            //fmin[m][n] = 0;
            for(int v = m; v < n; v++){
                fmin[m][n] = min(dp(m,v) + dp(v + 1,n) + All[m][n],t);
                t = fmin[m][n];
            }

            return fmin[m][n];
        }
    }
}

