template<typename T>
vector<vector<T>> Make2DVector(int d1, int d2, T default_value) {
  return vector<vector<T>>(d1, vector<T>(d2, default_value));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<int64> xs(n);
  for (int i = 0; i < n; i++) cin >> xs[i];

  vector<vector<int64>> dp1 = Make2DVector(n + 1, n + 1, -1LL);
  vector<vector<int64>> dp2 = Make2DVector(n + 1, n + 1, -1LL);
  function<void(int , int)> solve = [&](int l, int r) {
    if (r - l == 1) {
      dp1[l][r] = 0;
      dp2[l][r] = xs[l];
      return;
    }
    for (int m = l + 1; m <= r - 1; m++) {
      solve(l, m);
      solve(m, r);
      if (dp2[l][r] < 0) {
        dp2[l][r] = dp2[l][m] + dp2[m][r];
      }
      if (dp1[l][r] < 0) {
        dp1[l][r] = dp1[l][m] + dp1[m][r] + dp2[l][r];
      } else {
        dp1[l][r] = min(dp1[l][r], dp1[l][m] + dp1[m][r] + dp2[l][r]);
      }
    }
  };
  solve(0, n);
  cout << dp1[0][n] << endl;
}

