int main(){

  // read problem
  long long int N;
  long long int tmp;
  std::vector<long long int> a, a_accum;

  scanf("%lld", &N);

  for(long long int i = 0; i < N; i++){
    scanf("%lld", &tmp);
    a.push_back(tmp);
  }
  a_accum.push_back(a[0]);
  for(long long int i = 1; i < N; i++){
    a_accum.push_back(a_accum[i-1]+a[i]);
  }

  std::cerr << "a:" << std::endl;
  for(long long int i = 0; i < N; i++){
    std::cerr << a[i] << " ";
  }std::cerr << std::endl;

  std::cerr << "a_accum:" << std::endl;
  for(long long int i = 0; i < N; i++){
    std::cerr << a_accum[i] << " ";
  }std::cerr << std::endl;

  // solve problem
  std::vector<std::vector<long long int> > dp_table(N);
  for(long long int i = 0; i < N; i++){
    for(long long int j = 0; j < N; j++){
      dp_table[i].push_back(0);
    }
  }

  for(long long int l = 1; l < N; l++){
    for(long long int i = 0; i < N-l; i++){
      tmp = dp_table[i][i] + dp_table[i+1][i+l];
      for(long long int j = i+1; j < i+l; j++){
        tmp = std::min(tmp, dp_table[i][j] + dp_table[j+1][i+l]);
      }
      tmp += section_sum(a_accum, i, i+l);
      dp_table[i][i+l] = tmp;
    }
  }

  std::cerr << "Answer:" << std::endl;
  std::cout << dp_table[0][N-1] << std::endl;

  return 0;
}

long long int section_sum(std::vector<long long int> accumulated_sum, long long int i, long long int j){
  if(i == 0){
    return accumulated_sum[j];
  }
  else{
    return accumulated_sum[j] - accumulated_sum[i-1];
  }
}

