const ll LINF = 2e18;
const int INF = 1e9;

ll N;
std::vector<ll> a;
vector<ll> acc;
vector<vector<ll>> dp;

ll f(ll l, ll r) {
  if (dp.at(l).at(r) != -1) return dp.at(l).at(r);
  if (l == r) return dp.at(l).at(r) = 0;

  ll ret = LINF;
  FOR(m, l, r) ret = min(ret, f(l, m) + f(m + 1, r));
  ll c = acc.at(r + 1) - acc.at(l);
  return dp.at(l).at(r) = ret + c;
}

void solve() {
  acc.resize(N + 1, 0);
  dp.resize(N + 1, vector<ll>(N + 1, -1));

  rep(i, N) { acc.at(i + 1) += acc.at(i) + a.at(i); }

  cout << f(0, N - 1) << endl;
}

