ll solve(vector<ll> &A) {



	ll sum1[1000000] = {0};
	for (ll i = 0; i < n; i++)
	{
		sum1[i] += ((i > 0) ? sum1[i - 1] : 0) + A[i];

	}


	for (ll d = 1; d < n; d++) {
		ll i = 0, j = d;
		while (j < n) {
			ll ans = INT_MAX;
			for (ll k = i; k < j; k++) {
				ans = min ( ans, dp[i][k] + dp[k + 1][j] + sum1[j] - ((i > 0) ? sum1[i - 1] : 0 ));
