lli go(int x,int y){
	if(dp[x][y]!=-1){
		return dp[x][y];
	}
	if(y-x==1){
		return dp[x][y]=a[x]+a[y];
	}
	lli s=INT_MAX;
	for(int i=x;i<=y-1;i++){
		s=min(go(x,i)+go(i+1,y),s);
	}
	return dp[x][y]=s+prefix[y]-(x-1>=0?prefix[x-1]:0);
}

