ll func(int i,int j)
{
	if(i==j)
		return 0;
	if(dp[i][j]!=-1)
		return dp[i][j];
	ll k,d,min1=LLONG_MAX;
	for(k=i;k<=j-1;k++)
	{
		d=func(i,k)+func(k+1,j)+(sum[k]-sum[i-1])+(sum[j]-sum[k]);
		if(d<min1)
			min1=d;
	}
	dp[i][j]=min1;
	return dp[i][j];
}
