unsigned long long int dp(int l, int r) {
    if(flag[l][r] > 0)
        return mem[l][r];
    else if(l == r) {
        mem[l][r] = 0;
        flag[l][r] = 1;
        return mem[l][r];
    } else {
        int sumleft = 0;
        if(l > 0) sumleft = sum[l - 1];
        unsigned long long int min = ULLONG_MAX/2;
        for(int i = l; i < r; i++) {
            if(min > (dp(l, i) + dp(i + 1, r)) + sum[r] - sumleft) {
                min = (dp(l, i) + dp(i + 1, r)) + sum[r] - sumleft;
            }
        }
        mem[l][r] = min;
        flag[l][r] = 1;
        return mem[l][r];
    }
}
