using namespace std;

const int MAX = 410;
int64_t dp[MAX][MAX];
int vec[MAX];
int64_t sum[MAX][MAX];
int64_t INF = 1e18;

int64_t calc(int l, int r){
  if(dp[l][r] != -1){
    return dp[l][r];
  }
  else if(l == r){
    dp[l][r] = 0;
    return dp[l][r];
  }
  else if(r - l == 1){
    dp[l][r] = vec[l] + vec[r];
    return dp[l][r];
  }
  else{
    int64_t cost = INF;
    for(int i=0; i<r-l; i++){
      cost = min(cost, calc(l,l+i) + calc(l+i+1,r) + sum[l][l+i] + sum[l+i+1][r]);
    }
    dp[l][r] = cost;
    return dp[l][r];
  }
}

int main(){
  int N;
  cin >> N;
  for(int i=0; i<N; i++){
    cin >> vec[i];
  }
  for(int i=0; i<N; i++){
    sum[0][i] = vec[i];
    if(i != 0){
      sum[0][i] += sum[0][i-1];
    }
  }
  for(int i=1; i<N; i++){
    for(int j=i; j<N; j++){
      sum[i][j] = sum[0][j] - sum[0][i-1];
    }
  }
  for(int i=0; i<N; i++){
    for(int j=0; j<N; j++){
      dp[i][j] = -1;
    }
  }
  cout << calc(0,N-1) << endl;
}

