pll solve(ll s,ll e){
  //trace("s,e",s,e);
  if(dp[s][e][0]!=-1) return mp(dp[s][e][0],dp[s][e][1]);
  if(s==e){
      dp[s][e][0] = arr[s];
      dp[s][e][1] = 0;
      return mp(dp[s][e][0], dp[s][e][1]);
  }
  if(s+1==e){
    dp[s][e][0]=arr[s]+arr[e];
    dp[s][e][1]=arr[s]+arr[e];
    dp[s][s][0]=arr[s];
    dp[s][s][1]=0;
    dp[e][e][0]=arr[e];
    dp[e][e][1]=0;
    return mp(dp[s][e][0], dp[s][e][1]);
  }
  ll maxi = 1e18,val=1e18;
  for(int i=s;i<e;i++){
    auto k1 = solve(s,i);
    auto k2 = solve(i+1,e);
    ll tmaxi = k1.ff+k2.ff+k1.ss+k2.ss;
    ll tval = k1.ff+k2.ff;
    if(tmaxi<maxi){
        maxi=tmaxi;
        val=tval;
    }
  }
  dp[s][e][0]=val;
  dp[s][e][1]=maxi;
  return mp(dp[s][e][0], dp[s][e][1]);
}

