void solve() {
    i64 N; RD(N);
    auto A = RD_ARRAY<i64>(N);

    Cum1<i64> cum(N);
    REP(i, N) {
        cum.add(i, A[i]);
    }
    cum.build();

    auto ms = arrayn_make<i64>(N,N, -1);
    auto f = MEMOIZE<400,400>([&cum,&ms](auto&& self, i64 l, i64 r) -> i64 {
        assert(l <= r);
        if(l == r) return 0;

        i64 res = INF;
        FOR(m, l, r) {
            i64 cost = cum.query(l, m-l+1) + cum.query(m+1, r-m);
            if(chmin(res, cost + self(l,m) + self(m+1,r)))
                ms[l][r] = m;
        }
        return res;
    });

    i64 ans = f(0,N-1);

    PRINTLN(ans);

    vector<tuple<i64,i64,i64>> trace;
    trace.reserve(N-1);
    auto dfs = FIX([&ms,&trace](auto&& self, i64 l, i64 r) {
        if(l == r) return;
        i64 m = ms[l][r];
        self(l,m);
        self(m+1,r);
        trace.emplace_back(l,m,r);
    });
    dfs(0,N-1);
    DBG(trace);

    i64 sum = 0;
    for(const auto& t : trace) {
        i64 l,m,r; tie(l,m,r) = t;
        sum += cum.query(l,m-l+1) + cum.query(m+1, r-m);
    }
    assert(sum == ans);
}

signed main() {


    solve();

    EXIT();
}

