int main()
{
	int n, ai;
	cin >> n;

	const int N_MAX = 405;
	int a[N_MAX];
	for (int i = 0; i < n; ++i)
	{
		cin >> ai;
		a[i] = ai;
	}

	const int nax = 405;
	long long dp[nax][nax];
	//dp[i][j] - the minimum total cost of combining interval [i,j] into one vertex

	for (int L = n-1; L >= 0; --L)
	{
		for (int R = L; R < n; ++R)
		{
			if (L == R)
			{
				dp[L][R] = 0;
			}
			else
			{
				dp[L][R] = INT_MAX;
				long long s = sum(a, L, R);
				for (int i = L; i < R; ++i)
				{
					dp[L][R] = min(dp[L][R], dp[L][i] + dp[i + 1][R] + s);
				}
			}
		}
	}

	cout << dp[0][n-1];
;}

#include <math.h>
