int main() {
  int N;
  cin >> N;
  vector<long long int> a(N, 0);
  for (int i = 0; i < N; ++i) {
    cin >> a[i];
  }
  long long int ans = 0;
  for (int i = 0; i < N - 1; ++i) {
    long long int minV = -1;
    int minId1 = -1;
    int minId2 = -1;
    for (int j = 0; j < N - 1; ++j) {
      int id1;
      int id2;
      long long int sum = 0;

      while (a[j] == -1) ++j;
      sum += a[j];
      id1 = j++;

      while (a[j] == -1) ++j;
      sum += a[j];
      id2 = j--;

      if (minV == -1 || minV > sum) {
        minV = sum;
        minId1 = id1;
        minId2 = id2;
      }
    }
    a[minId1] = -1;
    a[minId2] = minV;
    ans += minV;
  }
  cout << ans;
}

