int n;
int a[MAXN];
long long sum[MAXN];
long long dp[MAXN][MAXN];

long long getSum(int l, int r) {
  long long res = sum[r];
  if (l > 0) {
    res -= sum[l - 1];
  }
  return res;
}

int main() { 

  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", &a[i]);
  }
  sum[0] = a[0];
  for (int i = 1; i < n; i++) {
    sum[i] = sum[i - 1] + a[i];
  }

  for (int len = 2; len <= n; len++) {
    for (int l = 0; l + len <= n; l++) {
      int r = l + len - 1;
      dp[l][r] = 1ll * INF * INF;
      for (int i = l + 1; i <= r; i++) {
        long long x = dp[l][i - 1], y = dp[i][r];
        long long xs = getSum(l, i - 1), ys = getSum(i, r);
        dp[l][r] = min(dp[l][r], x + y + xs + ys);
      }
      // cerr << l << " " << r << " " << dp[l][r] << endl;
    }
  }

  cout << dp[0][n - 1] << endl;

  return 0;
}

