ll recur(int i, int j)
{
    if(j == i) return 0;
    if(j == i+1) return arr[i]+arr[j];
    if(dp[i][j] != -1) return dp[i][j];

    ll cost = inf;
    for(int k=i; k<j; k++)
    {
        cost = min(cost,recur(i,k)+recur(k+1,j));
    }
    for(int k=i; k<=j; k++)
        cost += arr[k];
    return dp[i][j] = cost;
}

