using namespace std;
ll util(int i,int j,vector<ll>&sum,vector<l>&arr,V &dp){
	if(i==j)
		return 0;
	if(dp[i][j]!=-1)
		return dp[i][j];
	ll res=LONG_LONG_MAX;
	for(int k=i;k<j;k++){
		ll temp=util(i,k,sum,arr,dp)+util(k+1,j,sum,arr,dp)+sum[j];
		if(i-1>=0)
			temp-=sum[i-1];
		res=min(res,temp);
	}
	dp[i][j]=res;
	return dp[i][j];
}
