const ll INF = 1001001001001001;

ll dp[MAX][MAX];
ll cum_sum[MAX];
ll a[MAX];

ll rec(int l,int r){
    if(dp[l][r]>0) {
        return dp[l][r];
    }

    if((r-l)==1) {
        dp[l][r] = 0;
        return dp[l][r];
    }

    if((r-l)==2) {
        dp[l][r] = cum_sum[r]-cum_sum[l];
        return dp[l][r];
    }

    ll res = INF;
    for(int i=l+1;i<r;++i){
        res = min(res,rec(l,i)+rec(i,r));
    }

    dp[l][r] = res + cum_sum[r]-cum_sum[l];
    return dp[l][r];

}

