const int N = 405;
const ll INF = 1e15;

ll dp[N][N];

void solve() {
    int n;
    cin >> n;

    vector<ll> a(n);
    for (int i = 0; i < n; ++i)
        cin >> a[i];

    vector<ll> pref(n + 1, 0);
    for (int i = 1; i <= n; ++i)
        pref[i] = pref[i - 1] + a[i - 1];

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            dp[i][j] = INF;

    for (int i = 0; i < n; ++i)
        dp[i][i] = 0;

    for (int len = 1; len <= n; ++len) {
        for (int l = 0; l + len < n; ++l) {
            int r = l + len;

            for (int i = l; i < r; ++i)
                relax(dp[l][r], dp[l][i] + dp[i + 1][r] + pref[r + 1] - pref[l]);
        }
    }

    cout << dp[0][n - 1] << '\n';
}

