int dfs(int l, int r) {
    if (l == r)return 0;
    int &res = dp[l][r];
    if (res >= 0)return res;
    res = LINF;
    rep(m, l + 1, r) {
        int lv = dfs(l, m - 1);
        int rv = dfs(m + 1, r);
        int lsum = rui[m] - rui[l];
        int rsum = rui[r + 1] - rui[m + 1];
        chmin(res, lv + rv + 2 * A[m] + min(lsum, rsum) + lsum + rsum);
    }
    //左端が最後
    chmin(res, dfs(l + 1, r) + rui[r + 1]);
    chmin(res, dfs(l, r - 1) + rui[r + 1]);
    return res;
}
