int N;
long long a[MAX];

int main() {
	cin >> N;
	for( int i = 0; i < N; i++ ) {
		cin >> a[i];
	}

	long long ans = 0;
	for( int i = 0; i < N - 1; i++ ) {
		int idx = min_element( a, a + N ) - a;
		int idx1;
		if( idx <= 0 ) {
			for( int j = idx + 1; j < N; j++ ) {
				if( a[j] != INF ) {
					idx1 = j;
					break;
				}
			}
		}
		else if( idx >= N - 1 ) {
			for( int j = idx - 1; j >= 0; j-- ) {
				if( a[j] != INF ) {
					idx1 = j;
					break;
				}
			}
		}
		else {
			for( int j = idx + 1; j < N; j++ ) {
				if( a[j] != INF ) {
					idx1 = j;
					break;
				}
			}
			for( int j = idx - 1; j >= 0; j-- ) {
				if( a[j] != INF ) {
					if( a[j] < a[idx1] ) {
						idx1 = j;
					}
					break;
				}
			}
		}
		ans += a[idx] + a[idx1];
		a[idx] += a[idx1];
		a[idx1] = INF;
	}

	cout << ans << endl;

	return 0;
}

