ll memo[400][400];
ll A[400];
ll C[401];
ll calc(ll l, ll r)
{
    if (memo[l][r] != 0) {
        return memo[l][r];
    }
    if (l == r) {
        return 0;
    }
    ll ret = INF;
    for2 (i, l, r) {
        ll ret1 = calc(l, i) + calc(i + 1, r) + C[r + 1] - C[l];
        chmin(ret, ret1);
    }
    memo[l][r] = ret;
    return ret;
}

void solve()
{
    ll N;
    in(N);
    for1 (i, N) {
        in(A[i]);
    }
    for1 (i, N) {
        C[i + 1] = C[i] + A[i];
    }
    print(calc(0, N - 1));
}
