ll cal(vector<ll> &a, int n){
    vector<vector<ll>>dp(n,vector<ll>(n,0));
    vector<ll>prefix(n+1,0);
    for(int i=1;i<=n;++i)
        prefix[i] = prefix[i-1] + a[i-1];

    for(int l=2;l<=n;++l){
        for(int i=0;i<=n-l;++i){
            int j = i+l-1;
            if(l == 2){
                dp[i][j] = a[i] + a[j];
            }else{
                dp[i][j] = 1e12;
                for(int k=i;k<j;++k){
                    dp[i][j] = min(dp[i][j], (dp[i][k] + dp[k+1][j]) + prefix[j+1]-prefix[i]);
                }
            }

        }
    }
    return dp[0][n-1];
}



