ll sum(int l, int r) {
    assert(l<=r);
    ll res=acc[r];
    if (l) res-=acc[l-1];
    return res;
}

ll dp[maxn][maxn];


ll solve(int l, int r) {
    assert(l<=r);
    if (l==r) return 0;
    if (l+1==r) return sum(l,r);
    if (~dp[l][r]) return dp[l][r];

    ll &res=dp[l][r]=inf;

    for (int i=l; i<r; i++) {
	res=min(res, solve(l,i)+solve(i+1,r));
    }

    res += sum(l,r);
    return res;
}



