      for (int j = 0; j + i <= n; ++j) {
        int r = j + i;
        for (int k = j + 1; k < i + j; ++k) {
          dp[j][r] = min(dp[j][r], dp[j][k] + dp[k][r] + (a[r - 1] - (j == 0 ? 0 : a[j - 1])));
        }
      }
    }
    DBG(dp)
    cout << dp[0][n] << endl;
  }
};

