ll solve(int left, int right){
    if(right - left <= 1) return 0;
    if(ans[left][right] != 0) return ans[left][right];
    ll res = INF;
    loop(i, left+1, right-1) res = min(res, solve(left,i) + solve(i,right));
    res += sum[right] - sum[left];
    return res;
}

