ll calc(int l, int r) {
	if (l == r)
		return 0;
	ll &ret = dp[l][r];
	if (ret != -1)
		return ret;
	ret = LLONG_MAX;
	for (int i = l; i < r; ++i) {
		ll cost = cs[i];
		if (l != 0)
			cost -= cs[l - 1];
		cost += cs[r] - cs[i];
		ret = min(ret, cost + calc(l, i) + calc(i + 1, r));
	}
	return ret;
}
