  if (i > 0) {
    res -= pre[i - 1];
  }
  return res;
}

ll dp[405][405];

ll solve(int i, int j) {
  if (i == j) { return 0; }
  ll& res = dp[i][j];
  if (res != -1) { return res; }
  res = numeric_limits<ll>::max();
  for (int k = i; k < j; k++) {
    ll left = solve(i, k);
    ll right = solve(k + 1, j);
    res = min(res, left + right + getSum(i, j));
  }
  return res;
}

