const ll INF = 1LL << 60;
const int MAX_N = 410;

ll memo[MAX_N][MAX_N];
bool visited[MAX_N][MAX_N];
vector<ll> sum;

ll rec(int L, int R) { // [L, R]の最小コスト
    if (L == R) return 0;
    if (visited[L][R]) return memo[L][R];
    visited[L][R] = true;

    ll res = INF;
    ll now = sum[R + 1] - sum[L]; // 今回の合成で増えるコスト
    for (int i = L; i < R; i++) { // [L, R]間の区切り位置を全部試す
        chmin(res, rec(L, i) + rec(i + 1, R) + now);
    }
    return memo[L][R] = res;
}

