ll sum[3001][3001];

ll solve(std::vector<ll>& v, ll i, ll j)
{
	//base case
	if (i == j)
		return 0;
	//when answer is calculated before
	if (dp[i][j] != -1)
		return dp[i][j];

	//recursive
	ll minCost = INT_MAX;//store the minm value
	for (int k = i; k < j; k++)
	{
		minCost = min(minCost, sum[i][j] + solve(v, i, k) + solve(v,  k + 1, j));
	}

	return dp[i][j] = minCost;
}

