const int N = 444;
const ll INF = 1e18;

int a[N], p[N][N];
ll pref[N];
ll dp[N][N];

void solve(int l, int r) {
	if (l == r) {
		dp[l][r] = 0;
		p[l][r] = l;
		return;
	}
	ll &res = dp[l][r];
	if (res != INF) {
		return;
	}
	solve(l, r - 1);
	solve(l + 1, r);
	for (int i = p[l][r - 1]; i <= min(p[l + 1][r], r - 1); i++) {
		ll val = dp[l][i] + dp[i + 1][r] + pref[r + 1] - pref[l];
		if (res >= val) {
			res = val;
			p[l][r] = i;
		}
	}
}

void run() {
	int n;
