		cin >> a[i];
	}
	for (int i = 0; i < n; i++) {
		for (int j = i; j < n; j++) {
			dp[i][j] = INF;
		}
	}
	for (int i = 0; i < n; i++) {
		pref[i + 1] += pref[i] + a[i];
	}
	solve(0, n - 1);
	cout << dp[0][n - 1] << "\n";
}

