void solve() {
    ll n;
    cin >> n;
    v a = ga(n);
    v sum(n);
    sum[0] = a[0];
    for (ll i = 1; i < n; i++) {
        sum[i] = sum[i - 1] + a[i];
    }

    vv dp(n, v(n, 1e15));

    for (ll len = 1; len <= n; len++) {
        for (ll i = 0; i < n; i++) {
            ll j = i + len - 1;

            if (j >= n)
                break;
            if (len == 1) {
                dp[i][i] = 0;
            } else if (len == 2) {
                dp[i][j] = a[i] + a[j];
            } else {
                for (ll k = i + 1; k < j; k++) {
                    ll c = dp[i][k - 1] + dp[k + 1][j];
                    ll s1 = sum[k - 1] - sum[i] + a[i];
                    ll s2 = sum[j] - sum[k];

                    amin(dp[i][j], c + 2 * s1 + 2 * a[k] + s2);
                    amin(dp[i][j], c + s1 + 2 * s2 + 2 * a[k]);
                }
            }
        }
    }

    cout << dp[0][n - 1] << endl;
}

