LL dp[N][N];
LL pref[N];

LL sum(LL i,LL j){
    return pref[++j] - pref[++i-1];
}

LL solve(LL i,LL j){
    if(dp[i][j] != -1) return dp[i][j];
    if( i == j) return 0;
    if(j-i == 1){
        return arr[i] + arr[j];
    }
    dp[i][j] = INT_MAX;
    for(int k = i;k<j;k++){
        dp[i][j] = min(dp[i][j],sum(i,j) + solve(i,k) + solve(k+1,j));
    }
    return dp[i][j];
}


