i64 n;
v64 a;

void Problem::solve() {
	vv64 dp(n, v64(n));
	v64 pref(n);
	forn(i, n) {
		pref[i] = a[i] + (i ? pref[i - 1] : 0);
	}
	forn(i, n) {
		dp[i][i] = 0;
		if (i != n - 1) dp[i][i + 1] = a[i] + a[i + 1];
	}
	forr(ln, 3, n + 1) {
		forn(i, n) {
			i64 j = i + ln - 1;
			if (j >= n) break;
			dp[i][j] = inf;
			for (i64 k = i + 1; k <= j; k++) {
				check_min(dp[i][j], dp[i][k - 1] + dp[k][j]);
			}
			dp[i][j] += pref[j] - (i ? pref[i - 1] : 0);
		}
	}
	i64 ans = dp[0][n - 1];
	println(ans);
}

