void min_cost (int s,int e, int*a )
{
    if(cost[s][e] != -1)
        return;
    if(s==e)
    {
        sum[s][e] = a[s];
        cost[s][e] = 0;
        return;
    }
    int minn = LLONG_MAX;
    for (int i = s; i < e ; ++i)
    {
        min_cost (s,i,a);
        min_cost (i+1,e,a);

        sum[s][e] = sum[s][i] + sum[i+1][e];
        minn = min ( minn , cost[s][i] + cost[i+1][e] + sum[s][e]);
    } 
    cost[s][e] = minn;
}


