template<typename T>
struct BIT{
    int N;
    vector<T> dat;
    BIT(){}
    BIT(int n) : N(n), dat(n+1,0){ }
    void add(int i, T num){
        for(int x = i+1; x <= N; x += (x & -x)) dat[x] += num;
    }
    T sum(int i){
        T ret = 0;
        for(int x = i+1; x > 0; x -= (x & -x)) ret += dat[x];
        return ret;
    }
    T sum(int i, int j){
        return sum(j) - sum(i-1);
    }
};

vl A;
vvl dp;
BIT<ll> bit;

ll rec(int l, int r){
    if(l == r) return 0;
    if(dp[l][r] != INFL) return dp[l][r];
    ll ret = INFL;
    REP(i,l,r){
        ret = min(ret, (rec(l,i) + rec(i+1,r) + bit.sum(l,r)));
    }
    return dp[l][r] = ret;
}

