vector<int64_t> press(int x, vector<int64_t> z){ //xとx+1の圧縮
  vector<int64_t> ret(0);
  for(int i=0; i<z.size(); i++){
    if(i == x){
      ret.push_back(z[x] + z[x+1]);
    }
    else if(i == x+1){
      continue;
    }
    else{
      ret.push_back(z[i]);
    }
  }
  return ret;
}


