int f(vl ary, int cost)
{
	int nextSize = ary.size() - 1;
	int res = INT_MAX;

	if (ary.size() == 1) return 0;
	for (int i = 0; i < nextSize; i++) {
		vl tmp(nextSize);
		int tmpCost = ary[i] + ary[i + 1];
		int up = 0;
		for (int j = 0; j < nextSize;) {
			if (j == i) tmp[j] = tmpCost;
			else if (j == i + 1) {
				tmp[j] = ary[j + 1];
				up += 1;
			}
			else tmp[j] = ary[j + up];
			j++;
		}
		int tmpRes = f(tmp, cost) + cost + tmpCost;
		if (res > tmpRes) res = tmpRes;
	}
	return res;
}

