inline ll mul(ll a, ll b)
{
    return ((a%mod)*(b%mod))%mod;
}
inline ll add(ll a, ll b)
{
	a+= mod;
	b += mod;
	return (a%mod + b% mod) % mod;
}
ll binpow(ll x, ll y)
{
    ll z = 1;
    while(y)
    {
        if(y & 1) z = mul(z, x);
        x = mul(x, x);
        y >>= 1;
    }
    return z;
}

inline ll inv(ll x)
{
    return binpow(x, mod - 2);
}
inline ll divide(ll x, ll y)
{
    return mul(x, inv(y));
}
