			cum[i] += cum[i - 1];
		}
	}
	V <V <ll>> DP(N, V <ll> (N + 1, 1e18));

	for(int sz = 1; sz <= N; sz++) {
		for(int i = 0; i + sz - 1 < N; i++) {
			if(sz == 1) {
				DP[i][sz] = 0;
				continue;
			}
			for(int sz0 = 1; sz0 < sz; sz0++) {
				int sz1 = sz - sz0;
				ll cost = cum[i + sz - 1];
				if(i) {
					cost -= cum[i - 1];
				}
				DP[i][sz] = min(DP[i][sz0] + DP[i + sz0][sz1] + cost, DP[i][sz]);
			}
		}
	}
	cout << DP[0][N];

    return 0;
}

