uint64_t dfs(vector<vector<uint64_t>>& dp, const uint32_t l, const uint32_t r, const uint32_t tsum){
	if(dp[l][r] != 0) return dp[l][r];

	uint64_t tans = UINT64_MAX;

	uint64_t lsum = 0;
	uint64_t rsum = tsum;

	for(uint32_t d=l; d<r; d++) {
		lsum += dp[d][d];
		rsum -= dp[d][d];
		tans = min(tans, dfs(dp, l, d, lsum) + dfs(dp, d+1, r, rsum));
	}

	dp[l][r] = tans + tsum;
	//cout << l << "-" << r << ":" << dp[l][r] << endl;
	return dp[l][r];
}


