  ll res = INF;
  for (int i = l; i < r; i++) {
    res = min(res, rec(l, i) + rec(i + 1, r));
  }

  res += a[r];
  if (l > 0) res -= a[l - 1];

  dp[l][r] = res;
  return dp[l][r];
}

