  int N;
  cin >> N;
  for (int i = 0; i < N; i++) {
    cin >> a[i];
    if (i > 0) a[i] += a[i - 1];
  }

  memset(dp, 0, sizeof(dp));

  ll ans = rec(0, N - 1);
  cout << ans << endl;

  return 0;
}

