constexpr int INF = (1<<30);
constexpr ll INFLL = 1LL<<62;
constexpr long double EPS = 1e-12;

ll search(const int start, const int end, const vll& a, vvll& dp, const vvll& sum){
  if(start>=end) return dp[start][end]=0;
  if(dp[start][end]>=0) return dp[start][end];
  if(start+1==end) return dp[start][end] = a[start]+a[end];
  ll tmp=INFLL;
  rep(i, start, end){
    ll tmp1 = search(start, i, a, dp, sum);
    ll tmp2 = search(i+1, end, a, dp, sum);
    tmp = min(tmp, tmp1+tmp2);
  }
  return dp[start][end] = tmp+sum[start][end];
}

