        cache[l][r] = 0;
        return 0;
    }

    lli &ans = cache[l][r];

    if(ans != -1) {
        return ans;
    }
    ans = inf;

    for(int i = l; i < r; i ++) {
        ans = min(ans, dp(l, i) + dp(i + 1, r) + ps[r] - ps[l - 1]);
    }
    return ans;

}

