ll solve(vector<ll> arr)
{
    if(arr.size()==2)
    return arr[0]+arr[1];
    ll min = arr[0]+arr[1];
    ll i,j=0;
    for(i=1;i<arr.size()-1;i++)
    {
       if(arr[i]+arr[i+1]<min)
       {
           min=arr[i]+arr[i+1];
           j=i;
       }
    }
    ll temp=arr[j]+arr[j+1];
    arr.erase(arr.begin()+j,arr.begin()+j+2);
    arr.push_back(0);
    for(i=arr.size()-2;i>=j;i--)
    arr[i+1]=arr[i];
    arr[j]=temp;
    return temp+solve(arr);
}

