int N;
const long long INF = 1LL << 60;
vector<int> A;
vector<long long> S;
vector<vector<long long>> dp;

// [A_left, A_right) を合体させる最小コストを返す
long long func(int left, int right) {
  if (right - left == 1) return dp.at(left).at(right) = 0;  // 1 体のみなので 0
  if (dp.at(left).at(right) != INF) return dp.at(left).at(right);
  long long res = INF;
  long long cost = S.at(right) - S.at(left);  // 区間 [left, right)
  for (int i = 1; i < right - left; i++) {
    // [A_left ... A_left+i) と [A_left+i ... A_right) に分割
    long long tmp = func(left, left + i) + func(left + i, right);
    res = min(res, cost + tmp);
  }
  return dp.at(left).at(right) = res;
}

