struct RadixHeap {
    using ull = unsigned long long;
    int bsr (ull x) { if (x == 0) return -1; return 63-__builtin_clz(x); }
    vector<ull> v[65];
    ull last, sz;
    RadixHeap() : last(0), sz(0) { }
    void push(ull x) { assert(last <= x); sz++; v[bsr(x^last)+1].push_back(x); }
    ull pop () {
        assert(sz);
        if (!v[0].size()) {
            int i = 1;
            while (!v[i].size()) i++;
            ull nlast = *min_element(v[i].begin(), v[i].end());
            for (ull x : v[i]) { v[bsr(x^nlast)+1].push_back(x); }
            last = nlast; v[i].clear();
        }
        sz--; v[0].pop_back(); return last;
    }
    ull size() { return sz; }
};

