int64_t rec(int L, int R){
    if(L == R) return 0;
    if(dp[L][R] >= 0) return dp[L][R];
    int64_t ret = 1e18;
    for(int i=L; i<R; i++){
        int64_t result = rec(L, i) + rec(i+1, R) + S[R] - S[L-1];
        ret = min(ret, result);
    }
    dp[L][R] = ret;
    return ret;
}

