ll solve(int l, int r) {
	if (l == r)
	{
		return 0;
	}
	if (dp[l][r] != -1)
		return dp[l][r];
	ll& ans = dp[l][r];
	ans = INF;
	for (int i = l; i <= r - 1; ++i)
	{
		// partitioning at position i means that the aggregate silme
		// on the left(l,i) and on the right(i+1,r) are t be merged
		ans = min(ans, solve(l, i) + solve(i + 1, r) + (pref[r] - pref[l - 1]));
	}
	return ans;
}

