vector<vector<long long>> dp;

long long f(int left, int right, const vector<int> &v, const vector<vector<long long>> &sum) {
  if (left == right) {
    return 0;
  }

  if (dp[left][right] == -1) {
    long long ans = numeric_limits<long long>::max();
    for (int mid = left; mid < right; ++mid) {
      long long cost = (sum[left][mid] + sum[mid + 1][right]) + f(left, mid, v, sum) + f(mid + 1, right, v, sum);
      ans = min(ans, cost);
    }
    dp[left][right] = ans;
  }

  return dp[left][right];
}

