    function<ll(ll,ll)> F=[&](ll x,ll y){
        if(dp[x][y]!=-1)return dp[x][y];
        if(y==x+1)return dp[x][y]=0;
        ll ret=INF;
        for(ll i=x+1;i<=y-1;++i)chmin(ret,F(x,i)+F(i,y));
        return dp[x][y]=ret+tree.sum(x,y);
    };
    prt(F(0,N))

    return 0;
}

