int slimeCost(vector<int> a, int i, int j, vector<int> prefix_sum, vector<vector<int>> &dp)
{
    int &val = dp[i][j];

    if(val != -1) return val;

    if(i >= j) val = 0;

    else
    {

        int ans = 1e16;

        for(int k = i; k<j; k++)
        {
            int temp = slimeCost(a, i, k, prefix_sum, dp) + slimeCost(a, k+1, j, prefix_sum, dp);
            if(i == 0) {temp += prefix_sum[k];}
            else temp += (prefix_sum[k] - prefix_sum[i-1]);

            temp += prefix_sum[j] - prefix_sum[k];

            ans = min(ans, temp);
        }

        val = ans;

    }



    return val; 
}



