inline ll get(ll x, ll y){
    return pre[y] - pre[x-1];
}
ll f(ll x, ll y){
    if(dp[x][y] != 1e18)
        return dp[x][y];
    if(x >= y)
        return dp[x][y] = 0;
    for(ll i = x; i < y; ++i){
        ll tmp = f(x, i) + f(i+1, y) + get(x, y) ;
        dp[x][y] = min(dp[x][y], tmp);
    }
    return dp[x][y];
}
