typedef long long ll;
ll memo[402][402];
ll sum(ll *arr, int i, int j){
	ll ans = 0;
	//if(i == j) return 0;
	for(int k = i; k<=j; k++) ans += arr[k];
	return ans;
}

ll answer(ll *arr, int i, int j){
	if(memo[i][j] != 1000000000001) return memo[i][j];
	if(i == j) return arr[i];

	for(int k = i; k<j; k++){
		memo[i][j] = min(memo[i][j],answer(arr, i, k) + answer(arr, k+1, j) + sum(arr, i, k) + sum(arr, k+1, j));
	}

	return memo[i][j];
}
int main(){
	int n;
	cin >> n;
	ll arr[n];
	for(int i=0; i<n; i++) cin >> arr[i];
	for(int i=0; i<n+1; i++){
		for(int j = 0; j<n+1; j++) memo[i][j] = 1000000000001;
	}
	cout << answer(arr, 1, n-1) << endl;
}

