pair<ll, ll> f(int p, int q)
{
    if (p == q) return {0, a[p]};
    if (dp[p][q] != pair<ll, ll>{-1ll, -1ll}) return dp[p][q];
    pair<ll, ll> bst = {1e15, 1e15};
    for (int i = p; i < q; ++i)
    {
        ll tot = f(p, i).first + f(i + 1, q).first;
        ll cst = f(p, i).second + f(i + 1, q).second;
        bst = min(bst, {tot + cst, cst});
    }
    return dp[p][q] = bst;
}

