int n;

ll solve(int lhs, int rhs) {
  if(lhs == rhs) return 0;
  if(dp[lhs][rhs]) return dp[lhs][rhs];
  ll total = 0;
  for(int i = lhs; i <= rhs; i++) {
    total += l[i];
  }
  dp[lhs][rhs] = 1e18;
  for(int i = lhs; i < rhs; i++) {
    dp[lhs][rhs] = min(dp[lhs][rhs], solve(lhs, i) + solve(i+1, rhs));
  }
  dp[lhs][rhs] += total;
  return dp[lhs][rhs];
}

