inline int query(int a,int b){
	return rangeTree[b] - rangeTree[a] + v[a]; 
}

inline int dp(int a, int b){
	if(memo[a][b] != -1)return memo[a][b];
	if(a == b - 1)return memo[a][b] = v[a] + v[b];
	if(a == b)return 0;
	int ans = INT_MAX;
	for(int i = a; i < b; i++){
		ans = min(ans,dp(a,i) + dp(i + 1,b));
	}
	return memo[a][b] = ans + query(a,b);
}

