vi a; 
ll dp[400][401];

ll rec(int s, int e){
	if(e - s <= 1) return 0;
	if(dp[s][e]) return dp[s][e];
	ll ans = -1;
	ll total = accumulate(a.begin() + s, a.begin() + e, 0LL);
	ll pref = 0;
	rep2(m, s, e - 1){
		ll l = rec(s, m), r = rec(m + 1, e);
		ll r_sum = total - pref - a[m];
		if(m == s) ans = a[m] + l + r + pref + r_sum;
		else if(m == e - 1) ckmin(ans, a[m] + l + r + pref + r_sum);
		else ckmin(ans, 2 * a[m] + l + r + pref + r_sum + min(pref, r_sum));
		pref += a[m];
	}
	return dp[s][e] = ans;
}


