ll slimes(ll i,ll j,ll slime[],ll dp[][400])
{
    if(i>j || i==j)
    {
        return 0;
    }
    if(dp[i][j]!=-1)
    {
        return dp[i][j];
    }
    ll sum = LONG_MAX;
    for(ll k=i;k<j;k++)
    {
        ll sum1=0;
        ll sum2=0;
        for(ll q=i;q<=k;q++)
        {
            sum1 = sum1 +slime[q];
