int get(int l, int r)
{
	if ( l == r ) return dp[l][r] = 0;

	int &mafia = dp[l][r];
	if (mafia != -1 ) return mafia;

	int ans = INF;
	for (int p = l; p < r; p++) {
		int a1 = get(l, p), a2 =  get(p + 1, r);
		int total = a1 + a2 + (sum[r] - sum[l - 1]);
		ans = min(ans, total);
	}

	return mafia = ans;
}

