ll dp[401][401];
vector<ll> a;
ll slime(ll leftBound,ll rightBound){
	ll &ans = dp[leftBound][rightBound];
	if(ans!=-1)
		return dp[leftBound][rightBound];
	if(rightBound==leftBound)
		return 0;
	ans = 1e15;
	ll right = 0,left = 0;
	for(int k=rightBound;k>=leftBound;--k)
		right+=a[k];
	for(int k=leftBound;k<rightBound;++k){
		left+=a[k];
		right-=a[k];
		ans = min(slime(leftBound,k)+slime(k+1,rightBound)+left+right,ans);
	}
	return ans;
}

