    pre[0] = a[0];
    rep(i, 1, n-1) pre[i] = pre[i-1] + a[i];
    ll dp[n][n];
    repi(i, n) dp[i][i] = 0;
    repi(i, n-1) dp[i][i+1] = a[i]+a[i+1];
    rep(j, 2, n-1){
        for(ll i=0; i+j<n; i++){
            dp[i][i+j] = INF;
            rep(k, i, i+j){
                dp[i][i+j] = min(dp[i][i+j], dp[i][k] + pre[i+j] - (i>0 ? pre[i-1] : 0) + dp[k+1][i+j]);
            }
        }
    }
    cout<<dp[0][n-1];
    return 0;
}

