const int MAX_N = 400 + 2;
ll a[MAX_N];
ll dp[MAX_N][MAX_N];
ll suma[MAX_N];

ll rec(int i, int j) {
  if (dp[i][j] != INF) return dp[i][j];
  ll ans = INF;
  for (int k = 0; i + k + 1 <= j; k++) {
    ll tmp = (suma[i + k] - suma[i - 1]) + (suma[j] - suma[i + k]) + rec(i, i + k) + rec(i + k + 1, j);
    ans = min(ans, tmp);
  }
  dp[i][j] = ans;
  return dp[i][j];
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);

  int N;
  cin >> N;
  for (int i = 1; i <= N; i++) cin >> a[i];

  suma[0] = 0;
  for (int i = 1; i <= N; i++) suma[i] = suma[i - 1] + a[i];

  for (int i = 0; i < MAX_N; i++) {
    for (int j = 0; j < MAX_N; j++) {
      dp[i][j] = INF;
    }
  }
  for (int k = 1; k <= N; k++) dp[k][k] = 0;

  rec(1, N);
  cout << dp[1][N] << endl;

  return 0;
}

