long long  a[MAX], dp[MAX][MAX],n,ps[MAX];

long long calc(int a , int b) {
    return ps[b] - ps[a-1];
}


long long solve(int start, int end) {
    if( start == end || start > end) {
        return 0;
    }
    if( start + 1 == end) {
        return a[start] + a[end];
    }
    if(dp[start][end] != -1) {
        return dp[start][end];
    }
    long long res = INF;
    for(int split = start; split < end; split++) {
        res = min( res , solve(start, split) + solve(split + 1, end) + ps[end] - ps[start - 1]);
    }
    return dp[start][end]=res;
}



