	rep(w, 1, N) rep(i, 0, N) rep(j, i + 1, i + w + 1)
	{
		if (N <= i + w) continue;
		ll sum = (0 <= i - 1) ? memo[i + w] - memo[i - 1] : memo[i + w];
		dp[i][i + w] = min(dp[i][i + w], dp[i][j - 1] + dp[j][i + w] + sum);
	}

	cout << dp[0][N-1];
	return 0;
}

