const int N = 401;

int n, a[N]; long long f[N][N], p[N];

long long P(int l, int r)
{
    return p[r] - p[l-1];
}

long long F (int l, int r)
{
    if (l >= r)
        return 0;
    if (f[l][r])
        return f[l][r];
    if (l + 1 == r)
    {
        f[l][r] = a[l] + a[r];
    }
    else
    {
        long long ans = 1e16;
        for (int k=l; k<r; k++)
        {
            ans = min(ans, F(l, k) + F(k+1, r));
        }
        f[l][r] = ans + P(l,r);
    }
    return f[l][r];
}

