    dp = vector<vector<long>> (n, vector<long>(n, -1));
    for(int i = 0; i < n; i++)
    {
        if(i == 0)
            sum[0] = (long)v[0];
        else
            sum[i] = sum[i - 1] + v[i];
    }
    cout << solve(v, 0, v.size() - 1);
    return 0;
}
