long long helper(vector<long long> &vec,vector<vector<long long>> &dp,long long l,long long r)
{
	if(l==r)return 0;
	if(l+1==r)return dp[l][r]=vec[l]+vec[r];
    if(dp[l][r]!=-1)return dp[l][r];
	long long ans=LLONG_MAX,sum=0;
	for (long long i = l; i<=r; ++i)
	{
		sum+=vec[i];
	}
	for (long long i = l; i < r; ++i)
	{
		ans=min(ans,sum+helper(vec,dp,l,i)+helper(vec,dp,i+1,r));
	}
	return dp[l][r]=ans;
}

