ll computesum(ll i,ll j,vector<ll>& arr)
{
	ll s=0;
	for(ll x=i;x<=j;x++)
	{
		s+=arr[x];
	}
	return s;
}

void printmat(vector< vector<ll> >& dp,ll r,ll c)
{
	for(ll i=1;i<=r;i++)
	{
		for(ll j=1;j<=c;j++)
		{
			cout<<dp[i][j]<<" ";
		}
		cout<<endl;
	}
}

ll givemin(ll i,ll j,vector<ll>& arr,vector< vector<ll> >& dp)
{
	ll result=-1;
	ll sum1,sum2,mindp;
	for(ll k=i;k<j;k++)
	{
		sum1=computesum(i,k,arr);
		sum2=computesum(k+1,j,arr);
		mindp=sum1+sum2+dp[i][k]+dp[k+1][j];
		if(result==-1)
		{
			result=mindp;
			continue;
		}
		result=min(result,mindp);
	}
	return result;
}

int main()
{
	ll n;
	cin>>n;
	vector<ll> arr(n+1);
	vector< vector<ll> > dp(n+1);
	for(ll i=1;i<=n;i++)
	{
		cin>>arr[i];
	}
	for(ll i=0;i<=n;i++)
	{
		dp[i].resize(n+1,0);
	}

	//dp table

	ll s=1;
	while(s<n)
	{
		ll j;
		for(ll i=1;i<=n-s;i++)
		{
			j=i+s;
			dp[i][j]=givemin(i,j,arr,dp);
		}
		s++;
	}

	cout<<dp[1][n]<<endl;
	printmat(dp,n,n);
	return 0;
}

