ll s[410][410];
bool memos[410][410];

ll f(const vector<ll> &v,int x, int y){
  if(memo[x][y]) return dp[x][y];
  memo[x][y] = true;
  if(!memos[x][y]) {
    memos[x][y] = true;
    for(int i = x; i <=y; i++) {
      s[x][y]+=v.at(i);
    }
  }
  for(int i = x; i <= y-1; i++) {
    chmin(dp[x][y], f(v,x,i)+f(v,i+1,y)+s[x][y]);
  }
  return dp[x][y];
}

