int dfs(int l, int r)
{
    if (l == r)
        return 0;

    if (dp[l][r])
        return dp[l][r];

    int cnt = oo;
    for (int i = l; i < r; ++i)
    {
        int a = 0, b = 0;

        for (int j = l; j <= r; ++j)
            if (j <= i)
                a += val[j];
            else
                b += val[j];

        cnt = min(cnt, a + b + dfs(l, i) + dfs(i + 1, r));
    }

    return dp[l][r] = cnt;
}


