// dp[i][j] = min cost to combine from i to j index

long long rec(int i, int j)
{
    if (i == j)
        return dp[i][j] = 0;

    if (j == i + 1)
        return dp[i][j] = a[i] + a[j];

    if (dp[i][j] != -1)
        return dp[i][j];

    dp[i][j] = LLONG_MAX;
    for (int k = i; k < j; k++)
        dp[i][j] = min(dp[i][j], rec(i, k) + rec(k + 1, j));

    if (i > 0)
        dp[i][j] += pre[j] - pre[i - 1];
    else
        dp[i][j] += pre[j];

    return dp[i][j];
}

