long long minimaze(int depth, vector<long long> a) {
    if(a.size() == 1)
        return 0;

    long long minimo = LLONG_MAX;
    vector<long long> b;
    for(int i = 0; i < a.size() - 1; i++)
        b.push_back(a[i]);

    for(int i = b.size() - 1; i >= 0; i--) {
        b[i] = a[i] + a[i + 1];
        minimo = min(minimo , minimaze(depth + 1, b) + (a[i] + a[i + 1]));
        b[i] = a[i + 1];
    }

    return minimo;
}

