int n;

/*
dp[L][R] = costo de unir a[L..R] en un solo elemento.
dp[L][L] = 0
dp[L][R] = Primero reduzco a dos slimes: para eso pago dp[L][i] y dp[i+1][R].
Despues para unificarlos pago sum(a[L...R]).
Para que cuando estoy en un estado dp[L][R] ya esten definidos los dp[L][i] con i<R R tiene que iterar desde L hasta n.
Para que este definido dp[i+1][R] con i>=L, itero L desde n-1 hasta 0.
*/


int main () {
	//FIN
	cin >> n;
	ll a[n]; F0(i,n) cin >> a[i];
	ll dp[n+1][n+1];
	F0(i,n+1) F0(j,n+1) dp[i][j] = INFLL;
	ll prefix_sum[n];
	prefix_sum[0] = a[0];
	rep(i,1,n-1) prefix_sum[i] = a[i] + prefix_sum[i-1];
	auto sum = [&](int i, int j) {
		ll res = prefix_sum[j];
		if(i > 0) res -= prefix_sum[i-1];
		return res;
	};

	for (int L = n-1; L >= 0; L--) {
		for (int R = L; R < n; R++) {
			if (L == R) dp[L][R] = 0;
			else {
				for (int i = L; i < R; i++) {
					mini(dp[L][R], dp[L][i] + dp[i+1][R]);
				}
				dp[L][R] += sum(L,R);
			}
		}
	}

	cout << dp[0][n-1] << "\n";

	return 0;
}

