long long fmin[405][405];//m番目からn番目の区間の最小値fmin[m][n]

long long dp(int m,int n)
{
    //メモ済み
    if(fmin[m][n] != INT_MAX) return fmin[m][n];
    //メモしていない
    else {
        if(n - m == 1) return fmin[m][n] = p[m] + p[n];
        else if(m == n) return 0;
        else{
            long long t = fmin[m][n];
            fmin[m][n] = 0;
            for(int v = m; v < n; v++){
                fmin[m][n] = min(dp(m,v) + dp(v + 1,n),t);
                t = fmin[m][n];
            }
            fmin[m][n] += All[m][n];
            return fmin[m][n];
        }
    }
}

