/*
あからさまに区間DP
F(L,R) := [L,R]の区間のコストの最小値とする

[L,R)の区間のスライムを1つにする一手前の状態を考えると、[L,R)が2つに別れていることが分かる。
1 2 3 | 4 5
なので、分ける境界を全探索して、コストの最小値を求めていく。
累積和で区間和を高速に求められるようにしておかないとTLEする。
*/

ll rec(int l, int r) {
    if (dp[l][r] != -1) return dp[l][r];
    if (abs(l-r) <= 1) return 0;
    ll ret = LINF;
    for (int k = l+1; k < r; ++k) {
        // printf("l = %d, r = %d, k = %d\n",l,r,k);
        ret = min(ret, rec(l,k)+rec(k,r)+(s[r]-s[l]));
    }
    // printf("dp[%d][%d] = %lld\n",l,r,ret);
    return dp[l][r] = ret;
}

