template<class T>
T next(istream& in) {
    T ret;
    in >> ret;
    return ret;
}

template<class T>
vector<T> next_vec(istream& in, size_t n) {
  vector<T> ret(n);
  for (size_t i = 0; i < n; ++i) {
    ret[i] = next<T>(in);
  }
  return ret;
}


void solve(istream& in, ostream& out) {
  auto n = next<int>(in);
  auto a = next_vec<int64_t>(in, n);
  vec2d<int64_t> dp = makeVec2d<int64_t>(n, n, -1);
  vec<int64_t> sum(n);
  sum[0] = a[0];
  FORA(i, 1, n) sum[i] = sum[i-1] + a[i];

  auto getSum = [&] (int le, int ri) -> int64_t {
    if (le == 0) return sum[ri];
    return sum[ri] - sum[le - 1];
  };


  function<int64_t(int, int)> rec = [&](int le, int ri) -> int64_t {

    if (le == ri) {
      return 0;
    }
    auto& res = dp[le][ri];
    if (res != -1) return res;
    res = numeric_limits<int64_t>::max() / 2;

    for (int i = le; i < ri; ++i) {
      int64_t cur = rec(le, i) + rec(i + 1, ri) + getSum(le, ri);
      res = min(res, cur);
    }
    return res;
  };
  out << rec(0, n-1) << "\n";
}

