int slimes(int i, int j, vector<int> &cs) {
	int n = cs.size() - 1;
	if (i >= n || j >= n || i < 0 || j < 0)return 0;
	if (j <= i)dp[i][j] = 0;
	if (dp[i][j] != -1)return dp[i][j];
	int val = inf;
	int k;
	for (k = i; k < j; k++) {
		val = min(val, slimes(i, k, cs) + slimes(k + 1, j, cs));
	}
	return dp[i][j] = cs[j + 1] - cs[i] + val;
}

