long long int merge(vector<int>& slimes){
    int size = slimes.size();

    vector<vector<pair<long long int, long long int>> > records = vector<vector<pair<long long int, long long int>> >(size+1, vector<pair<long long int, long long int> >(size+1, make_pair(0, 0)));


    for(int i = 0;i < size; i++){
        records[i][i+1].first = slimes[i];
       // records[i][i+1].second = slimes[i];
    }

    for(int length = 1; length <= size; length++){
        for(int i = 0; i < size; i++){
            int j = i+length;

            if(j > size)
                continue;

            if(j-i == 1){
                continue;
            }

            pair<long long int, long long int> min_value = make_pair(0, LLONG_MAX);
            for(int split = i+1; split < j; split++){
                pair<long long int, long long int> value;

                value.first = records[i][split].first + records[split][j].first;
                value.second = records[i][split].second + records[split][j].second+value.first; 

      //          cout << i << "-" << split << "-" << j << " left=" << records[i][split].second << " right=" << records[split][j].second << "\n";  

                if(value.second < min_value.second){
                   min_value = value;  
                }
            }

            records[i][j] = min_value;

  //          cout << "(" << i << "," << j << ") value=" << min_value.first << " cost=" << min_value.second << "\n";
        }
    }

    return records[0][size].second;
}

