#include<stdio.h>

typedef long long int LL;

LL dp[401][401];
int opt[401][401];

class solution {
private:
	int n;
	LL pref[401];
	LL ar[401];
	void prec() {
		pref[0] = ar[0];
		for (int i = 1; i <= n; i++) {
			pref[i] = pref[i - 1] + ar[i];
		}
	}
	void solve() {
		for (int i = 0; i < n; i++) {
			for (int j = 1; j <= n - i; j++) {
				if (i < 2) {
					dp[j][j + i] = pref[j + i] - pref[j - 1];
					if (i == 0) dp[j][j] = 0;
					opt[j][j + i] = j;
				}
				else {
					dp[j][j + i] = ~(1ll << 63);
					for (int k = j; k < j + i; k++) {
						if (dp[j][k] + dp[k + 1][j + i] < dp[j][j + i]) {
							dp[j][j + i] = dp[j][k] + dp[k + 1][j + i];
							opt[j][j + i] = k;
						}
					}
					dp[j][j + i] += pref[j + i] - pref[j - 1];
				}
			}
		}
	}
public:
	solution() {
		scanf("%d", &n);
		ar[0] = 0;
		for (int i = 1; i <= n; i++) {
			scanf("%lld", &ar[i]);
		}
		prec();
		solve();
		printf("%lld\n", dp[1][n]);
	}
};

