ll f(int low, int top){
	if(low==top){
		return dp[low][top];
	}
	if(dp[low][top]!=-1LL){
		return dp[low][top];
	}
	dp[low][top] = f(low,low)+f(low+1,top)+sum[top];
	if(low>0) dp[low][top] -= sum[low-1];
	FOR(i,low,top+1){
		ll aux = sum[top];
		if(low>0) aux-= sum[low-1];
		dp[low][top] = min(f(low,i)+f(i+1,top)+aux,dp[low][top]);
	}
	return dp[low][top];
}

