class Solve {
public:
    int N;
    vector<ll> a;
    vector<ll> SUM;
    vector<vector<ll> > dp;

    void input() {
        cin >> N;
        a.resize(N);
        rep(i, 0, N) cin >> a[i];
        dp.resize(N, vector<ll>(N, -1));
        SUM.resize(N + 1);
        SUM[0] = a[0];
        for (int i = 1; i < N; ++i) {
            SUM[i] = SUM[i - 1] + a[i];
        }

    }

    ll rec(int i, int j) {
        if (dp[i][j] != -1) return dp[i][j];

        ll ret = INFl;
        if (i == j) return 0;
        if (i + 1 == j) return a[i] + a[j];

        for (int k = i; k < j; ++k) {
            ll tmp = rec(i, k) + rec(k + 1, j);
            ll more = 0;
            if (i == 0) more = SUM[j];
            else more = SUM[j] - SUM[i - 1];

            tmp += more;

            chmin(ret, tmp);
        }

        return dp[i][j] = ret;
    }

    void solve() {
        input();

        ll ans = rec(0, N - 1);
        cout << ans << endl;

    }
};


