uint64_t dfs(const vector<uint64_t>& a, const uint32_t l, const uint32_t r){
	if(l == r) return a[l];

	uint64_t ans = UINT64_MAX;
	uint64_t lsum = 0;
	uint64_t rsum = accumulate(a.begin() + l, a.begin() + r + 1, (uint64_t)0);

	for(uint32_t d=l; d<r; d++) {
		lsum += a[d]; 
		rsum -= a[d]; 
		ans = min(ans, lsum + dfs(a, l, d) + rsum + dfs(a, d+1, r));
	}
	//cout << l << "-" << r << ":" << ans << endl;
	return ans;
}


