ll dfs(const vector<ll>& c, int l, int r) {
    // [l,r)
    if (r - l == 1) {
        return dp[l][r] = 0;
    }
    if (dp[l][r] >= 0) {
        return dp[l][r];
    }
    ll res = INF;
    rep(i, l + 1, r) {
        ll left_cost = dfs(c, l, i);
        ll right_cost = dfs(c, i, r);
        res = min(res, left_cost + right_cost + c[r] - c[l]);
    }
    return dp[l][r] = res;
}

