using namespace ValLib;
using namespace vmath;

int N;
vector<ll> a;
vector<pair<ll, ll>> memo; // value, 累積値

int makeKey(int a, int b, int c) {
	int key = a;
	key *= 401;
	key += b;
	key *= 401;
	key += c;
	return key;
}

constexpr ll INF = 1000000000000000000ll;

pair<ll, ll> solve(int left, int center, int right) {

	assert(center - left > 0);
	assert(right - center > 0);

	int key = makeKey(left, center, right);
	if (memo[key].first > 0) {
		return memo[key];
	}

	pair<ll, ll> leftVal = make_pair(INF, INF);
	if (center - left == 1) {
		leftVal = pair<ll, ll>(a[left], 0ll);
	} else {
		for (int i = left + 1; i < center; ++i) {
			pair<ll, ll> val = solve(left, i, center);
			if (val.second < leftVal.second) {
				leftVal = val;
			}
		}
	}
	pair<ll, ll> rightVal = make_pair(INF, INF);
	if (right - center == 1) {
		rightVal = pair<ll, ll>(a[center], 0ll);
	} else {
		for (int i = center + 1; i < right; ++i) {
			pair<ll, ll> val = solve(center, i, right);
			if (val.second < rightVal.second) {
				rightVal = val;
			}
		}
	}

	pair<ll, ll> result = pair<ll, ll>(
		leftVal.first + rightVal.first,
		leftVal.first + rightVal.first + leftVal.second + rightVal.second
	);

	memo[key] = result;
	return result;
}

int main() {
	std::ios::sync_with_stdio(false);

	memo.resize(400 * 401 * 401 + 400 * 401 + 400 + 1);

	in(N);
	inr(a, N);

	pair<ll, ll> result = make_pair(INF, INF);
	for (int i = 1; i < N; ++i) {
		pair<ll, ll> val = solve(0, i, N);
		if (val.second < result.second) {
			result = val;
		}
	}
	out(result.second);

	getchar();
}

