ll recurse(int l , int r , vector<ll> &arr)
{
    if(l==r) return 0;
    else
    {
        if(dp[l][r] != -1) return dp[l][r];
        else
        {
            ll min_cost = LLONG_MAX;
            for(int i = l ; i < r ; i++ )
            {
                if(l-1 >0) min_cost = min(min_cost,recurse(l,i,arr) + recurse(i+1,r,arr) + prefix_sum[r] - prefix_sum[l-1]);
                else min_cost = min(min_cost,recurse(l,i,arr) + recurse(i+1,r,arr) + prefix_sum[r]);
            }
            return dp[l][r] = min_cost;
        }
    }
}

