const int Max = 402, inf = 1e17;
int arr[Max], memo[Max][Max], prefix[Max];

int solve(int l, int r) {
    if(l > r) return inf;
    if(l == r) return 0;
    if(l+1 == r) return arr[l] + arr[r];
    if(memo[l][r] != -1) return memo[l][r];
    int res = inf;
    for(int split = l; split < r; ++split) {
        res = min(res, solve(l, split) + solve(split+1, r));
    }
    return memo[l][r] = res + prefix[r] - (l-1 >= 0 ? prefix[l-1] : 0);
}

