long long int Search(int n, vector<long long int> a, vector<bool> alive)
{
	DebugPrint(a, a.size());
	if (n == 1) {
		return 0;
	}
	long long int min_value = 1000000000LL * 400 + 1;
	int left = 0;
	for (int i = 1; i < (int)a.size(); ++i) {
		if (alive[i]) {
			long long int save = a[i];
			a[left] += save;
			a[i] = 0;
			alive[i] = false;
			long long int result = Search(n - 1, a, alive) + a[left];
			if (min_value > result) {
				min_value = result;
			}
			alive[i] = true;
			a[i] = save;
			a[left] -= save;
			//cout << i << " " << a[left] << " + " << a[i] << " " << result << endl;
			left = i;
		}
	}
	return min_value;

}

