#include<bits/stdc++.h>
using namespace std;
vector<long long> sum;
vector<vector<long long>> dp;
long long solve(vector<long long>&v, int i, int j)
{
    if(i > j)
        return 0;
    if(i == j)
        return 0;
    if(i + 1 == j)
        return (long long)v[i] + v[j];
    if(dp[i][j] != -1)
        return dp[i][j];
    else
    {
        long sumij = sum[j] - (i - 1 >= 0 ? sum[i - 1] : 0);
        long long cost = LONG_MAX;
        for(int k = i; k < j; k++)
        {
            cost = min(cost, solve(v, i, k) + solve(v, k + 1, j) + sumij);
        }
        dp[i][j] = cost;
        return cost;
    }
    return LONG_MAX;
}

int main()
{
    int n;
    cin >> n;
    vector<long long> v(n);
    sum = vector<long long> (n);
    for(int i = 0; i < n; i++)
        cin >> v[i];
    dp = vector<vector<long long>> (n, vector<long long>(n, -1));
    for(int i = 0; i < n; i++)
    {
        if(i == 0)
            sum[0] = (long long)v[0];
        else
            sum[i] = sum[i - 1] + v[i];
    }
    cout << solve(v, 0, v.size() - 1);
    return 0;
}
