using namespace std;
int n;
vector<pair<ll, int>>a;
ll memo[401][401][401];
ll solve(int left, int right){
    if(left==right){
        return 0;
    }
    if(left > right)
        return 9999999;
    ll &ans = memo[a[left].s][a[right].s][a[(left+right)/2].s];
    if(ans != -1)
        return ans;
    pair<ll, int> first, second;
    first = a[left];
    second = a[left+1];
    a[left+1].f = first.f+second.f;
    ans = a[left+1].f+solve(left+1, right);
    a[left+1].f = second.f;
    first = a[right];
    second = a[right-1];
    a[right-1].f = first.f+second.f;
    ans = min(ans, a[right-1].f+solve(left, right-1));
    a[right-1].f = second.f;
    return ans;
}
int main()
{
    cin >> n;
    a.resize(n);
    memset(memo, -1, sizeof(memo));
    for(int i = 0; i < n; ++i){
        cin >> a[i].f;
        a[i].s = i;
    }
