ll recurse(ll i, ll j, const vector<ll>& arr, const vector<ll>& prefix, vector<vector<ll>>& dp) {
    if (i >= j) {
        return 0;
    }
    if (i == j-1) {
        return arr[i] + arr[j];
    }

    if (dp[i][j] != -1) {
        return dp[i][j];
    }

    ll cost = prefix[j];
    if (i > 0) {
        cost = cost - prefix[i-1];
    }
    ll added = LLONG_MAX;
    for (ll k = i; k < j; k++) {
        ll temp = recurse(i, k, arr, prefix, dp) + recurse(k+1, j, arr, prefix, dp);
        added = min(added, temp);
    }
    return dp[i][j] = cost + added;
}

