ll func(vvl &DP, vvl &used, vl &B, ll L, ll R) {
  if (L == R)
    return 0;
  if (used[L][R])
    return DP[L][R];
  used[L][R] = 1;
  ll res = llINF;
  FOR(c, L, R) {
    res = min(res, func(DP, used, B, L, c) + func(DP, used, B, c + 1, R) +
                       get(B, L, R));
  }
  return DP[L][R] = res;
}

