ll solve(){

	int dp[2001][2001]={0};
	for(ll i = 0; i<n ; i++){
		ll val = a[i];
		for(ll j = i+1 ; j < n ; j ++){
			val += a[j];
			sum[i][j] = val;
		}
	}

	for(ll i = 1; i < n ; i++){
		ll r = 0, c = i;
		while(c<n){
			ll val = INT_MAX;
			for(ll pivot = r; pivot<c; pivot++){
				val = min(val, dp[r][pivot]+dp[pivot+1][c] + sum[r][c]);
			}
			dp[r][c] = val;
			r++;c++; 
		} 
	} 
	return dp[0][n-1];
}

