ll power(ll num,ll g,ll mod){
  if(g==0)return 1;
  if(g%2==1)return (num*power((num*num)%mod,g/2,mod))%mod;
  return power((num*num)%mod,g/2,mod);
}

int main(){
	ll n; cin>>n;
	vector<ll> vec(n);
	FOR0(i, n)	cin>>vec[i];
	ll result = 0;
	FOR0(i, n-1){
		vector<ll> dp(n, -1);
		FOR0(j, n)
			if(!vec[j]) dp[j] = 0;

		ll j = 0, k = 1;
		ll minval = 9999999999, index = 0;
		while(k < n){
			if(vec[j] == 0 && j+1 == k){
				dp[j] = 0;
				j++; k++;
			}else if(vec[j] == 0){
				dp[j] = 0;
				j++;
			}
			else if(vec[k] == 0){
				dp[k] = 0;
				k++;
			}else{
				dp[k] = vec[j] + vec[k];
				if(minval > dp[k]){
					minval = dp[k];
					index = k;
				}
				j++; k++;
			}
		}
		result += minval;
		ll xt = index-1;
		while(xt >= 0){
			if(dp[xt] != 0){
				dp[xt] = 0;
				break;
			}
			xt--;
		}
		FOR0(l, n){
			if(!dp[l] || l == index){
				vec[l] = dp[l];
			}
		}
	}
	cout<<result<<"\n";
}

