       if(flag[l][k]==false){
            now[k]+=f(l,k);
        }else{
            now[k]+=dp[l][k];
        }
        if(flag[k+1][r]==false){
            now[k]+=f(k+1,r);
        }else{
            now[k]+=dp[k+1][r];
        }
        mn=min(mn,now[k]);
    }
    flag[l][r]=true;
    dp[l][r]=mn+cost;
    return mn+cost;
}
