			mincost[i][i] = 0; // initially no cost
		}


		REP(S, 2, n + 1) { // iterates interval size, from size 2
			REP(L, 0, n) { // iterates left bound
				int R = L + S - 1; // R is inclusive
				if (R >= n) {
					continue;
				}

				slimesize[L][R] = slimesize[L][L] + slimesize[L + 1][R];

				REP(split, L, R) {
