namespace { // cumsum

template <typename U, typename T, typename InputIt>
std::vector<U> cumsum(InputIt first, InputIt last, T init) {
  std::vector<U> sum((last-first)+1);
  sum[0] = static_cast<U>(init);
  size_t i = 0;
  for (auto iter = first; iter != last; ++iter, ++i) {
    sum[i+1] = sum[i] + *iter;
  }
  return sum;
}

