void solve(int N, vector<lli> const &As) {
  auto const sum = cumsum<lli>(begin(As), end(As), 0);
  vector<vector<lli>> dp(N+1, vector<lli>(N+1, infty<lli>));
  REP(i, N) { dp[i][0] = dp[i][1] = 0; }
  FOR(len, 2, N) for (int i = 0; i + len <= N; ++i) {
    int const j = i + len;
    FOR(k, i, j-1) {
