struct CumulativeSum{
    vector<int> data;
    CumulativeSum(int sz) : data(sz, 0) {};
    void add(int k, int x){
        data[k] += x;
    }
    void build(){
        for(int i = 1; i < data.size(); i++){
            data[i] += data[i - 1];
        }
    }
    int query(int k){
        if(k < 0) return 0;
        return (data[min(k, (int)data.size() - 1)]);
    }
    int query(int l, int r){
        return query(r - 1) - query(l - 1);
    }
};

int n;
int a[410];
int dp[410][410];
CumulativeSum cs(410);

int calc(int l, int r){
    if(l > r) return INF;
    if(l == r) return dp[l][r] = 0;
    if(dp[l][r] != -1) return dp[l][r];
    int res = INF;
    rep(k, l, r){
        int tmp = calc(l, k) + calc(k + 1, r) + cs.query(l, k + 1) + cs.query(k + 1, r + 1);
        res = min(res, tmp);
    }
    return dp[l][r] = res;
}

