using vl = vector<ll>;
using vvi = vector<vector<int>>;
using vvl = vector<vector<ll>>;

template<typename T>
struct CumulativeSum {
    vector<T> s;
    CumulativeSum(const vector<T> &nums) {
        int n = nums.size();
        s.resize(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            s[i + 1] = s[i] + nums[i];
        }
    }
    // [l, r), l and r is 0-indexed.
    T sum(int l, int r) {
        return s[r] - s[l];
    }
};

void Main() {
	int N; cin >> N;
	vl a(N);
	REP(i,N) cin >> a[i];
	CumulativeSum<ll> cs(a);

	// vvl dp(N, vl(N, 0));
	vvl memo(N, vl(N + 1));
	vector<vector<bool>> done(N, vector<bool>(N + 1));
	auto dp = [&](auto dp, int l, int r) {
		if (done[l][r]) return memo[l][r];
		ll sum = cs.sum(l, r);
		ll ans = numeric_limits<ll>::max();
		FOR(i, l + 1, r) {
			chmin(ans, dp(dp, l, i) + dp(dp, i, r) + sum);
		}
		if (ans == numeric_limits<ll>::max()) {
			ans = 0;
		}
		done[l][r] = true;
		memo[l][r] = ans;
		return ans;
	};
	cout << dp(dp, 0, N) << endl;
}

