	while(len)
	{
		ll mn = 1e13;
		ll sum[len] = {};

		loop(i,0,len)
		{
			sum[i] = arr[i] + arr[i+1];
			if(sum[i]<mn)
				mn = sum[i];
		}

		ll lr = 1e13;
		ll idx = -1;
		loop(i,0,len)
		{
			if(sum[i]==mn)
			{
				ll temp = 1e13;
				if((i-1)>=0)
