long long int minCost(long long int arr[], int n) 
{ 
    priority_queue<long long int, vector<long long int>, greater<long long int> > pq(arr, arr + n); 
    long long int res = 0; 
    while (pq.size() > 1) { 
        long long int first = pq.top(); 
        pq.pop(); 
        long long int second = pq.top(); 
        pq.pop(); 
        res += first + second; 
        pq.push(first + second); 
    } 

    return res; 
} 
