int sm(int i, int j) {
	int ans = 0;
	for (int k = i; k <= j; k++)
		ans += a[k];
	return ans;
}

int solve(int i, int j) {
	if (i == j)
		return a[i];
	if (i > j)
		return 0;
	if (~dp[i][j])
		return dp[i][j];
	int ans = 4e18;
	for (int k = i; k < j; k++) {
		int l = solve(i, k);

		int r = solve(k + 1, j);
		ans = min(ans, l + r + sm(i, k) + sm(k + 1, j));
	}

	return dp[i][j] = ans;
}

