    for (auto &v : V) cin >> v;

    for (int i = 1; i <= n; i++){
        P[i] = P[i - 1] + V[i -1];
    }

    ll ans = solve(0, n - 1);

    for (auto a : DP){
        cout << endl;
        for  (auto x : a){
            cout << x << " ";
        }
    }

    cout << endl << endl;

    cout << ans;
    return 0;
}

