	// state -- only depends on the portion of the array which is remaining
	// dp[i][j] -- minimum cost to combine array from a[i]....a[j]

	vector<ll> pre(n,0);
	pre[0] = a[0];
	for(int i = 1; i < n; i++) pre[i] = pre[i-1]+a[i];
	vector<vector<ll>> dp(n,vector<ll>(n,1e18));
