					ll left = pre[k] - (i == 0? 0 : pre[i-1]);
					ll right = pre[j] - pre[k];
					dp[i][j] = min(dp[i][j], left + right + dp[i][k] + dp[k+1][j]);
				}
			}
		}
	}
	cout << dp[0][n-1] << endl;

}	


