typedef long long int ll;

const int N = (int) 4e2 + 10;
const ll oo = (ll) 1e18;

int n;
int a[N];
ll prefix[N];
ll memo[N][N];

ll sum(int l, int r) {
    ll ans = prefix[r];
    if(l > 0) ans -= prefix[l - 1];
    return ans;
}

ll dp(int l, int r) {
    if(l == r) return 0;
    ll &ans = memo[l][r];
    if(ans != -1) return ans;
    ans = oo;
    for(int i = l; i < r; ++i) {

        ll tot=sum(l,r);
        ll cur = tot + dp(l, i) + dp(i + 1, r);

        ans = min(ans, cur);
    }
    return ans;
}

void solve() {
    cin >> n;
    for(int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    memset(memo, -1, sizeof(memo));
    for(int i = 0; i < n; ++i) {
        prefix[i] = a[i];
        if(i > 0) prefix[i] += prefix[i - 1];
    }
    cout << dp(0, n - 1) << endl;
}

