        for (int j=1; j<arr.size(); ++j){
            ll val = arr[j-1] + arr[j];
            if (val < cur_min){
                cur_min = val;
                pos = j;
            }
        }
        dp[i] = dp[i+1] + cur_min;
        vector<ll>::iterator it = arr.begin();
        arr.erase(it+pos-1, it+pos+1);
        arr.insert(it+pos-1,cur_min);
        // cout << "The vector elements are: ";  
