using namespace std;

void helper(const vector<long long>& slimes, vector<vector<long long>>& dp, int l, int r) {
	if (l > r) return;
	if (l == r) {
		dp[l][r] = 0;
		return;
	}
	if (dp[l][r] != numeric_limits<long long>::max()) return;
	if (r - l == 1) {
		dp[l][r] = slimes[l] + slimes[r];
	} else {
		long long sum = 0;
		for (int i = l; i <= r; i++) sum += slimes[i];
		for (int i = l; i < r; i++) {
			helper(slimes, dp, l, i);
			helper(slimes, dp, i + 1, r);
			dp[l][r] = min(dp[l][r], dp[l][i] + dp[i + 1][r] + sum);
		}
	}
}

int main (int argc, char* argv[]) {
	int n;
	cin >> n;

	vector<long long> slimes(n);
	for (int i = 0; i < n; i++) {
		cin >> slimes[i];
	}

	vector<vector<long long>> dp(n, vector<long long>(n, numeric_limits<long long>::max()));
	helper(slimes, dp, 0, n - 1);
	cout << dp[0][n - 1] << endl;
}

