int dp[3001][3001];
int sums[3001][3001];

int solve(int *a, int i, int j)
{
	if (i == j)
		return 0;
	if (dp[i][j] != -1)
		return dp[i][j];

	int minCost = inf;

	for (int k = i; k < j; k++)
	{
		minCost = min(minCost, solve(a, i, k) + solve(a, k + 1, j) + sums[i][j]);
	}

	return dp[i][j] = minCost;
}

void preProcess(int *a, int n)
{
	for (int i = 1; i <= n; i++)
	{
		for (int j = i; j <= n; j++)
			sums[i][j] = a[j] + ((i == j) ? 0 : sums[i][j - 1]);
	}
}


