			for(int k = opt[j][i-1]; k<=min(opt[j+1][i-1],i+j-2); k++)
			{
				ll tans = pre[j+i-1] - pre[j-1] + dp[j][k-j+1] + dp[k+1][j+i-k-1];
				if(tans<ans){
					ans = tans;
					optx = k;
				}
			}
			opt[j][i] = optx;
			dp[j][i] = ans;
		}
	}
	cout << dp[1][n] << endl;
}

