template <class T> bool chmin(T &a, T b) { if (a > b) {a = b; return true; } return false; }
template <class T> bool chmax(T &a, T b) { if (a < b) {a = b; return true; } return false; }

const ll INF = 100000000000000000;
const int MAX = 410;
ll N;
vector<ll> A;

/*
 * dp[l][r] := [l:r)までのスライムを合体させる最小コスト
 * dp[l][r] = dp[l][r] = A[l] if len == 1
 * dp[l][r] = sum(A[l:r]) + min([dp[l][k] + dp[k][r] for k in [l+1:r)]) if len >= 2
 */
ll dp[MAX][MAX] = {0};
ll acc[MAX] = {0};

void input() {
  cin >> N;
  ll a;
  acc[0] = 0;
  loop(n,0,N) {
    cin >> a;
    A.push_back(a);
    acc[n+1] = acc[n] + A[n];
  }
}

void solve() {
  for (int len=1; len<=N; len++) {
    for (int l=0; l+len<=N; l++) {
      if (len==1) { continue; }
      int r = l+len;
      ll self = acc[r] - acc[l];
      ll child = INF;
      for (int k=l+1; k<r; k++) {
        chmin(child, dp[l][k] + dp[k][r]);
      }
      dp[l][r] = self + child;
    }
  }
  cout << dp[0][N] << endl;
}

int main() {
  // cout.precision(15);
  input();
  solve();
  return 0;
}

