ll solve(vector<ll>a, ll cost){
    ll n = a.size();
    if(n == 1){
        return cost;
    }else{
        vector<ll>ret;
        ll ptr = 0;
        ll tmp = INF;
        rep(i, n-1){
            if(tmp > a[i] + a[i+1]){
                ptr = i;
                tmp = a[i] + a[i+1];
            }  
        }
        rep(i, n){
            if(i == ptr){
                ret.push_back(a[i]+a[i+1]);
                i++;
            }else{
                ret.push_back(a[i]);
            }
        }
        return solve(ret, cost+tmp);
    }
}

