long long dp(int l, int r) {
	if (l == r) return 0;
	if (res[l][r] != -1) return res[l][r];
	long long best = LLONG_MAX;
	long long s2 = 0, s1 = 0;
	for (int i = l; i <= r; i++) s2 += a[i];
