void preC(){
	pre[0] = arr[0];
	for(ll i = 1;i<N;i++)
		pre[i] = arr[i]+pre[i-1];
}

ll sum(ll i, ll j){
	if (i == 0)return pre[j-1];
	return pre[j-1]-pre[i-1];
}

ll solve(ll i, ll j){
	if (i>j) return 0;

	if(dp[i][j] != -1) return dp[i][j];

	if (i+1 == j) return dp[i][j] = 0;
	ll ans = 1e12;
	for(ll k = i+1;k<j;k++){
		ans = min(ans, sum(i,j) + solve(i,k) + solve(k,j));
	}
	dp[i][j] = ans;
	return dp[i][j];
}
