ll solve_by_dp(vector<ll> &a, ll i, ll j){
  if(j==i){
    return 0;
  }
  else if(dp[i][j]!=-1)
    return dp[i][j];
  else{
    ll ans = LLONG_MAX;
    for(ll k=i+1; k<=j; k++){
      ll part1 = solve_by_dp(a, i, k-1);
      ll part2 = solve_by_dp(a, k, j);
      ll curr_ans = part1 + part2 + sumij[i][k-1] + sumij[k][j];
      // cout<<curr_ans<<endl;
