ll d[410][410];
// bscht[x][y] := 半開区間 [x, y) の dp をすでに求めたかどうか
bool bscht[410][410];

ll dp( int x, int y ){
	if( y - x == 1 ) return 0;
	if( bscht[x][y] ) return d[x][y];
	else bscht[x][y] = true;
	ll sum = s[y]-s[x];
	ll cost = infll;
	for( int k = x+1; k < y; ++k ){
		cost = min( cost, dp(x, k)+dp(k, y) );
	}
	return d[x][y] = sum + cost;
}

