long solve(int beg, int end) {
    if (beg == end) return 0;
    if (beg + 1 == end) return a[beg] + a[end];
    if (dp[beg][end] != -1) return dp[beg][end];

    long ans = std::numeric_limits<long>::max();
    for (int i = beg; i < end; ++i) {
        long curr = solve(beg, i) + solve(i+1, end);
        curr += ps[i];
        if (beg != 0) curr -= ps[beg - 1];
        curr += ps[end] - ps[i];
        ans = min(ans, curr);
    }
    dp[beg][end] = ans;
    return ans;
}

