ll solve(int l, int r){
	if(l >= r) return 0;
	if(dp[l][r] != -1) return dp[l][r];

	ll ans = inf;

	rep(i,l,r){
		ans = min(ans, solve(l, i) + solve(i+1, r));
	}

	return dp[l][r] = ans + sum[r] - sum[l-1];
}

