LL dp[MAX_N][MAX_N], opt[MAX_N][MAX_N];

struct Solution {
    Solution(int) {
        int N;
        read(N);
        vector<int> a(N), prefix(N);
        for(int i : range(N)) {
            read(a[i]);

            prefix[i + 1] = a[i] + prefix[i];
            dp[i][i + 1] = 0;
            opt[i][i + 1] = i;
        }

        for(int i : range(N - 1, -1, -1)) {
            for(int j : range(i + 2, N + 1)) {

                int l = opt[i][j - 1];
                int r = opt[i + 1][j] + 1;

                dp[i][j] = LLINF;
                for(int k : range(l, r)) {
                    auto val = dp[i][k] + dp[k][j] + prefix[j] - prefix[i];

                    if(val < dp[i][j]) {
                        dp[i][j] = val;
                        opt[i][j] = k;
                    }
                }
            }
        }
        print(dp[0][N]);
    }
};

