ll get(ll L, ll R){
	return pref[R] - pref[L-1];
}

ll find_min(ll i, ll j, vector<vector<ll>>& dp){
	if(i == j)
		return dp[i][j] = 0;
	if(i+1 == j)
		return dp[i][j] = arr[i]+arr[j];

	if(dp[i][j] != -1)
		return dp[i][j];

	ll mini = INF;
	for(ll k=i;k<j;k++){
		ll cnt = get(i, j) + find_min(i, k, dp) + find_min(k+1, j, dp);
		if(cnt < mini)
			mini = cnt;
	}

	return dp[i][j] = mini;
}

