int main(){
    int N;
    std::cin >> N;
    std::vector<int> slime(N);
    std::vector<ll> sum(N + 1, 0); // 累積和sum[i] : slime[i - 1]までの和
    for(int i = 0; i < N; i++){
        std::cin >> slime[i];
    }
    sum[1] = slime[0];
    for(int i = 2; i <= N; i++){
        sum[i] += sum[i - 1] + slime[i - 1];
    }

    // dp[i][j] : i ~ j番目のスライムについて合体させていったときの最小コスト
    std::vector<std::vector<ll>> dp(N, std::vector<ll>(N, INF));
    for(int i = 0; i < N; i++) dp[i][i] = 0;

    for(int offset = 1; offset < N; offset++){
        for(int l = 0; l < N; l++){
            int r = l + offset;
            if(r > N - 1) continue;

            for(int mid = l; mid < r; mid++){
                // sum[r] - sum[l - 1]は[l, r]に含まれる値の和
                dp[l][r] = std::min(dp[l][r], dp[l][mid] + dp[mid + 1][r] + sum[r + 1] - sum[l]);
            }
        }
    }    

    std::cout << dp[0][N - 1] << std::endl;
    return 0;
}

