const ll MOD = 1000000007;
const int MAXN = 401;
const ll INF = (int)1e18;
ll dp[401][401];

inline ll cost(int left,int right){
	return pref[right] - ((left>0)?pref[left-1]:0);
}

ll DP(int left,int right){
	if(left == right){
		return 0;
	}
	if(dp[left][right] != -1)return dp[left][right];
	ll mnCST = INF;
	FORE(i,left,right-1){
		mnCST = min(mnCST,DP(left,i) + DP(i+1,right) + cost(left,right));

		if(mnCST != INF)mnCST %= MOD;
	}

	dp[left][right] = mnCST;
	return mnCST;
}


