    min = INT64_MAX;
    min_index = -1;
    cin >> n;
    vector<long long> slimes;

    for (int i = 0; i < n; i++) {
        cin >> elem;
        slimes.push_back(elem);
    }

    for (int step = 0; step < n - 1; step++) {
        for (int i = 1; i < slimes.size(); i++) {
            dp[i - 1] = slimes[i - 1] + slimes[i];
        }

        for (int i = 0; i < n - 1; i++) {
            min > dp[i] ? min = dp[i], min_index = i : dp[i]; 
        }

        slimes[min_index] = min;
        slimes.erase(slimes.begin() + min_index + 1);
        total += min;

        fill(begin(dp), end(dp) + n, INT64_MAX);
        min = INT64_MAX;
    }

    cout << total;

    return 0;
}

