int N;
vector<ll> a;
vector<vector<ll>> acc;
vector<vector<ll>> dp; // key1:幅, key2:left, value:生成コストの最小値

constexpr ll INF = 1000000000000000000ll;

int main() {
	std::ios::sync_with_stdio(false);

	in(N);
	inr(a, N);

	resize(acc, N + 1, N);
	resize(dp, N + 1, N);

	// 累積和計算
	for (int w = 1; w <= N; ++w) {
		for (int i = 0; i < N - w + 1; ++i) {
			acc[w][i] = acc[w - 1][i] + a[i + w - 1];
		}
	}

	// 最小コスト計算
	for (int w = 2; w <= N; ++w) {
		for (int i = 0; i < N - w + 1; ++i) {
			ll minVal = INF;
			for (int j = 1; j < w; ++j) {
				ll val = acc[j][i] + dp[j][i] + acc[w - j][i + j] + dp[w - j][i + j];
				if (val < minVal) {
					minVal = val;
				}
			}
			dp[w][i] = minVal;
		}
	}

	out(dp[N][0]);

	getchar();
}

