        cin >> slimes[i];
    }
    S[0] = slimes[0];
    for (int i = 1; i < N; i++) {
        S[i] = S[i - 1] + slimes[i];
    }
    auto sum = [&](int l, int r) -> long {
        if (l > r) return 0;
        return S[r] - (l == 0 ? 0 : S[l - 1]);
    };
    const long INF = 1e16;
    vector<vector<long>> dp(N + 1, vector<long>(N + 1, INF));
    for (int i = 0; i < N; i++) {
        dp[i][i] = 0;
    }
    for (int L = N - 1; L >= 0; L--) {
        for (int R = L; R < N; R++) {
            for (int k = L; k < R; k++) {
                long cost = sum(L, R);
                dp[L][R] = min(dp[L][R], dp[L][k] + dp[k + 1][R] + cost);
            }
        }
    }
    cout << dp[0][N - 1] << endl;
    return 0;
}

