class mint {
 private:
  int _num,_mod;
  mint set(int num){ 
      _num = num ;
      if(_num>=0) _num%=_mod;
      else _num+=(1-(_num+1)/_mod)*_mod; 
      return *this;
  }
  int mpow(int a,int n){
      int ans=1;
      while(n){
          if(n&1) ans*=a;
          a*=a;
          n/=2;
      }
      return ans;
  }
  int imod(int n){return mpow(n , _mod-2);}
 public:
  mint(){ _num = 0;_mod=mod; }
  mint(int num){ _mod = mod; _num = (num+(1LL<<30)*mod) % mod; }
  mint(int num,int M){ _mod=M;_num=(num+(1LL<<30)*mod)%_mod; }
  mint(const mint &cp){_num=cp._num;_mod=cp._mod;}
  mint operator= (const int x){ return set(x); }
  mint operator+ (const int x){ return mint(_num + (x % _mod) , _mod); }
  mint operator- (const int x){ return mint(_num - (x % _mod), _mod); }
  mint operator* (const int x){ return mint(_num * (x % _mod) , _mod); }
  mint operator/ (int x){ return mint(_num * imod(x) , _mod);}
  mint operator+=(const int x){ return set(_num + (x % _mod)); }
  mint operator-=(const int x){ return set(_num - (x % _mod)); }
  mint operator*=(const int x){ return set(_num * (x % _mod)); }
  mint operator/=(int x){ return set(_num * imod(x));}
  mint operator+ (const mint &x){ return mint(_num + x._num , _mod); }
  mint operator- (const mint &x){ return mint(_num - x._num , _mod);}
  mint operator* (const mint &x){ return mint(_num * x._num , _mod); }
  mint operator/ (mint x){ return mint(_num * imod(x._num) , _mod);}
  mint operator+=(const mint &x){ return set(_num + x._num); }
  mint operator-=(const mint &x){ return set(_num - x._num); }
  mint operator*=(const mint &x){ return set(_num * x._num); }
  mint operator/=(mint x){ return set(_num * imod(x._num));}

  bool operator<(const mint &x){return _num<x._num;}

  friend mint operator+(int x,const mint &m){return mint(m._num + (x % m._mod) , m._mod);}
  friend mint operator-(int x,const mint &m){return mint(m._num - (x % m._mod) , m._mod);}
