  for(int i=0; i<n; i++){
    for(int j=i; j<n; j++){
      if(i==j){
        sumij[i][j] = a[j];
        continue;
      }
      sumij[i][j] = a[j] + sumij[i][k-1] + sumij[k][j];
    }
  }

