#include <bits/stdc++.h>
using namespace std;
using LL = long long;

LL dp[455][455];
LL P[455];

// l ～ r番目 までの 総和
// @param l: 先頭要素の場所.
// @param r: 末尾要素の場所.
// @return : 総和を返却.
LL sum(int l, int r){
    if(l == 0) return P[r];
    else       return P[r] - P[l - 1];
}

// スライムを合体させるための最小コストを計算.
// @param l: 先頭要素の場所.
// @param r: 末尾要素の場所.
// @return : 再帰処理を行う.
LL recursive(int l, int r){
    if(l > r)          return 0;
    if(l == r)         return 0;
    if(dp[l][r] != -1) return dp[l][r];
    LL ans = LL(1e18);
    for(int i = l; i < r; i++) ans = min(ans, recursive(l, i) + recursive(i + 1, r) + sum(l, r));
    return (dp[l][r] = ans);
}

int main(){

    // 1. 入力情報取得.
    int N;
    scanf("%d", &N);
    for(int i = 0; i < N; i++) scanf("%lld", &P[i]);
    for(int i = 1; i < N; i++) P[i] += P[i - 1];

    // 2. dp更新.
    memset(dp, -1, sizeof(dp));
    LL ans = recursive(0, N - 1);
    // for(int i = 0; i < N; i++){
    //     for(int j = 0; j < N; j++) printf("%lld ", dp[i][j]);
    //     printf("\n");
    // }

    // 3. 出力.
    printf("%lld\n", ans);
    return 0;
}

