const int N = 400;
int n;
ll a[N];

pair<ll, ll> dp[N][N][N];

pair<ll, ll> calc(int i, int j, int k) {
    if(i == n) return {INF, 0};
    if(j == 0 && k == 0) return {0, a[i]};

    pair<ll, ll> &r = dp[i][j][k];
    if(r.fst != -1) return r;

    pair<ll, ll> res = {INF, 0};

    if(k) res = calc(i + 1, j + 1, k - 1);

    pair<ll, ll> izq, der;

    if(i == 0 || j == 0) izq = {0, 0};
    else izq = calc(i - j, 0, j - 1);

    if(i == n - 1 || k == 0) der = {0, 0};
    else der = calc(i + 1, 0, k - 1);

    ll cand = izq.fst + der.fst + 2 * min(izq.snd, der.snd) + a[i] + max(izq.snd, der.snd);
    if(j && k) cand += a[i];
    if(cand < res.fst) {
        res.fst = cand;
        res.snd = min(izq.snd, der.snd) + a[i] + max(izq.snd, der.snd);
    }
    // cout << i << " " << j << " " << k << " " << res.fst << " " << res.snd << endl;
    return r = res;
}

