void solve()
{
	ll n;
	cin>>n;
	vi a(n);
	for(ll i=0;i<n;++i)
	{
		cin>>a[i];
	}
	vvi cost(n,vi(n,INF)),val(n,vi(n));
	for(ll i=0;i<n;++i)
	{
		val[i][i]=a[i];
		cost[i][i]=0;
	}
	for(ll l=2;l<=n;++l)
	{
		for(ll i=0;i<=n-l;++i)
		{
			ll j=i+l-1;
			for(ll k=i;k<j;++k)
			{
				ll temp=cost[i][k]+cost[k+1][j]+val[i][k]+val[k+1][j];
