LL memo[410][410];
int visited[410][410];
LL a[410], b[410];

LL Get(int l, int r)
{
  LL res = b[r];
  if (l) res -= b[l - 1];
  return res;
}

LL Solve(int l, int r)
{
  if (l == r)
  {
    return 0;
  }

  if (visited[l][r])
  {
    return memo[l][r];
  }

  visited[l][r] = 1;

  LL ans = 1000000000000000010;
  for (int m = l; m < r; ++m)
  {
    ans = min(Solve(l, m) + Solve(m + 1, r) + Get(l, r), ans);
  }
  return memo[l][r] = ans;
}

