vector < int > l;
map < vector < int > , int > memo;

void print(vector < int > l){
    for(auto x:l) cout << x << " ";
    cout << endl;
}

int dp(vector < int > l){
    if(memo.count(l)) return memo[l];
    int ans = 1e17;

    int n = l.size(), curr, last = 0, notdone = 1;
    while(last < n and l[last] == 0) last++;


    for(int i = last + 1;i < n;++i){
        if(l[i] == 0) continue;
        notdone = 0;
        curr = l[i];
        l[last] += curr;
        l[i] = 0;
        ans = min(ans, l[last] + dp(l));
        l[last] -= curr;
        l[i] = curr;
        last = i;
    }


    if(notdone) ans = 0;
    memo[l] = ans;

    return ans;
}

