ll dp[3001][3001];
ll sum[3001][3001];

ll slimes(vector<ll>& v,int i,int j){
    if(i==j){
        return 0;
    }
    if(dp[i][j]!=-1){
        return dp[i][j];
    }
    ll minCost = 1000000000000;
    for(int k=i;k<j;k++){
        minCost = min(minCost,sum[i][j] + slimes(v,i,k) + slimes(v,k+1,j));
    }
    return dp[i][j] = minCost;
}

