class dp1
{
private:
    vector<int> val;
    vector<int> su;
    int n;

public:
    dp1(vector<int> &v1, int n1)
    {
        this->n = n1;
        this->val.resize(n);
        this->su.resize(n - 1);
        rep(i, 0, n) val[i] = v1[i];
        rep(i, 0, n - 1) su[i] = val[i] + val[i + 1];
    }
    void print()
    {
        rep(i, 0, n)
                cout
            << val[i] << " ";
        cout << endl
             << endl;
        rep(i, 0, n - 1)
                cout
            << su[i] << " ";
        cout << endl;
    }
    int minsum()
    {
        //complexity O(n)
        int mi = INF;
        rep(i, 0, n - 1)
        {
            if (su[i] != INF && mi == INF)
                mi = i;
            else if (mi != INF && su[i] < su[mi])
                mi = i;
        }
        return mi; //=INF when operations are complete
    }
    int update(int i) //, int n1)
    {
        // complexity O(n)
        int j0 = i - 1;
        while (j0 > -1 && su[j0] == INF)
            j0--;
        if (j0 > -1)
            su[j0] += val[i + 1];
        int j1 = i + 1;
        while (j1 < n - 1 && su[j1] == INF)
            j1++;
        if (j1 < n - 1)
            su[j1] += val[i];
        // n--;
        // val[i] = su[i];
        val[j0 + 1] = su[i];
        // val[i + 1] = su[i];
        val[j1] = su[i];
        su[i] = INF;
        // n1 = n;
        // cout << "exit" << endl;
        return (val[j0 + 1]);
    }
    ~dp1()
    {
        val.clear();
        su.clear();
        n = 0;
    }
};

