int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    // dp state is dp[i][j] = min cost to combine interval from i -> j
    // common idea to do with dp on interval is to start with smaller intervals
    // base case is that combining intervals of length 1 => 0
    // otherwise, to combine interval of [left, right], we look for "partition" points for the interval
    // and combine them, and actually the cost is equivalent to the cost of combining before the partition + after + the whole interval

    int n;
    cin >> n;

    vll sum(n + 2);
    rep(i,0,n) {
        cin >> sum[i];
    }
    rep(i,0,n) sum[i+1] += sum[i];

    vector<vll> dp(n + 1, vll(n + 1, 1LL << 60));

    for(int i = n - 1; i >= 0; i--) { // left point of interval
        for(int j = i; j < n; j++) { // right point of interval
            if(i == j) {
                dp[i][j] = 0;
            } else {
                ll x = sum[j] - (i == 0 ? 0 : sum[i - 1]); // sum of the interval is the cost to combine two subintervals
                for(int k = i; k < j; k++) { // we look for the optimal partition point
                    dp[i][j] = min(dp[i][j], x + dp[i][k] + dp[k + 1][j]);
                }
            }
        }
    }
    cout << dp[0][n-1] << endl;

    return 0;
}

