const int MAXN = 405;

int N;
ll A[MAXN], dp[MAXN][MAXN], pre[MAXN];

ll sum(int l, int r) {
    assert(l <= r);
    return pre[r] - (l == 0 ? 0 : pre[l - 1]);
}

ll solve(int l, int r) {
    assert(l <= r);
    if (l == r) return 0;
    if (dp[l][r] != LL_INF) return dp[l][r];
    For(m, l, r) MIN(dp[l][r], solve(l, m) + solve(m + 1, r) + sum(l, r));
    return dp[l][r];
}

int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    read(N);
    read(A, A + N);
    partial_sum(A, A + N, pre);
    FOR(l, N) FOR(r, N) dp[l][r] = LL_INF;
    writeln(solve(0, N - 1));
    return 0;
}

