int solve(int l, int r) {
	if (vis[l][r]) {
		return dp[l][r];
	}
	vis[l][r] = true;
	if (l + 1 >= r) return 0;
	int res = INF;
	for (int i = l + 1; i < r; i++) {
		chmin(res, solve(l, i) + solve(i, r));
