#include<bits/stdc++.h>
using namespace std;
typedef long long LL;
LL datas[405];
LL pref[405];
LL memo[405][405];
int n;
const LL INF=1e17;
LL solve(int L, int R)
{
	if(L==R) return 0;
	if(memo[L][R]!=-1) return memo[L][R];
	LL ret=INF;
	LL tmp=0, now=0;
	for(int z=L;z<R;z++)
	{
		if(z!=L)tmp+=(now+datas[z]);
		now+=datas[z];
		if(z==L) ret=min(ret, now+solve(z+1, R)+pref[R]-pref[z]);
		else ret=min(ret, tmp+now+solve(z+1, R)+pref[R]-pref[z]);
//		cout<<L<<" "<<R<<" : ";
//		cout<<"prefix : "<<ret<<endl;
	}
	tmp=0;
	now=0;
	for(int z=R;z>L;z--)
	{
		if(z!=R)tmp+=(now+datas[z]);
		now+=datas[z];
		if(z==R) ret=min(ret, now+solve(L, z-1)+pref[z-1]-pref[L-1]);
		else ret=min(ret, tmp+now+solve(L, z-1)+pref[z-1]-pref[L-1]);
//		cout<<L<<" "<<R<<" : ";
//		cout<<"suffix: "<<ret<<endl;
	}
	for(int z=1;z<((R-L)-1);z++)
	{
		LL tmp=(datas[L+z]+datas[L+z+1])+solve(L, L+z-1)+solve(L+z+2, R);
		LL kiri=pref[L+z-1]-pref[L-1], kanan=pref[R]-pref[L+z+1], mid=(datas[L+z]+datas[L+z+1]);
		tmp+=min((kiri+mid)*2+kanan, (kanan+mid)*2+kiri);
		ret=min(ret, tmp);
//		cout<<L<<" "<<R<<" : ";
//		cout<<"middle: "<<ret<<endl;
	}
	return memo[L][R]=ret;
}

int main()
{
	scanf("%d", &n);
	for(int a=1;a<=n;a++)
	{
		scanf("%lld", &datas[a]);
		pref[a]=datas[a]+pref[a-1];
	}
	memset(memo, -1, sizeof(memo));
	printf("%lld\n", solve(1, n));
	return 0;
}

