typedef long long ll;
typedef vector<ll> vl;

const ll INF = (ll)9e18;
int N;
vl S;
vector<vl> dp;

ll rec(int l, int r) {
	if (dp[l][r] != (ll)-1)
		return dp[l][r];
	if (l == r)
		return (ll)0;
	ll min_val = INF;
	for (int i = l; i < r; ++i) {
		ll val = rec(l, i) + rec(i + 1, r) + (S[r] - S[l - 1]);
		min_val = min(val, min_val);
	}
	return dp[l][r] = min_val;
}

int main(void) {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N;
	S.resize(N + 1, (ll)0);
	for (int i = 1; i <= N; ++i) {
		cin >> S[i];
		S[i] += S[i - 1];
	}

	dp.resize(N + 1, vl(N + 1, (ll)-1));
	ll ans = rec(1, N);

	cout << ans << '\n';
	return 0;
}

