    {
        if(l + 1 == r) return 0LL;
        if(dp[l][r] != 0LL) return dp[l][r];
        ll res = INF;
        for(int i = l+1; i < r; i++)
        {
            ll tmp = 0;
            if(l + 1 != i) tmp += rec(l, i);
            if(i + 1 != r) tmp += rec(i, r);
            res = min(res, tmp + sum[r] - sum[l]);
        }
        return dp[l][r] = res;
    };
