#include <bits/stdc++.h>

using namespace std;

const int N = 4e2+5;

const int mod = 1e9+7;

int n;
int ar[N];
long long prefix[N];
long long mem[N][N];

long long getsum(int l , int r){
    return prefix[r] - prefix[l - 1];
}

long long go(int l , int r){
    if(r - l + 1 == 2)
        return getsum(l , r);
    if(l >= r)
        return 0;
    if(~mem[l][r])
        return mem[l][r];
    long long best = 1e18;
    for(int i = l; i < r; i++){
        best = min(best , go(l , i) + go(i + 1 , r) + getsum(l , i) + getsum(i + 1 , r));
    }
    return mem[l][r] = best;
}

int main(){
    scanf("%d" , &n);
    for(int i = 1; i <= n; i++){
        scanf("%d" , &ar[i]);
        prefix[i] = ar[i] + prefix[i - 1];
    }
    memset(mem , -1 , sizeof mem);
    printf("%lld\n" , go(1 , n));
}

