vector<ll>sa[5000000];
ll a[1000001];
void build(ll s,ll e,ll i)
{
    if(s==e)
    {
        sa[i].push_back(a[s]);
        return;
    }
    ll m=(s+e)/2;
    build(s,m,2*i+1);
    build(m+1,e,2*i+2);
    sa[i]=merge(sa[2*i+1],sa[2*i+2]);
}
ll query(ll s,ll e,ll l,ll r,ll i,ll x1,ll x2)
{
    if(e<l || r<s || s>e)
        return 0;
    if(s>=l && e<=r)
    {
        ll v1= lower_bound(sa[i].begin(),sa[i].end(),x1)-sa[i].begin();

        ll v2= upper_bound(sa[i].begin(),sa[i].end(),x2-1)-sa[i].begin();
        v2--;
        ll xx=0;
        return max(xx,v2-v1+1);
    }
    ll m=(s+e)/2;
    ll ls=query(s,m,l,r,2*i+1,x1,x2);
    ll rs=query(m+1,e,l,r,2*i+2,x1,x2);
    return ls+rs;
}

