uint64_t dfs(const vector<uint64_t>& a, vector<vector<uint64_t>>& dp, const uint32_t l, const uint32_t r){
	if(dp[l][r] != 0) return dp[l][r];

	if(l == r) {
		dp[l][r] = a[l];
		return dp[l][r];
	}

	uint64_t ans = UINT64_MAX;

	for(uint32_t d=l; d<r; d++) ans = min(ans, dfs(a, dp, l, d) + dfs(a, dp, d+1, r));

	//cout << l << "-" << r << ":" << ans << endl;
	dp[l][r] = ans + accumulate(a.begin() + l, a.begin() + r + 1, (uint64_t)0);
	return dp[l][r];
}


