long long a[N];

long long dp[N][N];

bool u[N][N];

long long pref[N];

long long sum (int l, int r) {
	if (l > r) return 0ll;
	return pref[r] - (l ? pref[l - 1] : 0ll);
}

long long solve (int l, int r) {
	if (l >= r) return 0ll;
	if (r - l == 1) return sum (l, r);
	if (u[l][r]) return dp[l][r];
	u[l][r] = 1;
	dp[l][r] = INF;
	for (int k = l ; k <= r - 1 ; ++ k) {
		dp[l][r] = min (dp[l][r], solve (l, k) + solve (k + 1, r) + sum (l, r));
	}
	return dp[l][r];
}

