// dp[l][r] = minimum cost to merge from a[l] to a[r-1].
ll rec(int l, int r) {
    if (r - l == 1) return 0;
    if (r - l == 2) return a[l] + a[r-1];
    ll &res = dp[l][r];
    if (res != inf) return res;
    for (int i = l+1; i < r; ++i) {
        chmin(res, rec(l, i) + rec(i, r) + sum[r] - sum[l]);
    }
    return res;
}

