            if (i == j)
                val[i][j] = ais[i];
            else
                val[i][j] = val[i][j - 1] + ais[j];
        }
    }

    FOR(s, 1, n, 1) {
        REP(i, n) {
            if (i + s >= n) break;
            int b = i, t = i + s;
            FOR(j, b, t, 1) {
                dp[b][t] = min(dp[b][t], dp[b][j] + dp[j + 1][t] + val[b][j] + val[j + 1][t]);
            }
        }
    }

    cout << dp[0][n - 1] << endl;

    return 0;
}

