ll fnd( ll i, ll j)
{
  if(dp[i][j])return dp[i][j];
  if(j-i==1){
    return a[i]+a[j];
  }
  if(i == j) return 0;

  ll ret = inf;
  for(ll l=i;l<j;l++)
  {
    ret = min(fnd(i,l)+fnd(l+1,j)+s[j]-((i>0)?s[i-1]:0),ret);
  }
  dp[i][j]=ret;
  return dp[i][j];
}

