ll solve(ll i, ll j){
    if(i == j){
        return 0;
    }
    if(dp[i][j] != -1){
        return dp[i][j];
    }
    ll ans = 1e18;
    for(ll k=i;k<j;k++){
        ans = min(ans, solve(i,k) + solve(k+1,j) + prefix[j] - prefix[i-1]);
        dp[i][j] = ans;
    }
return dp[i][j];
}
