long long DFS(long long L, long long R) {
	if (L + 1 == R) return 0;
	if (used[L][R]) return DP[L][R];
	long long RET = 1000000000000000000;
	for (int i = L + 1; i < R; i++) RET = min(RET, DFS(L, i) + DFS(i, R));
	used[L][R] = true;
	return DP[L][R] = RET + SUM[R] - SUM[L];
}

