ll calc(int l, int r){
  // cout << "l:" << l << " r:" << r << endl;
  if(dp[l][r]) {
    // cout << "dp[" << l << "][" << r << "]:" << dp[l][r] << endl;
    // cout << endl;
    return dp[l][r];
  }
  if(l == r) {
    // cout << 0 << endl;
    // cout << endl;
    return 0;
  }
  ll ans = 1e18;
  for(int i = l + 1; i <= r; i++){
      // cout << l << " " << i - 1 << endl;
      ll L = calc(l, i - 1);
      // cout << i << " " << r << endl;
      ll R = calc(i, r);
      // cout << "l:" << l << " i-1:" << i-1  << " i:" << i << " r:" << r << " L:" << L << " R:" << R << " L+R:" << L + R << " ans:" << ans << endl;
      ans = min(ans, L + R);
      // cout << "ans:" << ans << endl;
  }
  // cout << endl;
  dp[l][r] = ans + f(l, r);
  // cout << "dp[" << l << "][" << r << "]:" << dp[l][r] << " = ans:" << ans << " + f:" << f(l, r) << endl;
  // cout << endl;
  return dp[l][r];
}

