void solve() {
  fill(dp[0], dp[N], INF);
  REP(i, N) {
    dp[i][i + 1] = 0;
    acc[i + 1] = acc[i] + a[i];
  }
  FOR(k, 2, N) FOR(i, 0, N - k) {
    ll cost = acc[i + k] - acc[i];
    FOR(j, i + 1, i + k - 1) {
      dp[i][i + k] = min(dp[i][i + k], dp[i][j] + dp[j][i + k] + cost);
    }
  }
  // DUMP2D(dp, N, N + 1);
  printf("%lld\n", dp[0][N]);
}

void input() {
  scanf("%d", &N);
  REP(i, N) scanf("%d", a + i);
}

