#include <bits/stdc++.h>

using namespace std;

const int MAXN = 400;
const long long LLINF = 1e15;

int a[MAXN + 7];
long long pre[MAXN + 7];

long long sum(int l, int r) {
  return pre[r] - pre[l - 1];
}

long long dp[MAXN + 7][MAXN + 7];

long long dpf(int l, int r) {
  if (l > r) {
    return 0;
  }
  long long &d = dp[l][r];
  if (d != -1) {
    return d;
  }
  if (l == r) {
    return d = a[l];
  }
  if (l == r - 1) {
    return d = a[l] + a[r];
  }
  d = LLINF;
  for (int i = l; i <= r - 1; i++) {
    long long temp = dpf(l, i) + dpf(i + 1, r) + sum(l, r);
    if (i == l) {
      temp -= a[l];
    }
    if (i == r - 1) {
      temp -= a[r];
    }
    d = min(d, temp); 
  }
  return d;
}

int main() {
  memset(dp, -1, sizeof dp);
  int n;
  cin >> n;

  for (int i = 1; i <= n; i++) {
    scanf("%d", &a[i]);
    pre[i] = pre[i - 1] + a[i];
  }

  cout << dpf(1, n) << "\n";

  return 0;
}

