    cin >> a[i];
    if(i==0) pref[i] = a[i];
    else pref[i] += pref[i-1]+a[i];
  }

  for(int i = 0; i < n; i++){
    for(int j = 0; j < n; j++){
      dp[i][j] = INF;
    }
  }

  for(int L = n-1; L >= 0; L--){
    for(int R = L; R < n; R++){
      if(L==R){
        dp[L][R] = 0;
      }else{
        for(int i = L; i < n; i++){
