	// TOP DOWN
	// cout<<MCM(0,n-1, arr);


	// Bottom-Up:
	for(int len=1;len<=n;len++){ // length of interval -> moving from smaller to larger intervals.
		for(int i=0;i<=n-len;i++){ // fixing the starting point.
			int j = i+len-1;
			// considering interval i to j
			if(i==j){
				dp[i][j] = 0;
			}
			else{
				ll tmp  = ULLONG_MAX/2;
				ll curr_cost = (i==0?sum[j]:sum[j]-sum[i-1]); // sum till i to j.(cost of joining the left and right intervals)
				for(int k=i;k<j;k++){
					tmp = min(tmp, dp[i][k] + dp[k+1][j] + curr_cost); 
				}
				dp[i][j] = tmp;
			}
		}
	}

	cout<<dp[0][n-1]<<endl;









