ll answer(const int& left, const int& right, const std::vector<ll>& a, const std::vector<ll>& sum, std::vector<std::vector<ll>>& dp) {
  if (dp[left][right] != INF) return dp[left][right];
  if (left+1 == right) return dp[left][right] = 0;
  for (int mid = left+1;mid < right;++mid) {
//    std::cout << "answer:" << left << '-' << right << ':' << left << '-' << mid << '-' << right << '\n';
