ll fun(ll i,ll j){
  if(i==j)return 0;        // cost will be 0 for single element to form single slime
  if(dp[i][j]!=-1)return dp[i][j];

  ll mini = 1e12;

  for(int r=i;r<=j-1;r++)
    mini=min(mini,sum[i][j]+fun(i,r)+fun(r+1,j));    // finding minimum cost for combining two slimes into one 

  return dp[i][j]= mini;
}

