int solve(int i, int j) {
    if(i == j) return 0;
    if(dp[i][j] != -1) return dp[i][j];
    int least = inf;
    for(int k=i; k<j; k++) least = min(least, solve(i, k) + solve(k+1, j) + sum[i][j]);
