long long cal_sum(const vector<int> &a, int i, const bitset<399> s) {
	long long res = 0;
	int l = i, r = i;
	while(l >= 0 && s[l]) {
		res += a[l];
		l--;
	}
	while(r + 1 < a.size() && s[r]) {
		res += a[r + 1];
		r++;
	}

	return res;
}

int main() {
	int N;
	cin >> N;
	vector<int> a(N);
	for(auto & x: a) cin >> x;

	vector<vector<pair<long long,bitset<399> > > > dp(N, vector<pair<long long, bitset<399> > >(N - 1, make_pair(0, bitset<399>())));

	for(int i = 1; i < N; i++) {
		for(int j = 0; j < N - 1; j++) {
				long long m = LLONG_MAX / 3;
				bitset<399> s;
			for(int k = 0; k < N - 1; k++) {
				bitset<399> ss = dp[i - 1][k].second;

				if(ss[j] || k == j) continue;
				ss[j] = true;
				long long mm = dp[i - 1][k].first + cal_sum(a, j, ss);
				if(m > mm) {
					m = mm;
					s = ss;
				}
			}
			//cout << i << " " << j << " " << m << " " << s << endl;
			dp[i][j] = make_pair(m, s);
		}
	}

	long long res = LLONG_MAX / 3;
	for(auto x: dp[N - 1]) {
		res = min(res, x.first);
	}

	cout << res << endl;
}

