ll inf = 1e17;

ll solve(int i, int j)
{
    if(i == j)
        return 0;
    ll &ans = dp[i][j];
    if(ans != -1)
        return ans;
    ans = inf;
    ll have = c[j];
    if(i)
        have -= c[i - 1];
    for(int k = i; k < j; k++)
        ans = min(ans, solve(i, k) + solve(k + 1, j) + have);
    return ans;
}

