void slime(int n, vector<int>&a){
    for(int l=n-1; l>=0; l--){
        for(int r=l; r<n; r++){
            if(l == r) {
                dp[l][r] = 0; // cost of joining the 2 same vertex is always 0
            }else {
                dp[l][r] = INF;
                for(int i=l; i<=r; i++){
                    dp[l][r] = min(dp[l][r], dp[l][i]+dp[i+1][r] + sum(l,r,a));
                }
            }

        }
    }
    cout << dp[0][n-1] << endl;
}

