using vvi = vector<vi>;

i64 cost(vi as) {
    int n = as.size();
    if (n == 1) {
        return 0;
    }

    vi sum(n + 1);
    for (int i = 0; i < n; i++) {
        sum[i + 1] = sum[i] + as[i];
    }

    i64 nin = 1e18, nini;
    for (int i = 1; i < n; i++) {
        if (abs(sum[n] - 2 * sum[i]) < nin) {
            nin = abs(sum[n] - 2 * sum[i]);
            nini = i;
        }
    }
    vi l, r;
    i64 ls = 0, rs = 0;
    for (int i = 0; i < nini; i++) {
        l.push_back(as[i]);
        ls += as[i];
    }
    for (int i = nini; i < n; i++) {
        r.push_back(as[i]);
        rs += as[i];
    }
    return ls + rs + cost(l) + cost(r);
}

