ll go(ll arr[],int n)
{
    //base case
    for(int i=1;i<=n;i++)
        dp[i][i] = 0;

    //prefix_arr
    ll prefix[n+1];
    memset(prefix,0,sizeof(prefix));
    for(int i=1;i<=n;i++)
        prefix[i] = prefix[i-1]+arr[i];

    //main fun
    for(int len=2;len<=n;len++)
    {
        for(int i=1;i<=n;i++)
        {
            int j = i+len-1;
            if(j<=n)
            {
                ll curr = 1e18;
                for(int k=i;k<j;k++)
                {
                    curr = min(curr,dp[i][k]+dp[k+1][j]+prefix[j]-prefix[i-1]);
                }
                dp[i][j] = curr;
            }
        }
    }

    return dp[1][n];
}

