        cin>>vec[i];
    pref[0]=vec[0];
    for(int i=1;i<n;i++)
        pref[i]=pref[i-1]+vec[i];
    dp.resize(n,vector<int>(n,inf));
    for(int i=0;i<n;i++)
        dp[i][i]=0;
