int go(int l,int r)
{
    if(l<0||r<0||l>=n||r>=n)
        return 0;
    if(dp[l][r]!=inf)
        return dp[l][r];
    int ans=inf;
    for(int i=l;i<r;i++)
    {
        int sd;
        if(l==0)
            sd=0;
        else
            sd=pref[l-1];
        ans=min(ans,go(l,i)+go(i+1,r)+pref[r]-sd);
    }
    return dp[l][r]=ans;
}

