using namespace std;

int n;
long long a[N];
long long dp1[N][N];
long long dp2[N][N];

long long solve()
{
	for (int i = 1; i <= n; i++)
	{
		dp1[i][i] = a[i];
		dp2[i][i] = 0;
	}
	for (int len = 2; len <= n; len++)
	{
		for (int i = 1; i <= n - len + 1; i++)
		{
			int j = i + len - 1;
			dp2[i][j] = LLONG_MAX;
			for (int k = i; k < j; k++)
			{
				long long temp = dp1[i][k] + dp1[k + 1][j] + dp2[i][k] + dp2[k + 1][j];
				if (temp < dp2[i][j])
				{
					dp1[i][j] = dp1[i][k] + dp1[k + 1][j];
					dp2[i][j] = temp;
				}
			}
		}
	}
	return dp2[1][n];
}

