const int MAXN = 405;

ll n, a[MAXN], dp[MAXN][MAXN], sum[MAXN][MAXN];      // Minimum cost to combine elements from st to en

ll rec(ll st, ll en)
{
	if(st == en) return dp[st][en] = 0;
	if(dp[st][en] != -1) return dp[st][en];
	ll ans = 1e18;
	for(int i=st;i<en;i++)
		ans = min(ans, rec(st, i) + rec(i + 1, en) + sum[st][i] + sum[i+1][en]); 
	return dp[st][en] = ans;
}

