	for(int i=0;i<n;i++)
	{
		sum[i][i] = a[i];
		for(int j=i+1;j<n;j++) sum[i][j] = sum[i][j-1] + a[j];
	}
	cout << rec(0, n-1) << endl;
    return 0;
}

