int main() {
    ll n;
    cin >> n;

    vl a(n);
    rep(i, n) {
        cin >> a[i];
    }

    vl rui(n+1);  // rui[i+1] : a[0]からa[i]までの累積和
    rep(i, n) {
        rui[i+1] = rui[i] + a[i];
    }

    vvl dp(n+1, vl(n+1));  // dp[l][r] : 区間[l,r)のスライムたちを1匹に合成するのに必要なコストの最小値
    exrep(len, 2, n) {  // 区間の長さが1のときはdp[l][r]=0なので区間の長さが2以上のときを考える 
        for(ll l = 0; l + len <= n; l++) {
            ll r = l + len;

            /* 区間[l,r)のスライムたちを1匹に合成する手順は以下。
               まず区間[l,x)と区間[x,r)に分ける。
               次にコストdp[l][x]で[l,x)のスライムたちを1匹のスライムAに合成する。
               同様にコストdp[x][r]で[x,r)のスライムたちも1匹のスライムBに合成する。
               スライムAとスライムBの大きさの合計は区間[l,r)のスライムたちの重さの合計に等しい。
               よって、最初に位置x (l < x < r) で区間[l,r)を分けたときの最小コストは dp[l][x] + dp[x][r] + (sum_{l <= i < r} a[i]) となる。
               あとは位置xを全て試して、(sum_{l <= i < r} a[i]) は rui[r] - rui[l] と累積和で高速に求めればよい。 */

            ll u = INF;  // dp[l][x] + dp[x][r] の最小値
            exrep(x, l+1, r-1) {  
                chmin(u, dp[l][x] + dp[x][r]);
            }

            dp[l][r] = u + rui[r] - rui[l];
        }
    }

    out(dp[0][n]);
    re0;
}

