    while(a.size()>1) {
        int min=INF;
        int mini=0;
        for(i=0; i<(int)a.size()-1; i++) {
            if(a[i]+a[i+1]<min) {
                min=a[i]+a[i+1]; mini=i;
            }
        }
        int p=mini+1;
        ll add = a[mini]+a[p];
        ans += add;
        vector<ll> b;
