int64_t dp[401][401]; 

int64_t solve(vector<int64_t>& arr,int i,int j)
{
  if(i == j)
    return 0;
  if(dp[i][j] !=-1)
    return dp[i][j];
  int64_t sum=accumulate(arr.begin()+i,arr.begin()+j+1,(int64_t)0);

  int64_t ans = LLONG_MAX;

  for(int k=i;k<j;k++)
     ans = min( solve(arr,i,k) + solve(arr,k+1,j),ans);
  ans+=sum;
  return dp[i][j]=ans;     
}



