using namespace std;

void solve(vector<long long>& slimes, long long& cost){
	if(slimes.size() == 1)
		return;
	int sum = INT_MAX, pivot = 0;
	for(int i = 0; i < slimes.size()-1; i++){
		if(slimes[i] + slimes[i+1] < sum){
			sum = slimes[i] + slimes[i+1];
			pivot = i;
		}
	}
	long long temp = slimes[pivot];
	slimes.erase(slimes.begin() + pivot);
	slimes[pivot] += temp;
	cost += slimes[pivot];
	solve(slimes, cost);
}

