long long r(int p, int k)
{
	if(bio[p][k] != -1)
	{
		return bio[p][k];
	}
	if(p == k)
	{
		return bio[p][k] = 0;
	}
	long long u = 1000000000000;	
	for(int j = p; j < k; j++)
	{
		if(p != 0)
		{
		    u = min(u, pref[k] - pref[p-1] + r(p, j) + r(j+1, k));
		}
		else
		{
			u = min(u, pref[k] + r(p, j) + r(j+1, k));
		}
	}	
	return bio[p][k] = u;
}
