// [l, r]
ll dfs(int l, int r, vvl &dp, vl const &a) {
    if (dp[l][r] != -1)
        return dp[l][r];
    if (l == r)
        return dp[l][r] = 0;
    ll mini = INF;
    for (int m = l; m < r; ++m) {
        chmin(mini, dfs(l, m, dp, a) + dfs(m + 1, r, dp, a) + a[r] - (l == 0 ? 0 : a[l - 1]));
    }
    return dp[l][r] = mini;
}

