// Returns <value of the unit after combining, cost of combination> 
pair<ll, ll> f(vector<ll>& A, int i, int j) {
  	// base case 
	if(i == j) {
      	return {A[i], 0};
    }

  	ll minCost = LONG_MAX;
  	ll size = 0;
  	for(int k=i; k<j;k++){
      	auto x =  f(A, i, k);
      	auto y = f(A, k+1, j);
		size = x.first + y.first;

      	ll cost = size + x.second + y.second;
    	minCost = min(minCost, cost);
    }

  	return {size, minCost};
}

