        cin>>arr[i];
    prefixSums[0] = arr[0];
    F(int, i, 1LL, n - 1LL)
        prefixSums[i] = arr[i] + prefixSums[i - 1];
    cout<<MinCost(0LL, n - 1LL, arr);
}

