#include <bits/stdc++.h>
using namespace std;
#define N 440
typedef long long ll;
int n;
ll a[N],memo[N][N],ps[N];

void precompute() {
    for (int i = 1 ; i <= n ; i++)
        ps[i] = ps[i - 1] + a[i];
}

ll rsum(int l , int r) {
    return ps[r] - ps[l - 1];
}

ll dp(int i , int j) {
    if (i > j) return INT_MAX;
    if (i == j) return 0;
    if (j - i == 1) return a[i] + a[j];
    ll &sol = memo[i][j];
    if (sol != -1) return sol;
    ll keep = LLONG_MAX;
    for (int k = i ; k < j ; k++) {
        keep = min(
            dp(i , k) + dp(k + 1 , j) + rsum(i , j),
            keep
        );
    }
    return sol = keep;
}

int main() {
    scanf("%d" , &n);
    for (int i = 1 ; i <= n ; i++)
        scanf("%lld" , &a[i]);
    memset (memo , -1 , sizeof memo);
    precompute();
    printf("%lld\n" , dp(1 , n));
}

