ll dfs(int l,int r){    //[l,r)
    if(dp[l][r]>=0)
        return dp[l][r];
    if(r-l<=1){
        dp[l][r]=0;
        return dp[l][r];
    }
    ll ret = -1;
    for(int mid = l+1;mid < r;mid++){
        if(ret<0)
            ret = dfs(l,mid)+dfs(mid,r)+rsum(l,r);
        else
            ret = min(ret,dfs(l,mid)+dfs(mid,r)+rsum(l,r));
    }
    dp[l][r]=ret;
    return ret;
}

