void update(vector<vector<int> > &matrix, int start, int end, vector<int> &nums) {
	int ans = 100000000000000LL;
	for (int k = start; k < end; ++k) {
		// start - k
		// k + 1 - end
		int prev = matrix[start][k] + matrix[k+1][end];
		int diff = sum(nums, start, k) + sum(nums, k + 1, end);
		ans = min(ans, prev + diff);
	}
	matrix[start][end] = ans;
}

