    LL N;
    cin >> N;

    auto A = make_v<LL>(N);
    FOR(i, 0, N) {
        cin >> A[i];
    }

    CumulativeSum<LL> cs;
    cs.build(A);

    auto dp = make_v<LL>(N + 10, N + 10);
    fill_v(dp, LONG_LONG_MAX);
    for (int i = 0; i < N; ++i) {
        dp[i][i] = 0;
        dp[i][i + 1] = 0;
    }

    for (int length = 1; length < N + 1; ++length) {
        for (int left = 0; left < N; ++left) {
            int right = left + length;
            if (right > N) {
                continue;
            }

            for (int m = left + 1; m < right; ++m) {
                LL c = cs.sum(left, m) + cs.sum(m, right);
                dp[left][right] = min(dp[left][right], dp[left][m] + dp[m][right] + c);
            }
        }
    }
    print(dp[0][N]);

    return 0;
}

