		dp[i][i] = 0;
	}
	for (int len = 2; len <= n; ++len)
	{
		for (int start = 0; start <= n - len; ++start)
		{
			int end = start + len - 1;
			dp[start][end] = dp[start][end - 1] + sum[start][end];
			for (int j = end - 1; j > start; --j)
			{
				dp[start][end] = min(dp[start][end], dp[start][j - 1] + dp[j][end] + sum[start][end]);
			}
		}
	}
	cout << dp[0][n - 1];
	return 0;
}

