#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MN = 412;
const ll inf = 1e15;
ll n,a[MN],dp[MN][MN],pf[MN];
int main (void) {
    ios::sync_with_stdio(false);cin.tie(0);
    cin >> n;
    for (ll i = 0; i < n; i++) cin >> a[i];
    pf[0] = a[0];
    for (ll i = 0; i < n; i++) pf[i+1] = pf[i]+a[i+1];
    for (ll i = 0; i < n; i++)
        for (ll j = 0; j < n; j++)
            dp[i][j] = inf;
    for (ll l = n-1; l >= 0; l--) {
        for (ll r = l; r < n; r++) {
            if (l == r) dp[l][r] = 0;
            else {
                ll ps = (l == 0) ? pf[r] : pf[r]-pf[l-1];
                for (ll i = l; i < r; i++)
                    dp[l][r] = min(dp[l][r], dp[l][i]+dp[i+1][r]+ps);
            }
        }
    }
    cout << dp[0][n-1] << '\n';
    return 0;
}

