ll dp(ll r, ll l)
{
    if (r + 1 == l)
    {
        value[r][l] = (A[r] + A[l]);
        return value[r][l];
    }
    if (r == l)
    {
        value[r][l] = A[r];
        return 0;
    }
    if (r > l)
    {
        return 0;
    }
    ll res = INF;
    ll index = -1; //最大値
    for (int i = 0; r + i < l; i++)
    {
        ll ans = dp(r, r + i) + dp(r + i + 1, l); //dpが答えを持つとした方が楽。
        ans += value[r][r + i] + value[r + i + 1][l];
        if (res > ans)
        {
            res = ans;
            index = r + i;
        }
    }
    value[r][l] = value[r][index] + value[index + 1][l];
    memo[r][l] = res;
    done[r][l] = 1;
    return res;
}
