vector<ll> a;
vector< vector<ll > > dp;

ll rec(int left, int right){
    if(left >= right)
        return 0;

    if(dp[left][right] > -1)
        return dp[left][right];

    ll cost = 0LL;
    for(int i = left; i <= right; i++){
        cost += a[i];
    }

    ll ans = LLONG_MAX;
    for(int i = left; i < right; i++){
        ans = min(ans, cost + rec(left, i) + rec(i + 1, right));
    }
    return dp[left][right] = ans;
}

