int N;
int a[400];
ll sum[401];
const ll INF = 1e15;
ll dp[401][401];
ll dfs(int l, int r) {
  // [l, r)
  if (l == r) return 0;
  if (l + 1 == r) return 0;
  if (dp[l][r] != INF) return dp[l][r];

  ll ans = INF;
  rep(i, l+1, r)
    ans = min(ans, dfs(l, i) + dfs(i, r) + sum[r] - sum[l]);

  return dp[l][r] = ans;
}
int main() {
