  rep(i, N) cin >> a[i];

  sum[0] = 0;
  rep(i, N) sum[i+1] = sum[i] + a[i];

  rep(i, 401) rep(j, 401) dp[i][j] = INF;

  cout << dfs(0, N) << endl;

  return 0;
}

