#define N  404

ll n;
ll a[N];
ll dp[N][N];
ll pre[N];

ll getval(ll st, ll en){
	if(st>en)return 0;
	if(st==en)return a[st];
	return pre[en]-pre[st-1];
}

ll solve(ll st, ll en){
	if(dp[st][en]!=-1)return dp[st][en];
	if(st==en)return dp[st][en]=0;
	ll ret=INF;
	rep(i,st,en+1){
		ll left  = 0;
		if(i>st)left=solve(st,i-1);
		ll right = 0;
		if(i<en)right=solve(i+1,en);
		ll ans = left + right;
		ans+=getval(st,i-1) + getval(i+1,en) + a[i];
		if(i>st and i<en){
			ans+=a[i];
			ans+=min(getval(st,i-1),getval(i+1,en));
		}
		// if(st==2 and en==4){
		// 	cerr<<" hey "<<i<<"  "<<ans<<" "<<getval(i+1,en)<<endl;
		// }
		ret=min(ret,ans);
	}
	// cerr<<st<<" "<<en<<" "<<ret<<endl;
	return dp[st][en]=ret;
}


