using namespace std;

long long dp[405][405];
vector<long long> cost;
vector<long long> prefix;

long long pref(int start, int end) {
	if (end < start)
		return 0;
	if (start <= 0)
		return prefix[end];
	return prefix[end] - prefix[start-1];
}

long long solve(int start, int end) {
	if (dp[start][end] != -1)
		return dp[start][end];
	if (end < start)
		return 0;
	if (end == start + 1)
		return dp[start][end] = cost[start] + cost[end];

	long long mini = LLONG_MAX;
	for (int i = start; i <= end; i++) {
		mini = min(mini, solve(start, i - 1) + solve(i + 1, end) + pref(start, i - 1) + 2ll * cost[i] + pref(i + 1, end) + min(pref(start, i - 1), pref(i + 1, end)));
	}
	return dp[start][end] = mini;
}

int main() {
	int n;
	cin >> n;
	memset(dp, -1, 405 * 405 * sizeof(long long));
	cost.resize(n);
	prefix.resize(n, 0);
	for (int i = 0; i < n; i++) {
		cin >> cost[i];
		dp[i][i] = 0;
	}
	prefix[0] = cost[0];
	for (int i = 1; i < n; i++) {
		prefix[i] = prefix[i - 1] + cost[i];
	}
	cout << solve(0, n - 1) << "\n";
	return 0;
}

