const int MAX_N = 402;
int N;
int a[MAX_N];
ll dp[MAX_N][MAX_N];
ll psum[MAX_N];

ll go(int le, int ri)
{
	if(le > ri) return 0;
	if(le == ri) return a[le];
	ll& res = dp[le][ri];
	if(res != -1) return res;
	res = 1e15;
	for(int k=le+1;k<=ri;++k){
		res = min(res, go(le,k-1)+go(k,ri));
	}
	res += psum[ri+1]-psum[le];
	return res;
}

void solve()
{
	psum[0]=0;
	for(int i=1;i<=N;++i) psum[i]=psum[i-1]+a[i-1];
	memset(dp, -1, sizeof(dp));
	ll ans = go(0, N-1);
	cout << ans-psum[N] << '\n';
}

int main()
{
