  //main
  //半開区間→[0,N)
  vector<vector<ll>> dp(N+1,vector<ll>(N+1,INF));
  vector<ll> sum(N+1,0LL);
  vector<vector<bool>> isSearched(N+1,vector<bool>(N+1,false));

  FOR(i,N){ sum[i+1] = sum[i]+A[i]; }
  FOR(i,N+1){ dp[i][i] = 0; isSearched[i][i] = true; }//0匹
  FOR(i,N){ dp[i][i+1] = 0; isSearched[i][i+1] = true; }//1匹

  // output
  function<ll(ll,ll)> dfs = [&](ll l, ll r){
    if(isSearched[l][r]) return dp[l][r];
    ll score = INF;
    for(int c=l+1; c<r; c++){
      ll tmp = dfs(l,c)+dfs(c,r)+(sum[r]-sum[l]);
      score = min(score,tmp);
    }
    isSearched[l][r] = true;
    return dp[l][r] = score;
  };

  cout << dfs(0,N) << endl;

  return 0;
}

