int choice[N][N];
ll memo[N][N];

ll getSize(int l, int r){
	if(r <= l) return 0LL;
	return l == 0? prefix[r] : prefix[r] - prefix[l-1];
}

ll DP(int l, int r){
	if(r <= l) return 0LL;
	if(l + 1 == r) return a[l]+a[r];
	if(vis[l][r]) return memo[l][r];
	ll ans = 1LL<<45;
	for(int k=l; k<r; k++){
		ll cand = DP(l,k) + getSize(l,r) + DP(k+1,r);
		if(ans > cand){
			choice[l][r] = k;
			ans = cand;
		}
	}
	vis[l][r] = true;
	return memo[l][r] = ans;
}

