void combine(ll k)
{
	register int i;
	ll tmp=a[k-1]+a[k];
	ans+=tmp;
	for(i=k;i<t-1;++i)a[i]=a[i+1];t--;
	for(i=k-1;i&&a[i-1]<tmp;--i)a[i]=a[i-1];
