const ll INF = 1e13;
int N;
ll a[410];
ll dp[410][410];
ll asum[410];

ll Sum(int l, int r)
{
    return asum[r] - asum[l - 1];
}

ll cost(int l, int r)
{
    if(dp[l][r] != -1) return dp[l][r];
    ll res = 0;
    if(l == r) return dp[l][r] = 0;
    res += Sum(l, r);
    ll cmin = INF;
    for(int m = l; m < r; m++)
    {
        cmin = min(cmin, cost(l, m) + cost(m + 1, r));
    }
    res += cmin;
    return dp[l][r] = res;
}

