    for(int k=2;k<=n;k++){
        for(int p=0;p<n;p++){
            ll ans=LONG_MAX;
            for(int q=p;q<p+k-1;q++){
                ans=min(ans,dp[p][q%n]+dp[(q+1)%n][(p+k-1)%n]);
            }
            x=0;
            for(int q=p;q<=p+k-1;q++){
