ll f1(ll l,ll r,ll dp[][401],ll w[])
{
   if(dp[l][r]!=-1)
   return dp[l][r];
   else if(l==r)
   {
      return dp[l][r]=0;
   }
   else if(r-l==1 && l!=0)
   return dp[l][r]=w[r]-w[l-1];
   else if(r-l==1)
   return dp[l][r]=w[r];
   else
   {
      ll cost1=1e18;
      ll add;
      if(l==0)
      add=w[r];
      else
      add=w[r]-w[l-1];

      for(ll i=l+1;i<=r;i++)
      {
         ll cost=f1(l,i-1,dp,w)+f1(i,r,dp,w)+add;
         cost1=min(cost,cost1);
      }
      return dp[l][r]=cost1;

   }


}



