using namespace std;

typedef long long ll;

const int MOD = 1e9+7;
ll dp[405][405];
int v[405];
ll psum[405];
bool mark[405][405];

ll f(int l, int r) {
	if(l == r) return 0;
	if(mark[l][r]) return dp[l][r];
	mark[l][r] = true;

	ll ret = 1e18;
	for(int i = l; i < r; i++) {
		ll junta = v[i];
		ll left, pleft, right, pright;
		if(i > l) {
			left = f(l, i-1);
			pleft = psum[i-1] - psum[l-1];
		}
		if(i < r) {
			right = f(i+1, r);
			pright = psum[r] - psum[i];
		} 

		if(i > l and i < r) {
			ret = min(ret, 2*junta + 2*pleft + pright + left + right);
			ret = min(ret, 2*junta + 2*pright + pleft + left + right);
		}
		else if(i > l)
			ret = min(ret, junta + pleft + left + right);
		else
			ret = min(ret, junta + pright + left + right);

	}

	return dp[l][r] = ret;
}

