	if (dp[l][r]!=-1)
	{
		return dp[l][r];
	}
	if (l==r) {dp[l][r]=0; return 0;}
	if (l==r-1) {dp[l][r]=a[l]+a[r];
	return dp[l][r];}
	int temp=INF;
	for (int i=l;i<=r;i++)
	{
		// cout<<i<<endl;
		if (i==l)
		{
			temp=min(temp,fun(l+1,r)+pref[r]-pref[l]+a[l]);
		}
		else if (i==r)
		{
			temp=min(temp,fun(l,r-1)+pref[r-1]-pref[l]+a[l]+a[r]);
		}
		else
		{
			int x=fun(l,i-1);
			if (i-1==l) x=a[l];
			int y=fun(i,r);
			temp=min(temp,x+y+pref[i-1]-pref[l]+a[l]+pref[r]-pref[i]+a[i]);
		}
		// cout<<temp<<" "<<i<<" "<<l<<" "<<r<<endl;
	}
	// cout<<l<<" "<<r<<" "<<temp<<endl;
	dp[l][r]=temp;
	return temp;
}
int powmod(int base,int exp,int mod)
{
	int res=1LL;
	while(exp>0)
	{
		if(exp&1LL)
			res=(res*base)%mod;
		exp/=2LL;
		base=(base*base)%mod;
	}
	return res%mod;
}
