ll rec(int l, int r) {
    if (visited[l][r]) return dp[l][r];
    if (l == r) return 0;
    visited[l][r] = true;

    dp[l][r] = INF;
    for (int i = l; i < r; ++i) {
        dp[l][r] = min(dp[l][r], rec(l, i) + rec(i + 1, r));
    }

    dp[l][r] += sum[r] - sum[l - 1];
    return dp[l][r];
}

