void fft(vector<cd>&  a, bool invert)
{
    ll n=a.size();
    ld PI=acos(-1);
    for(ll i=1,j=0; i<n; i++)
    {
        ll bit=n>>1;
        for(; j&bit; bit>>=1)
        {
            j^=bit;
        }
        j^=bit;
        if(i<j)
            swap(a[i], a[j]);
    }
    for(ll i=2; i<=n; i<<=1)
    {
        double ang=2*PI/i*(invert?-1:1);
        cd wn(cos(ang), sin(ang));
        for(ll j=0; j<n; j+=i)
        {
            cd w(1);
            for(ll k=j; k<j+i/2; k++)
            {
                cd u=a[k], v=a[k+i/2]*w;
                a[k]=u+v;
                a[k+i/2]=u-v;
                w*=wn;
            }
        }

    }
    if(invert)
    {
        for(ll i=0; i<n; i++)
            a[i]/=n;
    }

}
vector<ll>  multfft(vector<ll> a, vector<ll>b)
{
    vector<cd> fa(all(a)), fb(all(b));
    ll n=1;
    while(fa.size()+fb.size()>n)
        n*=2;
    fa.resize(n);
    fb.resize(n);
    vector<ll> result(n);
    fft(fa,false);
    fft(fb,false);
    for(ll i=0; i<n; i++)
        fa[i]*=fb[i];
    fft(fa,true);
    for(ll i=0; i<n; i++)
        result[i]=round(fa[i].real());
    return result;

}
bool isPrime(ll n)
{
    // Corner case
    if (n <= 1)
        return false;

    // Check from 2 to n-1
    for (ll i=2; i<n; i++)
        if (n%i == 0)
            return false;

    return true;
}

