class heap
{
    long long *arr;
    long long n;
    public:
    heap(long long m,long long *ele)
    {
        n=m;
        arr=new long long[n+1];
        long long i;
        for(i=1;i<=n;i++) arr[i]=ele[i-1];
        for(i=n/2;i>=1;i--) heapify(i);
    }
    void heapify(long long x)
    {
        long long l=2*x;
        long long r=2*x+1;
        long long sma=x;
        if(l<=n && arr[l]<arr[sma]) sma=l;
        if(r<=n && arr[r]<arr[sma]) sma=r;
        if(sma!=x)
        {
            swap(arr[sma],arr[x]);
            heapify(sma);
        }
    }
    long long del()
    {
        long long ele=arr[1];
        arr[1]=arr[n];
        n--;
        heapify(1);
        return ele;
    }
    void ins(long long ele)
    {
        n++;
        long long pos=n;
        long long par=pos/2;
        while(par>=1)
        {
            if(ele<arr[par])
            {
                arr[pos]=arr[par];
                pos=par;
                par=pos/2;
            }
            else break;
        }
        arr[pos]=ele;
    }
};
