ll sum[MAX_N];

ll rec(int l, int r){
  if (l == r){
    dp[l][r] = 0;
  }

  if (dp[l][r] != -1){
    return dp[l][r];
  }

  ll result = INF;
  for (int k = l; k < r; k++){
    ll tmp = rec(l, k) + rec(k+1, r);
    result = min(result, tmp);
  }

  result += sum[r+1] - sum[l];
  dp[l][r] = result;

  // printf("dp[%d][%d] = %lld\n", l, r, dp[l][r]);

  return result;
}

