ll findans(ll i,ll j)
{
    if(i==j)
    {
        return 0;
    }
    if(i+1==j)
    {
        return a[i]+a[j];
    }
    if(memo[i][j]!=-1)
    {
        return memo[i][j];
    }
    ll ans=1000000000000;
    for(ll k=i;k<=j-1;k++)
    {
        if(i>0)
        {
            ans=min(ans,findans(i,k)+findans(k+1,j)+pre[j]-pre[i-1]);
        }
        else
        {
            ans=min(ans,findans(i,k)+findans(k+1,j)+pre[j]);
        }
    }
    return memo[i][j]=ans;
}
