unsigned long long int matrix(unsigned long long int p[], int n)
{
	unsigned long long int arr[n+1][n+1];
	unsigned long long int color[n+1][n+1];
	for(int i=1;i<=n;i++)
	{arr[i][i]=0;
	color[i][i]=p[i-1];
	}



	for(int l=2;l<=n;l++)
	{
		for(int i=1;i<=n-l+1;i++)
		{
			int j=i+l-1;
			arr[i][j]=100000000000;
			for(int k=i;k<=j-1;k++)
			{
			   unsigned	long long int pp=arr[i][k]+arr[k+1][j]+color[i][k]+color[k+1][j];
				if(pp<arr[i][j])
				{arr[i][j]=pp;
				color[i][j]=color[i][k]+color[k+1][j];
			    }
			}
		}
	}



	return arr[1][n];
}



