int main() {
    ios::sync_with_stdio(false);

    int N; cin >> N;

    vector<int64_t> partial(N);
    for (int i = 0; i < N; ++i) {
        cin >> partial[i];
        if (i > 0)
            partial[i] += partial[i - 1];
    }

    vector< vector<int64_t> > dp(N, vector<int64_t>(N, numeric_limits<int64_t>::max() / 2));
    for (int i = 0; i < N; ++i)
        dp[i][i] = 0;

    for (int L = 1; L < N; ++L)
        for (int i = 0; i + L < N; ++i)
            for (int k = i; k < i + L; ++k)
                dp[i][i + L] = min(dp[i][i + L], dp[i][k] + dp[k + 1][i + L] + partial[i + L] - (i == 0 ? 0 : partial[i - 1]));

    cout << dp[0][N - 1] << "\n";
}

