pair<int, int> MEM(int i, int j)
{
	if(i==j)
	{
		return dp[i][j] = {0, a[i]};
	}

	pair<int, int> &ans = dp[i][j];

	if(ans.first!=-1)
		return ans;

	ans = {MAXI, MAXI};

	for(int l=i;l<j;l++)
	{
		pair<int, int> x = MEM(i, l);
		pair<int, int> y = MEM(l+1, j);

		pair<int, int> z;

		z.first = x.second + y.second + x.first + y.first;
		z.second = x.second + y.second;

		if(z.first<ans.first)
			ans = z;

	}

	return ans;
}


