LL solve(int l, int r, VVLL &dp, VLL &sum){
  if(l==r) return 0;
  if(dp.at(l).at(r)!=LINF) return dp.at(l).at(r);
  LL res = LINF;
  FOR(i,l+1,r){
    chmin(res, solve(l,i,dp,sum)+solve(i,r,dp,sum));
  }

  return dp.at(l).at(r) = res+sum.at(r)-sum.at(l);
}

