class slime
{
private:
	vector<unsigned long long> slimes;
	int count;
	unsigned long long total = 0;
	void shorten();
	void display();
public:
	slime();
};


slime::slime() {
	cin >> count;
	for (int i = 0; i < count; i++) {
		unsigned long long x;
		cin >> x;
		slimes.push_back(x);
	}
	while (slimes.size() > 1) {
		shorten();
	}
	display();
}
void slime::shorten() {
	unsigned long long min_gap = slimes[0] + slimes[1];
	int merge_index = 0;
	for (int i = 0; i < slimes.size() - 1; i++) {
		if (slimes[i] + slimes[i + 1] < min_gap) {
			merge_index = i;
			min_gap = slimes[i] + slimes[i + 1];
		}
	}
	slimes[merge_index] = min_gap;
	slimes.erase(slimes.begin() + merge_index + 1);
	total += min_gap;
}
void slime::display() {
	cout << total;
}
