LL solve(int l ,int r,const vector<LL> &v)
{
    LL &ret = dp[l][r];

    if(ret!=-1) return ret;

    if(l==r) return ret = 0;

    ret = LLONG_MAX;
    LL cost = sum(l,r,v);
    for(int i=l;i<r;i++)
        ret = min(ret, solve(l,i,v) + solve(i+1,r,v) + cost);

    return ret;

}

