int rec(int l, int r) {
  if (l == r) return 0;
  if (l + 1 == r) return sum[r] - sum[l - 1];
  if (dp[l][r]) return dp[l][r];

  int res = INF;
  for (int i = l; i < r; i++) {
    chmin(res, rec(l, i) + rec(i + 1, r));
  }

  return dp[l][r] = res + sum[r] - sum[l - 1];
}

