ll solve(vector<int>& v, int i, int j)
{
	if (i == j) return 0;
	if (dp[i][j] != -1) return dp[i][j];

	ll minCost = inf;
	for (int k = i; k < j; k++) {
		minCost = min(minCost, sum[i][j] + solve(v, i, k) + solve(v, k + 1, j));
	}
	return dp[i][j] = minCost;
}

