const int N = 410;
const ll INF = 1e18;
int n, a[N];
ll dp[N][N], pref[N];

ll solve(int left, int right) {
	if (left == right) {
		return 0;
	}
	if (dp[left][right] != -1) {
		return dp[left][right];
	}
	dp[left][right] = INF;
	for (int i = left; i < right; i++) {
		dp[left][right] = min(dp[left][right], solve(left, i) + solve(i + 1, right));
	}
	dp[left][right] += (pref[right] - pref[left - 1]);
	return dp[left][right];
}

