long long calc_cost(int begin, int end, vector<long long>& a, vector<long long>& a_sum, vector<vector<long long>>& memo){
  //cout << begin << ' ' << end << endl;
  if(end - begin == 1){
    return memo[begin][end] = 0;
  }
  if(memo[begin][end] != -1){
    return memo[begin][end];
  }

  long long ret = 1e15;
  // [begin, end) = [begin, sep) + [sep, end)
  for(int sep = begin + 1; sep < end; sep++){
    calc_cost(begin, sep, a, a_sum, memo);
    calc_cost(sep, end, a, a_sum, memo);
    long long sum = a_sum[end] - a_sum[begin];
    ret = min(ret, memo[begin][sep] + memo[sep][end] + sum);
  }
  //cout << memo[begin][end] << endl;
  return memo[begin][end] = ret;
}

