ll rec(int s, int e){
	if(e - s <= 1) return 0;
	if(dp[s][e]) return dp[s][e];
	ll ans = 1LL << 50;
	ll total = accumulate(a.begin() + s, a.begin() + e, 0LL);
	ll pref = 0;
	rep2(m, s, e - 1){
		ll l = rec(s, m), r = rec(m + 1, e);
		ll r_sum = total - pref - a[m];
		if(m == s || m == e - 1) ckmin(ans, a[m] + l + r + pref + r_sum);
