ll calc(ll a[],ll i,ll j,vector<vector<ll>> &sum,vector<vector<ll>> &dp)
{
    if(i==j)
        return 0;

    if(dp[i][j]!=-1)
        return dp[i][j];

    ll ans=INF;

    for(int k=i;k<j;k++)
    {
        ans=min(ans,sum[i][j]+calc(a,i,k,sum,dp)+calc(a,k+1,j,sum,dp));
    }

    return dp[i][j]=ans;
}

