vector<ll> acc;
void init(const vector<int>& a) {
    int n = a.size(); acc.assign(n + 1, 0);
    for (int i = 0; i < n; i++) acc[i + 1] = acc[i] + a[i];
}
ll get(int l, int r) { return acc[r] - acc[l]; }

vector<vector<bool>> vis;
vector<vector<ll>> memo;
ll dp(int l, int r) {
    if (l + 1 == r) return 0;
    if (vis[l][r]) return memo[l][r];
    vis[l][r] = true;
    ll res = INF;
    for (int sep = l + 1; sep < r; sep++) {
        res = min(res, dp(l, sep) + dp(sep, r) + get(l, r));
    }
    return memo[l][r] = res;
}

