ull getWeight(int i, int j, ull *w) {
    // std::cout << i << " " << j << "\n";
    if (i==j) { cost[i][j] = 0; return w[i]; }
    if (~dp[i][j]) { return dp[i][j]; }
    ull min = std::numeric_limits<ull>::max();
    for (int k=i; k<j; k++) {
        ull left_weight = getWeight(i,k,w);
        ull right_weight = getWeight(k+1,j,w);
        ull left_cost = left_weight + cost[i][k];
        ull right_cost = right_weight + cost[k+1][j];
        // min = std::min(min,  left_weight);
        if (left_cost + right_cost < cost[i][j]) {
            min = left_weight + right_weight;
            cost[i][j] = left_cost + right_cost;
        }
    }
    dp[i][j] = min;
    return dp[i][j];
}

void solve() {

    int N; std::cin >> N;
    ull w[N];
    for (int i=0; i<N; i++) { read(w[i]); }
    memset(dp, -1, sizeof(dp));
    memset(cost, std::numeric_limits<int>::max(), sizeof(cost));

    getWeight(0,N-1,w);

    std::cout << cost[0][N-1] << "\n";

}

