void combine(ll k)
{
    ll tmp = stone[k] + stone[k-1];
    ans += tmp;
    for(ll i=k;i<t-1;i++)
        stone[i] = stone[i+1];
    t--;
    ll j = 0;
    for(j=k-1;j>0 && stone[j-1] < tmp;j--)
        stone[j] = stone[j-1];
    stone[j] = tmp;
    while(j >= 2 && stone[j] >= stone[j-2])
    {
        ll d = t - j;
        combine(j-1);
        j = t - d;
    }
}

