ll solve(vector<ll>& picks,int i,int j){
    if(i==j){
        dp[i][j]=0;
        return dp[i][j];
    }
    if(dp[i][j]!=-1)
        return dp[i][j];
    ll minCost=inf;
    for(ll k=i;k<j;++k){
        minCost=min(minCost,arr[i][j]+solve(picks,i,k)+solve(picks,k+1,j));
    }
    return dp[i][j]=minCost;
}   

