lint memo[410][410];

lint rec(int l,int r)
{
	if(memo[l][r]!=-1)
		return memo[l][r];

	if(l==r)
	{
		memo[l][r]=0;
		return memo[l][r];
	}

	lint ret=1e18;
	for(int i=l;i<r;i++)
	{
		if(dp[l][r]==dp[l][i]+dp[i+1][r])
