ll rec(int l, int r, vector<ll> &B) {
    if (l == r - 1) return 0;
    if (dp[l][r] != 0) return dp[l][r];

    ll ans = INF;
    rep2(m, l + 1, r) {
        ans = min(ans, rec(l, m, B) + rec(m, r, B) + B[r] - B[l]);
    }

    dp[l][r] = ans;
    return ans;
}

