int dfs(int l, int r) {
    if (dp[l][r] >= 0) return dp[l][r];
    if (r - l == 1) return dp[l][r] = 0;

    int res = INF;
    FOR(k, l + 1, r - 1) {
        int tmp = dfs(l, k) + dfs(k, r);
        res = min(res, tmp);
    }

    return dp[l][r] = res + sum[r] - sum[l];
}

