ll d[MAXN+1][MAXN+1]; 

ll merge(int a, int b)
{
    if(d[a][b]) return d[a][b];
    if(a==b) return 0;

    ll r = merge(a, a) + merge(a+1, b);
    for(int i=a+2 ; i<=b ; i++)
        r = min(r, merge(a, i-1) + merge(i, b));
    d[a][b] = r + acc[b] - acc[a-1];

    return d[a][b];
}

