const int maxn = 405;
typedef long long ll;
int A[maxn];
ll ta[maxn],memo[maxn][maxn];
ll solve(int l,int r){
    if (l+1 == r)return A[l]+A[r];
    if (l == r)return 0;
    if (l > r)return 0;
    ll &ans = memo[l][r];
    if (ans != -1)return ans;
    ans = LLONG_MAX;
    ll c= ta[r]+ta[l-1];
    for (int k = l+1; k < r;k++){
        ans = min(ans,solve(l,k)+solve(k+1,r));
    }
    return (ans = (ans+c));
}
int main()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
