ll Calculate(int L, int R){

    if(dp[L][R]!=-1)return dp[L][R];

    if(L==R)return dp[L][R]=0LL;

    ll cost = sum(L,R);
    ll ans = 1e18+9;

    for(int i=L;i<=R-1;i++){
        ans = min (ans, Calculate(L,i)+Calculate(i+1,R)+cost);
    }

    return dp[L][R]=ans;
}

