template<class T> inline bool chmin(T& a, T b) {if (a > b) {a = b;return true;}return false;}
template<class T> inline bool chmax(T& a, T b) {if (a < b) {a = b;return true;}return false;}

int N;
ll a[410];
ll memo[410][410];

void init() {
    rep(i, 1, N) a[i] += a[i - 1];
    rep(i, 0, N + 1) rep(j, 0, N + 1) memo[i][j] = INF;
}

ll get(int l, int r) {
    ll rsl = a[r];
    if(l) rsl -= a[l - 1];
    return rsl;
}

ll dp(int l, int r) {
    if(l == r) return 0;
    if(memo[l][r] != INF) return memo[l][r];

    ll rsl = INF;
    rep(i, l, r) chmin(rsl, dp(l, i) + dp(i + 1, r) + get(l, r));
    return memo[l][r] = rsl;
}

