        ll sum = s(l, r);
        for (int pivot = l; pivot < r; pivot++) {
          dp[l][r] = min(dp[l][r], dp[l][pivot] + dp[pivot + 1][r] + sum);
        }
      }
    }
  }

  cout << dp[0][n - 1];
}

