	if(dp[i][j]!=0)return dp[i][j];
	if(i==j){
		dp[i][j]=p[j]-p[i-1];
		return 0LL;
	}
	ll mi=1e16;
	for(ll k=i;k<j;k++){
		mi=min(mi,fun(i,k)+p[k]-p[i-1]+fun(k+1,j)+p[j]-p[k]);
	}
	dp[i][j]=mi;
	return mi;
}
