long long solve(int start, int end) {
    if ((dp[start][end] == 0) and (start != end)) {
        long long res = LONG_LONG_MAX;
        for (int i = start; i < end; ++i)
            res = min(res, pref_sums[i + 1] - pref_sums[start] + pref_sums[end + 1] - pref_sums[i + 1] +
                               solve(start, i) + solve(i + 1, end));

        dp[start][end] = res;
    }

    return dp[start][end];
}

