ll dp[501][501];

ll func(int l, int r, int a[], ll pref[])
{
	if (l == r) return 0;
	auto &ret = dp[l][r];
	if (ret != -1) return ret;

	ret = pref[r+1] - pref[l] + func(l+1, r, a, pref);
	for (int pos = l+1; pos < r; ++pos)
		ret = min(ret, pref[r+1] - pref[l] + func(l, pos, a, pref) + func(pos+1, r, a, pref));
	return ret;
}

void solve()
{
	int n; cin >> n;
	int a[n];
	ll pref[n+1] = {0};
	for (int i = 0; i < n; ++i)
	{
		cin >> a[i];
		pref[i+1] = a[i] + pref[i];
		memset (dp[i], -1, sizeof dp[i]);
	}
	cout << func(0, n-1, a, pref);
}

