const LL INF=1e17;
LL solve(int L, int R)
{
	if(L==R) return 0;
	if(memo[L][R]!=-1) return memo[L][R];
	LL ret=INF;
	LL tmp=0, now=0;
	for(int z=L;z<R;z++)
	{
		if(z!=L)tmp+=(now+datas[z]);
		now+=datas[z];
		if(z==L) ret=min(ret, now+solve(z+1, R)+pref[R]-pref[z]);
		else ret=min(ret, tmp+now+solve(z+1, R)+pref[R]-pref[z]);
//		cout<<L<<" "<<R<<" : ";
//		cout<<"prefix : "<<ret<<endl;
	}
	tmp=0;
	now=0;
	for(int z=R;z>L;z--)
	{
		if(z!=R)tmp+=(now+datas[z]);
		now+=datas[z];
		if(z==R) ret=min(ret, now+solve(L, z-1)+pref[z-1]-pref[L-1]);
		else ret=min(ret, tmp+now+solve(L, z-1)+pref[z-1]-pref[L-1]);
//		cout<<L<<" "<<R<<" : ";
//		cout<<"suffix: "<<ret<<endl;
	}
	return memo[L][R]=ret;
}

