long long dfs(long long L, long long R) {
	if (L > R) return 0;
	if (L == R) return A[L];
	if (dp[L][R] != 0) return dp[L][R];

	long long minx = (1LL << 60);
	for (int i = L + 1; i <= R; i++) {
		minx = min(minx, V[L][R] + dfs(L, i - 1) + dfs(i, R));
	}
	dp[L][R] = minx;
	return minx;
}

