ll modexp(ll x, ll n)
{
    if (n == 0)return 1;
    else if (n % 2 == 0)
    {
        return modexp((x * x) % M, n / 2);
    }
    else
    {
        return (x * modexp((x * x) % M, (n - 1) / 2) % M);
    }
}

ll getFractionModulo(ll a, ll b)
{
    ll c = gcd(a, b);
    a = a / c;
    b = b / c;
    ll d = modexp(b, M - 2);
    ll ans = ((a % M) * (d % M)) % M;
    return ans;
}

void dfs(ll x,ll vis[],vector<ll> adj[],vector<ll> order,vector<ll> ans[])
{
    vis[x]=1;
    for(ll i=order.size()-1;i>=0;i--)
    {
        ans[x].push_back(order[order[i]]);
    }
    order.push_back(x);
    for(ll y: adj[x])
    {
        if(vis[y]==0)
        {
            dfs(y,vis,adj,order,ans);
        }
    }
}

void bfs(ll x,ll vis[],vector<ll> adj[],ll color[])
{
    queue<ll> q;
    q.push(x);
    vis[x]=1;
    while(!q.empty())
    {
        ll cur=q.front();
        q.pop();
        ll cnt=1;
        for(ll y : adj[cur])
        {
            if(vis[y]==0)
            {
                vis[y]=1;
                q.push(y);
                color[y]=(color[cur]+cnt);
                cnt++;
            }
        }
    }
}

