    vector<vector<ll>> dp(N+1, vector<ll>(N+1, LINF));
    for (int i = 0; i < N; i++) { dp[i][i+1] = 0; }
    for (int len = 1; len <= N; len++) {
        for (int x = 0; x <= N - len; x++) {
            int y = x + len;
            for (int z = x + 1; z < y; z++) {
                ll cost = dp[x][z] + dp[z][y] + (cum[z]-cum[x]) + (cum[y] - cum[z]);
                dp[x][y] = min(dp[x][y], cost);
            }
        }
    }

    cout << dp[0][N] << '\n';
}

