typedef long long ll;

map<pair<ll, ll>, ll> dp[401];
ll n, v[401];

const ll p = 11;
const ll mod1 = 1e9+9, mod2 = 1e7+7;

pair<ll, ll> Power[410];
void PowerGen() {
    Power[0] = {1, 1};
    for(int i = 1; i < 410; ++i) {
        Power[i].first = (Power[i-1].first * p)%mod1;
        Power[i].second = (Power[i-1].second * p)%mod2;
}}

pair<ll, ll> doubleHash() {
    ll hashVal1 = 0, hashVal2 = 0;
    for(int i = 0; i < n; ++i) {
        hashVal1 = (hashVal1 + v[i] * Power[i].first)%mod1;
        hashVal2 = (hashVal2 + v[i] * Power[i].second)%mod2;
    }
    return make_pair(hashVal1, hashVal2);
}


ll recur(int sz) {
    //cerr << "SZ " << sz << endl;
    if(sz == 1)
        return 0;

    pair<ll, ll> h = doubleHash();
    auto it = dp[sz].find(h);

    if(it != dp[sz].end()) {
        //cerr << "HIT\n";
        return it->second;
    }

    ll ret = 1000000000000000LL;
    for(int i = 0; i < n; ++i) {
        if(v[i] != 0) {
            for(int j = i+1; j < n; ++j) {
                if(v[j] != 0) {
                    ll x = v[i], y = v[j];
                    v[i] = x+y, v[j] = 0;
                    //cerr << "CHOSE " << i << ", " << j << endl;
                    ret = min(ret, recur(sz-1)+(ll)v[i]);
                    v[i] = x, v[j] = y;
                    break;
                }
            }
        }
    }

    //cerr << "SZ " << sz << " :: " << ret << endl;
    return dp[sz][h] = ret;
}

int main() {
    PowerGen();
    cin >> n;

    for(int i = 0; i < n; ++i)
        cin >> v[i];

    cout << recur(n) << endl;
    return 0;
}

