long long Cal(int L, int R)
{
    if (L == R)
    {
        return 0;
    }
    if (dp[L][R] != 0)
    {
        return dp[L][R];
    }
    dp[L][R] = 1e18;
    for (int i = L; i < R; i++)
    {
        dp[L][R] = min(dp[L][R], Cal(L, i) + Cal(i + 1, R));
    }
    dp[L][R] += ps[R] - ps[L - 1];
    return dp[L][R];
}

