class BIT {

public:
	vll d;
	vll v;
	ll size;
	BIT(ll sizeget) {
		size = sizeget;
		d.asn(size + 1, 0);
		v.asn(size, 0);
	}
	BIT(vll cpyvec) {
		copy(cpyvec);
	}
	void add(ll index, ll num) {
//		if (index < 0) return false;
//		if (index >= size) return false;
		v[index] += num;
		index++;
		while (index <= size) {
			d[index] += num;
			index += LSB(index);
		}
//		return true;
		return;
	}
	ll sum(ll index = INF) {
		index++;
		index = min(index, size);
		ll ans = 0;
		while (index) {
			ans += d[index];
			index -= LSB(index);
		}
		return ans;
	}
	void copy(vll cpyvec) {
		size = cpyvec.sz;
		d.asn(size + 1, 0);
		v.asn(size, 0);
		REP(i, size) add(i, cpyvec[i]);
	}

};

class UFT {

public:
	ll size;
	ll mode;
	vll root;
	vll rank;
	UFT(ll sizeget, ll modeget = 0){
		size = sizeget;
		mode = modeget;
		root.res(size, 0);
		if (!mode) rank.res(size, 0);
		IOTA(root, 0);
	}
	ll find(ll x) {
		return root[x] == x ? x : root[x] = find(root[x]);
	}
	bool same(ll x, ll y) {
		return find(x) == find(y);
	}
	void unite(ll x, ll y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (mode) root[y] = x;
		else {
			if (rank[x] < rank[y]) {
				root[x] = y;
			}
			else {
				root[y] = x;
				if (rank[x] == rank[y]) rank[x]++;
			}
		}
	}
};

ll gcd(ll a, ll b) { if (b == 0)return a; return gcd(b, a%b); }
ll lcm(ll a, ll b) { return a / gcd(a, b)*b; }

ll inverse[N];

void init_inverse() {
	inverse[1] = 1;
	for (int i = 2; i < N; i++) inverse[i] = (MOD - MOD / i) * inverse[MOD%i] % MOD;
}

pl4 Bezout(ll a, ll b) {
	if (b != 0) {
		pl4 xy;
		xy = Bezout(b, a%b);
		return mp(xy.se, xy.fi - ((a / b)*xy.se));
	}
	if (b == 0) {
		return mp(1, 0);
	}
}
pl4 Bez(ll a, ll b, ll c) {
	pl4 xy;
	ll x, y, z, gc;
	xy = Bezout(a, b);
	gc = gcd(a, b);
	if (c%gc != 0) return mp(-1, -1);
	x = xy.fi*(c / gc); y = xy.se*(c / gc);
	if (x < 0) z = rup(-x, (b / gc));
	if (x >= 0) z = -x / (b / gc);
	x += z * (b / gc);
	y -= z * (a / gc);
	return mp(x, y);
}

