int N;

void init() {
  for (int i = 1; i <= N; ++i) {
    for (int j = 1; j <= N; ++j) {
      dp[i][j] = -1;
    }
  }
}

// dp[l][r] = minimal moves to unify slime segment [l, r]
// Transitions are all possible positions of the final split.

lld dfs(int l, int r) {
  if (dp[l][r] >= 0) {
    return dp[l][r];
  }
  if (l == r) {
    return dp[l][r] = 0;
  }
  lld res = INFN;
  for (int m = l; m < r; ++m) {
    res = std::min(
      dfs(l, m) + dfs(m+1, r) + pre[r] - pre[l-1],
      res
    );
  }
  return dp[l][r] = res;
}

int main() {
  scanf("%d", &N);
  init();
  pre[0] = 0;
  for (int i = 1; i <= N; ++i) {
    scanf("%d", &A[i]);
    pre[i] = pre[i-1] + A[i];
  }
  printf("%lld\n", dfs(1, N));
  return 0;
}

