	loop(i,2,n+1) prefix[i] = prefix[i-1] + a[i-1]; 
	// dp[i][j] = min cost for piling up slimes of range [i,j] = min m (dp[i][m] + dp[m+1][j] + prefix[i][j]) , m E [i,j-1].
	for(int j=0;j<n;j++)
	{
		for(int i=j-1;i>=0;i--)
		{
			int mn = INT_MAX;
			for(int m=i;m<j;m++)
				mn = min(mn, dp[i][m] + dp[m+1][j] + prefix[j+1] - prefix[i]);
			dp[i][j] = mn;
		}
	}

	cout<<dp[0][n-1]<<endl;
	return 0;	
}

