const long long pinf = (1ULL << 61) - 1;

vector <vector <long long>> dp;

long long solve(int l, int h, vector <long long> &sum, vector <int> &arr) {
  debug(l, h);
  if (l > h) return 0;
  if (l == h) return 0;
  if (l + 1 == h) {
    return (long long) arr[l] + arr[h];
  }
  if (dp[l][h] != -1) return dp[l][h];

  auto Get = [&](int i, int j) -> long long {
    if (i > j) return 0;
    long long rsum = sum[j];
    long long lsum = i - 1 >= 0 ? sum[i - 1] : 0;
    return rsum - lsum;
  };

  long long ans = pinf;
  for (int i = l; i <= h - 1; i++) {
    long long ll = solve(l, i, sum, arr);
    long long rr = solve(i + 1, h, sum, arr);
    long long cost = Get(l, i) + Get(i + 1, h);
    ans = min(ans, cost + ll + rr);
  }
  return dp[l][h] = ans;
} 

