long long pref[450];
long long dprec(long long l,long long r){

    if(dp[l][r]){
        return dp[l][r];
    }
    if(l == r){

        return dp[l][r] = 0;
    }
    long long holdmin = dprec(l+1,r);
    for(int i=l+1;i<r;i++){
        holdmin = min(holdmin,dprec(l,i)+dprec(i+1,r));
    }
    return dp[l][r] = holdmin + pref[r]-pref[l-1];
}
