using namespace std;

int dp[405][405];
// dp[i][j] the minimum cost to combine between i , j
int solve(int i,int j,int *arr,int *pref){
    if(i>j) return 0;
    if(i == j) return dp[i][j] = 0;
    if(j-i+1 == 2) return dp[i][j] = arr[i]+arr[j];

    if(dp[i][j]!=-1) return dp[i][j];

    int wt = ULLONG_MAX;

    for(int x = i ; x <=j ; x++){
        if(x == i){
            int rt = solve(i+1,j,arr,pref);
            wt = min(wt,arr[i]+rt + pref[j]-pref[i]);
        }
        else if(x == j){
            int left = solve(i,j-1,arr,pref);
            int sec_term = i == 0?pref[j-1]:pref[j-1]-pref[i-1];
            wt = min(wt,arr[x]+left + sec_term);
        }
        else{
            int l = solve(i,x-1,arr,pref);
            int r = solve(x+1,j,arr,pref);
            int right = pref[j] - pref[x] ;
            int left = i==0?pref[x-1]:pref[x-1] - pref[i-1];
            int mid = arr[x];

            wt = min(wt,2*mid+2*left+right+l+r);
            wt =min(wt,2*mid+2*right+left+l+r);
        }
    }
    return dp[i][j] = wt;
}


