unsigned long long int dp(int l, int r) {
    if(flag[l][r] > 0)
        return mem[l][r];
    else if(l == r) {
        mem[l][r] = 0;
        flag[l][r] = 1;
        return mem[l][r];
    } else {
        unsigned long long int min = ULLONG_MAX;
        for(int i = l; i < r; i++) {
            int sumleft;
            if(l > 0)
