map< vector<ll>, ll > dp;

ll dfs(vector<ll> v)
{
    if (dp.find(v) != dp.end()) {
        return dp[v];
    }
    else if (v.size() == 2) {
        dp[v] = v[0] + v[1];
        return dp[v];
    }
    else {
        ll minCost = 1000000000000000;
        for (int i = 0; i < v.size() - 1; ++i) {
            // combine v[i] and v[i + 1]
            ll s = v[i] + v[i + 1];
            vector<ll> u = v;
            u.erase(u.begin() + i + 1);
            u[i] = s;
            ll t = s + dfs(u);
            if (t < minCost) minCost = t;
        }
        dp[v] = minCost;
        return minCost;
    }
}

