long long int recursive(vector<long long int> a) {
  long long int minV = -1;
  if (a.size() == 1) return 0;
  for (int i = 0; i < a.size() - 1; ++i) {
    long long int sum = a[i] + a[i + 1];
    long long int tmp1 = a[i];
    long long int tmp2 = a[i + 1];
    a[i] = sum;
    a.erase(a.begin() + i + 1);
    long long int result = recursive(a);
    result += sum;
    if (minV == -1 || result < minV) minV = result;
    a.insert(a.begin() + i + 1, tmp2);
    a[i] = tmp1;
  }
  return minV;
}

