ll solve(int l,int r){
  if(dp[l][r]<1e16) return dp[l][r];
  if(r-l<=1) return (dp[l][r]=A[l]+A[r]);
  ll res=1e16;
  for(int i=l;i<r;i++){
    ll tmp=solve(l,i)+solve(i+1,r);
    res=min(res,tmp+sum[r+1]-sum[l]);
  }
  return (dp[l][r]=res);
}

