int n;
int a[N];
ll prefix[N];
ll memo[N][N];

ll sum(int l, int r) {
    ll ans = prefix[r];
    if(l > 0) ans -= prefix[l - 1];
    return ans;
}

ll dp(int l, int r) {
    if(l == r) return 0;
    ll &ans = memo[l][r];
    if(ans != -1) return ans;
    ans = oo;
    for(int i = l; i < r; ++i) {
        ll left = sum(l, i);
        ll right = sum(i + 1, r);
        ll cur = left + right + dp(l, i) + dp(i + 1, r);
        ans = min(ans, cur);
    }
    return ans;
}

