    VB arr(n + 1, true);
    arr[0] = arr[1] = false;
    for (LL i = 2; i * i <= n; i++) {
        if (arr[i]) {
            for (LL j = i * 2LL; j <= n; j += i) {
                arr[j] = false;
            }
