//の間のスライムを合成する最小コスト
LL f(int i, int j, VLL &a, VLL &b, VVLL &dp) {
    if (dp[i][j] != INF) return dp[i][j];
    if (j - i == 1) return dp[i][j] = 0;
    for (int k = 1; k < (j - i); k++) {
        dp[i][j] = min(dp[i][j], f(i, i + k, a, b, dp) + f(i + k, j, a, b, dp));
    }
    return dp[i][j] = dp[i][j] + b[j] - b[i];
}

