ll dp(int i, int j) {
	ll& ans = memo[i][j];
	if(ans != -1) return ans;
	if(i == j) return ans = 0;
	if(i + 1 == j) return ans = v[i] + v[j];
	ans = 1e15;
	for (int k = i; k < j; ++k) {
		ans = min(ans, dp(i, k) + dp(k+1, j));
	}
	ans += part[j];
	if(i != 0) ans -= part[i-1]; 
	return ans;
}

