const long long INF = 1e18L + 10;
const int N = 410;
ll prefix_sum[N];
vector<vector<long long>> dp(N, vector<long long> (N, INF));
// dp[i][j] will be the minumum cost to combine slimes [i, j] together


long long get_prefix_sum(int i, int j)
{
  if(i == 0)
    return prefix_sum[j];
  else
    return prefix_sum[j] - prefix_sum[i - 1];
}

int main()
{
  int n;
  scanf("%d", &n);
  vector<long long> a(n);
  for(int i = 0; i < n; i++)
  {
    scanf("%lld", &a[i]);
  }

  prefix_sum[0] = a[0];
  for(int i = 1; i < n; i++)
  {
    prefix_sum[i] = prefix_sum[i - 1] + a[i];
  }

  for(int L = n - 1; L >= 0; L--)
  {
    for(int R = L; R < n; R++)
    {
      if(L == R)
        dp[L][R] = 0;
      else
      {
        for(int i = L; i <= R; i++)
        {
          dp[L][R] = min(dp[L][R], dp[L][i] + dp[i + 1][R] + get_prefix_sum(L, R));
        }
      }
    }
  }
  printf("%lld", dp[0][n - 1]);

  return 0;
}

