ll solve(vl& a, vl& pre, int i, int j) {
    if (i >= j)
        return 0;

    if (dp.count(i) && dp[i].count(j))
        return dp[i][j];

    ll mn = INF(ll);
    rep(k, i, j) {
        mn = min(mn, solve(a, pre, i, k) + solve(a, pre, k + 1, j) + pre[j] - ((i) ? pre[i - 1] : 0));    
    }    

    dp[i][j] = mn;
    return mn;
} 

