ll solve(int l, int r){
    if (l == r) return 0;
    if (dp[l][r]) return dp[l][r];
    ll res = LONG_LONG_MAX;
    ll dif = sm[r] - sm[l-1];
    for(int i = l; i < r; i++){
        res = min(res, solve(l, i) + solve(i+1, r) + dif);
    }
    dp[l][r] = res;
    return dp[l][r];
}

