 ll dp[3001][3001];
 ll sum[3001][3001];

 ll min_cost(vector<ll>vect,ll i,  ll j)
{
    if(i == j)
    	return 0;
    if(dp[i][j] != -1)
    	return dp[i][j];
    ll minC = inf;
    for(int k=i; k<j; k++)
    {
            minC = min(minC, sum[i][j] + min_cost(vect, i, k) + min_cost(vect, k+1, j));
    }
    return dp[i][j] = minC;

}
