void EducationalDP_N()
{
	int N;
	cin >> N;
	vi a(N);
	for (auto& x : a)
		cin >> x;
	vl b(N+1);
	for (int i = 0; i < N; ++i)
		b[i + 1] = b[i] + a[i];

	vvl dp(N, vl(N, 1e12));
	for (int i = 0; i < N; ++i)
		dp[i][i] = 0;
	for (int k = 1; k < N; ++k)
	{
		for (int i = 0; i < N; ++i)
		{
			int j = i + k;
			if (j >= N)
				continue;
			ll B = b[j + 1] - b[i];
			for (int m = i; m < j; ++m)
			{
				dp[i][j] = min(dp[i][j], dp[i][m] + dp[m + 1][j] + B);
			}
		}
	}
	cout << dp[0][N - 1] << endl;
}
