using namespace std;

vector<vector<int> > dp(401, vector<int>(401, -1));
vector<int> v(401);
vector<ll> pre(401, 0);

ll ans(int l, int r) {
    if (l == r)
        return 0;
    else if (dp[l][r] != -1)
        return dp[l][r];

    ll a = LLONG_MAX;
    // first merge (l, i-1) and (i+1, r);
    for (int i = l + 1; i < r; i++) {
        ll cost = 0;

        cost += ans(l, i - 1);
        cost += ans(i + 1, r);

        cost += pre[r] - pre[l - 1];
        cost += min(pre[i] - pre[l - 1], pre[r] - pre[i - 1]);

        a = min(a, cost);
    }
    // when i = l or r
    a = min(a, ans(l + 1, r) - pre[l - 1] + pre[r]);
    a = min(a, ans(l, r - 1) - pre[l - 1] + pre[r]);

    dp[l][r] = a;
    return a;
}

