const int lim = 5e2 + 2;


int N;
ll ai[lim];
ll dp[lim][lim];
bool mark[lim][lim];

ll cumul[lim];

ll query(int a, int b)
{
    return cumul[b] - cumul[a - 1];
}

ll DynamicProgrmming(int le, int ri)
{
    if(le == ri)
        return 0;

    if(mark[le][ri])
        return dp[le][ri];

    mark[le][ri] = true;

    ll curr = inf;

    for(int i = le; i < ri; i++)
    {
        ll auxLe = DynamicProgrmming(le, i);
        ll auxRi = DynamicProgrmming(i + 1, ri);

        ll auxSum = auxLe + auxRi + query(le, ri);

        curr = min(curr, auxSum);
    }
    dp[le][ri] = curr;
    return curr;
}

void solve()
{
    cin >> N;
    for(int i = 1; i <= N; i++)
    {
        cin >> ai[i];
        cumul[i] = cumul[i-1] + ai[i];
    }

    ll answ = DynamicProgrmming(1, N);

    cout << answ;
}


