ll solve(int l, int r) {
    if (l == r) {
        return 0.0;
    }
    ll& d= dp[l][r];

    if (d != -1) {
        return d;
    }

    ll cost = p[r] - (l==0? 0 : p[l-1]);

    d = inf;
    for (int i = l+1; i <= r; i++) {
        d = min(d, solve(l, i-1) + solve(i, r) + cost);
    }

    return d;
}

