int a[400];
LL dp[400][400];    //! [head][tail] minimal cost to merge slimes from head to tail
LL sum[400][400];   //! [head][tail] total size of merged slime from head to tail

LL solve(int head, int tail)
{
    LL ret = dp[head][tail];
    if (!ret) {
        if (head == tail) {
            ret = 0;
        } else if (head+1 == tail) {
            ret = a[head] + a[tail];
        } else {
            //! final merge is done between head and head+1
            ret = a[head] + sum[head+1][tail] + solve(head+1, tail);
            for (int h = head+1; h < tail; ++h) {
                //! final merge is done between h and h+1
                LL x = solve(head, h) + solve(h+1, tail) + sum[head][h] + sum[h+1][tail];
                ret = min(ret, x);
            }
        }
        dp[head][tail] = ret;
        // cout << "dp[" << head << "][" << tail << "] = " << dp[head][tail] << endl;
    }
    return ret;
}

