// dp[l][r]: pair<ll, ll>: size of slime produced by merging [l, r], and cost of it.
p dp[N][N];
ll a[N];
int n;

bool update(ll& a, ll b) {
    if (b < a) {
        a = b;
        return true;
    }
    return false;
}

void solve() {
    for (int i = 0; i < N; ++i) fill(dp[i], dp[i] + N, make_pair(0, __LONG_LONG_MAX__));
    for (int i = 0; i < n; ++i) {
        scanf("%lld", a + i);
    }
    for (int len = 0; len < n; ++len) {
        // [l, r]
        for (int l = 0, r = l + len; r < n; ++l, ++r) {
            if (!len) {
                dp[l][r] = make_pair(a[l], 0); // merge 1 slime need 0 cost
                continue;
            }
            for (int mid = l; mid + 1 <= r; ++mid) {
                // merge two slime [l, mid] and [mid + 1, r]
                ll b = dp[l][mid].first;
                ll c = dp[l][mid].second;
                ll d = dp[mid + 1][r].first;
                ll e = dp[mid + 1][r].second;
                if (b + c + d + e < dp[l][r].second) {
                    dp[l][r] = make_pair(b + d, b + c + d + e);
                }
            }
        }
    }
    // printf("%lld %lld\n", dp[0][n - 1].first, dp[0][n - 1].second);
    printf("%lld\n", dp[0][n - 1].second);
}

int main() {
    while (~scanf("%d", &n)) {
        solve();
    }
    return 0;
}

