ll const MOD = 1000000007;
ll const INF = (long long int)1 << 61;

ll rec(vector<vector<ll>> &dp,const vector<ll> &s_size, ll l, ll r){
    if(dp[l][r] >= 0) return dp[l][r];
    if(l >= r) return (dp[l][r] = 0);

    ll ret = INF;
    for(int i = l; i < r; i++){
        ret = min(ret,rec(dp,s_size,l,i) + rec(dp,s_size,i+1,r) + s_size[r] - s_size[l-1]);
    }

    return (dp[l][r] = ret);
}

