typedef long long ll;

int n;
ll a[410];
ll prefix[410];

ll dp[410][410];

ll go(int l, int r) {

    // sl = sum[0, l - 1]
    // sr = sum[r + 1, n - 1]

    ll sl = prefix[l - 1];
    ll sr = prefix[n - 1] - prefix[r];

    if(r < l) {
        return sl + sr;
    }

    if(dp[l][r] != -1) return dp[l][r];

    ll op1 = sl + a[l] + go(l + 1, r);
    ll op2 = sr + a[r] + go(l, r - 1);

    return dp[l][r] = min(op1, op2);
}

