ll slimes(const vector<ll>& v,int s,int e) {
	if(s>=e)
		return 0;
	if(dp[s][e] != -1)
		return dp[s][e];

	ll ans = inf;

	for(int k=s;k<e;k++) {
		ll currentSum = sum(v,s,k) + sum(v,k+1,e);
		ans = min(ans, currentSum + slimes(v,s,k) + slimes(v,k+1,e));
	}

	return dp[s][e] = ans;
}

