ll f(ll l, ll r) {
    if (l == r) return 0;
    if (r - l == 1) return v[l] + v[r];

    if (dp[l][r] != -1) return dp[l][r];

    ll ans = -1;
    for (ll i = l; i < r; i++) {
        if (ans == -1) {
            ans = f(l, i) + f(i + 1, r) + get(l, i) + get(i + 1, r);
        } else {
            ans = min(ans, f(l, i) + f(i + 1, r) + get(l, i) + get(i + 1, r));
        }
    }
    dp[l][r] = ans;
    return ans;
}

