// [l, r)
ll Solve(int l, int r)
{
    assert(r - l > 0);
    if (dp[l][r] >= 0) return dp[l][r];
    if (r - l == 1) return 0;
    if (r - l == 2) return a[l] + a[l + 1];
    ll res = 1000000000000000000LL;
    for (int m = l + 1; m < r; ++m)
    {
        chmin(res, Solve(l, m) + Solve(m, r) + sum[r] - sum[l]);
    }
    return dp[l][r] = res;
}

