ll store[3005][3005];

ll geti(ll a, ll b, ll c)
{
    return 2*b + min(a,c)*2 + max(a,c);
}

ll get(ll l, ll r, ll arr[], ll pref[])
{
    if(r<=l)
        return 0;
    if(r-l == 1)
        return arr[l] + arr[r];

    if(store[l][r]!=INF)
        return store[l][r];

    ll ans = INF;
    for(ll i=l;i<=r;i++)
    {
        if(i == l)
        {
            ll temp = get(l+1,r,arr,pref) + pref[r+1] - pref[l];
            if(temp<=0)
                continue;
            ans = min(ans, temp);
            continue;
        }

        if(i == r)
        {
            ll temp = get(l,r-1,arr,pref) + pref[r+1] - pref[l];
            if(temp<=0)
                continue;
            ans = min(ans, temp);
            continue;
        }
        ll temp = get(l,i-1,arr,pref)+ get(i+1,r,arr,pref) + geti(pref[i] - pref[l], arr[i], pref[r+1] - pref[i+1]);
        if(temp<=0)
            continue;
        ans = min(ans,temp);
    }
    return store[l][r] = ans;
}

