std::vector<T> make_v(size_t a){return std::vector<T>(a);}

template<typename T,typename... Ts>
auto make_v(size_t a,Ts... ts){
  return std::vector<decltype(make_v<T>(ts...))>(a,make_v<T>(ts...));
}

int main() {
	int n; scanf("%d", &n); std::vector<i64> a(n);
	for(int i = 0; i < n; i++) scanf("%lld", &a[i]);

	auto dp = make_v<i64>(n + 1, n + 1);
	std::function<i64 (int, int)> solve = [&](i64 L, i64 R) {
		if(L >= R) return 0LL;
		if(L + 1 == R) return a[L];

		i64 A = 0, B = 0, ret = 1LL << 60;
		for(int i = L; i < R; i++) A += a[i];
		for(int i = L; i < R - 1; i++) {
			B += a[i]; A -= a[i];

			ret = std::min(ret, solve(L, i + 1) + solve(i + 1, R) + (A + B));
		}
		return dp[L][R] = ret;
	};
	solve(0, n);

	for(auto v: a) dp[0][n] -= v;
	printf("%lld\n", dp[0][n]);
	return 0;
}

