int64_t prefSums[MAX_N + 5], dp[MAX_N + 5][MAX_N + 5];

int64_t GetSum(int32_t low, int32_t high) {
	return prefSums[high] - prefSums[low - 1];
}

int main() {
	std::ios_base::sync_with_stdio(false);
