	}

	for(int32_t j = 2; j <= n; j++) {
		for(int32_t i = n - j + 1; i >= 1; i--) {
			dp[i][j] = INF;

			int32_t low = i, high = i + j - 1;	
			for(int32_t mid = low; mid < high; mid++) {
				int64_t aux = dp[low][mid - low + 1] + dp[mid + 1][high - mid] + GetSum(low, high); 
				dp[i][j] = std::min(dp[i][j], aux);
			}
		}
	}

	std::cout << dp[1][n] << '\n';
}

