const int MAX_N = 400;
const ull MAX_VAL = numeric_limits<ull>::max();
ull costs[MAX_N + 1][MAX_N + 1];
ull sums[MAX_N + 1][MAX_N + 1];
ull inp[MAX_N + 1];

int main() {
	ios_base::sync_with_stdio(false);
	int N; cin >> N;
	for (int i = 0; i <= MAX_N; i++) {
		for (int j = 0; j <= MAX_N; j++) {
			costs[i][j] = MAX_VAL;
		}
	}
	for (int i = 1; i <= N; i++) {
		cin >> inp[i];
		costs[i][i] = 0;
	}

	for (int i = 1; i <= N; i++) {
		sums[i][i] = inp[i];
		for (int j = i + 1; j <= N; j++) {
			sums[i][j] = inp[j] + sums[i][j - 1];
		}
	}

	for (int L = 1; L <= N; L++) {
		for (int start = 1; start + L <= N; start++) {
			for (int div = 0; div + 1 <= L; div++) {
				costs[start][start + L] = min(costs[start][start + L], costs[start][start + div] + costs[start + div + 1][start + L]);
			}
          	costs[start][start + L) +=  sums[start][start + L];
		}
	}
	cout << costs[1][N] << endl;
	return 0;
}

