ll rec(auto &dp, int l, int r){
  if(dp[l][r]!=0) return dp[l][r];
  ll ans=((ll)1<<59);
  ll cst=dp[l][l+1];
  for(int i=l+1;i<r;i++){
    ans=min(ans,rec(dp,l,i)+rec(dp,i,r));
    cst+=dp[i][i+1];
  }
  //cout << l << " " << r << ":" << ans+cst << endl;
