li go(int l, int r) {
	if (l > r) return 0;
	if (l == r) return dp[l][r] = a[l];
	if (dp[l][r] != -1) return dp[l][r];
	li ans = 1e13;
	for (int i = l; i < r; i++) {
		ans = min(ans, go(l, i) + go(i + 1, r));
	}
	return dp[l][r] = ans;
}

li retrace(int l, int r) {
	if (l == r) return 0;
	if (dp2[l][r] != -1) return dp2[l][r];
	li ans = 4e13;
	for (int i = l; i < r; i++) {
		if (dp[l][r] == dp[l][i] + dp[i + 1][r]) {
			ans = min(ans, retrace(l, i) + retrace(i + 1, r));
		}
	}
	return dp2[l][r] = ans + dp[l][r];
}

