template<typename Head, typename Value> auto vectors(const Head &head, const Value &v) { return vector<Value>(head, v); }
template<typename Head, typename... Tail> auto vectors(Head x, Tail... tail) { auto inner = vectors(tail...); return vector<decltype(inner)>(x, inner); }

template<class T, class Func = function<T(T,T)>>
class CumulativeSum{
public:
    vector<T>sum;
    T e;
    CumulativeSum(const vector<T>v,T e,const Func& f = [](T a, T b){return a + b;}) : sum(v.size()),e(e){
        copy(v.begin(),v.end(),sum.begin());
        T past = 0;
        for(auto & itr : sum){
            itr = f(itr,past);
            past = itr;
        }
    }
    //[l,r)
    auto query(Int l, Int r, const Func& f = [](T a,T b){return a - b;}){
        if(r > 0) return f(sum[r - 1],(l == 0 ? 0 : sum[l - 1]));
        else return e;

    }
};
signed main(){
    constexpr Int inf = (1LL << 60);
    Int N; cin >> N;
    vector<Int>v(N);
    for(auto&e : v)  cin >> e;
    CumulativeSum<Int> csum(v,0LL);
    auto dp = vectors(N + 1,N + 1,inf);
    for(Int i = 0; i < v.size(); ++i){
        dp[i][i+1] = 0;
    }
    function<Int(Int,Int)>solve = [&](Int l, Int r) {

        if(dp[l][r] != inf) return dp[l][r] + csum.query(l,r);
        Int minans = inf;
        for(Int i = l + 1; i < r; ++i){
            minans = min(minans, solve(l,i) + solve(i,r));
        }
        dp[l][r] = minans;

        return minans + csum.query(l,r);
    };
    cout << solve(0,v.size())  - accumulate(v.begin(),v.end(),0LL) << endl;
}

