void solve(){
    ll n; cin>>n;
    vec<vec<vec<ll>>> dp(n,vec<vec<ll>>(n,{INF,INF}));
    for(ll i = 0LL; i<n; i++){
        ll x; cin>>x;
        dp[i][i] = {x,0LL};
    }
    for(ll ln = 2LL; ln<n+1; ln++){
        for(ll l = 0LL; l<n-ln+1; l++){
            ll r = l+ln-1;
            for(ll k = l; k<r; k++){
                ll curr_val = dp[l][k][0]+dp[k+1][r][0];
                ll curr_cost = curr_val+dp[l][k][1]+dp[k+1][r][1];
                if(curr_cost<dp[l][r][1]){
                    dp[l][r][0] = curr_val;
                    dp[l][r][1] = curr_cost;
                }
            }
        }
    }
    cout<<dp[0][n-1][1]<<endl;
}
