map<vector<long long int>, long long int> m;

long long f(vector<long long int>& a) {

    int n = a.size();
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return a[0];
    }
    if (n == 2) {
        return a[0] + a[1];
    }

    if (m.find(a) != m.end()) {
        return m[a];
    }

    long long ans = 100000000000000L;

    for (int i = 0; i < n-1; ++i) {
        int x = a[i];
        int y = a[i+1];
        a.erase(a.begin() + i, a.begin() + i + 2);
        a.insert(a.begin() + i, x + y);
        ans = min(ans, x + y + f(a));
        a.erase(a.begin() + i);
        a.insert(a.begin() + i, x);
        a.insert(a.begin() + i + 1, y);
    }


    m[a] = ans;
    return ans;
}


