		ll combineSum = interval(starting, i) + interval(i + 1, ending);
		ll subsetSum = recurse(starting, i) + recurse(i + 1, ending);

		result = min(result, combineSum + subsetSum);
	}

	dp[starting][ending] = result;
	return result;
}


