    if (L == R)return 0;
    ll &ans  = DP[L][R];
    if(ans != -1)return ans;
    ans = INF;
    for(int k = L ; k<R+1 ; k++){
        ans = min(ans , calc(L,k) + calc(k+1,R) + cost(L,R));
    }
    return ans;
}

