typedef long long LL;
LL datas[405];
LL pref[405];
LL memo[405][405];
int n;
const LL INF=1e17;
LL solve(int L, int R)
{
	if(L==R) return 0;
	if(memo[L][R]!=-1) return memo[L][R];
	LL ret=INF;
	for(int z=L;z<R;z++)
	{
		solve(L+1, R);
	}
	for(int z=R;z>L;z--)
	{
		solve(L, R-1);
	}
	LL total=pref[R]-pref[L-1];
	LL now=0;
	for(int z=L;z<R;z++)
	{
		ret=min(ret, now+solve(L, z)+solve(z+1, R)+(total-now));
	}
	return memo[L][R]=ret;
}

