// dp[left][right] := 区間 [left,right) におけるコストの最小値
vector<vector<ll>> dp(405, vector<ll>(405, -1));
ll sum[405];

// メモ化再帰
ll memo_rec(int left, int right){
    if(dp[left][right] != -1)   return dp[left][right];
    if(right - left == 1)   return dp[left][right] = a[left];
    if(right - left < 1)    return 0;

    ll res = numeric_limits<ll>::max();
    for(int pos = left + 1; pos < right; ++pos){
        ll tmp = 0;
        if(pos - left > 1)  tmp += memo_rec(left, pos) + sum[pos] - sum[left];
        else    tmp += memo_rec(left, pos);
        if(right - pos > 1) tmp += memo_rec(pos, right) + sum[right] - sum[pos];
        else    tmp += memo_rec(pos, right);
        chmin(res, tmp);
    }
    return dp[left][right] = res;
}

