long solve(int l, int r){
  if(l >= r) return 0;
  if(dp[l][r] > 0) return dp[l][r];
  long ret = solve(l, l) + solve(l+1, r);
  for(int i=1; i<r-l; i++) ret = min(ret, solve(l, l+i) + solve(l+i+1, r));
  return dp[l][r] = ret + s[r+1] - s[l];
}

