long long dpmin(vector <long long> &arr,long long cost){
    if(arr.size()==1)
        return cost+arr[0];
    if(arr.size()==2)
        return cost+arr[0]+arr[1];
    vector <long long> dp;
    long long min1=LLONG_MAX,pos=-1;
    for(int i=0;i<arr.size()-1;i++){
        if(arr[i]+arr[i+1]<min1){
            min1=arr[i]+arr[i+1];
            pos=i;
        }
    }
    for(int i=0;i<arr.size();i++){
        if(i==pos){
            dp.push_back(arr[i]+arr[i+1]);
            i++;
        }
        else{
            dp.push_back(arr[i]);
        }
    }
    arr=dp;
    return dpmin(arr,cost+min1);
}

