// a^n mod を二分累乗法で計算する
long long modpow(long long a, long long n, long long mod) {
    long long res = 1;
    while (n > 0) {
        if (n & 1) res = res * a % mod;
        a = a * a % mod;
        n >>= 1;
    }
    return res;
}
// a^{-1} mod を計算する
long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m; 
    if (u < 0) u += m;
    return u;
}
long long moddiv(long long a, long long b, long long mod){
    a %= mod;
    return a*modinv(b, mod) % mod;
}
//任意の二項係数nCkをO(n)->O(1)で求める
long long fac[MAX], finv[MAX], inv[MAX];

 // テーブルを作る前処理
void nCkinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

 // 二項係数計算
long long nCk(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
} 

//最大公約数
template<class T>
inline T GCD(const T x, const T y) {
    if (x < 0)return GCD(-x, y);
    if (y < 0)return GCD(x, -y);
    return (!y) ? x : GCD(y, x % y);
}

//最小公倍数
template<class T>
inline T LCM(const T x, const T y) {
    if (x < 0)return LCM(-x, y);
    if (y < 0)return LCM(x, -y);
    return x * (y / GCD(x, y));
}
//探索系
void dfs(VVI& G,VI& O,VI& counter,int u){
    FOREACH(v,G[u]){
        if(counter[v]!=-1) continue;
        counter[v]=counter[u]+O[v];
        dfs(G,O,counter,v);
    }
    return;
}
int bfs(VVI& M){
    const int dx[4]={-1,0,1,0};
    const int dy[4]={0,-1,0,1};
    int h=M.size(),w=M[0].size();   
    queue<PI> q;
    q.push({0,0});
    while(!q.empty()){
        PI u = q.front();
        q.pop();
        REP(i,4){
            PI next={u.first+dx[i],u.second+dy[i]};
            if(next.first<0||next.first>=h||next.second<0||next.second>=w){
                continue;
            }else if(M[next.first][next.second]==0){
                M[next.first][next.second]=M[u.first][u.second]+1;
                q.push(next);
            }
        }
    };
    return M[h-1][w-1];
}
