ll rec(vector<VVL>& dp,int i,int j){
    if(dp[i][j-1][1]!=-1)return  dp[i][j-1][1];

    if(dp[i][j-1][0]==-1){
        dp[i][j-1][0]=0;
        FOR(k,i,j)dp[i][j-1][0]+=dp[k][k][0];
    }
    ll mink = pow(10,15);
    FOR(k,i+1,j){
        mink=min(rec(dp,i,k)+rec(dp,k,j)+dp[i][k-1][0]+dp[k][j-1][0],mink);
    }
    return dp[i][j-1][1]=mink;
}
