ll dpslv(int L, int R) {
	if(dp[L][R]!=LLINF) return dp[L][R];
	if(R-L==2) return dp[L][R]=slime[R]-slime[L];
	ll res=LLINF;
	for(int mid=L+1; mid<R; mid++) {
		chmin(res,dpslv(L,mid)+dpslv(mid,R)+slime[R]-slime[L]);
	}
	return dp[L][R]=res;
}

