pll dp[N][N] = {};
pll solve(ll st, ll en)
{
	if (st > en)
		return {INF, INF};
	if (st == en)
	{
		return {a[st], 0};
	}
	if ((st + 1) == en)
	{
		return {(a[st] + a[en]), (a[st] + a[en])};
	}
	if (dp[st][en].fst != -1 and dp[st][en].scd != -1)
		return dp[st][en];
	pll ans = {INF, INF};
	forab(i, st, (en - 1), 1)
	{
		pll left = solve(st, i);
		pll right = solve(i + 1, en);
		ans.fst = min(ans.fst, (left.fst + right.fst));
		ans.scd = min(ans.scd, (ans.fst + left.scd + right.scd));
	}
	dp[st][en] = ans;
	return ans;
}

