lli func(lli l,lli r)
{
    //cout << l << " " << r << endl;
    if(dp[l][r]!=-1)
        return dp[l][r];
    if(l==r)
    {
        dp[l][r]=v[l];
        return dp[l][r];
    }
    if(r==l+1)
    {
        dp[l][r]=v[l]+v[r];
        return dp[l][r];
    }
    vector<lli>ind=minimum(l,r);
    //cout << ind[0] << endl;
    lli ans=1e18;
    for(lli i=0;i<ind.size();i++)
    {
        if(ind[i]==l)
            ans=min(ans,v[ind[i]]+func(l+1,r)+sum(l+1,r));
        else if(ind[i]==r)
            ans=min(ans,v[ind[i]]+func(l,r-1)+sum(l,r-1));
        else
        {
            lli a=func(l,ind[i]-1),b=func(ind[i]+1,r);
            lli a1=sum(l,ind[i]-1),b1=sum(ind[i]+1,r);
            lli c=2*min(a1,b1)+2*v[ind[i]]+max(a1,b1)+a+b;
            ans=min(ans,c);
        }
    }   
    dp[l][r]=ans;
    return dp[l][r];
}

