ll ans(int l, int r) {
    if (l == r)
        return 0;
    else if (dp[l][r] != -1LL)
        return dp[l][r];

    ll a = LLONG_MAX;
    // merge (l, i-1) and (i, r);
    for (int i = l + 1; i <= r; i++) {
