 for(ll i=0;i<n-1;i++){
  if(a[i]+a[i+1]<ans){
   if(i!=0&&i!=n-1) prev=a[i-1]+a[i+2];
   else if(i==0) prev=a[2];
   else if(i==n-2) prev=a[i-1];
   ans=a[i]+a[i+1];
   ind=i;
  }
  else if(a[i]+a[i+1]==ans){
   ll prev2;
   if(i!=0&&i!=n-1) prev2=a[i-1]+a[i+2];
   else if(i==0) prev2=a[2];
   else if(i==n-2) prev2=a[i-1];
   if(prev2<prev){
    prev=prev2;
    ind=i;
   }
  }
 }
 b[ind+1]=a[ind]+a[ind+1];
 b.erase(b.begin()+ind);
 ans=ans+f(b);
 return memo[a]=ans;
}
