#define N	    	500
ll a[N];
ll dp[N][N];
bool check[N][N];
ll sum[N];

ll get(int l, int r) {
    ll tmp = -1;
    if(check[l][r]) 
        return dp[l][r];

    check[l][r] = true;
    if(l == r) {
        return 0;
    }
    rep(i, l, r) {
        ll a = get(l, i);
        ll b = get(i+1, r);
        if(tmp == -1)
            tmp = a + b;
        else
            tmp = min(tmp, a + b);
    }
    ll ans = sum[r] - sum[l-1] + tmp;
    dp[l][r] = ans;
    return ans;
}

