lli a[404];
lli dp[404][404];
lli s[404];

lli func(lli l,lli r){
    if(dp[l][r]!=-1) return dp[l][r];
    if(l==r) return dp[l][r]=0;
    if(l>r) return 0;
    lli res = 100000000000000;
    for(lli i=l;i<r;i++){
        lli j = func(l,i);
        j = j + func(i+1,r);
        if(l>0) j = j + s[r] - s[l-1];
        else j=j + s[r];
        res = min(res, j);
    }
    return dp[l][r] = res;
}

