ll solve(int i, int j, ll ans) {
    if(i == j) return a[i] * ans;
    if(dp[i][j] != -1) return dp[i][j];

    ans++;

    ll tmp = LONG_MAX;
    chmin(tmp, solve(i+1, j, ans) + (a[i]*ans));
    chmin(tmp, solve(i, j-1, ans) + (a[j]*ans));

    return dp[i][j] = tmp;
}


