//[l, r)
int solve(int l, int r){

    //cout << l << " " << r << endl;
    if(!(dp[l][r] == MOD)) return dp[l][r];
    if(r - l == 1){
        dp[l][r] = 0;
        return dp[l][r];
    }

    int rec = MOD;
    int sum = 0;
    for(int i = l; i < r; i++){
        sum += a[i];
    }

    for(int i = l + 1; i < r; i++){    
        rec = min(rec, solve(l, i) + solve(i, r) + sum);
    }

    dp[l][r] = rec;
    return dp[l][r];
}

