  // 区間DPする
  for (int w = 2; w <= n; w++)  // w…横幅
    for (int i = 0; i + w <= n; i++)
      for (int j = i + 1; j < i + w; j++)
        dp[i][i + w] = min(dp[i][i + w], dp[i][j] + dp[j][i + w] + s[i][i + w]);

  cout << dp[0][n] << endl;
