/*

dp[l][r] = Min. possible cost in joining slimes a[l, l+1, ..., r] and making it into 1 slime.

dp[l][r] = min(dp[l][i]+dp[i+1][r]+pre[r]-pre[l]+a[l], l<=i<r)

dp[i][i+1] = a[i]+a[i+1]
dp[i][i] = 0
*/

#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef unsigned long long ull;

const ull INF = 1e17;
const ll MDO = 1e9+7;

int main(){
	int n;
	vector<ull> a, pre;
	vector<vector<ull> > dp;
	cin>>n;
	a.assign(n+1, 0);
	pre.assign(n+1, 0);
	dp.assign(n+1, vector<ull>(n+1, 0));
	for(int i=0;i<n;i++){
		cin>>a[i];
	}
	pre[0] = a[0];
	for(int i=1;i<n;i++){
		pre[i] = pre[i-1]+a[i];
	}
	for(int l=n-1;l>=0;l--){
		for(int r=0;r<n;r++){
			if(l==r)
				continue;
			ull mini = INF;
			for(int i=l;i<r;i++){
				mini = min(mini, dp[l][i]+dp[i+1][r]+pre[r]-pre[l]+a[l]);				
			}
			dp[l][r] = mini;
		}
	}
	cout<<dp[0][n-1]<<"\n";
	return 0;
}

