void solve(ll n,vector<ll> &v)
{
    if(n>1)
    {
    ll min=LLONG_MAX;
    ll min_index;
    for(int i=0;i<v.size()-1;i++)
    {
        ll sum=v.at(i)+v.at(i+1);
        if(min>sum)
        {
            min=sum;
            min_index=i;
