int minMerge(int i,int j,int* arr)
{
    if(i==j)
        return 0;
    if(v[i][j])
        return dp[i][j];
    v[i][j]=1;
    int& x=dp[i][j];
    x=INT_MAX;
    int tot=0;
    for(int k=i; k<=j; k++)
        tot+=arr[k];
    for(int k=i+1; k<=j; k++)
    {
        x=min(x,tot+minMerge(i,k-1,arr)+minMerge(k,j,arr));
    }
    return x;
}
