ll dp[MAX_N][MAX_N];

void init(){
    rep(i,MAX_N){
        rep(j,MAX_N){
            dp[i][j] = -1;
        }
    }
}


ll f(int l, int r){
    if(dp[l][r]>=0) return dp[l][r];
    if(l == r) return dp[l][r] = 0;

    // どこで切るか全通り試す
    ll res = INF;
    for(int m=l; m<r; m++){
        res = min(res, f(l,m)+f(m+1,r));
    }
    if(l == 0) res = res + a[r];
    else res = res + a[r]-a[l-1];
    return dp[l][r] = res;
}


