int mmnmm(int st, int en)
{
    if (memoneMomo[st][en] != INF) return memoneMomo[st][en];
    int ret = INF;
    for (int i = st; i < en; i++) {  // i は左
        ret = min(ret, mmnmm(st, i) + mmnmm(i+1, en) + ruisekiSum[i+1] - ruisekiSum[st] + ruisekiSum[en+1] - ruisekiSum[i+1]);
    }
    return memoneMomo[st][en] = ret;
}

