const int MAXN = 410;

long long int n;
long long int a[MAXN];

long long int parent(long long int index){
	return index/2;
}

long long int leftChild(long long int index){
	if(index*2 > n)
		return -1;
	return index*2;
}

long long int rightChild(long long int index){
	if (index*2+1 > n)
		return -1;
	return index*2+1;
}

long long int father(long long int index){
	return index/2;
}

void bubbleDown(long long int index){
	long long int min = index;
	if (leftChild(index) != -1 && a[leftChild(index)] < a[index])
		min = leftChild(index);
	if (rightChild(index) != -1 && a[rightChild(index)] < a[min])
		min = rightChild(index);
	if (min == index)
		return;
	swap(a[index], a[min]);
	bubbleDown(min);
}

void bubbleUp(long long int index){
	if (index == 1 || a[father(index)] <= a[index]){
		return;
	}
	swap(a[index], a[father(index)]);
}

void push(long long int num){
	n++;
	a[n] = num;
	bubbleUp(n);
}

long long int extractMin(){
	swap(a[1], a[n]);
	n--;
	bubbleDown(1);
	return a[n+1];
}

void makeHeap(){
	for (long long int i = n; i >= 1; i--)
		bubbleDown(i);
}

int main(){
	cin >> n;
	for (long long int i = 1; i <= n; i++){
		cin >> a[i];
	}
	makeHeap();
	long long int price = 0;
	while (n > 1){
		long long int x = extractMin();
		long long int y = extractMin();
		price += x + y;
		push(x + y);
	}
	cout << price << endl;
	return 0;
}

