long long f_imp(int l, int r)
{
	if (l == r)
		return 0;
	long long rs = LONG_LONG_MAX/2;
	for (int i = l; i < r; i++)
	{
		rs = min(rs, f(l, i) + f(i + 1, r) + ps[r] - ps[l - 1]);
	}
	return rs;
}

