const ll INF = numeric_limits<ll>::max();

ll getMinCount (const vector <ll> &arr) {
    int n = arr.size();
    vector <vector <ll>> dp(n, vector <ll> (n, INF));

    for (int left = n - 1; left >= 0; --left) {
        for (int right = left; right < n; ++right) {
            if (left == right) {
                dp[left][right] = 0;
            } else {
                dp[left][right] = INF;
                ll sum = accumulate(arr.begin() + left, (arr.begin() + right + 1), (ll)0);
                for (int i = left; i < right; ++i) {
                    dp[left][right] = min(dp[left][right], dp[left][i] + dp[i + 1][right] + sum);
                }
            }
        }
    }
    return dp[0][n - 1];
}

