#include <algorithm>

#define MAX_N (400L)
#define INF (1000000000000000000L)

using namespace std;

long dpss[MAX_N + 1][MAX_N + 1];

void init(long N) {
  for (long i = 0; i <= N; i++) {
    for (long j = 0; j <= N; j++) {
      dpss[i][j] = -1;
    }
  }
}

long calc_cost(const long *as, long b, long e) {
  if (e - b <= 1) {
    return 0;
  }
  if (dpss[b][e] < 0) {
    long dp = INF;
    for (long m = b + 1; m <= e - 1; m++) {
      dp = min(dp, calc_cost(as, b, m) + calc_cost(as, m, e));
    }
    for (long i = b; i < e; i++) {
      dp += as[i];
    }
    dpss[b][e] = dp;
  }
//   printf("b = %ld, e = %ld, dpss[b][e] = %ld\n", b, e, dpss[b][e]);
  return dpss[b][e];
}

int main() {
  // read inputs
  long N, as[MAX_N];
  scanf("%ld", &N);
  for (long i = 0; i < N; i++) {
    scanf("%ld", &as[i]);
  }

  // solve dp
  init(N);
  printf("%ld\n", calc_cost(as, 0, N));
}

