template <class RandomIt>
intmax_t hoge(RandomIt first, RandomIt last) {
  if (first+1 == last) return 0;
  intmax_t whole = std::accumulate(first, last, 0L);
  intmax_t part = 0;
  RandomIt it;
  for (it = first; it < last; ++it) {
    if ((part+*it)*2 > whole) {
      if (std::abs(2*(part+*it)-whole) < std::abs(2*part-whole))
        part += *it++;
      break;
    }
    part += *it;
  }
  return whole + hoge(first, it) + hoge(it, last);
}

int main() {
  size_t N;
  scanf("%zu", &N);

  std::vector<intmax_t> a(N);
  for (auto& a_i: a) scanf("%jd", &a_i);
  printf("%jd\n", hoge(a.begin(), a.end()));
}

