int merge(int l, int r){
    if (r-l <= 1) return 0;
    if (r-l == 2) return a[l] + a[l+1];
    if (dp[l][r]) return dp[l][r];
    int ret = 1LL << 60;
    FOR(mid, l+1, r){
        int lsize = rui[mid] - rui[l];
        int rsize = rui[r] - rui[mid];
        int lcost = merge(l,mid);
        int rcost = merge(mid,r);
        ret = min(ret, lsize + rsize + lcost + rcost);
    }
    return dp[l][r] = ret;
}

