ll rec(int l, int r,  vector<int> & values, map<vector<int>, ll> & memo) {
	if (l >= r) return 0;
	if(r - l == 1) return values[l] + values[r];
	vector<int> cur = {l, r};
	if(memo.count({cur})) return memo[cur];

	ll acc = inf;
	ll curAcc = accumulate(values.begin() + l, values.begin() + r + 1, 0l); 
	for (auto k = l; k < r; ++k) {
		acc = min(acc, rec(l, k, values, memo) + rec(k + 1, r, values, memo));
	}
	acc += curAcc;
	memo[cur] = acc;
	return acc;
}
