    int sum=0;
    for(int k=i;k<=j;k++){
        sum+=a[k];
    }
    return sum;
}
int slime(int *a,int i,int j,int dp[][401]){
    if(i>=j){
        return 0;
    }
    if(dp[i][j]!=-1){
        return dp[i][j];
    }
    int ans=LONG_LONG_MAX;
    for(int k=i;k<=j-1;k++){
        ans=min(ans,sum(a,i,j)+slime(a,i,k,dp)+slime(a,k+1,j,dp));
    }
    return dp[i][j]=ans;
}
int32_t main(){
    int n;
    cin>>n;
    int a[401];
    for(int i=1;i<=n;i++){
        cin>>a[i];
    }
    int dp[401][401];
    memset(dp,-1,sizeof dp);
    cout<<slime(a,1,n,dp)<<endl;
    return 0;
}

