    pre[0]=a[0];
    for(int i=1;i<=n;i++)
        pre[i]=pre[i-1]+a[i];
    for(int l=1;l<=n;l++)
    {
        for(int i=0;i<=n-l;i++)
        {
            int j=i+l-1;
            if(l==1)
