  a.insert(a.begin(), 0);
  for (size_t i = 1; i <= n; ++i) a[i] += a[i-1];

  intmax_t const inf = 1e18;
  auto dp = make_vector({n, n+1}, inf);
  for (size_t i = 0; i < n; ++i) dp[i][i+1] = 0;

  for (size_t w = 2; w <= n; ++w) {
    for (size_t i = 0; i+w <= n; ++i) {
      intmax_t cur = a[i+w] - a[i];
      for (size_t  j = i+1; j < i+w; ++j) {
        dp[i][i+w] = std::min(dp[i][i+w], dp[i][j] + dp[j][i+w] + cur);
      }
    }
  }

  printf("%jd\n", dp[0][n]);
}

