const ll INF = numeric_limits<ll>::max();

// [from, to)
ll get_sum(const vector<ll>& pref, int from, int to)
{
    ll left = 0;
    if(from - 1 >= 0)
        left = pref[from - 1];

    ll right = pref[to - 1];
    return right - left;
}

int main()
{
    int n;
    cin >> n;

    vector<ll> v(n);

    for(int i = 0; i < n; ++i)
        cin >> v[i];

    vector<ll> pref(n);
    pref[0] = v[0];

    for(int i = 1; i < n; ++i)
        pref[i] = pref[i - 1] + v[i];

    vector<vector<ll> > dp(n, vector<ll>(n + 1, INF));

    for(int i = 0; i < n; ++i)
        dp[i][i + 1] = 0;

    for(int len = 2; len <= n; ++len) {
        for(int left = 0; left + len <= n; ++left) {
            int right = left + len;

            for(int k = left + 1; k < right; ++k) {
                ll cur = dp[left][k] + dp[k][right] +
                         get_sum(pref, left, k) + get_sum(pref, k, right);

                dp[left][right] = min(cur, dp[left][right]);
            }
        }
    }


    cout << dp[0][n] << endl;

    return 0;
}

