using namespace std;

int n;
vector<long long> a;
vector<vector<pair<long long, long long>>> DP;

int main()
{
	cin >> n;
	a.resize(n + 1);
	for (int i = 1; i < n + 1; i++)
		cin >> a[i];

	// I spent a lot of time thinking about how to represent the data after merge
	// the key idea is to never use input array after initialization
	// got the idea of 2D DP from Errichto
	// DP[i][j] can store 2 things: 
	// 1. total energy generated by merging from i to j
	// 2. sum of elements from i to j (used to calculate energy for future merges)
	// i 1 ... n, j 1 ... n
	DP.resize(n + 1);
	for (int i = 0; i < n + 1; i++)
		DP[i].resize(n + 1, { 0, 0 });

	for (int i = n; i >= 1; i--)
	{
		for (int j = 1; j< n + 1; j++)
		{
			if (j < i)
				continue;
			if (j == i) // update the sum, no energy generated
			{
				DP[i][j].second = a[i];
				DP[i][j].first = 0;
			}
			else if (j == i + 1)
			{
				DP[i][j].second = a[i] + a[j];
				DP[i][j].first = DP[i][j].second;
			}
			else if (j == i + 2)
			{
				DP[i][j].second = DP[i][i+1].second + a[j];
				DP[i][j].first = DP[i][j].second;
				DP[i][j].first += min(DP[i][i + 1].first , DP[i + 1][j].first);
			}
			else//j>=i+3
			{
				// i merge with i+1 or i merge with [i+1, j]
				DP[i][j].second = a[i] + DP[i + 1][j].second;
				DP[i][j].first = DP[i][j].second;
				DP[i][j].first += min(min(min(DP[i][i + 1].first + DP[i + 2][j].first, DP[i + 1][j].first), DP[i][j - 1].first), DP[j - 1][j].first + DP[i][j - 2].first);
			}
		}
	}
	cout << DP[1][n].first << endl;
}

