#define FOR(i,a,b) for(int i=(a);i<(b);++i)
#define REP(i,n) FOR(i,0,n)
#define OUT(v) cout<<v<<"\n"
const int MOD = 1e9+7;
const ll INF = 1e15;
const int MAX_N = 405;

int N;
int A[MAX_N];
ll dp[MAX_N][MAX_N];
ll sum[MAX_N];
ll solve(int s, int t) {
  if (dp[s][t] != INF)
    return dp[s][t];
  if (s + 1 >= t)
    return dp[s][t] = 0;
  if (s + 2 >= t)
    return dp[s][t] = sum[t] - sum[s];

  ll ans = INF;
  FOR(i, s + 1, t)
    ans = min(ans, (sum[t] - sum[s]) + solve(s, i) + solve(i, t));

  return dp[s][t] = ans;
}
int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  cin >> N;

  sum[0] = 0LL;
  REP(i, N) {
    cin >> A[i];
    sum[i+1] = (ll)sum[i] + A[i];
  }

  REP(i, MAX_N) REP(j, MAX_N)
    dp[i][j] = INF;

  OUT(solve(0, N));

  return 0;
}

