ll matrix(vector<ll> &p, int n)
{
    ll m[n+1][n+1],pre[n+1];
    pre[0]=0;
    for(int i=1;i<=n;i++)
        pre[i]=pre[i-1]+p[i-1];

    int i, j, k, L;
    memset(m,0,sizeof m);
    for (L=2; L<=n; L++)
    {
        for (i=1; i<=n-L+1; i++)
        {
            j = i+L-1;
            m[i][j] = INF;
            for (k=i; k<=j-1; k++)
            {
              ll  q = m[i][k] + m[k+1][j];
                if (q < m[i][j])
                {
                    m[i][j] = q;
                }
            }
            m[i][j]+=pre[j]-pre[i-1];
        }
    }
