ll dp[3000][3000],sum[3000][3000];
ll solve(vector<ll> &v,ll i,ll j){
	if(i==j)
		return 0;
	if(dp[i][j]!=-1) return dp[i][j];
	ll mincost=1e16;
	for(ll k=i;k<j;k++){
		mincost=min(mincost,sum[i][j]+solve(v,i,k)+solve(v,k+1,j));

	}
	return dp[i][j]=mincost;
}
void preprocess(vector<ll> &v){
	for(ll i=1;i<=v.size();i++){
		for(ll j=i;j<=v.size();j++){
			sum[i][j]=v[j] + ( (j==i) ? 0 : sum[i][j-1]);
		}
	}
}
