inline ll range_sum(int l, int r) {
    return subsum[r] - subsum[l];
}

ll calc(int l, int r) {
    if (r - l < 1) return 1e15;
    if (r - l == 1) return 0;
    if (dp[l][r] < 0) {
        ll res = 1e15;
        for (int i = l+1; i < r; i++) {
            res = min(res, calc(l, i) + calc(i, r) + range_sum(l, r));
        }
        dp[l][r] = res;
    }
    return dp[l][r];
}

ll solve() {
    memset(dp, -1, sizeof(dp));
    for (int i = 1; i <= n; i++) {
        subsum[i] = subsum[i-1] + a[i-1];
    }
    return calc(0, n);
}

