int n;
ll a[N], psuma[N];
ll f[N][N];


ll DP(int L, int R) {
    ll &ans = f[L][R];
    if (ans != -1) return ans;
    if (L == R) return ans = 0;
    ans = inf;
    for(int i = L; i < R; i++) 
        ans = min(ans, DP(L, i) + DP(i + 1, R));
    return ans += psuma[R] - psuma[L - 1];
}
