#define mod 1000000007
#define ll long long
ll dp[3001][3001];
ll sum[3001][3001];
ll solve(int *a , int i , int j){
   if(i == j){
       return 0;
   }
   if(dp[i][j] != -1){
       return dp[i][j];
   }
   ll minCost = (1ll<<60);
   for(int k=i ; k<j ; k++){
       minCost = min(minCost , sum[i][j] + solve(a , i , k ) + solve(a , k+1 , j));
   }
   return dp[i][j] = minCost;
}
