ll rec(int l,int r,vector<vector<ll>>& dp,vector<ll>& sums) {
    if (dp[l][r]) return dp[l][r];
    ll ret = INT64_MAX;
    if (r-l) {
        for (int i = l;i < r;++i) ret = min(ret,rec(l,i,dp,sums)+rec(i+1,r,dp,sums)+sums[r+1]-sums[l]);
    } else ret = 0;
    return dp[l][r] = ret;
}

