		cin >> cost[i];
		dp[i][i] = 0;
	}
	prefix[0] = cost[0];
	for (int i = 1; i < n; i++) {
		prefix[i] = prefix[i - 1] + cost[i];
	}
	cout << solve(0, n - 1) << "\n";
	return 0;
