      int j = i + L - 1;
      if (L == 2) {
        dp[i][j] = arr[i] + arr[j];
      } else {
        dp[i][j] = inf;
        for (int k = i; k <= j; k++) {
          if (k == i) {
            dp[i][j] = min(dp[i][j], dp[i + 1][j] + sum(i, j));
          } else if (k == j) {
            dp[i][j] = min(dp[i][j], dp[i][j - 1] + sum(i, j));
          } else {
            long long ans = 0, lef = dp[i][k - 1], rig = dp[k + 1][j];
            if (k - i > 1) ans += lef; // left
