            if (j - k > 1) ans += rig;
            ans += arr[k] + sum(k + 1, j);
            ans += arr[k] + sum(k + 1, j) + sum(i, k - 1);
            dp[i][j] = min(dp[i][j], ans);
          }
        }
      }
    }
  }
  cout << dp[0][n - 1] << endl;
