    ll& ret = dp[l][r];
    if (l == r) return ret = 0;
    else if (ret != 1e15) return ret;

    ret = 1e15;
    for (int m=l; m<r; ++m) {
        ret = min(ret, solve(l, m) + solve(m+1, r) + get(l, r));
    }

    return ret;
}

