int rec(int i, int j) {
    if (i >= j) return 0;
    if (dp[i][j] >= 0) return dp[i][j];
    if (i + 1 == j) return dp[i][j] =  A[i] + A[j];

    int ret = 0 + rec(i+1, j) + S[j+1] - S[i];
