ll sol(int l ,int r) {
    if(l == r) return 0;

    ll &ret = dp[l][r];
    if(ret != -1) return ret;

    ret = 1e18L;
    for(int i = l; i < r; i++) {
        ret = min(ret, sol(l, i) + sol(i + 1, r) + pre[r + 1] - pre[l]);
    }

    return ret;
}



