void go(vector<ll> arr)
{
    queue <pair<vector<ll>,ll>> q;
    q.push({arr,0});

    while(!q.empty())
    {
        pair<vector<ll>,ll> p = q.front();
        vector<ll> v = p.first;
        ll curr = p.second;
        int len = v.size();
        q.pop();

        if(len <= 2)
        {
            //cout << curr + v[0] + v[1] << endl;
            ans = min(ans,curr+v[0]+v[1]);
        }    
        else
        {
            for(int i=0;i<len-1;i++)// len = 3,i=1 
            {
                vector<ll> t(v);

                ll cost = t[i] + t[i+1];
                t.insert(t.begin()+i+2,cost);

                t.erase(t.begin()+i);
                t.erase(t.begin()+i);

                q.push({t,curr+cost});
                t.clear();
            }
        }
    }    
}        

