long long int hello(int l, int r){
	if (r - l < 2)
		return 0;

	if (dp[l][r] != 0)
		return dp[l][r];

	long long int sum = 0;
	for (int i = l; i < r; i++)
		sum += a[i];

	long long int res = inf;
	for (int i = l+1; i < r; i++){
		res = min(hello(l, i) + hello(i, r), res);
	}

	dp[l][r] = res + sum;
	return dp[l][r];
}

