ll rekur(int a,int s)
{
	if(s-a==0)return 0;
	if(s-a==1)return arr[a]+arr[s];
	if(dp[a][s]!=-1)return dp[a][s];
	dp[a][s]=0;
	ll temp=(ll)1e18;
	for(int q=a;q<s;q++)
	{
		temp=min(temp,(prefix[q]-prefix[a-1]) + (prefix[s]-prefix[q]) + rekur(a,q) + rekur(q+1,s));
	}
	dp[a][s]=temp;
	return dp[a][s];
}

