const int mx=404;
ll pre[mx];
ll arr[mx];
ll dp[mx][mx];
const ll inf=1e14;
ll cal(ll L,ll R){
    if(L>R){
        return inf;
    }
    return pre[R]-pre[L-1];
}

ll solve(int L,int R){
    if(dp[L][R] != -1)return dp[L][R];
    if(L==R)return dp[L][R]=0;
    if((L+1)==R)return dp[L][R]=arr[L]+arr[R];

    ll best=1e15;
    for(int i=L;i<R;i++){
            ll cans=solve(L,i)+solve(i+1,R)+cal(L,R);
        best=min(best,cans);
    }

    return dp[L][R]=best;
}


