LL dfs(int l, int r) {
   if (visit[l][r]) return dp[l][r];
   visit[l][r] = 1;
   if (r - l == 1) return dp[l][r] = 0;
   LL ans = (LL)1e18;
   for (int i = l + 1; i <= r - 1; i++) {
       ans = min(ans, dfs(l, i) + dfs(i, r) + psum[r - 1] - psum[l - 1]);
   }
   //printf("l = %d r = %d dp = %lld\n", l, r, ans);
   return dp[l][r] = ans;
}

