// // i番目以降の品物から重さの総和がj以下になるように選ぶ
void rec(ll l, ll r){
	if (dp[l][r]!=-1) return;
	else{
		if (r-l==0) dp[l][r] = 0;
		else if (r-l==1) dp[l][r] = a[l] + a[r];
		else{
		ll tmp = INF;
			for (ll i = l; i < r; ++i){ // [l-r)-> [l-i)+[i+1-l]
				rec(l, i);
				rec(i+1, r);
				tmp = min(tmp, dp[l][i] + dp[i+1][r]);
			}
		for (ll i = l; i <= r; ++i) tmp += a[i];
		dp[l][r] = tmp;
		}
		// printf("%lld - %lld: %lld\n", l, r, dp[l][r]);
	}
	return;
}


