void fill(std::vector<long> &v,std::vector<long> &sum,std::vector<std::vector<long> > &cost){
	int n=v.size();
	for(int l=2;l<=n;l++){
		for (int i = 0; i < n-l+1; ++i)
		{
			int j=i+l-1;
			long mini=LONG_MAX;
			for(int k=i;k<j;k++){
				if(i)mini=min(mini,cost[i][k]+cost[k+1][j]+sum[j]-sum[i-1]);
				else mini=min(mini,cost[i][k]+cost[k+1][j]+sum[j]);

			}
			cost[i][j]=mini;
		}
	}
	return ;
}
