int N;							//number of elements in set
int a[MAXN];					//given set
long long dp[MAXN][MAXN];	//dp table for minimum cost of merging elements from [i]to[j]
long long sum[MAXN][MAXN];	//actually not necessary
long long cost;				//dynamic cost for minimization

long long solve(int i,int j){
	if(i==j){
		dp[i][j] = 0;
		sum[i][j] = a[i];
	}
	else if(dp[i][j]==0){
		dp[i][j] = INT64_MAX;
		for(int k=i;k<j;k++){
			solve(i,k);
			solve(k+1,j);
			cost = dp[i][k] + dp[k+1][j] + sum[i][k] + sum[k+1][j] ;
			if(dp[i][j]>cost){
				dp[i][j]  = cost;
				sum[i][j] = sum[i][k] + sum[k+1][j];
			}
		}
	}

	return dp[i][j];
}

