ll minval(ll ar[],ll i,ll j,ll c){
	if(i==j){
		return ar[i];
	}
	if(j-i==1){
		return (ar[i]+ar[j]);
	}

	if(dp[i][j][c]!=-1){
		return dp[i][j][c];
	}

	ll k,f,l=100000000000;
	ll tr[(j-i)];
	for(k=i;k<j;k++){
		ll z=0;
		for(f=i;f<=j;f++){
			if(f==k){
				tr[z++]=ar[f]+ar[f+1];
				f++;
			}
			else {
				tr[z++]=ar[f];
			}
		}
		l=min(l,ar[k]+ar[k+1]+minval(tr,i,j-1,k));	
	}
	//cout<<i<<" "<<j<<" "<<c<<" "<<l<<endl;
	return l;
}
