int64_t dp[401][401], p[401];

inline int64_t rsq(int l, int r) {
	if(l == 0) return p[r];
	return p[r] - p[l - 1];
}

int64_t recurse(int i, int j) {
	int64_t& state = dp[i][j];
  	if(state != -1) return state;
  	if(i == j) return state = 0;
  	state = numeric_limits<int64_t>::max();
  	int64_t cost = rsq(i, j);
  	for(int k = i; k < j; ++k) {
    	state = min(state, recurse(i, k) + recurse(k + 1, j) + cost);
    }
  	return state;
}

