ll rec(int l,int r){
    if(dp[l][r]>0) return dp[l][r];

    if((r-l)==1) return dp[l][r]=0;

    if((r-l)==2) return dp[l][r] = cum_sum[r]-cum_sum[l];

    ll res = INF;
    for(int i=l+1;i<r;++i){
        res = min(res,rec(l,i)+rec(i,r));
    }

    dp[l][r] = res + cum_sum[r]-cum_sum[l];
    return dp[l][r];

}

