ll dp[nax][nax], cost[nax][nax] = {0}, arr[nax] = {0}, prefix[nax] = {0}, n;

ll range(ll l, ll r){
    if(l > r) swap(l, r);
    return prefix[r] - (l ? prefix[l-1] : 0);
}

int main(int argc, char **argv){
    ios_base::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL);
    memset(dp, INF, sizeof dp);

    cin >> n;
    for(ll i = 0; i < n; ++i) cin >> arr[i];

    prefix[0] = arr[0];
    for(ll i = 1; i < n; ++i) prefix[i] = prefix[i-1] + arr[i];

    for(ll i = n-1; i >= 0; --i){
        for(ll j = i; j < n; ++j){
            if(i == j) dp[i][j] = 0;
            for(ll k = i; k <= j-1; ++k){
                dp[i][j] = min(dp[i][j], dp[i][k] + dp[k+1][j] + range(i, j));
            }
        }
    }
    cout << dp[0][n-1] << endl;

    return 0;
}

