int n;
int arr[N];
int p[N];
long long sz[N];

int fs(int u) {
  return (p[u] == u ? u : p[u] = fs(p[u]));
}

void join(int x, int y) {
  int a = fs(x), b = fs(y);
  if (a != b) {
    p[b] = a;
    sz[a] += sz[b];
  }
}

int32_t main() {
  cin >> n;
  for (int i = 0; i < n; i++) cin >> arr[i];
  for (int i = 0; i < n; i++) {
    p[i] = i;
    sz[i] = arr[i];
  }
  multiset < pair <int, pair <int, int> > > ms;
  set <int> s;
  for (int i = 0; i < n; i++) s.insert(i);
  for (int i = 0; i + 1 < n; i++) {
    ms.insert({arr[i] + arr[i + 1], {i, i + 1}});
  }
  long long ans = 0;
  while (s.size() > 1) {
    auto it = *(ms.begin()); ms.erase(ms.begin());
    int w = it.first, x = fs(it.second.first), y = fs(it.second.second);
    if (w != sz[x] + sz[y]) continue;
    if (!s.count(x) || !s.count(y)) continue;
    ans += w;
    join(x, y);
    s.erase(y);
    auto pos = s.lower_bound(x);
    if (pos != s.begin()) {
      pos--;
      ms.insert({sz[fs(*pos)] + sz[x], {fs(*pos), x}});
      pos++;
    }
    if (pos != (--s.end())) {
      pos++;
      ms.insert({sz[x] + sz[fs(*pos)], {x, fs(*pos)}});
      pos--;
    }
  }
  cout << ans << endl;
  return 0;
}

