const ll oo = 1e18;

ll dp[N][N];
ll a[N];

ll solve(int l, int r)
{
	if(l > r)
		return oo;

	if(l == r)
		return 0;

	if(l + 1 == r)
		return a[l] + a[r];

	ll &ans = dp[l][r];

	if(ans != -1)
		return ans;

	ans = oo;

	ll s = 0;
	for(int i = l; i <= r; i++)
		s += a[i];

	for(int i = l; i <= r; i++)
	{
		ll cur = solve(l, i) + solve(i + 1, r) + s;

		ans = min(ans, cur);
	}

	return ans;
}

