ll sum(ll arr[], ll L, ll R)
{
    ll s = 0;
    for (ll i = L; i <= R; i++)
        s += arr[i];
    return s;
}
ll getRes(ll arr[], ll n)
{
    ll dp[405][405];
    // dp[i][j] -> minimum total cost of combining interval [i,j] into one vertex

    for (ll L = n - 1; L >= 0; L--)
    {
        for (ll R = L; R < n; R++)
        {
            if (L == R)
                dp[L][R] = 0;
            else
            {
                dp[L][R] = INF;
                ll s = sum(arr,L, R);

                for (ll i = L; i <= R - 1; i++)
                {
                    dp[L][R] = min(dp[L][R], dp[L][i] + dp[i + 1][R] + s);
                }
            }
        }
    }


    return dp[0][n - 1];
}

