#include <bits/stdc++.h>
using namespace std;

map<vector<long>, long> memo;

long func(auto a)
{
    int n=a.size();
    if (n<2) return 0;
    if (memo.count(a)) return memo[a];
    auto& res=memo[a];
    res=LONG_MAX;
    for(int i=0; i+1<n; ++i) {
        vector<long> b(n-1);
        for(int j=0; j<i; ++j) b[j]=a[j];
        b[i]=a[i]+a[i+1];
        for(int j=i+1; j+1<n; ++j) b[j]=a[j+1];
        res=min(res, a[i]+a[i+1]+func(b));
    }
    return res;
}

int main()
{
    int n; cin>>n;
    vector<long> a(n);
    for(auto& e: a) cin>>e;
