unordered_map<ll, ll> memo;

ll rec(ll from, ll to) {
  ll key = from * 1000 + to;
  if (memo.count(key)) return memo[key];
  ll ans = 0;
  if (from == to) {
    ans = 0;
  } else if (from + 1 == to) {
    ans = A[from] + A[to];
  } else {
    ans = rec(from,  from) + rec(from + 1, to) + acc[to + 1] - acc[from];
    rep (i,  to - from) {
      if (i == 0) continue;
      ll tmp = rec(from,  from + i) + rec(from + i + 1, to) + acc[to + 1] - acc[from];
      ans = min(ans, tmp);
    }
  }
  memo[key] = ans;
  return ans;
}

