int solve(int l, int r) {
	if (visited[l][r])
		return dp[l][r];
	visited[l][r] = true;
	if (r - l == 1)
		return dp[l][r] = 0;
	dp[l][r] = inf;
	for (int i = 1; i < r - l; i++) {
		dp[l][r] = min(dp[l][r], solve(l, l + i) + solve(l + i, r));
	}
	dp[l][r] = dp[l][r] + pref[r - 1] - pref[l - 1];
	return dp[l][r];
}

