int n;
long long sum[407], dp[407][407], a[407];
bool vis[407][407];

long long solve(int l, int r){
	if(vis[l][r]) return dp[l][r];
	vis[l][r] = true;
	if(l >= r) return 0LL;
	long long ans = 2e18;
	for(int i = l; i <= r; i++){
		long long cal = 0;
		if(i == l) cal = a[l] + sum[r] - sum[l] + solve(l + 1, r);
		else if(i == r) cal = a[r] + sum[r - 1] - sum[l - 1] + solve(l, r - 1);
		else{
			long long lef = sum[i - 1] - sum[l - 1];
			long long rig = sum[r] - sum[i];
			cal = 2LL * (min(lef, rig) + a[i]) + max(lef, rig) + solve(l, i - 1) + solve(i + 1, r);
			long long cal2 = sum[i] - sum[l - 1] + sum[r] - sum[i] + solve(l, i) + solve(i + 1, r);
			cal = min(cal, cal2);
		}
		ans = min(ans, cal);
	}
	dp[l][r] = ans;
	return ans;
}

