ll minCost(vector<ll> &prefix,int i,int j){
	if(i >= j){
		return 0;
	}
	if(dp[i][j]!=-1){
		return dp[i][j];
	}
	ll ans = INT_MAX;
	for(int k=i;k<j;k++){
		ans = min(ans,prefix[j+1] - prefix[i] + minCost(prefix,i,k) + minCost(prefix,k+1,j));
	}
	return dp[i][j] = ans;
}
