pair<ll, ll> solve(int lo, int hi) {
    if(lo == hi) return {0, ar[lo]};

    if(used[lo][hi]) return dp[lo][hi];
    used[lo][hi] = 1;

    pll ret = {inf, inf};
    for(int i = lo; i < hi; i++) {

        pll x = solve(lo, i);
        pll y = solve(i+1, hi);

        if(x.ss+y.ss+x.ff+y.ff < ret.ff)
            ret = {x.ss+y.ss+x.ff+y.ff, x.ss+y.ss};
    }
    return dp[lo][hi] = ret;
}

