size_t solution(const int L, const int R)
{
  if (L+1 >= R) return 0;
  size_t s = 0;
  for (int i = L; i < R; ++i) s += v[i];
  size_t res = numeric_limits<size_t>::max();
  for (int i = L+1; i < R; ++i)
  {
    if (dp[L][i] == 0) dp[L][i] = solution(L, i); 
    if (dp[i][R] == 0) dp[i][R] = solution(i, R); 
    res = min(res, dp[L][i] + dp[i][R]);
  }
  return res + s;
}

