using namespace std;
class heap
{
    long long *arr;
    int n;
    public:
    heap(int m,long long *ele)
    {
        n=m;
        arr=new long long[n+1];
        int i;
        for(i=1;i<=n;i++) arr[i]=ele[i-1];
        for(i=n/2;i>=1;i--) heapify(i);
    }
    void heapify(int x)
    {
        int l=2*x;
        int r=2*x+1;
        int sma=x;
        if(l<=n && arr[l]<arr[sma]) sma=l;
        if(r<=n && arr[r]<arr[sma]) sma=r;
        if(sma!=x)
        {
            swap(arr[sma],arr[x]);
            heapify(sma);
        }
    }
    long long del()
    {
        long long ele=arr[1];
        arr[1]=arr[n];
        n--;
        heapify(1);
        return ele;
    }
    void ins(long long ele)
    {
        n++;
        int pos=n;
        int par=pos/2;
        while(par>=1)
        {
            if(ele<arr[par])
            {
                arr[pos]=arr[par];
                pos=par;
                par=pos/2;
            }
            else break;
        }
        arr[pos]=ele;
    }
};
int main()
{
    int n,i,j,k;
    cin>>n;
    long long x,y;
    long long *arr=new long long[n];
    for(i=0;i<n;i++)    cin>>arr[i];
    heap hp(n,arr);
    long long ans=0;
    for(i=1;i<=n-1;i++)
    {
        x=hp.del();
        y=hp.del();
        hp.ins(x+y);
        ans+=x+y;
    }
    cout<<ans;
}

