	auto sum = [&](int L, int R)
	{
		ll s = 0;
		loop(i, L, R)
			s += a[i];
		return s;
	};

	// dp[i][j] represents cost of adding i -> j to a new element
	for(int L = n - 1; L >= 0; L--)
	{
		for(int R = L; R < n; R++)
		{
			if(L == R)
				dp[L][R] = 0;
			ll s = sum(L, R);

			for(int i  = L; i <= R - 1; i++)
			{
				if(!dp[L][R])
				{
					dp[L][R] = dp[L][i] + dp[i + 1][R] + sum(L, R);
				}
				dp[L][R] = min(dp[L][R], dp[L][i] + dp[i + 1][R] + s);
			}
		}
	}


