using namespace std;

const int64_t LL_INF = (int64_t) 2e18 + 5;

int N;
vector<int64_t> A, prefix_sum;
vector<vector<int64_t>> dp;
vector<vector<int16_t>> opt;

int main() {
    ios::sync_with_stdio(false);
#ifndef NEAL_DEBUG
    cin.tie(nullptr);
#endif

    cin >> N;
    A.resize(N);
    prefix_sum.assign(N + 1, 0);

    for (int i = 0; i < N; i++) {
        cin >> A[i];
        prefix_sum[i + 1] = prefix_sum[i] + A[i];
    }

    dp.assign(N + 1, vector<int64_t>(N + 1, LL_INF));
    opt.assign(N + 1, vector<int16_t>(N + 1, -1));

    for (int i = 0; i < N; i++) {
        dp[i][i + 1] = 0;
        opt[i][i + 1] = i;
    }

    // Knuth optimization: opt[i][j - 1] <= opt[i][j] <= opt[i + 1][j].
    for (int i = N - 1; i >= 0; i--)
        for (int j = i + 2; j <= N; j++)
            for (int k = opt[i][j - 1]; k <= opt[i + 1][j]; k++) {
                int64_t candidate = dp[i][k] + dp[k][j] + prefix_sum[j] - prefix_sum[i];

                if (candidate < dp[i][j]) {
                    dp[i][j] = candidate;
                    opt[i][j] = k;
                }
            }

    cout << dp[0][N] << '\n';
}

