int recurse(int i, int j) {
	auto& state = dp[i][j];
  	if(state != -1) return state;
  	if(i == j) return state = 0;
  	int cost = rsq(i, j);
  	state = numeric_limits<int>::max();
  	for(int k = i; k < j; ++k) {
    	state = min(
          state,
          recurse(i, k) + recurse(k + 1, j) + cost
        );
    }
}

