            dp[j][j+i] = oo;

            for(int k = mid[j][j+i-1]; k <= mid[j+1][j+i]; ++k) {
                ll val = dp[j][k] + dp[k+1][j+i] + (pref[j+i]-(j-1 >= 0 ? pref[j-1] : 0));
