  }
  for(int l=0;l<N;l++){
    dp[l][l+1]=0;
  }
  for(int l=N-1;l>=0;l--){
    for(int r=l+1;r<=N;r++){
      for(int m=l+1;m<r;m++){
	dp[l][r]=std::min(dp[l][r],dp[l][m]+dp[m][r]+as[r]-as[l]);
      }
    }
  }
  printf("%ld\n",dp[0][N]);
  return 0;
}

