ll sum(int l, int r) {
    assert(l <= r);
    return pre[r + 1] - pre[l];
}

ll solve(int l, int r) {
    assert(l <= r);
    if (l == r) return 0;
    if (dp[l][r] != LL_INF) return dp[l][r];
    For(m, l, r) MIN(dp[l][r], solve(l, m) + solve(m + 1, r) + sum(l, m) + sum(m + 1, r));
    return dp[l][r];
}

