ll rec(int l, int r){

    //基底
    if (l >= r) return 0;


    //メモ化処理
    if(visited[l][r]){
        return memo[l][r];
    }
    visited[l][r] = true;

    ll& ret = memo[l][r];
    ret = 1LL<<50;

    for(auto k = l; k<r ;k++){
        ret = min(ret, rec(l,k) + rec(k+1,r) + cumSum[r]-cumSum[l-1]);

    }


    return ret;
}


