pair<ll,ll> help(int i,int j) {
    if(i>j) return {0,0};
    if(i==j) {
        dp[i][j]=arr[i];
        cost[i][j]=dp[i][j];
        return {cost[i][j],dp[i][j]};
    }
    if(cost[i][j]!=-1) return { cost[i][j],dp[i][j] };

    ll mn=inf;
    for(int x=i;x<j;x++) {
        auto p1= help(i,x), p2= help(x+1,j);
        dp[i][j]= p1.second+ p2.second;
        mn= min( p1.first+ p2.first + dp[i][j], mn );
    }
    cost[i][j]=mn;
    return {cost[i][j],dp[i][j]};
}

