int rec(int l,int r,vv<int> &dp,v<int> &s){
  if(dp[l][r]!=-1) return dp[l][r];
  if(abs(l-r)<=1) return 0;
  int res=INF;
  for(int mid=l+1;mid<=r-1;mid++){
    chmin(res,rec(l,mid,dp,s)+rec(mid,r,dp,s)+s[r]-s[l]);
  }
  return dp[l][r]=res;
}

