ll calc(ll l, ll r)
{
    if (memo[l][r] != 0) {
        return memo[l][r];
    }
    if (l == r) {
        return 0;
    }
    ll ret = INF;
    for2 (i, l, r) {
        ll ret1 = calc(l, i) + calc(i + 1, r) + C[r + 1] - C[l];
        chmin(ret, ret1);
    }
    return ret;
}

