        S[i + 1] += S[i] + A[i];
    }

    REP(k, 1, N) {
        REP(i, 0, N - k) {
            REP(j, i, i + k) {
                chmin(dp[i][i + k], dp[i][j] + dp[j + 1][i + k] + S[i + k + 1] - S[i]);
            }
        }
    }

    cout << dp[0][N - 1] << endl;

    return 0;
}

