ll dfs(int l, int r){
    if(dp[l][r]) return dp[l][r];
    if(l >= r) return (1LL<<60);
    if(r-l == 1) return dp[l][r] = a[l] + a[r];
    ll ans = (1LL<<60);
//    cout << ans << endl;
    for(int mid = l; mid <= r; mid++){
        if(mid == l){
            ans = min(ans, a[l] + sum[r] - sum[l] + dfs(mid+1, r));
            continue;
        }
        if(mid == r){
            ans = min(ans, a[r] + sum[r-1] - sum[l-1] + dfs(l, mid-1));
            continue;
