typedef long long LL;
const int N = 5e2+9, M = 1e5+9, OO = 0x3f3f3f3f,MOD = 1e9 + 7;
int n;
LL memo[N][N],csum[N];
LL solve(int l=1,int r=n)
{
  if(l==r) return 0;
  LL &ret = memo[l][r];
  if(~ret) return ret;

  ret = LONG_LONG_MAX;
  for(int i=l;i<r;++i)
  {
    ret = min(ret,solve(l,i)+solve(i+1,r)+(csum[r]-csum[l-1]));
  }

  return ret; 
}

int main()
{
  memset(memo,-1,sizeof memo);
  scanf("%d",&n);
  for(int i=1;i<=n;++i)
  {
    LL x;
    scanf("%lld",&x);
    csum[i]+=csum[i-1]+x;
  }
  printf("%lld\n",solve());

  #ifdef _LOCAL_DEFINE
  cerr << (double)clock() * 1.0 / CLOCKS_PER_SEC << endl;
  #endif
  return 0; 
