        for(int a=0; a<N-len+1; a++) {
            int b = a + len - 1;
            int cost = sum[b+1] - sum[a];

            int l = idx[a][b-1];
            int r = idx[a+1][b];

            for(int k=r; k>=l; k--) {
                if(dp[a][b] > dp[a][k] + dp[k+1][b] + cost) {
                    dp[a][b] = dp[a][k] + dp[k+1][b] + cost;
                    idx[a][b] = k;
                }
            }
        }
    }

    cout << dp[0][N-1] << endl;
    return 0;
}

