ll solve(int n, int m){
    if(dp[n][m] != -1) return dp[n][m];
    if(n==m) {
        dp[n][m] = 0;
        // cout << n << " " << m << " " << dp[n][m] << endl;
        return dp[n][m];
    }
    if(n+1==m) {
        dp[n][m] = a[n] + a[m];
        // cout << n << " " << m << " " << dp[n][m] << endl;
        return dp[n][m];
    }

    dp[n][m] = 1e18;
    for(int i=n+1; i<=m; i++){
        dp[n][m] = min(dp[n][m], solve(n,i-1) + solve(i,m) + Sa[m] - Sa[n-1]);
    }
    // cout << n << " " << m << " " << dp[n][m] << endl;
    return dp[n][m];
}

