pair<long long int, long long int> recursive(
    vector<long long int>& a, int l, int r,
    vector<vector<pair<long long int, long long int>>>& table) {
  if (table[l][r].first != -1) return table[l][r];
  if (r - l == 1) {
    int sum = a[l] + a[r];
    table[l][r] = {sum, sum};
    return table[l][r];
  } else if (l == r) {
    table[l][r] = {a[l], 0};
    return table[l][r];
  }

  long long int minCost = -1;
  long long int value = 0;
  for (int i = l; i < r; ++i) {
    pair<long long int, long long int> result1 = recursive(a, l, i, table);
    pair<long long int, long long int> result2 = recursive(a, i + 1, r, table);
    long long int cost =
        result1.first + result2.first + result1.second + result2.second;
    if (minCost == -1 || cost < minCost) {
      value = result1.first + result2.first;
      minCost = cost;
    }
  }
  table[l][r] = {value, minCost};
  return {value, minCost};
}

