ll rek(int a, int b) {
	if (a == b) return A[a];
	ll &ret = DP[a][b];
	if (ret != -1) return ret;
	ret = INF;
	FOR(i, a, b) {
		if (i == a) {
			ll val = A[i] + rek(a + 1, b);
			ret = min(ret, val);
		}
		else if (i == b) {
			ll val = A[i] + rek(a, b - 1);
			ret = min(ret, val);
