class UnionFind {
    public:
        UnionFind(){}
        UnionFind(int size) { Init(size); }
        // size: Union-Find で扱いたい要素の数
        void Init(int size) { m_Data.assign(size, -1); }

        // x と y の属する集合を併合
        // 既に一緒な集合内にいるなら false を
        // 新たに併合されたなら true を返す
        bool Unite(int x, int y) {
            x = Find(x), y = Find(y);
            if(x == y) { return (false); }
            if(m_Data[x] > m_Data[y]) { swap(x, y); }
            m_Data[x] += m_Data[y];
            m_Data[y] = x;
            return (true);
        }

        // 要素 k が属する集合の根を返す
        int Find(int k) {
            if(m_Data[k] < 0) { return (k); }
            return (m_Data[k] = Find(m_Data[k]));
        }

        // 要素 k と同じ集合の要素数を返す
        int Size(int k) { return (-m_Data[Find(k)]); }

    private:
        vector<int> m_Data;
};

ll N;
vector<ll> A;

signed main()
{
    cin >> N;
    A.assign(N, 0);
    REP(i, N) {
        cin >> A[i];
    }
    UnionFind uf(N);

    // 合体時の数, インデックス i, j
    priority_queue< tuple<ll, ll, ll>, vector< tuple<ll, ll, ll> >, greater< tuple<ll, ll, ll> > > pq;
    REP(i, N) {
        if(i > 0) { pq.push(make_tuple(A[i-1] + A[i], i-1, i)); }
    }

    ll ans = 0;
    while(pq.size() > 0) {
        tuple<ll, ll, ll> t = pq.top();
        pq.pop();
        ll val = get<0>(t);
        ll ind1 = get<1>(t);
        ll ind2 = get<2>(t);
        DBG("val: %lld ind1: %lld ind2: %lld\n", val, ind1, ind2);
        // すでに合体済みなら飛ばす
        if(uf.Find(ind1) == uf.Find(ind2)) {
            DBG("  skip1\n");
            continue;
        }
        // val が更新されている場合も飛ばす
        if(uf.Find(ind1) != ind1 || uf.Find(ind2 != ind2) ||
                val != A[uf.Find(ind1)] + A[uf.Find(ind2)])
        {
            ll ind_r = uf.Find(ind2);
            DBG("  skip2\n");
            if(ind_r > 0) {
                ll ind_l = uf.Find(ind_r-1);
                val = A[ind_r] + A[ind_l];
                if(ind_r != ind_l) {
                    pq.push(make_tuple(val, ind_l, ind_r));
                    DBG("  add %lld %lld %lld\n", ind_l, ind_r, val);
                }
            }
            ind_r = uf.Find(ind1);
            if(ind_r > 0) {
                ll ind_l = uf.Find(ind_r-1);
                val = A[ind_r] + A[ind_l];
                if(ind_r != ind_l) {
                    pq.push(make_tuple(val, ind_l, ind_r));
                    DBG("  add %lld %lld %lld\n", ind_l, ind_r, val);
                }
            }
            ind_r = uf.Find(ind2);
            ll ind_l = uf.Find(ind1);
            val = A[ind_r] + A[ind_l];
            if(ind_r != ind_l) {
                pq.push(make_tuple(val, ind_l, ind_r));
                DBG("  add %lld %lld %lld\n", ind_l, ind_r, val);
            }
            continue;
        }
        ans += val;
        A[ind1] = 0;
        A[ind2] = 0;
        uf.Unite(ind1, ind2);
        DBG("  unite -> %lld\n", uf.Find(ind1));
        // 値の更新
        A[uf.Find(ind1)] = val;
        // 隣のグループとの合体したときの値をキューに追加
        ll ind_r = uf.Find(ind1);
        if(ind_r > 0) {
            ll ind_l = uf.Find(ind_r-1);
            val = A[ind_r] + A[ind_l];
            if(ind_r != ind_l) {
                pq.push(make_tuple(val, ind_l, ind_r));
                DBG("  add %lld %lld %lld\n", ind_l, ind_r, val);
            }
        }
    }
    printf("%lld\n", ans);
    return 0;
}

