vector <int> ar(N, 0);
vector <int> pref(N, 0);
int dp[N][N];

int solve(int i, int j) {
	int &res = dp[i][j];
	if (j - i <= 0) {
		return 0ll;
	}
	if (res != -1) {
		return res;
	}
	int x = LLONG_MAX;
	for (int k = i; k < j; k++) {
		x = min(x, (solve(i, k) + solve(k + 1, j) + pref[j] - pref[i - 1]));
	}
	return res = x;
}

