//begin inclusive, end exclusive
ll rec(ll begin_slime, ll end_slime){

    if(begin_slime+1 == end_slime){
        return 0;
    }
    if(dp[begin_slime][end_slime-1] != -1){
        return dp[begin_slime][end_slime-1];
    }
    ll res = oo;
    FOR(i, begin_slime+1, end_slime){
        ll left_res = rec(begin_slime, i);
        ll right_res = rec(i, end_slime);
        ll tmp_new = left_res + right_res + slimes[i-begin_slime-1][begin_slime] + slimes[end_slime-i-1][i];
        res = min(tmp_new, res);
    }
    dp[begin_slime][end_slime-1] = res;
    return res;
}


