ll rsum(ll l, ll r) {
	if (rsumdp[l][r] != -1)
		return rsumdp[l][r];
	ll sum = 0;
	for (int i=l; i<=r; i++)
		sum += A[i];
	return rsumdp[l][r] = sum;
}

ll dp(ll l, ll r) {
	if (l > r) 
		return 0;

	if (l == r)
		return 0;

	if (mem[l][r] != -1)
		return mem[l][r];

	ll min_cost = (ll)1e13;

	for (ll i=l; i<r; i++) {
		min_cost = min(min_cost, dp(i+1, r) + dp(l, i) + rsum(i+1, r) + rsum(l, i)); 
	}

	return mem[l][r] = min_cost;
}

