pair<long long, long long> solve(long long i, long long j){
    if(i == j)
        return {arr[i], 0};
    pair<long long, long long> &res = dp[i][j];
    if(res.second == -1){
        for(long long k=i; k<j; ++k){
            ii a = solve(i, k), b = solve(k+1, j);
            long long cost = a.second + b.second + a.first + b.first;
            if(res.second == -1 or cost < res.second)
                res = {a.first + b.first, cost};
            else if(cost == res.second)
                res.first = min(res.first, a.first + b.first);
        }
    }
    return res;
}

