ll go(int l, int r) {
    if(l == r) {
        return 0;
    }

    if(dp[l][r] != -1) return dp[l][r];

    ll ans = 1LL << 60;

    for(int i = l; i < r; i++) {
        ll cur = go(l, i) + go(i + 1, r);

        cur += prefix[i] - (l > 0 ? prefix[l - 1] : 0);
        cur += prefix[r] - prefix[i];

        ans = min(ans, cur);
    }


    return dp[l][r] = ans;
}

