ll rec(ll from, ll to) {
  if (from == to) return 0;
  if (from + 1 == to) {
    ll ans = A[from] + A[to];
    return ans;
  }
  ll a = from;
  ll b = abs((acc[from+1] - acc[from]) * 2 -  (acc[to + 1] - acc[from]));
  for (ll i = from; i <= to; i++) {
    ll tmp = abs((acc[i+1] - acc[from]) * 2 -  (acc[to + 1] - acc[from]));
    if (tmp < b) {
      a = i;
      b = tmp;
    }
  }
  ll ans = rec(from,  a) + rec(a+1, to) + acc[to + 1] - acc[from];
  return ans;
}

