int solveDp(int beg, int end) {
       if (beg >= end)      return 0;
       if (dp[beg][end] != -1) return dp[beg][end];

       dp[beg][end] = solveDp(beg, end - 1) + solveDp(end, end) + prefix[end] - prefix[beg - 1];
       for (int i = end - 1; i >= beg; i--)
              dp[beg][end] = min(dp[beg][end], solveDp(beg, i) + solveDp(i + 1, end) + prefix[end] - prefix[beg - 1]);
       return dp[beg][end];
}


