Long DP(int l, int r) {
	if (l == r) return 0LL;
	if (l + 1 == r) return a[l] + a[r];
	if (dp[l][r] != 0LL) return dp[l][r];
	dp[l][r] = INF;
	for (int i = l; i < r; i++) {
		dp[l][r] = min(dp[l][r], DP(l, i) + DP(i + 1, r) + acc[r] - acc[l - 1]);
	}
	return dp[l][r]; 
}

