ll dfs(int l, int r, ll cost = 0) {
  if (l == r) return 0;
  if (cache[l][r] != -1) return cache[l][r];

  cost += RUI[r + 1] - RUI[l];

  ll minCost = LONG_MAX;

  for (int m = l; m <= r - 1; ++m) {
    ll ncost = cost + dfs(l, m) + dfs(m + 1, r);

    minCost = min(minCost, ncost);
  }

  return cache[l][r] = minCost;
}

