	pair<ll, ll> result = make_pair(intPow(10, 18), intPow(10, 18));
	for (int i = 1; i < N; ++i) {
		pair<ll, ll> val = solve(0, i, N);
		if (val.second < result.second) {
			result = val;
		}
	}
	out(result.second);

	getchar();
}

