const int MAX_N = 400;
int S[MAX_N + 1];
int dp[MAX_N][MAX_N];
bool visited[MAX_N][MAX_N];

int rec(int left, int right) {
    if (left >= right) return 0;
    if (visited[left][right]) return dp[left][right];
    visited[left][right] = true;
    int mn = INF;
    for (int middle = left; middle <= right - 1; middle++) {
        mn = min(rec(left, middle) + rec(middle + 1, right) + S[right + 1] - S[left], mn);
    }
    return dp[left][right] = mn;
}

