ll dp[N][N];

ll solve(int l, int r){
	if(l == r) return 0;

	if(dp[l][r] != -1) return dp[l][r];

	ll ans = INF;

	for(int i = l; i < r; i++){
		ans = min(ans, solve(l, i) + solve(i + 1, r) - presum[l - 1] + presum[r]);
	}

	return dp[l][r] = ans;
}

