typedef long long ll;

const int N = 1e5 + 10;
const int MOD = 1e9 + 7;
const ll inf = 1e18 + 10;


int n;
ll a[N];
ll cost[N];
set<pair<ll, ll>> mset;
set<int> alive;
int main() {
    cin >> n;
    for(int i = 1; i <= n; i++) cin >> a[i];
    a[0] = a[n + 1] = inf;
    for(int i = 0; i <= n; i++) cost[i] = a[i] + a[i + 1];

    for(int i = 0; i <= n + 1; i++)
        alive.insert(i);
    for(int i = 0; i <= n; i++) {
        mset.insert({cost[i], i});
    }

    ll ans = 0;
    for(int i = 1; i < n; i++) {
        auto use = *mset.begin();
        ans += use.first;

        int pos = use.second;
        auto ite = alive.lower_bound(pos);
        auto iteL = ite; iteL--;
        auto iteR = ite; iteR++;

        int posL = *iteL;
        int posR = *iteR;
        mset.erase(use);
        mset.erase({cost[posL], posL});
        mset.erase({cost[posR], posR});
        alive.erase(posR);

        a[pos] += a[posR];
        cost[posL] = a[posL] + a[pos];
        cost[pos] = a[pos] + a[*alive.upper_bound(pos)];
        mset.insert({cost[posL], posL});
        mset.insert({cost[pos], pos});
    }
    cout << ans;
}

