ll dp[410][410];

ll rec(int l, int r) {
  if (dp[l][r] != INFLL) return dp[l][r];
  if (l == r) return 0;
  // どこで切るか全通り試す
  ll res = INFLL;
  for (int i = l; i < r; ++i) chmin(res, rec(l,i)+rec(i+1,r));
  return dp[l][r] = res + (csum[r+1] - csum[l]);
}

