using namespace std;
typedef long long int llu;

pair<llu, llu> memoTable[400][400];
bool isComputed[400][400];

int nSlimes;
int slimesLen[400];

pair<llu, llu> minCost(int i, int j){

    if(i == j){
        return make_pair(slimesLen[i], 0);
    }

    if(isComputed[i][j] == 1){
        return memoTable[i][j];
    }

    isComputed[i][j] = 1;

    pair<llu, llu> cost (LONG_MAX, LONG_MAX);
    pair<llu, llu> t1;
    pair<llu, llu> t2;


    for(int k = i; k<j; ++k){

        t1 = minCost(i, k);
        t2 = minCost(k+1, j);

        if(t1.first + t2.first <= cost.first && t1.second + t2.second < cost.second){
            cost.first = t1.first + t2.first;
            cost.second =  t1.second + t2.second;
        }
    }

    cost.second += cost.first;
    memoTable[i][j] = cost;
    return cost;
}


int main(){

    // freopen("input.txt", "r", stdin); freopen("output.txt", "w", stdout); cout<<"Slimes.cpp\n";

    memset(isComputed, 0, sizeof(isComputed));

    cin >> nSlimes;
    for(int i=0; i<nSlimes; ++i){
        cin >> slimesLen[i];
    }    

    pair<llu,llu>p = minCost(0, nSlimes-1);
    cout<<p.second;
    return 0;
}

