int arr[400];

ii rec(int l, int r)
{
    if (sht[l][r]) return dp[l][r];
    sht[l][r] = 1;

    if (l == r) return dp[l][r] = {0, arr[l]};

    for (int i = l; i != r; ++i)
    {
        ii s = rec(l, i), t = rec(i + 1, r);
        dp[l][r].second = s.second + t.second;
        if (dp[l][r].first)
            dp[l][r].first = min(dp[l][r].first, dp[l][r].second + s.first + t.first);
        else
            dp[l][r].first = dp[l][r].second + s.first + t.first;
    }

    return dp[l][r];
}

