ll rec(ll x, ll y) {
	if (x == y) return dp[x][y] = 0;
	ll tmp = INF;
	FOR(i, x, y - 1) {
		emin(tmp, rec(x, i) + rec(i + 1, y) + b[y + 1] - b[x]);
	}
	return dp[x][y] = tmp;
}

void Solve() {

