long long solve(int start, int end) {
	if (dp[start][end] != -1)
		return dp[start][end];
	if (end < start)
		return 0;
	if (end == start + 1)
		return dp[start][end] = (long long)(cost[start] + cost[end]);

	long long mini = LLONG_MAX, sum = 0;
	for (int i = start+1; i <= end-1; i++) {
		mini = min(mini, solve(start, i - 1) + solve(i + 1, end) + pref(start, i - 1) + (long long)(2 * cost[i]) + pref(i + 1, end) + min(pref(start, i - 1), pref(i + 1, end)));
	}
	return dp[start][end] = mini;
}

