        while(v[j]==0) j++;
        unsigned long long x=v[i]; v[i]=0;
        unsigned long long y=v[j]; v[j]=x+y;
        ans= min( ans, x+y+ solve( v, n+1));    
        v[i]=x; v[j]=y;
    }
    return ans;
}
