pll solve(vector<int>& V, int beg, int end) {
	if (beg > end || beg < 0 || end >= V.size()) return { 0ll,0ll };
	if (beg == end) {
		return { V[beg],0ll };
	}
	if (dp[beg][end] != -1ll) return {dp[beg][end],cost[beg][end]};

	pll P = solve(V, beg + 1, end);
	dp[beg][end] = P.first + V[beg]*1ll;

	cost[beg][end] = P.second + dp[beg][end];

	for (int i = beg + 1; i < end; i++) {
		pll X = solve(V,beg, i);
		pll Y = solve(V, i + 1, end);
		ll z =  dp[beg][end] + X.second + Y.second;
		if (cost[beg][end] > z) {
			cost[beg][end] = z;

		}
	}
	P = solve(V, beg, end - 1);
	if (cost[beg][end] >= dp[beg][end] + P.second) {

		cost[beg][end] = P.first + V[end] + P.second;

		dp[beg][end] = min(dp[beg][end], P.first + V[end]);
	}

	return { dp[beg][end],cost[beg][end] };

}
