P rec(int l = 0, int r = N) {  // メモ化再帰
    if (r - l == 1) return make_pair(0, a[l]);
    P &ret = dp[l][r];
    if (ret.first != INF) return ret;

    for (int i = l + 1; i < r; i++) {
        P L = rec(l, i);
        P R = rec(i, r);
        ll sum = L.second + R.second;
        ll cost = L.first + R.first + sum;
        chmin(ret, make_pair(cost, sum));
    }

    return ret;
}

