ll rec(int i, int j) {
    if (~dp[i][j]) return dp[i][j];
    ll &tmp = dp[i][j];
    if (i == j) return tmp = 0;
    tmp = INF;
    for (int k = i; k < j; ++k) { tmp = min(tmp, rec(i, k) + rec(k + 1, j)); }
    tmp += s[j] - s[i - 1];
    return tmp;
}

