// every union comes from an finite set of operations inside a contigous segment
// you have to decide "i" position to join both sides

ll f(int l, int r){
  if(~dp[l][r]) return dp[l][r];
  if(l==r) return 0;
  ll ans=linf;
  for(int i=l; i<r; i++){
    ans=min(ans, f(l, i)+f(i+1, r));
  }
  return dp[l][r]=ans+v[r]-v[l-1];
}

