void slv() {
    for (int i = 0; i <= n; ++i) {
        for (int l = 0; l <= n - i; ++l) {
            int r = l + i;
            if (r - l < 2) {
                dp[l][r] = 0;
                continue;
            }
            long long tmp = ps[r] - ps[l];
            for (int mid = l; mid <= r; ++mid)
                dp[l][r] = min(dp[l][r], dp[l][mid] + dp[mid][r] + tmp);
        }
    }
	cout << dp[0][n] << endl;
}

