ll rec(ll i, ll j){
  if(dp[i][j]!=0) return dp[i][j];
  if(i==j) return 0;

  // どこで切る
  ll mi = inf;
  FOR(k, i, j){
    ll cost = rec(i, k) + rec(k+1, j) + Acc.sum(i, j);
    chmin(mi, cost);
  }
  return dp[i][j] = mi;
}

