long long int f(int i, int j, vector<vector<long long>>& dp)
{
  auto S = sum(i,j);
  if (i == j)
    return a[i];
  auto& res = dp[i][j];
  if (res != numeric_limits<long long>::max())
    return res;
  for (int k = i; k < j; ++k)
  {
    res = min(res, S + f(i, k, dp) + f(k+1, j, dp));
  }
  return res;
}


