#define INF 1e9 * 401
vector<vector<ll> > dp(401, vector<ll> (400, -1LL));
vector<ll> prefixSums(401, 0LL);

ll MinCost(ll  st, ll  end, vector<ll > &arr){
    if(st == end)
        return 0;
    if(dp[st][end ] != -1)
        return dp[st][end];
    ll ans = INF;
    ll mergeCost = (st == 0)?(prefixSums[end]):(prefixSums[end] - prefixSums[st - 1]); 
    F(ll , mark, st, end - 1){
        ans = min(ans, mergeCost + MinCost(st, mark, arr) + MinCost(mark + 1, end, arr));
    }
    dp[st][end] = ans;
    return ans;
}

