using namespace std;

using VL = vector<long long>;
using VVL = vector<VL>;

const long long inf = 1e18;

int n;
VL a;
VVL memo; // [i, j)な範囲の合成に必要なコスト

void show() {
	for (int i = 0; i < memo.size(); i++) {
		printf("%2d: ", i);
		for (auto x: memo[i]) {
			if (x == inf) {
				printf(" %4s", "inf");
			} else {
				printf(" %4lld", x);
			}
		}
		printf("\n");
	}
}

long long dfs(int l, int r) {
	if (memo[l][r] != inf) {
		return memo[l][r];
	}

	if (r - l == 1) {
		memo[l][r] = 0;
		return 0;
	}

	long long mini = inf;
	int mid = -1;
	long long sum = a[l];
	for (int m = l + 1; m < r; m++) {
		sum += a[m];

		auto val1 = dfs(l, m);
		auto val2 = dfs(m, r);

		long long tmp = val1 + val2;
		if (tmp < mini) {
			mini = tmp;
			mid = m;
		}
	}

	memo[l][r] = mini + sum;
	return memo[l][r];
}

int main() {
	cin >> n;

	a.assign(n, 0);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
	}

	memo.assign(n+1, VL(n+1, inf));
	auto ans = dfs(0, n);
	cout << ans << endl;

	// show();
	return 0;
}

