struct item{
    ll cost;
    ll sum;
};

vector<vector<item>> dp;


item DP(int b, int e, vector<ll>&a){
    if (e-b==1) return {0,a[b]};
    if (dp[b][e].cost != -1) return dp[b][e];
    ll mxcst = 1LL << 60;
    item ret = {mxcst,0};
    for(int i = b+1; i < e; i++){
        item left = DP(b,i,a);
        item right = DP(i,e,a);
        ll cst = left.cost + right.cost + left.sum + right.sum;
        if (ret.cost >  cst){

            ret = {cst , left.sum + right.sum};
        }

    }
    return dp[b][e] = ret;
}

