int slimes(int i, int j){
    if(i >= j)
        return 0;

    if(dp[i][j] != -1)
        return dp[i][j];

    dp[i][j] = LLONG_MAX;
    for(int k = i; k <= j; ++k){
        int x = (pre[k] - pre[i - 1]);
        int y = (pre[j] - pre[k]);
        x += y;
        dp[i][j] = min(dp[i][j], slimes(i, k) + slimes(k + 1, j) + x);
    }

    return dp[i][j];
}

