    vector<vector<ll>> dp(n, vector<ll>(n,inf));
    vector<vector<ll>> price(n, vector<ll>(n,inf));
    ll i,j;


    for(ll k=0; k<n; k++){
    	i = 0;
    	j = k;

    	while(i<n and j<n){
    		if(i == j){
    			dp[i][j] = v[i];
    			price[i][j] = 0;
    		}
    		else{
    			for(ll p=i; p<j; p++){
    				// i to p and  p+1 to j

    				ll newValue = dp[i][p] + dp[p+1][j];
    				ll newPrice = price[i][p] + price[p+1][j] + newValue;

    				if(newPrice < price[i][j]){
    					price[i][j] = newPrice;
    					dp[i][j] = newValue;
    				}
    			}
    		}

    		i++;
    		j++;
    	}
    }

    cout<<price[0][n-1]<<"\n";

	return 0;
}

