#include <bits/stdc++.h>
using namespace std;
int N;
const int MAX=500;
unsigned long long int a[MAX], sum[MAX], mem[MAX][MAX];
int flag[MAX][MAX];
unsigned long long int dp(int l, int r) {
    if(flag[l][r] > 0)
        return mem[l][r];
    else if(l == r) {
        mem[l][r] = 0;
        flag[l][r] = 1;
        return mem[l][r];
    } else {
        int sumleft = 0;
        if(l > 0) sumleft = sum[l - 1];
        unsigned long long int min = ULLONG_MAX;
        for(int i = l; i < r; i++) {
            if(min > (dp(l, i) + dp(i + 1, r)) + sum[r] - sumleft) {
                min = (dp(l, i) + dp(i + 1, r)) + sum[r] - sumleft;
            }
        }
        mem[l][r] = min;
        flag[l][r] = 1;
        return mem[l][r];
    }
}
int main(void) {
    cin >> N;
    for(int i = 0; i < MAX; i++) {
        for(int j = 0; j < MAX; j++) {
            flag[i][j] = -1;
        }
    }
    for(int i = 0; i < N; i++) {
        cin >> a[i];
        if(i > 0)
            sum[i] = sum[i - 1] + a[i];
        else
            sum[i] = a[i];
    }
    cout << dp(0, N - 1) << endl;
    return 0;
}

