long rec(int a[], int n, long **mem, int i, int j, int sum[])
{
  if(i==j)
    return 0;          
  if(mem[i][j]!=1e18)
    return mem[i][j];
  for(int k=i;k<=j;k++)
    mem[i][j]=min(mem[i][j],rec(a,n,mem,i,k,sum)+rec(a,n,mem,k+1,j,sum)+sum[j+1]-sum[i]);
  return mem[i][j];
}

