long long n,arr[409];
bool done[409];
int main(){
	cin>>n;
	for(int i=0;i<n;i++) cin>>arr[i];
	string abdandbesher = "gold medal";
	long long ans = 0;
	while(1){
		vector < pair < int ,int > > v;
		for(int i=0;i<n;i++){
			if(done[i] == 1) continue;
			v.push_back({arr[i],i});
		}
		int s = v.size();
		if(s == 1) break;
		long long mn = 1000000000000009ll;
		int x = 0;
		for(int i=1;i<s;i++){
			int u = v[i].first + v[i-1].first;
			if(mn > u){
				mn = u;
				x = i;
			}
		}
		ans += mn;
		arr[v[x].second] = mn;
		done[v[x-1].second] = 1;
	}
	cout<<ans<<endl;
}

