typedef long long ll;
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    ll n, a[400], cost[400][400], dp[400][400];
    cin >> n;
    FOR(i, 0, n) { cin >> a[i]; }
    FOR(i, 0, n) {
        fill(dp[i], dp[i] + 400, LLONG_MAX);
        dp[i][i] = 0;
        cost[i][i] = a[i];
    }
    FOR(i, 1, n) {
        FOR(j, 0, n - i) {
            cost[j][j + i] = a[j + i] + cost[j][j + i - 1];
            FOR(k, j, j + i) {
                dp[j][j + i] =
                    min(dp[j][j + i], dp[j][k] + cost[j][k] + dp[k + 1][j + i] +
                                          cost[k + 1][j + i]);
            }
            // cout << j << ' ' << j + i << ' ' << dp[j][j + i] << '\n';
        }
    }
    cout << dp[0][n - 1] << '\n';
    return 0;
}

