  if (n > 3000) exit (1);
  i64 *a = ALLOC (n + 1, i64);
  for (i32 i = 0; i < n; ++i) {
    scanf ("%" SCNi64, a + i);
  }
  for (i32 i = n - 1; i >= 0; --i) {
    a[i] += a[i + 1];
  }
  i64 *dp = ALLOC ((n + 1) * (n + 1), i64);
  i32 *p = ALLOC ((n + 1) * (n + 1), i32);
  for (i32 l = 0; l <= n - 2; ++l) {
    i32 r = l + 2;
    dp[POS(l, r)] = a[l] - a[r];
    p[POS(l, r)] = l + 1;
  }
  for (i32 len = 3; len <= n; ++len) {
    for (i32 l = 0; l <= n - len; ++l) {
      i32 r = l + len;
      i32 k = p[POS(l, r - 1)];
