long slime ( int n, int i, int j )
{
  if ( S[i][j] != -1 ) return S[i][j];

  int k;
  long min,tmp;
  min = slime(n,i,i) + slime(n,i+1,j) + SUM[i]-SUM[i-1]+SUM[j]-SUM[i];
  for ( k = 0; k < j-i; k++ ) {
    tmp = slime( n, i, i+k ) + slime(n, i+k+1, j) + SUM[i+k]-SUM[i-1]+SUM[j]-SUM[i+k];
    if ( min > tmp ) min = tmp;
  }
  return S[i][j] = min;
}


