int64 calc(int x,int y,int64 *dp){
  if(y-x<=1) return 0;
  if(dp[POS(x,y)]>0) return dp[POS(x,y)];
  int64 local=1000000000000000000LL;
  int i;
  for(i=x+1;i<y;i++){
