const long long sup = (long long)1 << 60;

long long recursion(int l, int r)
{
	if (dp[l][r] != 0 || l == r) return dp[l][r];
	else dp[l][r] = sup;

	int k;
	long long tmp;
	for (k = l + 1; k <= r; k++) {
		tmp = recursion(l, k - 1) + recursion(k, r);
		if (tmp < dp[l][r]) dp[l][r] = tmp;
	}
	dp[l][r] += sum[r] - sum[l-1];
	return dp[l][r];
}

