  i32 *p = ALLOC ((n + 1) * (n + 1), i32);
  for (i32 l = 0; l <= n - 2; ++l) {
    i32 r = l + 2;
    p[POS(l, r)] = l + 1;
    dp[POS(l, r)] = a[l] - a[r];
