  for (i32 len = 3; len <= n; ++len) {
    for (i32 l = 0; l <= n - len; ++l) {
      i32 r = l + len;
      p[POS(l, r)] = p[POS(l, r - 1)];
      dp[POS(l, r)] = dp[POS(l, r - 1)];
      for (i32 i = p[POS(l, r - 1)]; i <= p[POS(l + 1, r)]; ++i) {
