struct vertex {
    int depth;
    int parent;
    uint64_t cost;
};

#define VERTEX_MAX ARR_MAX

struct vertex *create_ufind(int size) {
    static struct vertex ufind[VERTEX_MAX];
    int i;
    for(i = 0; i < size; i++) {
        ufind[i].depth = 1;
        ufind[i].parent = i;
    }
    return ufind;
}

int get_root(struct vertex ufind[], int i) {
    struct vertex *v = &ufind[i];
    int base = i;
    while(base != v->parent) {
        // update
        base = v->parent;
        v = &ufind[v->parent];
    }
    return base;
}

void unify(struct vertex ufind[], int i1, int i2) {
    int root1 = get_root(ufind, i1);
    int root2 = get_root(ufind, i2);
    struct vertex *v1 = &ufind[root1];
    struct vertex *v2 = &ufind[root2];
    if(root1 == root2) return;
    // ensure that i1 and i2 are separated;
    // update v2
    if(v1->depth > v2->depth) { // v1 <- v2
        if(v1->depth == v2->depth) {
            v1->depth++;
        }
        v2->depth = v1->depth;
        v2->parent = root1;
    } else { // update v1
        v1->depth = v2->depth;
        v1->parent = root2;
    }
    v2->cost = v1->cost = v1->cost + v2->cost;
}

int judge(struct vertex ufind[], int v1, int v2) {
    return get_root(ufind, v1) == get_root(ufind, v2);
}

uint64_t get_root_cost(struct vertex ufind[], int v) {
    int root = get_root(ufind, v);
    return ufind[root].cost;
}

#define INF ((uint64_t)0x0101010101010101)

int main(void) {
    int arr[ARR_MAX];
    int num = get_int();
    fget_array(arr, num);
    struct vertex *ufind = create_ufind(num);
    int i;
    for(i = 0; i < num; i++) {
        ufind[i].cost = arr[i];
    }

    uint64_t ans = 0;
    while(1) {
        int i;
        uint64_t minimum = INF;
        int argmin = -1;
        for(i = 1; i < num; i++) {
            if(judge(ufind, i-1, i)) continue;
            uint64_t res = get_root_cost(ufind, i-1) + get_root_cost(ufind, i);
            if(res < minimum) {
                argmin = i-1;
                minimum = res;
            }
        }

        // if member of arr are all unified
        if(argmin==-1) break;
#ifdef DEBUG
        printf("%d-%d -> %llu\n", argmin, argmin+1, minimum);
#endif
        unify(ufind, argmin, argmin+1);
        ans += minimum;
    }
    printf("%llu\n", ans);
    return 0;
}

