fun <T, R> Iterable<T>.scanLeft(initial: R, operation: (acc: R, T) -> R): Sequence<R> {
    var last = initial
    return this.asSequence().map { last = operation(last, it); last }
}

fun solve(N: Int, a: LongArray) {
    val cumSum = a.toList().scanLeft(0L) { a, b -> a + b }.toList()
    val dp = Array(N + 1) { LongArray(N + 1) { -1 } }
    for (i in 0 until N) {
        dp[i][i + 1] = 0L
    }
    fun rec(i: Int, j: Int): Long {
        // [i, j)の最小値
        if (dp[i][j] >= 0L) return dp[i][j]
        val s = cumSum[j - 1] - cumSum.getOrElse(i - 1) { 0L }
        val ret = (i + 1 until j)
            .map { rec(i, it) + rec(it, j) }
            .min() ?: 0L
        dp[i][j] = ret + s
        return ret + s
    }
    println(rec(0, N))
    // println(dp.contentDeepToString())
    return
}

