public class Main {

    static long rec(int i, int j, int[] b, long[][] dp) {
        if (dp[i][j] != Long.MAX_VALUE) {
            return dp[i][j];
        }

        if (j - i == 1) {
            return dp[i][j] = 0;
        }

        for (int k = 1; k < (j - i); k++) {
            dp[i][j] = Math.min(dp[i][j], rec(i, i + k, b, dp) + rec(i + k, j, b, dp));
        }

        return dp[i][j] = dp[i][j] + b[j] - b[i];
    }

