	}

	static long dfs(int l, int r) {
		if (dp[l][r] > 0 || l == r) {
			return dp[l][r];
		}

		long ret = Long.MAX_VALUE;
		for (int i = l; i < r; i++) {
			long val = dfs(l, i) + dfs(i + 1, r) + b[r] - b[l - 1];
			ret = Math.min(ret, val);
		}
		return dp[l][r] = ret;
	}
}

