  private static long fN(int[] a, int l, int r) {
    if (l == r) return 0;
    long min = Long.MAX_VALUE;
    long sum = a[r];
    for (int i = l; i < r; i++) {
      long b = fN(a, l, i) + fN(a, i + 1, r);
      min = Long.min(min, b);
      sum += a[i];
    }
    return sum + min;
  }
