                for (int j = i; j < n; j++) {
                    if (i == j) {
                        dp[i][j] = 0;
                    } else {
                        dp[i][j] = INF;
                        long sum = 0L;
                        for (int k = i; k <= j; k++) {
                            sum += a[k];
                        }
                        for (int k = i; k <= j - 1; k++) {
                            dp[i][j] = min(dp[i][j], dp[i][k] + dp[k + 1][j] + sum);
                        }
                    }
                }
            }

            out.println(dp[0][n - 1]);

        }


