public class Main {

	private static Scanner in;

    private static int n;
    private static int[] a;
    private static long[][] dp;

    public static void main(String[] args) {
        in = new Scanner(System.in);
        n = in.nextInt();
        a = new int[n];
        for(int i=0; i<n; i++) a[i] = in.nextInt();

        dp = new long[n][n];

        for(int i=0; i<n; i++) {
            Arrays.fill(dp[i], -1);
        }

        System.out.println(solve(0, n-1));

    }

    private static long solve(int left, int right) {
        if (left==right) return 0;

        if (dp[left][right]!=-1) return dp[left][right];

        long ans = (long)1e15;

        long cost = 0;
        for(int i=left; i<=right; i++) cost+=a[i];

        for(int k=left; k<right; k++) {
            //left:k and k+1:right are combined seperately
            ans = Math.min(ans, cost+solve(left, k)+solve(k+1, right));
        }

        return dp[left][right]=ans;
    }


}

import java.util.*;

public class Main {
    private static long solve(int N, int[] a) {
        PriorityQueue<Long> pq = new PriorityQueue<>();
        for (int ai: a) pq.add((long)ai);

        long result = 0;
        while (!pq.isEmpty()) {
            long m1 = pq.poll();
            if (pq.isEmpty()) break;
            long m2 = pq.poll();

            long sum = m1 + m2;
            result += sum;
            pq.add(sum);
        }
        return result;
    }

    public static long run(Scanner scanner) {
        int N = scanner.nextInt();
        int[] a = new int[N];
        for (int i=0; i < N; i++) a[i] = scanner.nextInt();

        return solve(N, a);
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            System.out.println(run(scanner));
        }
        //Tests.run();
    }
}

