    static long calculate(int i, int j, int[] a, long[] s){
        if(i >= j)
            return 0;
        if(dp[i][j] != 0)
            return dp[i][j];
        long min = Long.MAX_VALUE;
        for(int k = i+1; k <= j; k++){
