public class Main {
    static final Scanner sc  = new Scanner(System.in);
    static final int     MOD = (int) 1E9 + 7;

    static long[][] memo;
    static long[][] sum;

    public static void main(String[] args) {
        int N = nint();
        int[] a = nints(N, 1, 0);
        sum = new long[N+1][N+1];

        for (int h = 1; h <= N; h++) {
            sum[1][h] = sum[1][h-1] + a[h];
        }
        for (int h = 2; h <= N; h++) {
            for (int w = h; w <= N; w++) {
                sum[h][w] = sum[h-1][w] - sum[h-1][h-1];
            }
        }
        memo = new long[N+1][N+1];

        System.out.println(calcCost(1, N));
    }

    private static long calcCost(int from, int  to) {
        if (from == to) {
            return 0;
        }

        if (memo[from][to] != 0) {
            return memo[from][to];
        }

        long cost = Long.MAX_VALUE;
        for (int bet = from; bet < to; bet++) {
            long temp = calcCost(from, bet) + sum[from][to] + calcCost(bet + 1, to);
            cost = min(temp, cost);
        }
        memo[from][to] = cost;
        return cost;
    }

    private static int nint() {
        return sc.nextInt();
    }

    private static int[] nints(int n) {
        return nints(n, 0, 0);
    }

    private static int[] nints(int n, int padL, int padR) {
        int[] a = new int[padL + n + padR];
        for (int i = 0; i < n; i++)
            a[padL + i] = nint();
        return a;
    }

