class Main{
	static int N;
	static int[] a;
	static long[] sum;
	static long[][] dp;
	static long f(int i, int j) {
		if(i == j) return 0;
		if(dp[i][j] != -1) return dp[i][j];
		long ans = Long.MAX_VALUE;
		for(int k = i; k < j; k++) {
			ans = Math.min(ans, f(i, k) + f(k + 1, j) + sum[j + 1] - sum[i]);
		}
		return dp[i][j] = ans;
	}
