		for(int i = 0; i < n; i++) {
			pre[i + 1] = pre[i] + arr[i];
		}
		long[][] dp = new long[n][n];

		for(int l = n - 1; l >= 0; l--) {
			for(int r = l; r < n; r++) {
				if(l == r) {
					continue;
				}
				dp[l][r] =  Long.MAX_VALUE;
				for(int sep = l; sep < r; sep++) {
					dp[l][r] = Math.min(dp[l][r], dp[l][sep] + dp[sep + 1][r] + pre[r + 1] - pre[l]);
				}
			}
		}

		out.println(dp[0][n - 1]);
	}

