		int N = Integer.parseInt(br.readLine());

		st = new StringTokenizer(br.readLine());
		long[] psa = new long[N+1];
		psa[0] = 0;
		for(int i=1; i<=N; i++) {
			psa[i] = Integer.parseInt(st.nextToken()) + psa[i-1];
		}

		long[][] dp = new long[N][N];
		for(int i=N-1; i>=0; i--) {
			for(int j=i+1; j<N; j++) {
				dp[i][j] = Long.MAX_VALUE;
				for(int k=i; k<j; k++) {
					dp[i][j] = Math.min(dp[i][j], dp[i][k]+dp[k+1][j]);
				}
				dp[i][j] += psa[j+1]-psa[i];
			}
		}
		System.out.println(dp[0][N-1]);
	}
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		long lsum[][] = new long[n][n]; // local sum:部分和
		for ( int c = 0; c < n; c++ ) {
			lsum[c][c] = in.nextInt();
			for ( int r = 0; r < c; r++ ) {
				lsum[r][c] = lsum[r][c - 1] + lsum[c][c];
			}
		}

		long cost[][] = new long[n][n]; // 累積コスト
		for ( int r = n - 2; 0 <= r; r-- ) {
			for ( int c = r + 1; c < n; c++ ) {
				Long min = Long.MAX_VALUE;
				for ( int i = r; i <= c - 1; i++ ) {
					if ( min > cost[r][i] + cost[i + 1][c] ) {
						min = cost[r][i] + cost[i + 1][c];
					}
				}
				cost[r][c] = min + lsum[r][c];
			}
		}

		System.out.println(cost[0][n - 1]);
		in.close();
	}
}

