        BigInteger cost = new BigInteger("0");
        for(int i=0;i<n;i++) {
            pQueue.add(sc.nextBigInteger());
        }
        while (pQueue.size() != 1) {
            BigInteger first = pQueue.poll();
            BigInteger second = pQueue.poll();
            BigInteger dummyCost = first.add(second);
            pQueue.add(dummyCost);
            cost = cost.add(dummyCost);
        }
