			else dp[i][j]=inf;
		}
		for(int i=0;i<402;i++) {//区間の幅
			for(int j=0;j<402;j++) {
				if(j+i>=n)break;
				for(int k=j;k<j+i;k++) {
					dp[j][j+i] = Math.min(dp[j][j+i],dp[j][k] + dp[k+1][j+i] + sum[j+i+1] - sum[j]);
				}
			}
		}
		System.out.println(dp[0][n-1]);
	}
}

