		int n = in.nextInt();
		long lsum[][] = new long[n][n]; // local sum:部分和
		for ( int c = 0; c < n; c++ ) {
			lsum[c][c] = in.nextInt();
			for ( int r = 0; r < c; r++ ) {
				lsum[r][c] = lsum[r][c - 1] + lsum[c][c];
			}
		}

		long cost[][] = new long[n][n]; // 累積コスト
		Long min = Long.MAX_VALUE;
		for ( int r = n - 2; 0 <= r; r-- ) {
			for ( int c = r + 1; c < n; c++ ) {				
				for ( int i = r; i <= c - 1; i++ ) {
					if ( min > cost[r][i] + cost[i + 1][c] ) {
						min = cost[r][i] + cost[i + 1][c];
					}
				}
				cost[r][c] = min + lsum[r][c];
				min = Long.MAX_VALUE;
			}
		}

		System.out.println(cost[0][n - 1]);
		in.close();
	}
}

import java.util.*;
import java.io.*;

public class Main {


	public static void main(String[] args) {
		Main ans = new Main();
		System.out.println(ans.solve());
	}

	private long solve() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int [] array = new int[N+1];

		for(int i=1;i<=N;i++){
			array[i] = sc.nextInt();
		}		 
		long [][] dp = new long[N+1][N+1];
 		long [][] sum = preProcess(array, N);
 		return solve(sum, 1, N, dp);
	}

	private long solve(long [][]sum, int i, int j, long[][] dp) {
		if (i==j) return 0;
		if (dp[i][j] != 0) return dp[i][j];

		long bestCost = (long) (1e15);
		for(int k=i;k<=j-1;k++) {
			long cost = sum[i][j] + solve(sum, i, k, dp) + solve(sum, k+1, j, dp);
			bestCost = Math.min(bestCost, cost);
		}
		dp[i][j] = bestCost;
		return bestCost;
	}

	private long [][] preProcess(int[]array, int N) {		 
		long [][] sum = new long[N+1][N+1];
		for(int i=1;i<=N;i++){
			for(int j=i;j<=N;j++){
				sum[i][j] = array[j] + ((i==j) ? 0 : sum[i][j-1]);
			}
		}
		return sum;
	}
}

