/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        NSlimes solver = new NSlimes();
        solver.solve(1, in, out);
        out.close();
    }

    static class NSlimes {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int[] a = in.nextIntArray(N);
            long[][] dp = new long[500][500];
            //dp[i][j] = minimum cost for combining i to j
            long[] sum = new long[N + 1];
            // range for i to j inclusive - sum[r+1] - sum[l]
            for (int i = 0; i < N; i++) {
                sum[i + 1] = sum[i] + a[i];
            }

            for (int i = N - 1; i >= 0; i--) {
                for (int j = i; j < N; j++) {
                    if (i == j) {
                        dp[i][j] = 0;
                        continue;
                    }
                    dp[i][j] = (long) Integer.MAX_VALUE * 1000;
                    for (int k = i; k < j; k++) {
                        dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j] + (sum[j + 1] - sum[i]));
                    }
                }
            }
            out.print(dp[0][N - 1]);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int[] nextIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++)
                array[i] = nextInt();
            return array;
        }

    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author vdewansa
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        NSlimes solver = new NSlimes();
        solver.solve(1, in, out);
        out.close();
    }

    static class NSlimes {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int N = in.nextInt();
            int[] a = new int[N + 1];
            for (int i = 1; i <= N; i++) {
                a[i] = in.nextInt();
            }
            long[] cumsum = new long[N + 1];
            for (int i = 1; i <= N; i++) {
                cumsum[i] = cumsum[i - 1] + a[i];
            }
            long[][] cost = new long[N + 1][N + 2];
            for (int len = 2; len <= N; len++) {
                for (int start = 1; start + len - 1 <= N; start++) {
                    cost[len][start] = Long.MAX_VALUE;
                    final int end = start + len - 1;
                    for (int i = start; i <= end; i++) {
                        long costLeft = cost[i - start][start];
                        long costRight = cost[end - i][i + 1];
                        long sumAll = cumsum[end] - cumsum[start - 1];
                        long curCost = costLeft + costRight + sumAll;
                        if (i > start && i < end) {
                            long sum1 = cumsum[i] - cumsum[start - 1];
                            long sum2 = cumsum[end] - cumsum[i - 1];
                            curCost += Math.min(sum1, sum2);
                        }
                        cost[len][start] = Math.min(cost[len][start], curCost);
                    }
                }
            }
            out.println(cost[N][1]);
        }

    }
}

