public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static long solve() {
        long[] dp = new long[N];
        for (int i = 0; i < N; i++) {
            dp[i] = A[i];
        }
        long cost = 0;
        while(dp.length > 1) {
            int minIndex = 0;
            long min = Long.MAX_VALUE / 2;

            for (int i = 0; i < dp.length-1; i++) {
                if( dp[i] + dp[i+1] < min ) {
                    minIndex = i;
                    min = dp[i] + dp[i+1];
                }
            }

            long[] next = new long[dp.length-1];
            for (int i = 0, j = 0; i < dp.length; i++, j++) {
                if( i == minIndex ) {
                    next[j] = dp[i] + dp[i+1];
                    cost += dp[i] + dp[i+1];
                    i++;
                } else {
                    next[j] = dp[i];
                }
            }
            dp = next;
        }
        return cost;
    }

