		}
		System.out.println(f(1,n));
	}
	static long f(int l,int r){
		if(l==r) return 0;
		if(dp[l][r]!=0) return dp[l][r];
		long min=Long.MAX_VALUE;
		for(int i=l; i<r; i++){
			min=Math.min(min,f(l,i)+f(i+1,r));
		}
		return dp[l][r]=min+a_cum[r]-a_cum[l-1];
	}
