            for(int i = j-1 ; i >= 1 ; i--){
                long ans = Long.MAX_VALUE;
                for(int k = i ; k < j ; k++){
                    ans = Math.min(ans , dp[i][k] + dp[k+1][j] + sum(arr,i,k) + sum(arr,k+1 ,j));
