public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();

		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = sc.nextInt();
		}
		long[] cumsum = new long[n + 1];
		for (int i = 0; i < n; i++) {
			cumsum[i + 1] = cumsum[i] + a[i];
		}

		final long INF = Long.MAX_VALUE / 2;
		long[][] dp = new long[n][n];
		for (int d = 1; d < n; d++) {
			for (int i = 0; i + d < n; i++) {
				for (int j = i + d; j < n; j++) {
					dp[i][j] = INF;
					for (int k = i; k < j; k++) {
						dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j] + cumsum[k + 1] - cumsum[i] + cumsum[j + 1] - cumsum[k + 1]);
					}
				}
			}
		}

		pr.println(dp[0][n - 1]);
	}

    // ---------------------------------------------------
