import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int[] a = na(n);
		out.println(obst(a));
	}

	public static long obst(int[] a)
	{
		int n = a.length;
		long[][] dp = new long[n][n];
		int[][] argmin = new int[n][n];
		long[] cum = new long[n+1];
		for(int i = 0;i < n;i++)cum[i+1] = cum[i] + a[i];
		for(int len = 1;len <= n;len++){
			for(int i = 0;i+len-1 < n;i++){
				if(len == 1){
					dp[i][i] = 0;
					argmin[i][i] = i;
				}else{
					int j = i+len-1;
					long min = Long.MAX_VALUE;
					for(int k = Math.max(argmin[i][j-1], i);k <= Math.min(argmin[i+1][j], j-1);k++){
						if(dp[i][k] + dp[k+1][j] < min){
							min = dp[i][k] + dp[k+1][j];
							argmin[i][j] = k;
						}
					}
					dp[i][j] = dp[i][argmin[i][j]] + dp[argmin[i][j]+1][j] + cum[j+1] - cum[i];
				}
			}
		}
		return dp[0][n-1];
	}

	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.LongStream;

public class Main {

	private final int n;
	private final List<Long> a;
	private long[][] dp;
	private long[] prefixSums;
	private long[] suffixSums;

	public Main(int n, List<Long> a) {
		this.n = n;
		this.a = a;
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		List<Long> a = LongStream.range(0, n).map(i -> sc.nextLong()).boxed().collect(Collectors.toList());

		new Main(n, a).solve();
	}

	private void solve() {
		dp = new long[n][n];
		prefixSums = new long[n];
		suffixSums = new long[n];
		Arrays.fill(prefixSums, -1);
		Arrays.fill(suffixSums, -1);

		for (int i = 0; i < n; i++) {
			Arrays.fill(dp[i], -1);
		}

		System.out.println(best(0, n - 1));
	}

	private long best(int from, int to) {
		if (from == to) return 0;
		if (dp[from][to] != -1) return dp[from][to];

		long best = Long.MAX_VALUE;
		for (int lastFromLeft = from; lastFromLeft < to; lastFromLeft++) {
			best = Math.min(best,
				sumBetween(from, lastFromLeft) + sumBetween(lastFromLeft + 1, to) +
							best(from, lastFromLeft) + best(lastFromLeft + 1, to));
		}
		return best;
	}

	private long sumBetween(int l, int r) {
		return prefixSum(r) - (l == 0? 0 : prefixSum(l - 1));
	}

	private long prefixSum(int lastFromLeft) {
		if (lastFromLeft == 0) return a.get(0);
		if (prefixSums[lastFromLeft] != -1) return prefixSums[lastFromLeft];
		return prefixSums[lastFromLeft] =
				a.get(lastFromLeft) + prefixSum(lastFromLeft - 1);
	}

}

