    public static long minCost(int[] size){
        long[][] dp = new long[size.length][size.length];
        for (int L = size.length-1; L >= 0; L--) {
            for (int R = L; R < size.length; R++) {
                if (L == R){
                    dp[L][R] = 0;
                }else {
                    dp[L][R] = (long) (1e18+9);
                    long sum = 0;
                    for (int i = L; i <= R; i++) {
                        sum += size[i];
                    }
                    for (int i = L; i < R; i++) {
                        dp[L][R] = Math.min(dp[L][R], dp[L][i]+dp[i+1][R]+sum);
