import java.util.*;
import java.io.*;
public class Main {
    static long arr[],dp[][],pre_sum[];
    public static void main(String args[]) {
        Scanner input=new Scanner(System.in);
        int n=input.nextInt();
        arr=new long[n];
        pre_sum=new long[n];
        for(int i=0;i<n;i++) {
            arr[i]=input.nextLong();
            if(i==0) {
                pre_sum[i]=arr[i];
            }
            else {
                pre_sum[i]=pre_sum[i-1]+arr[i];
            }
        }
        dp=new long[n][n];
        for(int i=0;i<n;i++) {
            for(int j=0;j<n;j++) {
                dp[i][j]=-1;
            }
        }
        System.out.println(solve(0,n-1));
    }
    public static long solve(int l,int r) {
        if(l==r) {
            return 0;
        }
        if(dp[l][r]!=-1) {
            return dp[l][r];
        }
        long cost=Long.MAX_VALUE;
        for(int i=l;i<r;i++) {
            long cst=solve(l,i)+solve(i+1,r)+(prefix_sum(l,i)+prefix_sum(i+1,r));
            cost=Math.min(cost,cst);
        }
        dp[l][r]=cost;
        return dp[l][r];
    }
    public static long prefix_sum(int l,int r) {
        if(l==0) {
            return pre_sum[r];
        }
        else {
            return pre_sum[r]-pre_sum[l-1];
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
	static int n;
	static int[] a;
	static long[] b;
	static long[][] dp;

	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		a = new int[n + 1];
		for (int i = 1; i <= n; i++) {
			a[i] = sc.nextInt();
		}
		sc.close();

		b = new long[n + 1];
		for (int i = 1; i <= n; i++) {
			b[i] = b[i - 1] + a[i];
		}

		dp = new long[n + 1][n + 1];
		for (int i = 1; i <= n; i++) {
			Arrays.fill(dp[i], Long.MAX_VALUE);
		}
		System.out.println(dfs(1, n));
	}

	static long dfs(int l, int r) {
		if (dp[l][r] < Long.MAX_VALUE) {
			return dp[l][r];
		}
		if (l == r) {
			return dp[l][r] = 0;
		}

		long sum = b[r] - b[l - 1];
		long ret = Long.MAX_VALUE;
		for (int i = l; i < r; i++) {
			long s1 = dfs(l, i);
			long s2 = dfs(i + 1, r);
			long val = s1 + s2 + sum;
			ret = Math.min(ret, val);
		}
		return dp[l][r] = ret;
	}
}

