public class Main {


  private static void solve() {
    int n = ni();
    int[] a = na(n);

    dp = new long[n][n + 1];
    for (long[] v : dp) Arrays.fill(v, -1);

    long[] sum = new long[n + 1];
    for (int i = 0; i < n; i ++) {
      sum[i + 1] = sum[i] + a[i];
    }

    System.out.println(rec(0, n, a, sum));
  }

  static long[][] dp;
  private static long rec (int i, int j, int[] a, long[] sum) {
    if (j == i + 1) {
      return 0;
    }
    if (dp[i][j] >= 0)
      return dp[i][j];

    long ret = Long.MAX_VALUE;
    for (int k = i + 1; k < j; k ++) {
      ret = Math.min(ret, rec(i, k, a, sum) + rec(k, j, a, sum));
    }
    ret += sum[j] - sum[i];

    dp[i][j] = ret;
    return ret;
  }

