		for(int i=0;i<cmd.length;i++)
		{
			ans[i]=Long.valueOf(cmd[i]);
		}
		return ans;
	}
	static long[][]dp;
	static long[]arr;
	static long solve(int l,int r)
	{
		if(l>=r)
			return 0;
		if(dp[l][r]!=-1)
			return dp[l][r];
		long res=(long)Math.pow(10, 18);
		long sum=0;
		for(int i=l;i<=r;i++)
		{
			sum+=arr[i];
		}
		for(int i=l;i<=r-1;i++)
		{
			res=Math.min(res,solve(l,i)+solve(i+1,r)+sum);
		}
		dp[l][r]=res;
		return res;
	}
