public class slimes {

    public static long sum(int[] arr, int i, int j) {
        int sum = 0;
        for(int k = i; k <= j; k++){
            sum += arr[k];

        }
        return sum;
    }

    static long solve(int[] arr, int i, int j,long[][] dp){
        if(i>= j)
            return 0;
        if(dp[i][j] != -1)
            return dp[i][j];

        long ans = Long.MAX_VALUE;

        for(int k = i; k < j; k++){
          ans =  Math.min(ans, solve(arr,i,k,dp) + solve(arr, k+1, j,dp) + sum(arr,i,k) + sum(arr,k+1,j));
        }

        return  dp[i][j] = ans;

    }
