namespace AtCoder.DP
{
    class EDPC_N
    {
        static long[,] dp;
        static long[] acc;

        public static void Main()
        {
            var n = int.Parse(Console.ReadLine());
            var a = Console.ReadLine().Split(' ').Select(s => long.Parse(s)).ToArray();
            dp = new long[n, n + 1];
            acc = new long[n + 1];

            for (int i = 0; i < n; i++)
            {
                dp[i, i + 1] = a[i];
                acc[i + 1] = acc[i] + a[i];
            }

            Union(0, n);
            Console.WriteLine(dp[0, n]);
        }

        public static long Union(int left, int right)
        {
            if (right - left == 1)
                return 0;

            long min = long.MaxValue;
            for (int i = left + 1; i < right; i++)
            {
                var temp = Union(left, i) + Union(i, right);
                if (min > temp)
                    min = temp;
            }
            dp[left, right] = min + acc[right] - acc[left];
            return dp[left, right];
        }
    }
}

