public class MainClass
{
	public const long Giri = 1000000007;
	public const long DpInf = 999999999999;

	static long[] s;
	static long[,] dp;
	static bool[,] visited;
	public static void Main(string[] args)
	{
		var n = Console.ReadLine().ToInt();
		var sa = Input();
		var a = new long[n];
		for(int i = 0; i < n; i++)
		{
			a[i] = sa[i].ToLong();
		}

		s = new long[n+1];

		s[0] = a[0];
		for(int i = 1; i < n; i++)
		{
			s[i] = s[i - 1] + a[i];
		}

		dp = new long[n+1,n+1];
		visited = new bool[n+1,n+1];
		Console.WriteLine(Solve(0, n-1));
	}

	private static long Solve(int l, int r)
	{
		if(r == l) return 0;

		if(visited[l, r]) return dp[l, r];

		int mid = (l + r) / 2;
		long min = DpInf;
		for(int c = l; c < r; c++)
			min = Math.Min(min, Solve(l, c) + Solve(c+1, r));

		long res = s[r];
		if(l > 0) res -= s[l-1];
		dp[l, r] = min + res;
		visited[l, r] = true;
		return dp[l, r];
	}

	static long GCD(long a, long b)
	{
		var v = new[] { a, b };
		while (v[1] != 0) { v = new[] { v[1], v[0] % v[1] }; }
		return v[0];
	}
	public static string[] Input() { return Console.ReadLine().Split(); }
}

