namespace Training20200727.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/dp/tasks/dp_n
    /// </summary>
    public class QuestionD : AtCoderQuestionBase
    {
        public override IEnumerable<object> Solve(TextReader inputStream)
        {
            _ = inputStream.ReadInt();
            var slimes = inputStream.ReadLongArray().ToList();
            long cost = 0;

            while (slimes.Count > 1)
            {
                long min = long.MaxValue;
                int minIndex = -1;

                for (int i = 0; i + 1 < slimes.Count; i++)
                {
                    var combined = slimes[i] + slimes[i + 1];
                    if (combined < min)
                    {
                        min = combined;
                        minIndex = i;
                    }
                }

                cost += min;
                slimes[minIndex] = min;
                slimes.RemoveAt(minIndex + 1);
            }

            yield return cost;
        }
    }
}

