    public static void solver(long N, long[] slimes){

        /*
            EDPC N Slimes

            まったく意味が分からない。
            合成コストが最も低いものを合成し続けるだけで、
            これはN^2で完走できる処理ではないの？
         */

        long cost = 0;
        var sl = new List<long>(slimes);

        var amalgam = new long[N];
        long min = long.MaxValue;
        int minIndex = -1;

        while(sl.Count() != 1){
			min = long.MaxValue;
			minIndex = -1;
            for(int i = 0; i < sl.Count() - 1; i++){
                amalgam[i] = sl[i] + sl[i+1];
                if(amalgam[i] < min){
                    min = amalgam[i];
                    minIndex = i;
                }
            }
            cost+= min;
            sl[minIndex+1] += sl[minIndex];
            sl.RemoveAt(minIndex);

        }



        Console.WriteLine(cost);


	}

