class Program
{
    static void Main(string[] args)
    {
        N = sc.ReadInt();
        A = sc.ReadLongArray(N);
        Sum = new long[N + 1];
        for (int i = 0; i < N; i++)
        {
            Sum[i + 1] = Sum[i] + A[i];
        }
        DP = new long[N + 1, N + 1];
        var ans = Rec(0, N);
        Console.WriteLine(ans);
    }
    static int N;
    static long[] A;
    static long[] Sum;
    static long[,] DP;
    static long Rec(int start, int len)
    {
        if (DP[start, len] > 0) return DP[start, len];

        if (len == 1) return 0;
        else
        {
            var res = long.MaxValue;
            for (int start2 = start + 1; start2 < start + len; start2++)
            {
                var len1 = start2 - start;
                var res1 = Rec(start, len1);
                var len2 = len - len1;
                var res2 = Rec(start2, len2);
                var x = res1 + res2
                    + (Sum[start + len1] - Sum[start])
                    + (Sum[start2 + len2] - Sum[start2]);
                res = Math.Min(res, x);
            }
            DP[start, len] = res;
        }
        return DP[start, len];
    }

    static Scanner sc = new Scanner();
}
