internal partial class Solver {

    long?[,] memo;

    long dfs(int[] a, int begin, int end) {
        if (begin + 1 == end) return 0;
        if (!memo[begin, end].HasValue) {
            long val = long.MaxValue;

            for (int i = begin + 1; i < end; i++) {
                val = Math.Min(val, dfs(a, begin, i) + dfs(a, i, end));
            }

            for (int i = begin; i < end; i++) {
                val += a[i];
            }

            memo[begin, end] = val;
        }
        return memo[begin, end].Value;
    }

    public void Run() {
        var n = ni();
        var a = ni(n);

        memo = new long?[n, n + 1];

        cout.WriteLine(dfs(a, 0, n));
    }
