    class N
    {
        static void Main(string[] args)
        {
            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            long[] array = ReadLongs();
            long[,] dp = new long[n, n];
            for(int i = n - 1; i >= 0; i--)
            {
                for (int j = i + 1; j < n; j++)
                {
                    long minCost = long.MaxValue;
                    long sum = 0;
                    for (int k = i; k + 1 <= j; k++)
                    {
                        minCost = Math.Min(minCost,
                            dp[i, k] + dp[k + 1, j]);
                        sum += array[k];
                    }
                    sum += array[j];
                    dp[i, j] = minCost + sum;
                }
            }
            Console.WriteLine(dp[0, n - 1]);
        }

