    int[] A;


    void calc()
    {
        cin = new Scanner();
        N = cin.nextInt();
        A = cin.ArrayInt(N);

        long[,] dp = new long[N + 1, N + 1];
        long[] sum = new long[N + 1];
        for (int i = 0; i < N; i++)
        {
            sum[i + 1] = sum[i] + A[i];
        }


        for (int len = 2; len <= N; len++)
        {
            for (int l = 0; l <= N - len; l++)
            {
                int r = l + len;
                long AddCost = sum[r] - sum[l];
                long PreCost = long.MaxValue / 4;

                for (int k = l + 1; k < r; k++)
                {
                    PreCost = Math.Min(PreCost, dp[l, k] + dp[k, r]);
                }

                dp[l, r] = PreCost + AddCost;
            }
        }

        Console.WriteLine(dp[0, N]);
    }


}


