	private long[,] memo;
	public void Solve()
	{
		N = GetLong();
		a = GetLongs(N);

		sum = new long[N + 1];
		for(long i = 0; i < N; i++)
			sum[i + 1] = sum[i] + a[i];

		flag = new bool[N, N];
		memo = new long[N, N];
		WriteLine(rec(0, N - 1));
	}

	private long rec(long l, long r)
	{
		if(flag[l, r])
			return memo[l, r];

		flag[l, r] = true;

		if(l == r)
			return (memo[l, r] = 0);

		long min = long.MaxValue;
		for(long i = l; i < r; i++)
			chmin(ref min, rec(l, i) + rec(i + 1, r) + sum[r + 1] - sum[l]);

		return (memo[l, r] = min);
	}
}

