            for(int l=0;l+len<=n;l++){
                int r=l+len;
                for(int i=l+1;i<=r-1;i++){
                    Chmin(ref dp[l,r], dp[l,i]+dp[i,r]);
                }
                dp[l,r]+=sum[l,r];
            }
        }
        Console.WriteLine(dp[0,n]);
    }
