    {
        public static long[] kaij;
        static void Main(string[] args)
        {
            StreamScanner scan = new StreamScanner(System.Console.OpenStandardInput());
            int n = scan.Integer();
             a = scan.Long(n);
            s = new long[n + 1];
            for (int i = 0; i < n; i++)
            {
                s[i + 1] = a[i] + s[i];
            }
            dp = new long[n, n];
            long res = solve(0, n - 1);
            Console.WriteLine(res);
        }
        static long[,] dp;
        static long[] a;
        static long[] s;
        public static long solve(int migi,int hidari)
        {
            if (migi == hidari) { return 0; }
            if (dp[migi, hidari] > 0) { return dp[migi, hidari]; }
            long min = long.MaxValue;
            for (int i = migi; i < hidari; i++)
            {
                min = Math.Min(min, solve(migi, i) + solve(i + 1, hidari));
            }
            dp[migi, hidari] = min + s[hidari + 1] - s[migi];
            return dp[migi, hidari];
        }
        public static long kaijyo(int n)
        {
            if (n <= 1)
                return 1;
            if (kaij[n] > 0)
                return kaij[n];
            long kekka = n * kaijyo(n - 1);
            return kekka;
        }

        public static long modPow(long a,long n,long p)//a^n(mod p)
        {
            if (n == 1) { return a % p; }
            if (n % 2 == 1) { return (a * modPow(a, n - 1, p)) % p; }
            long buf = modPow(a, n / 2, p);
            return (buf * buf) % p;
        }

    }
