using System;
using System.IO;

namespace Contest
{
    class Program
    {
        private Scanner sc;
        private int N;
        private long[] A;
        private long[] Sum;
        private long[,] Memo;

        public void Solve()
        {
            sc = new Scanner();
            N = sc.NextInt();
            A = sc.LongArray();
            Memo = new long[N + 1, N + 1];
            Sum = new long[N + 1];
            for (int i = 0; i < N; i++)
            {
                Sum[i + 1] = Sum[i] + A[i];
            }
            for (int i = 0; i <= N; i++)
            {
                for (int j = 0; j <= N; j++)
                {
                    Memo[i, j] = -1;
                }
            }

            Console.WriteLine(Calc(0, N));
        }

        // [left, right)を合体させる
        private long Calc(int left, int right)
        {
            if (Memo[left, right] != -1)
            {
                return Memo[left, right];
            }

            long res;

            if (right - left <= 1)
            {
                res = 0;
            }
            else
            {
                res = long.MaxValue;

                for (int i = left + 1; i < right; i++)
                {
                    long l = Calc(left, i);
                    long r = Calc(i, right);
                    res = Math.Min(res, l + r);
                }

                res += S(left, right);
            }

            Memo[left, right] = res;
            return res;
        }

        // [left, right) の和
        private long S(int left, int right)
        {
            return Sum[right] - Sum[left];
        }




        static void Main() => new Program().Solve();
    }
}

