	const long Inf = (long) 1e18;
	public void Solve(){

		sum = new long[N + 1];
		for(int i=0;i<N;i++){
			sum[i + 1] = sum[i] + A[i];
		}
		memo = new long[N][];
		for(int i=0;i<N;i++){
			memo[i] = new long[N + 1];
			for(int j=0;j<=N;j++) memo[i][j] = Inf;
		}
		Console.WriteLine(dfs(0,N));


	}

	long[][] memo;
	long[] sum;
	long dfs(int now, int cnt){
		if(memo[now][cnt] != Inf) return memo[now][cnt];
		if(cnt == 1){
			return memo[now][cnt] = 0;
		}
		long min = Inf;
		for(int i=1;i<cnt;i++){
			long a = dfs(now,i);
			long b = dfs(now + i, cnt - i);
			min = Math.Min(min, a + b + (sum[now + cnt] - sum[now]));
		}
		return memo[now][cnt] = min;
	}


