        public object Calc()
        {
            N = consoleReader.Int;
            a = consoleReader.Split.Int;
            dp = new Slime[N, N];
            return Calc(0, N - 1).history;
        }
        Slime Calc(int start, int end)
        {
            if (dp[start, end].size > 0) return dp[start, end];
            if (start == end)
                return dp[start, end] = new Slime { size = a[start], history = 0 };
            if (end - start == 1)
                return dp[start, end] = new Slime { size = a[start] + a[end], history = a[start] + a[end] };

            var count = end - start;
            var min = new Slime { history = long.MaxValue };
            for (int i = 1; i <= count; i++)
            {
                var left = Calc(start, start + i - 1);
                var right = Calc(start + i, end);

                var tmp = new Slime
                {
                    size = left.size + right.size,
                    history = left.size + right.size + left.history + right.history
                };
                if (tmp.history < min.history)
                    min = tmp;
            }
            return dp[start, end] = min;
        }
        int N;
        Slime[,] dp;
        int[] a;

