	{
		if(r == l) return 0;

		if(visited[l, r]) return dp[l, r];

		int mid = (l + r) / 2;
		long min = DpInf;
		for(int c = l; c < r; c++)
			min = Math.Min(min, Solve(l, c) + Solve(c+1, r));
		dp[l, r] = min + (s[r+1] - s[l]);
		visited[l, r] = true;
		return dp[l, r];
	}

