public class Solver
{
    N n;
    N[] a;
    public void Solve()
    {
        n = ri;
        a = new N[n];
        for(int i = 0; i < n; i++) { a[i] = ri; }
        N[,] dp = new N[n + 1, n + 1];//dp[i,j]:スライム(i+1)からスライムjまでで考えたときのコストの最小値
        N[] sum = new N[n + 1];//sum[i]:a[0]からa[i-1]までの和
        for(int i = 0; i < n; i++)
        {
            sum[i + 1] = sum[i] + a[i];
        }
        N t = 0, j = 0;
        for(int l = 2; l <= n; l++)//1匹は当然コスト0なので2匹から
        {
            for(int i = 0; i <= n - l; i++)
            {
                j = i + l;
                t = dp[i, i + 1] + dp[i + 1, j];
                for(int k = i + 2; k < j; k++)//スライムをi+1,...,k|k+1,...,jにわける
                {
                    t = Math.Min(t, dp[i, k] + dp[k, j]);
                }
                dp[i, j] = t + sum[j] - sum[i];
            }
        }
        Write(dp[0, n]);
    }

