            var n = scanner.Integer();
            var a = scanner.ScanLine().Split().Select(v => long.Parse(v)).ToList();

            var ans = GetAns(n, a);
            IO.Printer.Out.WriteLine(ans);
            IO.Printer.Out.Flush();
        }

        public static long GetAns(int n, List<long> a)
        {
            var dp = new long[n, n];
            var sum = new long[n];
            sum[0] = a[0];
            for (int i = 1; i < n; i++) sum[i] = sum[i - 1] + a[i];

            for (int w = 1; w <= n; w++)
            {
                for (int i = 0; i < n; i++)
                {
                    var j = i + w;
                    if (j >= n) break;

                    dp[i, j] = long.MaxValue;
                    for (int k = i; k <= j - 1; k++)
                    {
                        dp[i, j] = Math.Min(dp[i, j], dp[i, k] + dp[k + 1, j] + sum[j] - (i == 0 ? 0 : sum[i - 1]));
                    }
                }
            }

            return dp[0, n - 1];
        }
    }

