  for(var i = 1; i < n; i++)for(var j = 0; j < n-i; j++){
    cost[i][j] = cost[i-1][j] + cost[0][i+j];
  }
  var dp = xArray(1e15,n,n);
  dp[0] = xArray(0,n);
  for(var i = 1; i < n; i++)
  for(var j = 0; j < n-i; j++)
  for(var k = 1; k <= i; k++){
    var t = dp[i-k][j] + dp[k-1][i-k+j+1] + cost[i][j];
    if(t < dp[i][j])dp[i][j] = t;
  }
  return dp[n-1][0];
}

