function kukanDP(l, r){
	if (DP[l][r] != null) return DP[l][r];
	if (l === r) {
		DP[l][r] = 0;
		return 0;
	}
	if (r === l + 1){
		DP[l][r] = a[l] + a[r];
		return DP[l][r];
	}
	let tmp = Infinity;
	for (let i = l; i < r; i++){
		tmp = Math.min(tmp, kukanDP(l, i) + kukanDP(i + 1, r) - ruisekiwa[l] + ruisekiwa[r + 1]);
	}
	DP[l][r] = tmp;
	return tmp;
}

