func solve(a []int) int {
	n := len(a)
	if n == 2 {
		return a[0] + a[1]
	}
	min := math.MaxInt64
	for i := 1; i < n; i++ {
		s := a[i] + a[i-1]
		if s < min {
			min = s
		}
	}
	ret := math.MaxInt64
	for i := 1; i < n; i++ {
		b := make([]int, n)
		copy(b, a)
		s := a[i] + a[i-1]
		if s == min {
			b[i-1] = s
			b = append(b[:i], b[i+1:]...)
			res := solve(b) + s
			if res < ret {
				ret = res
			}
		}
	}
	return ret
}

