type entry struct {
	value uint64
	cost  uint64
}

func entryAdd(a *entry, b *entry) entry {
	return entry{
		value: a.value + b.value,
		cost:  a.cost + b.cost + a.value + b.value,
	}
}

func nextInt(s *bufio.Scanner) int {
	s.Scan()

	n, _ := strconv.Atoi(s.Text())
	return n
}

func solve(a []int, n int) uint64 {
	dp := make([][]entry, n)

	for i := 0; i < n; i++ {
		dp[i] = make([]entry, n+1)
		dp[i][i+1].value = uint64(a[i])
	}

	for length := 2; length <= n; length++ {
		for i := 0; i < n-length+1; i++ {
			min := entry{
				value: math.MaxUint64,
				cost:  math.MaxUint64,
			}
			for j := i + 1; j < i+length; j++ {
				e := entryAdd(&dp[i][j], &dp[j][i+length])
				if e.cost < min.cost {
					min = e
				}
			}

			dp[i][i+length] = min
		}
	}

	return dp[0][n].cost
}

