	转移方程:
		dp[i][j]=min(dp[i][k]+dp[k+1][j])+sums[j]-sums[i]+A[i]
*/
func solve(A []int, N int) int {
	dp := make([][]int, N)
	for i := range dp {
		dp[i] = make([]int, N)
	}

	sums := make([]int, N)
	sums[0] = A[0]
