			dp[i][j] = math.MaxInt32
			for k:=i; k<j; k++ {
				dp[i][j] = min(dp[i][j], dp[i][k]+dp[k+1][j])
			}
			dp[i][j] += sums[j]-sums[i]+A[i]
		}
	}
	return dp[0][N-1]
}

