	return a
}

func count(i int) int {
	i++
	s := 0
	for i > 0 {
		s += bit[i]
		i-= i&(-i)
	}
	return s
}

func cnt(i, k int) int {
	return count(k) - count(i-1)
}

func update(i, v int) {
	i++
	for i < len(bit) {
		bit[i] += v
		i += i&(-i)
	}
}

