			if i == j {
				DP[i][j] = arr[i]
			} else if j == i+1 {
				DP[i][j] = arr[i]+arr[j]
			} else {
				for k:=i; k<j; k++ {
					tmp := DP[i][k] + DP[k+1][j] + cnt(i,j)
