	dp := make([][]int64, n)
	for index := 0; index < n; index++ {
		fmt.Fscan(fp, &aList[index])
		dp[index] = make([]int64, n)
	}
	fmt.Println(chokudai(0, n-1, aList, dp))
}
func chokudai(l int, r int, alist []int, dp [][]int64) int64 {
	if l >= r {
		return 0
	}
	if dp[l][r] > 0 {
		return dp[l][r]
	}
	cost := int64(0)
	for index := l; index <= r; index++ {
		cost += int64(alist[index])
	}
	if r-l == 1 {
		dp[l][r] = cost
		return dp[l][r]
	}

	for index := l; index <= r; index++ {
		lPart := chokudai(l, index, alist, dp)
		rPart := chokudai(index+1, r, alist, dp)
		if dp[l][r] == 0 {
			dp[l][r] = cost + lPart + rPart
			continue
		}
		if dp[l][r] > cost+lPart+rPart {
			dp[l][r] = cost + lPart + rPart
		}
	}

	return dp[l][r]
}

