    var mi int
    for i := 0; i < len(s)-1; i++ {
        c := s[i] + s[i+1]
        if c < min {
            min = c
            mi = i
        }
    }
    return calc(unite(s, mi)) + min
}

func unite(s []int, i int) []int {
    ns := make([]int, len(s)-1)
    for j := range ns {
        switch {
        case j == i:
            ns[j] = s[j] + s[j+1]
        case j > i:
            ns[j] = s[j+1]
        default:
            ns[j] = s[j]
        }
    }
    return ns
}

func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}

