        }

        long ans = inf;

        foreach (i ; l+1 .. r) {
            ans = min(ans, ssum(l, r) + dfs(l, i) + dfs(i, r));
        }

        return dp[l][r] = ans;
    }

    long ans = dfs(0, n);

    debug {
        writefln("%(%s\n%)", dp);
    }


    writeln(ans);
}







