  let n = readInt1()
  let a = readSeq().map(parseInt)
  let c = a.buildCumTab()

  var dp = newSeq2[int](n + 1, n + 1)
  for i in 0..n:
    for j in 0..n:
      dp[i][j] = -1

  echo solve(a, c, 0, n, dp)

main()

