template<typename F>
i64 mongeDP(i64 N, F f) {
  vector<vector<i64>> dp(N, vector<i64>(N, 1e18));
  vector<vector<i64>> k(N, vector<i64>(N));
  rep(i, 0, N) {
    dp[i][i] = 0;
    k[i][i] = i;
  }

  rep(d, 1, N) {
    rep(i, 0, N - d) {
       i64 j = i + d;
       i64 l = k[i][j - 1];
       i64 r = k[i + 1][j];
       rep(s, l, r + 1) {
         if(s + 1 >= N) break;
         if(dp[i][s] + dp[s + 1][j] <= dp[i][j]) {
           dp[i][j] = dp[i][s] + dp[s + 1][j];
           k[i][j] = s;
         }
       }
       dp[i][j] += f(i, j);
    }
  }
  return dp[0][N - 1];
}

