def cost(a):
    la = len(a)
    if la == 1:
        return 0
    if la == 2:
        return a[0] + a[1]
    if a in memo:
        return memo[a]
    re = []
    for i in range(1, la):
        re += [cost(a[:i]) + cost(a[i:]) + sum(a)]
    re = min(re)
    memo[a] = re
    return re


