def solve(N, slimes):
  # dp[L][R]: minimum cost to combine [L..R] into a single vertex
  dp = [[0 for _ in range(N)] for _ in range(N)]

  prefix_sum = [0 for _ in range(N + 1)]
  for i in range(N):
    prefix_sum[i + 1] = prefix_sum[i] + slimes[i]

  for L in range(N - 1, -1, -1):
    for R in range(L, N):
      if L == R:
        dp[L][R] = 0
      else:
        min_cost = float('inf')
        merge_cost = prefix_sum[R + 1] - prefix_sum[L]
        for i in range(L, R):   # i: [L..R-1]
          # min_cost = min(min_cost, dp[L][i] + dp[i + 1][R] + merge_cost)
          temp = dp[L][i] + dp[i + 1][R] + merge_cost
          if min_cost > temp:
            min_cost = temp
        dp[L][R] = min_cost

  print(dp[0][N - 1])


