def slimes(a):
    n = len(a)
    d = [[0] * (n + 1) for _ in range(n + 1)]
    prefix = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix[i] = prefix[i - 1] + a[i - 1]

    for l in range(2, n + 1):
        for x in range(n - l + 1):
            z = x + l
            d[x][z] = min(d[x][y] + d[y][z] for y in range(x + 1, z)) + (prefix[z] - prefix[x])

    return d[0][n]


