def solve(A):
    if len(A) == 2:
        return sum(A)
    costs = [A[i] + A[i + 1] for i in range(len(A) - 1)]
    min_cost = min(costs)
    index = costs.index(min_cost)
    next_A = A[:index] + [min_cost] + A[(index + 2):]
    return min_cost + solve(next_A)


