def calc(qLeft, qRight):
    st = deque([(False, qLeft, qRight)])
    memo = dict()

    while st:
        canCalc, left, right = st.pop()

        if left + 1 == right:
            memo[(left, right)] = slime[left]
            continue

        if (left, right) in memo:
            continue

        if canCalc:
            ret = float('inf')
            for mid in range(left + 1, right):
                ret = min(ret, memo[(left, mid)] + memo[(mid, right)])
            ret += cumSlime[right] - cumSlime[left]
            memo[(left, right)] = ret
        else:
            st.append((True, left, right))
            for mid in range(left + 1, right):
                if not (left, mid) in memo:
                    st.append((False, left, mid))
                if not (mid, right) in memo:
                    st.append((False, mid, right))

    return memo[(qLeft, qRight)]

