fn main() {
    input!{
      n: usize,
      aa: [usize; n],
    }
    let mut acm = vec![0; n+1];
    for i in 0..n {
        acm[i+1] = acm[i] + aa[i];
    }

    const INF: usize = 1 << 60;

    let mut dp = vec![vec![INF; n]; n+1];
    for w in 0..2 {
        for l in 0..n {
            dp[w][l] = 0;
        }
    }

    for w in 2..n+1 {
        for l in 0..n {
            let r = l+w-1;
            if r >= n { break; }
            for pos in l..r {
                // [l,pos] | (pos, r] に分割
                let w1 = pos-l+1;
                let w2 = r-pos;
                dp[w][l] = min(dp[w][l], dp[w1][l] + dp[w2][pos+1] + acm[r+1] - acm[l]);
            }
        }
    }
    println!("{}", dp[n][0]);
}

