fn rec(dp: &mut Vec<Vec<Option<u64>>>, c: &Cum, l: usize, r: usize) -> u64 {
    if let Some(src) = dp[l][r] {
        return src;
    }

    let mut ret = 1u64 << 60;
    for i in l..r {
        ret = std::cmp::min(
            ret,
            rec(dp,c,l,i) + rec(dp,c,i+1,r)
        );
    }
    ret += c.sum(l,r+1);
    dp[l][r] = Some(ret);
    ret
}

