const M: i64 = 900000000000;

fn main() {
    let mut sc = Scanner::new();
    let n: usize = sc.cin();
    let xs: Vec<i64> = (0..n).map(|_|sc.cin()).collect();
    let mut memo = vec![vec![None; n+1]; n+1];
    let mut stack = vec![(0, n)];
    while let Some((l, r)) = stack.pop() {
        if memo[l][r].is_some() {
            continue;
        }
        if l + 1 == r {
            memo[l][r] = Some(0);
            continue;
        }
        stack.push((l, r));
        let mut ok = true;
        for i in l+1..r {
            if memo[l][i].is_none() { stack.push((l, i)); ok=false; }
            if memo[i][r].is_none() { stack.push((i, r)); ok=false; }
        }
        if ok {
            let mut mn = M;
            for i in l+1..r {
                mn = min(mn, memo[l][i].unwrap() + memo[i][r].unwrap());
            }
            for i in l..r {
                mn += xs[i];
            }
            memo[l][r] = Some(mn);
        }
    }
    put!(memo[0][n].unwrap());
}

use std::io::{self, Write};
use std::str::FromStr;
use std::collections::VecDeque;

struct Scanner { stdin: io::Stdin, buffer: VecDeque<String>, }
impl Scanner {
    fn new() -> Scanner { Scanner { stdin: io::stdin(), buffer: VecDeque::new() } }
    fn cin<T: FromStr>(&mut self) -> T {
        while self.buffer.len() == 0 {
            let mut line = String::new();
            let _ = self.stdin.read_line(&mut line);
            for w in line.split_whitespace() {
                self.buffer.push_back(String::from(w));
            }
        }
        self.buffer.pop_front().unwrap().parse::<T>().ok().unwrap()
    }
}

