struct Rec {
    cum: CumSum1,
    dp: Vec<Vec<Option<i64>>>,
}
impl Rec {
    fn f(&mut self, i: usize, j: usize) -> i64 {
        if i==j { return 0 }
        if i+1==j { return self.cum.query(i,i+1) }

        if let Some(x) = self.dp[i][j] { return x }

        let mut minv = 1<<60;
        for k in i+1..j {
            let left = if k-i==1 {
                self.cum.query(i,k)
            } else {
                self.cum.query(i,k)+self.f(i,k)
            };
            let right = if j-k==1 {
                self.cum.query(k,j)
            } else {
                self.cum.query(k,j)+self.f(k,j)
            };
            let cand = left+right;
            minv = min(minv, cand);
        }
        self.dp[i][j] = Some(minv);
        minv
    }
}
