    input!{
        N:usize,
        a:[i64;N],
    }
    let cum = CumSum1::build(&a);
    let mut dp = dvec![None; 401,401];
    let mut rec = Rec {
        cum: cum,
        dp: dp,
    };
    println!("{}",rec.f(0,N));
}
struct CumSum1 {
    dp: Vec<i64>,
}
impl CumSum1 {
    fn build(base: &[i64]) -> CumSum1 {
        let n = base.len();
        let mut dp = vec![0; n + 1];
        let mut acc = 0;
        for i in 0..n {
            acc += base[i];
            dp[i + 1] = acc;
        }
        CumSum1 { dp: dp }
    }
    fn query(&self, i: usize, j: usize) -> i64 {
        self.dp[j] - self.dp[i]
    }
}

