use std::ops::Range;

fn solve(aa: &[u64], ss: &[u64], range: Range<usize>, memo: &mut [Vec<Option<u64>>]) -> u64 {
    memo[range.start][range.end].unwrap_or_else(|| {
        let len = range.len();
        let res = if len == 1 { 0 } else if len == 2 { aa[range.clone()].iter().sum() } else {
            let s = ss[range.end] - ss[range.start];
            s + (range.start+1 .. range.end).map(|end| {
                solve(aa, ss, range.start..end, memo) + solve(aa, ss, end..range.end, memo)
            }).min().unwrap()
        };
        memo[range.start][range.end] = Some(res);
        res
    })
}

