    input.clear();
    io::stdin().read_line(&mut input);
    let slime: Vec<i64> = input.split_whitespace().map(|s| s.parse::<i64>().unwrap()).collect();
    if slime.len() <= 1{
        println!("0");
        return Ok(())
    }
    let mut dp = vec![vec![std::i64::MAX; slime.len()]; slime.len()];
    let mut prefix = vec![0; slime.len() + 1];
    for i in 0..slime.len() {
        prefix[i + 1] = prefix[i] + slime[i];
    }
    do_solve(0, slime.len() - 1, &mut dp, &slime, &prefix);
    println!("{}", dp[0][slime.len() - 1]);
    Ok(())
}

fn do_solve(from: usize, to: usize, dp: &mut Vec<Vec<i64>>, slime: &Vec<i64>, prefix_sum: &Vec<i64>) -> i64 {
    if dp[from][to] != std::i64::MAX {
        return dp[from][to];
    }
    if from + 1 == to {
        dp[from][to] = slime[from] + slime[to];
        return slime[from] + slime[to];
    }
    if from == to {
        dp[from][to] = 0;
        return 0;
    }
    let mut result = std::i64::MAX;
    for i in from..to {
        let cost = do_solve(from, i, dp, slime, prefix_sum) + do_solve(i + 1, to, dp, slime, prefix_sum);
        let final_cost = prefix_sum[to + 1] - prefix_sum[from];
        result = min(result, cost + final_cost);
    }
    dp[from][to] = result;
    result
}

