const INF: usize = 1_000_000_000_000_000;

fn dfs(l: usize, r: usize, sums: &Vec<usize>, dp: &mut Vec<Vec<usize>>) -> usize {
    if l+1 == r {
        return 0;
    }
    if dp[l][r] != INF {
        return dp[l][r];
    }
    let mut mn = std::usize::MAX;
    for i in (l+1)..r {
        let left = dfs(l,i,sums,dp);
        let right = dfs(i,r,sums,dp);
        mn = min!(mn, left+right);
    }
    mn += sums[r] - sums[l];
    dp[l][r] = min!(dp[l][r], mn);
    mn
}

