// Based on EbTech's Scanner https://stackoverflow.com/q/56449027
//
struct Scanner<'a, R: std::io::BufRead> {
    reader: R,
    buf: String,
    iter: std::str::SplitWhitespace<'a>,
}

impl<'a, R: std::io::BufRead> Scanner<'a, R> {
    fn new(reader: R) -> Scanner<'a, R> {
        Scanner { reader: reader, buf: String::new(), iter: "".split_whitespace() }
    }

    fn get_str(&mut self) -> &str {
        if let Some(t) = self.iter.next() {
            return t;
        }
        self.buf.clear();
        self.reader.read_line(&mut self.buf).expect("I/O error");
        self.iter = unsafe { std::mem::transmute(self.buf.split_whitespace()) };
        self.get_str()
    }

    fn get<T: std::str::FromStr>(&mut self) -> T {
        self.get_str().parse().ok().expect("Parse error")
    }
}

fn main() {
    let stdin = std::io::stdin();
    solve(Scanner::new(stdin.lock()));
}

fn solve<R: std::io::BufRead>(mut sc: Scanner<R>) {
    let n: usize = sc.get();
    let mut ss: Vec<i64> = (0..n).map(|_| sc.get()).collect();

    let mut cost = 0;
    let mut used = vec![false; n];
    let mut pq = std::collections::BinaryHeap::new();
    pq.extend(ss.iter().map(|s| -s).zip(0..n));

    while pq.len() > 1 {
        let (s, i) = pq.pop().unwrap();
        if -s != ss[i] {
            continue;
        }
        used[i] = true;

        let l = (0..i).rev().find(|&j| !used[j]);
        let r = ((i + 1)..n).find(|&j| !used[j]);
        if l.is_some() || r.is_some() {
            let j = match (l, r) {
                (Some(il), None) => il,
                (None, Some(ir)) => ir,
                (Some(il), Some(ir)) if ss[il] <= ss[ir] => il,
                (Some(il), Some(ir)) => ir,
                (None, None) => unreachable!(),
            };
            cost += ss[i] + ss[j];
            ss[j] += ss[i];
            pq.push((-ss[j], j));
        }
    }

    println!("{}", cost);
}

