fn dfs(l: usize, r: usize, dp: &mut Vec<Vec<Option<usize>>>, a: &Vec<usize>, sums: &Vec<usize>) -> usize { //[l,r)
    if let Some(res) = dp[l][r] {
        return res;
    } else if l+1 == r {
        return 0;
    }
    let mut mn = std::usize::MAX;
    for i in (l+1)..r {
        mn = min!(mn, dfs(l,i,dp,a,sums)+dfs(i,r,dp,a,sums)+sums[r]-sums[l]);
    }
    dp[l][r] = Some(mn);
    mn
}

