fn solve(
    l: usize,
    r: usize,
    n: usize,
    a: &Vec<usize>,
    sum: &Vec<usize>,
    dp: &mut Vec<Vec<Option<usize>>>,
) -> usize {
    if r - l == 2 {
        return a[l] + a[l + 1];
    } else if r - l == 1 {
        return 0;
    }
    if dp[l][r].is_some() {
        return dp[l][r].unwrap();
    }
    let mut res = 1 << 61;
    let mut i = l + 1;
    while i < r {
        let cost = { sum[r - 1] - if l > 0 { sum[l - 1] } else { 0 } };
        res = std::cmp::min(
            res,
            cost + solve(l, i, n, a, sum, dp) + solve(i, r, n, a, sum, dp),
        );
        i += 1;
    }
    dp[l][r] = Some(res);
    // println!("{}, {}, {}", l, r, res);
    res
}

