    let mut sum = vec![0; n];
    for i in 0..n {
        if i > 0 {
            sum[i] += sum[i - 1];
        }
        sum[i] += a[i];
    }
    println!("{}", solve(0, n, n, &a, &sum, &mut dp));
}

