fn main() {
    let N = read!(usize);
    let A = read![[i64]];

    let mut acc = vec![0; N + 1];
    for i in 0..N {
        acc[i + 1] = acc[i] + A[i];
    }

    // dp[l][r] : 区間 l..r を1個のスライムにするときにかかる最小のコスト
    let mut dp = vec![vec![std::i64::MAX; N + 1]; N + 1];

    // dp[l][l + 1] = 0
    // dp[l][r] = dp[l][m] + dp[m][r] + acc[r] - acc[l]

    for h in 1..N + 1 {
        for l in 0..N {
            let r = l + h;
            if r > N {
                continue;
            }

            if h == 1 {
                dp[l][r] = 0;
                continue;
            }

            for m in l + 1..r {
                dp[l][r] = min(dp[l][r], dp[l][m] + dp[m][r] + acc[r] - acc[l])
            }
        }
    }

    debug!(acc, dp);

    println!("{}", dp[0][N])
}

