struct G {
    n: usize,
    a: Vec<i64>,
    ds: Vec<i64>,
    dp: Vec<Vec<i64>>,
}

impl G {
    fn f(&mut self, l: usize, r: usize) -> i64 {
        if self.dp[l][r] != -INF {
            return self.dp[l][r];
        }
        if l == r {
            self.dp[l][r] = 0;
            return 0;
        }
        // dbg!(l, r);
        let mut ret = INF;
        for m in l..r {
            ret = min(ret, self.f(l, m) + self.f(m + 1, r));
        }
        self.dp[l][r] = ret + self.ds[r] - self.ds[l - 1];
        return self.dp[l][r];
    }
}

const INF: i64 = 1 << 60;

use std::vec::Vec;
use std::cmp::*;

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().split_whitespace()
        .map(|e| e.parse().ok().unwrap()).collect()
}

fn main() {
    let n: usize = read();
    let a: Vec<u64> = read_vec();
    // dp[i][j]はa_i ~ a_jを合成するときの最小コスト 答えはdp[0][n-1]
    // dp[i][j] = min(dp[i][l] + dp[l+1][j] + cost(i, l, j)) (i < l < j)
    // cost(i, l, j) = SUM(a_k) (for k = i ~ l) + SUM(a_k) (for k = l+1 ~ j)

    // コストを計算するための累積和
    let mut sum: Vec<u64> = vec![0; n+1];
    // dp_table
    let mut dp: Vec<Vec<u64>> = vec![vec![std::u64::MAX/2; n]; n];


    // 累積和を作成
    for i in 0..n {
      sum[i+1] = sum[i] + a[i];
    }

    // i == jの時、要素は１つなので合成できずコストは０、つまり、dp_tableの体格成分は０
    for i in 0..n {
      dp[i][i] = 0;
    }

    // dp_tableを更新
    // 区間の幅に関してループを回す
    for len in 1..n {
      for i in 0..n-len {
        // dp[i][i + len] = min(dp[i][i + len], )
        for j in i..i+len {
          dp[i][i + len]
            = min(dp[i][i + len],
                  dp[i][j] + dp[j+1][i + len]
                  + sum[i + len + 1] - sum[j+1]
                  + sum[j+1] - sum[i]);
        }
      }
    }
    println!("{}", dp[0][n-1]);
}

