fn solve() {
    input! {
        n: usize,
        a: [usize;n]
    }

    let mut ans = 0;

    // dp[x][y] x番目からy番目のスライムの総和の最小コスト
    let mut dp = vec![vec![0; n + 1]; n + 1];

    for i in 1..n {
        let index = i - 1;
        dp[i][i + 1] = a[index] + a[index + 1];
    }

    let mut cum_sum = vec![0; n + 1];
    for i in 1..n + 1 {
        cum_sum[i] = cum_sum[i - 1] + a[i - 1];
    }

    for length in 2..n {
        for i in 1..n {
            let index = i - 1;
            if i + length <= n {
                let mut min = MAX;
                let sum = cum_sum[i + length] - cum_sum[i - 1];

                for j in i + 1..(i + length) + 1 {
                    let left = dp[i][j - 1];
                    let right = dp[j][i + length];
                    min = cmp::min(min, left + right);
                }

                dp[i][i + length] = min + sum;
            }
        }
    }

    println!("{:?}", dp[1][n]);
}

