const LARGE_PRIME: u64 = 1_000_000_007;

fn power_mod(base: u64, exp: u64, modulo: u64) -> u64 {
    if exp == 0 {
        return 1;
    } else if exp & 1 == 0 {
        return (power_mod(base, exp / 2, modulo) % modulo).pow(2) % modulo;
    } else {
        return power_mod(base, exp - 1, modulo) % modulo * base % modulo;
    }
}

fn inverse_mod(element: u64, modulo: u64) -> u64 {
    // フェルマーの小定理からpが素数なら a^(p-1) = 1
    // よってa*a^(p-2) = 1 より a^(p-2)がaの逆元

    power_mod(element, modulo - 2, modulo) % modulo
}

fn combination_mod(m: u64, n: u64, modulo: u64) -> u64 {
    // m C n = m! / ( n! * (m - n)! )
    //       = m*(m-1)*(m-2)*...*(m-n+1)/n!
    //       = m*(m-1)*(m-2)*...*(m-n+1) * (n!)^-1

    let mut numerator = 1;
    for i in 0..n {
        numerator *= m - i;
        numerator %= modulo;
    }

    // n!
    let mut element = 1;
    for j in 1..(n + 1) {
        element *= j;
        element %= modulo;
    }

    numerator * inverse_mod(element, modulo) % modulo
}

fn topological_sort(n: usize, edges: Vec<(usize, usize)>) -> Vec<usize> {
    let mut result = vec![];
    let mut isolated = VecDeque::new();

    // to[x] = [a,b] x -> a, x -> b が存在
    let mut to = vec![vec![]; n + 1];

    // deg[x] = a -> x, b -> xのような辺の数
    let mut deg = vec![0; n + 1];
    for e in edges {
        to[e.0].push(e.1);
        deg[e.1] += 1;
    }

    for i in 1..n + 1 {
        if deg[i] == 0 {
            isolated.push_front(i);
        }
    }

    while isolated.len() != 0 {
        let next = isolated.pop_back().unwrap();
        result.push(next);
        for i in &to[next] {
            deg[*i] -= 1;
            if deg[*i] == 0 {
                isolated.push_front(*i);
            }
        }
    }

    result
}

