fn dp(l: usize, r: usize, memo: &mut Vec<Vec<Option<u64>>>, s: &[u64]) -> u64 {
    if let Some(src) = memo[l][r] {
        return src;
    }

    let mut cost = 1u64 << 60;
    for i in l+1..r {
        chmin!(cost, dp(l,i,memo,s) + dp(i,r,memo,s));
    }
    cost += s[r] - s[l];
    memo[l][r] = Some(cost);
    cost
}

use std::cmp::{max, min};
use std::error::Error;
