#[derive(Eq, PartialEq, Clone, Debug)]
pub struct Rev<T>(pub T);
impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}
fn solve() {
    let n = get!(usize);
    let mut a = get!([usize]).into_iter().map(|e| Rev(e)).collect::<BinaryHeap<Rev<usize>>>();

    let mut sum = 0usize;
    while a.len() > 1 {
        let Rev(n1) = a.pop().unwrap();
        let Rev(n2) = a.pop().unwrap();
        sum += n1+n2;
        a.push(Rev(n1+n2));
    }
    println!("{}", sum);
}

#[allow(unused_macros)]
macro_rules! input {
    ( source = $ s : expr , $ ( $ r : tt ) * ) => { let mut iter = $ s . split_whitespace ( ) ; let mut next = || { iter . next ( ) . unwrap ( ) } ; input_inner ! { next , $ ( $ r ) * } };
    ( $ ( $ r : tt ) * ) => { let stdin = std :: io :: stdin ( ) ; let mut bytes = std :: io :: Read :: bytes ( std :: io :: BufReader :: new ( stdin . lock ( ) ) ) ; let mut next = move || -> String { bytes . by_ref ( ) . map ( | r | r . unwrap ( ) as char ) . skip_while ( | c | c . is_whitespace ( ) ) . take_while ( | c |! c . is_whitespace ( ) ) . collect ( ) } ; input_inner ! { next , $ ( $ r ) * } };
}
#[allow(unused_macros)]
macro_rules! input_inner {
    ( $ next : expr ) => { };
    ( $ next : expr , ) => { };
    ( $ next : expr , $ var : ident : $ t : tt $ ( $ r : tt ) * ) => { let $ var = read_value ! ( $ next , $ t ) ; input_inner ! { $ next $ ( $ r ) * } };
}
#[allow(unused_macros)]
macro_rules! read_value {
    ( $ next : expr , ( $ ( $ t : tt ) ,* ) ) => { ( $ ( read_value ! ( $ next , $ t ) ) ,* ) };
    ( $ next : expr , [ $ t : tt ; $ len : expr ] ) => { ( 0 ..$ len ) . map ( | _ | read_value ! ( $ next , $ t ) ) . collect ::< Vec < _ >> ( ) };
    ( $ next : expr , chars ) => { read_value ! ( $ next , String ) . chars ( ) . collect ::< Vec < char >> ( ) };
    ( $ next : expr , usize1 ) => { read_value ! ( $ next , usize ) - 1 };
    ( $ next : expr , $ t : ty ) => { $ next ( ) . parse ::<$ t > ( ) . expect ( "Parse error" ) };
}

#[allow(unused_macros)]
macro_rules! vec_md {
    ( $ init : expr ; $ ( $ dim : expr ) ;* ) => { vec_md ! ( $ ( $ dim ) ;* => $ init ) };
    ( $ head : expr ; $ ( $ tail : expr ) ;* => $ init : expr ) => { vec ! [ vec_md ! ( $ ( $ tail ) ;* => $ init ) ; $ head ] };
    ( $ head : expr => $ init : expr ) => { vec ! [ $ init ; $ head ] };
}

#[allow(unused_macros)]
macro_rules! chmin {
    ( $ x : expr , $ y : expr ) => { if $ x > $ y { $ x = $ y ; true } else { false } };
}

fn main() {
    input! {
        n: usize,
        a: [u64; n]
    }

    let mut dp = vec_md![None;n;n];
    for i in 0..n {
        dp[i][i] = Some(0);
    }
    let cum = Cum::new(&a);
    println!("{}", rec(&mut dp, &cum, 0, n-1));
}

fn rec(dp: &mut [Vec<Option<u64>>], cum: &Cum, l: usize, r: usize) -> u64 {
    if let Some(src) = dp[l][r] {
        return src;
    }

    let mut ret = 1u64 << 60;
    for i in l..r {
        chmin!(ret, rec(dp,cum,l,i) + rec(dp,cum,i+1,r));
    }
    ret += cum.sum(l, r+1);
    dp[l][r] = Some(ret);
    ret
}

#[derive(Debug)]
#[allow(dead_code)]
struct Cum {
    s: Vec<u64>,
}
#[allow(dead_code)]
impl Cum {
    fn new(a: &Vec<u64>) -> Cum {
        let mut s = vec![0; a.len() + 1];
        for i in 0..a.len() {
            s[i + 1] = s[i] + a[i];
        }
        Cum { s: s }
    }
    #[doc = " [l,r)"]
    fn sum(&self, l: usize, r: usize) -> u64 {
        self.s[r] - self.s[l]
    }
}

use std::collections::VecDeque;

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> VecDeque<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

fn main() {
    let n = read::<usize>();
    let mut a = read_vec::<usize>();
    a.push_back(0);
    a.push_front(0);

    let mut sum_a = vec![0; n + 2];
    for i in 1..n + 2 {
        sum_a[i] = sum_a[i - 1] + a[i];
    }

    let mut dp: Vec<Vec<usize>> = vec![vec![0; n + 2]; n + 1];

    for w in 2..n + 2 {
        for i in 0..n + 2 - w {
            let j = i + w;
            let mut t = std::usize::MAX;
            for k in i + 1..j {
                t = std::cmp::min(t, dp[i][k] + dp[k][j]);
            }
            dp[i][j] = t + sum_a[j] - sum_a[i];
        }
    }
    println!("{:?}", dp[0][n]);
}

macro_rules !input {(source =$s :expr ,$($r :tt ) *) =>{let mut iter =$s .split_whitespace () ;let mut next =||{iter .next () .unwrap () } ;input_inner !{next ,$($r ) *} } ;($($r :tt ) *) =>{let stdin =std ::io ::stdin () ;let mut bytes =std ::io ::Read ::bytes (std ::io ::BufReader ::new (stdin .lock () ) ) ;let mut next =move ||->String {bytes .by_ref () .map (|r |r .unwrap () as char ) .skip_while (|c |c .is_whitespace () ) .take_while (|c |!c .is_whitespace () ) .collect () } ;input_inner !{next ,$($r ) *} } ;}
macro_rules !input_inner {($next :expr ) =>{} ;($next :expr ,) =>{} ;($next :expr ,$var :ident :$t :tt $($r :tt ) *) =>{let $var =read_value !($next ,$t ) ;input_inner !{$next $($r ) *} } ;}
macro_rules !read_value {($next :expr ,($($t :tt ) ,*) ) =>{($(read_value !($next ,$t ) ) ,*) } ;($next :expr ,[$t :tt ;$len :expr ] ) =>{(0 ..$len ) .map (|_ |read_value !($next ,$t ) ) .collect ::<Vec <_ >>() } ;($next :expr ,chars ) =>{read_value !($next ,String ) .chars () .collect ::<Vec <char >>() } ;($next :expr ,usize1 ) =>{read_value !($next ,usize ) -1 } ;($next :expr ,$t :ty ) =>{$next () .parse ::<$t >() .expect ("Parse error" ) } ;}

fn main() {
   input! {
      n: usize,
      a: [usize; n]
   }
   let mut dp = vec![vec![0usize; n]; n];
   for l in 1..n {
      for i in 0..n - l {
         let mut mn = 1001001001001001;
         for m in i..i + l {
            mn = std::cmp::min(mn, dp[i][m] + dp[m + 1][i + l]);
            dp[i][i + l] += a[m];
         }
         dp[i][i + l] += a[i + l];
         dp[i][i + l] += mn;
      }
   }
   println!("{}", dp[0][n - 1]);
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input!{
        n: usize,
        v: [usize; n]
    }
    let mut tab: Vec<Vec<usize>> = vec![vec![usize::max_value(); n]; n];
    let mut ps: Vec<usize> = v.iter().clone().scan(0, |ac, x| {*ac += *x; Some(*ac)}).collect();
    ps.insert(0, 0);
    for i in 0..n {
        tab[i][i] = 0;
    }
    for d in 1..n {
        for i in 0..n - d {
            tab[i][i + d] = ps[i + d + 1] - ps[i] + (i..i + d).map(|x| tab[i][x] + tab[x + 1][i + d]).min().unwrap();
        }
    }
    println!("{}", tab[0][n - 1]);
}
